window.BOOK={"key":"zad","app":"mutoon","lsk":"mutoon_zad_v1","title":"زاد المستقنع","unitWord":"فقرة","sub":"الفقه الحنبلي: زاد المستقنع في اختصار المقنع · شرف الدين موسى الحجاوي (ت ٩٦٨هـ) · ٢٨٦ بابًا","source":"المتن المفرد «زاد المستقنع في اختصار المقنع» (نسخ وتشكيل ومراجعة مكتب الرحاب، الشاملة الذهبية) = https://ketabonline.com/ar/books/102403 · قوبل بـ: قوبل كلمةً كلمةً بسكربت على تحقيق عبد الرحمن العسكر (دار الوطن) https://shamela.ws/book/11230 = https://ketabonline.com/ar/books/753، وعلى المتن المشكول داخل «الروض المربع» ط ركائز (ت. المشيقح والعيدان واليتامى) https://shamela.ws/book/147658؛ حيث اختلف الرحاب عن الاثنين أُخذ ما اتفق عليه اثنان، والشكل من متن الروض حيث اتفق اللفظ، وعند اختلاف الشكل يُحتكم إلى متن «الشرح الممتع» (https://shamela.ws/book/10649) — انظر zad-sources.md","note":"لفظ المتن المفرد (نشرة الرحاب) مقابَلًا كلمةً كلمةً بسكربت على تحقيق العسكر (دار الوطن) وعلى المتن داخل «الروض المربع» ط ركائز، ويؤخذ في كل خلاف ما اتفق عليه اثنان منها. والشكل من متن الروض المشكول حيث اتفق اللفظ، ويُحتكم إلى متن «الشرح الممتع» عند اختلاف الشكل، وكل ذلك في تقرير المصادر. والحركات الناقصة من الطبعات (نحو ١٦٪) أكملها الذكاء الاصطناعي وصحّح أخطاء ظاهرة فيها، فإذا شككت بحركة فراجع شيخك.","chapters":[{"id":"za1","title":"مُقَدِّمَةُ الْمُؤَلِّفِ","units":[{"id":"za1_1","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١","segs":[["matn","الْحَمْدُ لِلَّهِ حَمْدًا لَا يَنْفَدُ، أَفْضَلَ مَا يَنْبَغِي أَنْ يُحْمَدَ، وَصَلَّى اللَّهُ وَسَلَّمَ عَلَى أَفْضَلِ الْمُصْطَفَيْنَ مُحَمَّدٍ، وَعَلَى آلِهِ وَأَصْحَابِهِ وَمَنْ تَعَبَّدَ."]]},{"id":"za1_2","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢","segs":[["matn","أَمَّا بَعْدُ، فَهَذَا مُخْتَصَرٌ فِي الْفِقْهِ مِنْ مُقْنِعِ الْإِمَامِ الْمُوَفَّقِ أَبِي مُحَمَّدٍ، عَلَى قَوْلٍ وَاحِدٍ، وَهُوَ الرَّاجِحُ فِي مَذْهَبِ أَحْمَدَ، وَرُبَّمَا حَذَفْتُ مِنْهُ مَسَائِلَ نَادِرَةَ الْوُقُوعِ وَزِدْتُ مَا عَلَى مِثْلِهِ يُعْتَمَدُ، إِذِ الْهِمَمُ قَدْ قَصُرَتْ،"]]},{"id":"za1_3","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٣","segs":[["matn","وَالْأَسْبَابُ الْمُثَبِّطَةُ عَنْ نَيْلِ الْمُرَادِ قَدْ كَثُرَتْ، وَمَعَ صِغَرِ حَجْمِهِ حَوَى مَا يُغْنِي عَنِ التَّطْوِيلِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، وَهُوَ حَسْبُنَا وَنِعْمَ الْوَكِيلُ."]]}],"group":"مُقَدِّمَةُ الْمُؤَلِّفِ"},{"id":"za2","title":"كِتَابُ الطَّهَارَةِ","units":[{"id":"za2_1","label":"كِتَابُ الطَّهَارَةِ · ١","segs":[["matn","وَهِيَ ارْتِفَاعُ الْحَدَثِ وَمَا فِي مَعْنَاهُ وَزَوَالُ الْخَبَثِ."]]},{"id":"za2_2","label":"كِتَابُ الطَّهَارَةِ · ٢","segs":[["matn","الْمِيَاهُ ثَلَاثَةٌ: طَهُورٌ لَا يَرْفَعُ الْحَدَثَ وَلَا يُزِيلُ النَّجَسَ الطَّارِئَ غَيْرُهُ، وَهُوَ الْبَاقِي عَلَى خِلْقَتِهِ، فَإِنْ تَغَيَّرَ بِغَيْرِ مُمَازِجٍ كَقِطَعِ كَافُورٍ وَدُهْنٍ أَوْ بِمِلْحٍ مَائِيٍّ أَوْ سُخِّنَ بِنَجِسٍ كُرِهَ،"]]},{"id":"za2_3","label":"كِتَابُ الطَّهَارَةِ · ٣","segs":[["matn","وَإِنْ تَغَيَّرَ بِمُكْثِهِ أَوْ بِمَا يَشُقُّ صَوْنُ الْمَاءِ عَنْهُ مِنْ نَابِتٍ فِيهِ وَوَرَقِ شَجَرٍ أَوْ بِمُجَاوَرَةِ مَيْتَةٍ أَوْ سُخِّنَ بِالشَّمْسِ أَوْ بِطَاهِرٍ لَمْ يُكْرَهْ،"]]},{"id":"za2_4","label":"كِتَابُ الطَّهَارَةِ · ٤","segs":[["matn","وَإِنِ اسْتُعْمِلَ فِي طَهَارَةٍ مُسْتَحَبَّةٍ كَتَجْدِيدِ وُضُوءٍ وَغُسْلِ جُمُعَةٍ وَغَسْلَةٍ ثَانِيَةٍ وَثَالِثَةٍ كُرِهَ،"]]},{"id":"za2_5","label":"كِتَابُ الطَّهَارَةِ · ٥","segs":[["matn","وَإِنْ بَلَغَ قُلَّتَيْنِ وَهُوَ الْكَثِيرُ وَهُمَا خَمْسُمِائَةِ رَطْلٍ عِرَاقِيٍّ تَقْرِيبًا فَخَالَطَتْهُ نَجَاسَةٌ غَيْرُ بَوْلِ آدَمِيٍّ أَوْ عَذِرَتِهِ الْمَائِعَةِ فَلَمْ تُغَيِّرْهُ أَوْ خَالَطَهُ الْبَوْلُ أَوْ الْعَذِرَةُ وَيَشُقُّ نَزْحُهُ كَمَصَانِعِ طَرِيقِ مَكَّةَ فَطَهُورٌ."]]},{"id":"za2_6","label":"كِتَابُ الطَّهَارَةِ · ٦","segs":[["matn","وَلَا يَرْفَعُ حَدَثَ رَجُلٍ طَهُورٌ يَسِيرٌ خَلَتْ بِهِ امْرَأَةٌ لِطَهَارَةٍ كَامِلَةٍ عَنْ حَدَثٍ."]]},{"id":"za2_7","label":"كِتَابُ الطَّهَارَةِ · ٧","segs":[["matn","وَإِنْ تَغَيَّرَ طَعْمُهُ أَوْ لَوْنُهُ أَوْ رِيحُهُ بِطَبْخٍ أَوْ سَاقِطٍ فِيهِ أَوْ رُفِعَ بِقَلِيلِهِ حَدَثٌ أَوْ غُمِسَ فِيهِ يَدُ قَائِمٍ مِنْ نَوْمِ لَيْلٍ نَاقِضٍ لِوُضُوءٍ، أَوْ كَانَ آخِرَ غَسْلَةٍ زَالَتْ النَّجَاسَةُ بِهَا فَطَاهِرٌ."]]},{"id":"za2_8","label":"كِتَابُ الطَّهَارَةِ · ٨","segs":[["matn","وَالنَّجِسُ مَا تَغَيَّرَ بِنَجَاسَةٍ أَوْ لَاقَاهَا وَهُوَ يَسِيرٌ أَوِ انْفَصَلَ عَنْ مَحَلِّ نَجَاسَةٍ قَبْلَ زَوَالِهَا، فَإِنْ أُضِيفَ إِلَى الْمَاءِ النَّجِسِ طَهُورٌ كَثِيرٌ غَيْرُ تُرَابٍ وَنَحْوِهِ أَوْ زَالَ تَغَيُّرُ النَّجِسِ الْكَثِيرِ بِنَفْسِهِ أَوْ نُزِحَ مِنْهُ فَبَقِيَ بَعْدَهُ كَثِيرٌ غَيْرُ مُتَغَيِّرٍ طَهُرَ."]]},{"id":"za2_9","label":"كِتَابُ الطَّهَارَةِ · ٩","segs":[["matn","وَإِنْ شَكَّ فِي نَجَاسَةِ مَاءٍ أَوْ غَيْرِهِ أَوْ طَهَارَتِهِ بَنَى عَلَى الْيَقِينِ، وَإِنِ اشْتَبَهَ طَهُورٌ بِنَجِسٍ حَرُمَ اسْتِعْمَالُهُمَا وَلَمْ يَتَحَرَّ، وَلَا يُشْتَرَطُ لِلتَّيَمُّمِ إِرَاقَتُهُمَا وَلَا خَلْطُهُمَا، وَإِنِ اشْتَبَهَ بِطَاهِرٍ تَوَضَّأَ مِنْهُمَا وُضُوءًا وَاحِدًا،"]]},{"id":"za2_10","label":"كِتَابُ الطَّهَارَةِ · ١٠","segs":[["matn","مِنْ هَذَا غَرْفَةً وَمِنْ هَذَا غَرْفَةً وَصَلَّى صَلَاةً وَاحِدَةً."]]},{"id":"za2_11","label":"كِتَابُ الطَّهَارَةِ · ١١","segs":[["matn","وَإِنِ اشْتَبَهَتْ ثِيَابٌ طَاهِرَةٌ بِنَجِسَةٍ أَوْ بِمُحَرَّمَةٍ صَلَّى فِي كُلِّ ثَوْبٍ صَلَاةً بِعَدَدِ النَّجِسِ وَزَادَ صَلَاةً."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za3","title":"بَابُ الْآنِيَةِ","units":[{"id":"za3_1","label":"بَابُ الْآنِيَةِ · ١","segs":[["matn","كُلُّ إِنَاءٍ طَاهِرٍ وَلَوْ ثَمِينًا يُبَاحُ اتِّخَاذُهُ وَاسْتِعْمَالُهُ إِلَّا آنِيَةَ ذَهَبٍ وَفِضَّةٍ وَمُضَبَّبًا بِهِمَا فَإِنَّهُ يَحْرُمُ اتِّخَاذُهَا وَاسْتِعْمَالُهَا وَلَوْ عَلَى أُنْثَى، وَتَصِحُّ الطَّهَارَةُ مِنْهَا إِلَّا ضَبَّةً يَسِيرَةً مِنْ فِضَّةٍ لِحَاجَةٍ."]]},{"id":"za3_2","label":"بَابُ الْآنِيَةِ · ٢","segs":[["matn","وَتُكْرَهُ مُبَاشَرَتُهَا لِغَيْرِ حَاجَةٍ، وَتُبَاحُ آنِيَةُ الْكُفَّارِ وَلَوْ لَمْ تَحِلَّ ذَبَائِحُهُمْ، وَثِيَابُهُمْ إِنْ جُهِلَ حَالُهَا، وَلَا يَطْهُرُ جِلْدُ مَيْتَةٍ بِدِبَاغٍ، وَيُبَاحُ اسْتِعْمَالُهُ بَعْدَ الدَّبْغِ فِي يَابِسٍ مِنْ حَيْوَانٍ طَاهِرٍ فِي الْحَيَاةِ،"]]},{"id":"za3_3","label":"بَابُ الْآنِيَةِ · ٣","segs":[["matn","وَلَبَنُهَا وَكُلُّ أَجْزَائِهَا نَجِسَةٌ غَيْرَ شَعْرٍ وَنَحْوِهِ، وَمَا أُبِيْنَ مِنْ حَيٍّ فَهُوَ كَمَيْتَتِهِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za4","title":"بَابُ الِاسْتِنْجَاءِ","units":[{"id":"za4_1","label":"بَابُ الِاسْتِنْجَاءِ · ١","segs":[["matn","يُسْتَحَبُّ عِنْدَ دُخُولِ الْخَلَاءِ قَوْلُ: بِسْمِ اللَّهِ، أَعُوذُ بِاللَّهِ مِنَ الْخُبْثِ وَالْخَبَائِثِ وَعِنْدَ الْخُرُوجِ مِنْهُ: غُفْرَانَكَ، الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّيَ الْأَذَى وَعَافَانِي، وَتَقْدِيمُ رِجْلِهِ الْيُسْرَى دُخُولًا وَيُمْنَى خُرُوجًا عَكْسَ مَسْجِدٍ وَنَعْلٍ،"]]},{"id":"za4_2","label":"بَابُ الِاسْتِنْجَاءِ · ٢","segs":[["matn","وَاعْتِمَادُهُ عَلَى رِجْلِهِ الْيُسْرَى، وَبُعْدُهُ فِي فَضَاءٍ، وَاسْتِتَارُهُ، وَارْتِيَادُهُ لِبَوْلِهِ مَكَانًا رِخْوًا، وَمَسْحُهُ بِيَدِهِ الْيُسْرَى إِذَا فَرَغَ مِنْ بَوْلِهِ مِنْ أَصْلِ ذَكَرِهِ إِلَى رَأْسِهِ ثَلَاثًا وَنَتْرَهَ ثَلَاثًا،"]]},{"id":"za4_3","label":"بَابُ الِاسْتِنْجَاءِ · ٣","segs":[["matn","وَتَحَوُّلُهُ مِنْ مَوْضِعِهِ لِيَسْتَنْجِيَ فِي غَيْرِهِ إِنْ خَافَ تَلَوُّثًا."]]},{"id":"za4_4","label":"بَابُ الِاسْتِنْجَاءِ · ٤","segs":[["matn","وَيُكْرَهُ دُخُولُهُ بِشَيْءٍ فِيهِ ذِكْرُ اللَّهِ تَعَالَى إِلَّا لِحَاجَةٍ، وَرَفْعُ ثَوْبِهِ قَبْلَ دُنُوِّهِ مِنَ الْأَرْضِ، وَكَلَامُهُ فِيهِ، وَبَوْلُهُ فِي شَقٍّ وَنَحْوِهِ، وَمَسُّ فَرْجِهِ بِيَمِينِهِ وَاسْتِنْجَاؤُهُ وَاسْتِجْمَارُهُ بِهَا، وَاسْتِقْبَالُ النَّيِّرَيْنِ."]]},{"id":"za4_5","label":"بَابُ الِاسْتِنْجَاءِ · ٥","segs":[["matn","وَيَحْرُمُ اسْتِقْبَالُ الْقِبْلَةِ وَاسْتِدْبَارُهَا فِي غَيْرِ بُنْيَانٍ، وَلُبْثُهُ فَوْقَ حَاجَتِهِ، وَبَوْلُهُ فِي طَرِيقٍ وَظِلٍّ نَافِعٍ وَتَحْتَ شَجَرَةٍ عَلَيْهَا ثَمَرَةٌ وَيَسْتَجْمِرُ ثُمَّ يَسْتَنْجِي بِالْمَاءِ، وَيُجْزِئُهُ الِاسْتِجْمَارُ إِنْ لَمْ يَعْدُ الْخَارِجُ مَوْضِعَ الْعَادَةِ."]]},{"id":"za4_6","label":"بَابُ الِاسْتِنْجَاءِ · ٦","segs":[["matn","وَيُشْتَرَطُ لِلِاسْتِجْمَارِ بِأَحْجَارٍ وَنَحْوِهَا أَنْ يَكُونَ طَاهِرًا مُنْقِيًا غَيْرَ عَظْمٍ وَرَوْثٍ وَطَعَامٍ وَمُحْتَرَمٍ وَمُتَّصِلٍ بِحَيْوَانٍ، وَيُشْتَرَطُ ثَلَاثُ مَسَحَاتٍ مُنْقِيَةٍ فَأَكْثَرُ وَلَوْ بِحَجَرٍ ذِي شُعَبٍ، وَيُسَنُّ قَطْعُهُ عَلَى وِتْرٍ."]]},{"id":"za4_7","label":"بَابُ الِاسْتِنْجَاءِ · ٧","segs":[["matn","وَيَجِبُ الِاسْتِنْجَاءُ لِكِلِّ خَارِجٍ إِلَّا الرِّيحَ، وَلَا يَصِحُّ قَبْلَهُ وُضُوءٌ وَلَا تَيَمُّمٌ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za5","title":"بَابُ السِّوَاكِ وَسُنَنِ الْوُضُوءِ","units":[{"id":"za5_1","label":"بَابُ السِّوَاكِ وَسُنَنِ الْوُضُوءِ · ١","segs":[["matn","التَّسَوُّكُ بِعُودٍ لَيِّنٍ مُنْقٍ غَيْرِ مُضِرٍّ لَا يَتَفَتَّتُ، لَا بِأُصْبِعِهِ وَخِرْقَةٍ: مَسْنُونٌ كُلَّ وِقْتٍ لِغَيْرِ صَائِمٍ بَعْدَ الزَّوَالِ، مُتَأَكِّدٌ عِنْدَ صَلَاةٍ وَانْتِبَاهٍ وَتَغَيُّرِ فَمٍ، وَيَسْتَاكُ عَرْضًا مُبْتَدِئًا بِجَانِبِ فَمِهِ الْأَيْمَنِ وَيَدَّهِنُ غِبًّا وَيَكْتَحِلُ وِتْرًا وَيَجِبُ التَّسْمِيَةُ فِي الْوُضُوءِ مَعَ الذِّكْرِ."]]},{"id":"za5_2","label":"بَابُ السِّوَاكِ وَسُنَنِ الْوُضُوءِ · ٢","segs":[["matn","وَيَجِبُ الْخِتَانُ مَا لَمْ يَخَفْ عَلَى نَفْسِهِ، وَيُكْرَهُ الْقَزَعُ."]]},{"id":"za5_3","label":"بَابُ السِّوَاكِ وَسُنَنِ الْوُضُوءِ · ٣","segs":[["matn","وَمِنْ سُنَنِ الْوُضُوءِ السِّوَاكُ، وَغَسْلُ الْكَفَّيْنِ ثَلَاثًا، وَيَجِبُ مِنْ نَوْمِ لَيْلٍ نَاقِضٍ لِوُضُوءٍ وَالْبَدَاءَةُ بِمَضْمَضَةٍ ثُمَّ اسْتِنْشَاقٍ وَمُبَالَغَةٌ فِيهِمَا لِغَيْرِ صَائِمٍ وَتَخْلِيلُ اللِّحْيَةِ الْكَثِيفَةِ وَالْأَصَابِعِ، وَالتَّيَامُنُ، وَأَخْذُ مَاءٍ جَدِيدٍ لِلْأُذُنَيْنِ، وَالْغَسْلَةُ الثَّانِيَةُ وَالثَّالِثَةُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za6","title":"بَابُ فُرُوضِ الْوُضُوءِ وَصِفَتِهِ","units":[{"id":"za6_1","label":"بَابُ فُرُوضِ الْوُضُوءِ وَصِفَتِهِ · ١","segs":[["matn","فُرُوضُهُ سِتَّةٌ: غَسْلُ الْوَجْهِ وَالْفَمُ وَالْأَنْفُ مِنْهُ، وَغَسْلُ الْيَدَيْنِ، وَمَسْحُ الرَّأْسِ وَمِنْهُ الْأَذُنَانِ، وَغَسْلُ الرِّجْلَيْنِ وَالتَّرْتِيبُ وَالْمُوَالَاةُ، وَهِيَ أَنْ لَا يُؤَخِّرَ غَسْلَ عُضْوٍ حَتَى يَنْشِفَ الَّذِي قَبْلَهُ، وَالنِّيَّةُ شَرْطٌ لِطَهَارَةِ الْأَحْدَاثِ كُلِّهَا،"]]},{"id":"za6_2","label":"بَابُ فُرُوضِ الْوُضُوءِ وَصِفَتِهِ · ٢","segs":[["matn","فَيَنْوِي رَفْعَ الْحَدَثِ أَوْ الطَّهَارَةِ لِمَا لَا يُبَاحُ إِلَّا بِهَا، فَإِنْ نَوَى مَا تُسَنُّ لَهُ الطَّهَارَةُ كَقِرَاءَةٍ أَوْ تَجْدِيدًا مَسْنُونًا نَاسِيًا حَدَثَهُ ارْتَفَعَ، وَإِنْ نَوَى غُسْلًا مَسْنُونًا أَجْزَأَ عَنْ وَاجِبٍ وَكَذَا عَكْسُهُ،"]]},{"id":"za6_3","label":"بَابُ فُرُوضِ الْوُضُوءِ وَصِفَتِهِ · ٣","segs":[["matn","وَإِنْ اجْتَمَعَتْ أَحْدَاثٌ تُوجِبُ وُضُوءًا أَوْ غُسْلًا فَنَوَى بِطَهَارَتِهِ أَحَدَهَا ارْتَفَعَ سَائِرُهَا، وَيَجِبُ الْإِتْيَانُ بِهَا عِنْدَ أَوَّلِ وَاجِبَاتِ الطَّهَارَةِ وَهُوَ التَّسْمِيَةُ، وَتُسَنُّ عِنْدَ أَوَّلِ مَسْنُونَاتِهَا إِنْ وُجِدَ قَبْلَ وَاجِبٍ، وَاسْتِصْحَابُ ذِكْرِهَا فِي جَمِيعِهَا،"]]},{"id":"za6_4","label":"بَابُ فُرُوضِ الْوُضُوءِ وَصِفَتِهِ · ٤","segs":[["matn","وَيَجِبُ اسْتِصْحَابُ حُكْمِهَا. وَصِفَةُ الْوُضُوءِ أَنْ يَنْوِيَ ثُمَّ يُسَمِّيَ وَيَغْسِلَ كَفَّيْهِ ثَلَاثًا ثُمَّ يَتَمَضْمَضَ وَيَسْتَنْشِقَ وَيَغْسِلَ وَجْهَهُ مِنْ مَنَابِتِ شَعَرِ الرَّأْسِ إِلَى مَا انْحَدَرَ مِنَ اللَّحْيَيْنِ وَالذَّقَنِ طُولًا وَمِنَ الْأُذُنِ إِلَى الْأُذُنِ عَرْضًا،"]]},{"id":"za6_5","label":"بَابُ فُرُوضِ الْوُضُوءِ وَصِفَتِهِ · ٥","segs":[["matn","وَمَا فِيهِ مِنْ شَعَرٍ خَفِيفٍ وَالظَّاهِرِ الْكَثِيفِ مَعَ مَا اسْتَرْسَلَ مِنْهُ، ثُمَّ يَدَيْهِ مَعَ الْمِرْفَقَيْنِ، ثُمَّ يَمْسَحَ كُلَّ رَأْسِهِ مَعَ الْأُذُنَيْنِ مَرَّةً وَاحِدَةً ثُمَّ يَغْسِلَ رِجْلَيْهِ مَعَ الْكَعْبَيْنِ، وَيَغْسِلُ الْأَقْطَعُ بَقِيَّةَ الْمَفْرُوضِ،"]]},{"id":"za6_6","label":"بَابُ فُرُوضِ الْوُضُوءِ وَصِفَتِهِ · ٦","segs":[["matn","فَإِنْ قُطِعَ مِنْ الْمَفْصِلِ غَسَلَ رَأْسَ الْعَضُدِ مِنْهُ، ثُمَّ يَرْفَعَ نَظَرَهُ إِلَى السَّمَاءِ وَيَقُولَ مَا وَرَدَ، وَتُبَاحُ مَعُونَتُهُ وَتَنْشِيفُ أَعْضَائِهِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za7","title":"بَابُ مَسْحِ الْخُفَّيْنِ","units":[{"id":"za7_1","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ١","segs":[["matn","يَجُوزُ يَوْمًا وَلَيْلَةً، وَلِمُسَافِرٍ ثَلَاثَةً بِلَيَالِيهَا وَمِنْ حَدَثٍ بَعْدَ لُبْسٍ عَلَى طَاهِرٍ مُبَاحٍ سَاتِرٍ لِلْمَفْرُوضِ يَثْبُتُ بِنَفْسِهِ مِنْ خُفٍّ وَجَوْرَبٍ صَفِيقٍ وَنَحْوِهِمَا،"]]},{"id":"za7_2","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٢","segs":[["matn","وَعَلَى عِمَامَةٍ لَرَجُلٍ مُحَنَّكَةٍ أَوْ ذَاتِ ذُؤَابَةٍ وَعَلَى خُمُرِ نِسَاءٍ مُدَارَةٍ تَحْتَ حُلُوقِهِنَّ فِي حَدَثٍ أَصْغَرَ، وَجَبِيرَةٍ لَمْ تَتَجَاوَزْ قَدْرَ الْحَاجَةِ وَلَوْ فِي أَكْبَرَ إِلَى حَلِّهَا إِذَا لَبِسَ ذَلِكَ بَعْدَ كَمَالِ الطَّهَارَةِ،"]]},{"id":"za7_3","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٣","segs":[["matn","وَمَنْ مَسَحَ فِي سَفَرٍ ثُمَّ أَقَامَ أَوْ عَكَسَ أَوْ شَكَّ فِي ابْتِدَائِهِ فَمَسْحَ مُقِيْمٍ، وَإِنْ أَحْدَثَ ثُمَّ سَافَرَ قَبْلَ مَسْحِهِ فَمَسْحَ مُسَافِرٍ، وَلَا يَمْسَحُ قَلَانِسَ وَلِفَافَةً وَلَا مَا يَسْقُطُ مِنَ الْقَدَمِ أَوْ يُرَى مِنْهُ بَعْضُهُ،"]]},{"id":"za7_4","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٤","segs":[["matn","فَإِنْ لَبِسَ خُفًّا عَلَى خُفٍّ قَبْلَ الْحَدَثِ فَالْحُكْمُ لِلْفَوْقَانِيِّ، وَيَمْسَحُ أَكْثَرَ الْعِمَامَةِ وَظَاهِرِ قَدَمِ الْخُفِّ مِنْ أَصَابِعِهِ إِلَى سَاقِهِ دُونَ أَسْفَلِهِ وَعَقِبِهِ،"]]},{"id":"za7_5","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٥","segs":[["matn","وَعَلَى جَمِيعِ الْجَبِيْرَةِ وَمَتَى ظَهَرَ بَعْضُ مَحَلِّ الْفَرْضِ بَعْدَ الْحَدَثِ أَوْ تَمَّتْ مُدَّتُهُ اسْتَأْنَفَ الطَّهَارَةَ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za8","title":"بَابُ نَوَاقِضِ الْوُضُوءِ","units":[{"id":"za8_1","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ١","segs":[["matn","يَنْقُضُ مَا خَرَجَ مِنْ سَبِيلٍ، وَخَارِجٌ مِنْ بَقِيَّةِ الْبَدَنِ إِنْ كَانَ بَوْلًا أَوْ غَائِطًا أَوْ كَثِيرًا نَجِسًا غَيْرَهُمَا، وَزَوَالُ الْعَقْلِ إِلَّا يَسِيرَ نَوْمٍ مِنْ قَاعِدٍ وَقَائِمٍ، وَمَسُّ ذَكَرٍ مُتَّصِلٍ أَوْ قُبُلٍ بِظَهْرِ كَفِّهِ أَوْ بَطْنِهِ،"]]},{"id":"za8_2","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٢","segs":[["matn","وَلَمْسُهُمَا مِنْ خُنْثَى مُشْكِلٍ، وَلَمْسُ ذَكَرٍ ذَكَرَهُ أَوْ أُنْثَى قُبُلَهُ لِشَهْوَةٍ فِيهِمَا، وَمَسُّهُ امْرَأَةً بِشَهْوَةٍ أَوْ تَمَسُّهُ بِهَا،"]]},{"id":"za8_3","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٣","segs":[["matn","وَمَسُّ حَلْقَةِ دُبُرٍ لَا مَسُّ شَعَرٍ وَسِنٍّ وَظُفُرٍ وَأَمْرَدَ وَلَا مَعَ حَائِلٍ وَلَا مَلْمُوسٍ بَدَنُهُ وَلَوْ وُجِدَ مِنْهُ شَهْوَةٌ، وَيَنْقُضُ غَسْلُ مَيِّتٍ، وَأَكْلُ اللَّحْمِ خَاصَّةً مِنَ الْجَزُورِ، وَكُلُّ مَا أَوْجَبَ غُسْلًا أَوْجَبَ وُضُوءًا إِلَّا الْمَوْتَ،"]]},{"id":"za8_4","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٤","segs":[["matn","وَمَنْ تَيَقَّنَ الطَّهَارَةَ وَشَكَّ فِي الْحَدَثِ أَوْ بِالْعَكْسِ بَنَى عَلَى الْيَقِينِ، فِإِنْ تَيَقَّنَهُمَا وَجَهِلَ السَّابِقَ فَهُوَ بِضِدِّ حَالِهِ قَبْلَهُمَا، وَيَحْرُمُ عَلَى الْمُحْدِثِ مَسُّ الْمُصْحَفِ، وَالصَّلَاةُ، وَالطَّوَافُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za9","title":"بَابُ الْغُسْلِ","units":[{"id":"za9_1","label":"بَابُ الْغُسْلِ · ١","segs":[["matn","وَمُوجِبُهُ خُرُوجُ الْمَنِيِّ دَفْقًا بِلَذَّةٍ لَا بِدُونِهِمَا مِنْ غَيْرِ نَائِمٍ."]]},{"id":"za9_2","label":"بَابُ الْغُسْلِ · ٢","segs":[["matn","وَإِنْ انْتَقَلَ وَلَمْ يَخْرُجْ اغْتَسَلَ لَهُ، فَإِنْ خَرَجَ بَعْدَهُ لَمْ يُعِدْهُ، وَتَغْيِيبُ حَشَفَةٍ أَصْلِيَّةٍ فِي فَرْجٍ أَصْلِيٍّ قُبُلًا كَانَ أَوْ دُبُرًا وَلَوْ مِنْ بَهِيمَةٍ أَوْ مَيْتٍ، وَإِسْلَامُ كَافِرٍ، وَمَوْتٌ، وَحَيْضٌ، وَنِفَاسٌ،"]]},{"id":"za9_3","label":"بَابُ الْغُسْلِ · ٣","segs":[["matn","لَا وِلَادَةٌ عَارِيَةٌ عَنْ دَمٍ، وَمَنْ لَزِمَهُ الْغُسْلُ حَرُمَ عَلَيْهِ قِرَاءَةُ الْقُرْآنِ."]]},{"id":"za9_4","label":"بَابُ الْغُسْلِ · ٤","segs":[["matn","وَيَعْبُرُ الْمَسْجِدَ لِحَاجَةٍ وَلَا يَلْبَثُ فِيهِ بِغَيْرِ وُضُوءٍ."]]},{"id":"za9_5","label":"بَابُ الْغُسْلِ · ٥","segs":[["matn","وَمَنْ غَسَّلَ مَيْتًا أَوْ أَفَاقَ مِنْ جُنُونٍ أَوْ إِغْمَاءٍ بِلَا حُلْمٍ سُنَّ لَهُ الْغُسْلُ."]]},{"id":"za9_6","label":"بَابُ الْغُسْلِ · ٦","segs":[["matn","وَالْغُسْلُ الْكَامِلُ أَنْ يَنْوِيَ ثُمَّ يُسَمِّيَ وَيَغْسِلَ يَدَيْهِ ثَلَاثًا وَمَا لَوَّثَهُ، وَيَتَوَضَّأَ وَيَحْثِيَ عَلَى رَأْسِهِ ثَلَاثًا تُرَوِّيهِ وَيَعُمَّ بَدَنَهُ غُسْلًا ثَلَاثًا وَيَدْلُكَهُ وَيَتَيَامَنُ وَيَغْسِلُ قَدَمَيْهِ مَكَانًا آخَرَ، وَالْمُجْزِئُ أَنْ يَنْوِيَ وَيُسَمِّيَ وَيَعُمَّ بَدَنَهُ بِالْغُسْلِ مَرَّةً،"]]},{"id":"za9_7","label":"بَابُ الْغُسْلِ · ٧","segs":[["matn","وَيَتَوَضَّأُ بِمُدٍّ، وَيَغْتَسِلُ بِصَاعٍ، فَإِنْ أَسْبَغَ بِأَقَلَّ أَوْ نَوَى بِغُسْلِهِ الْحَدَثَيْنِ أَجْزَأَ، وَيُسَنُّ لِجُنُبٍ غَسْلُ فَرْجِهِ، وَالْوُضُوءُ، لِأَكْلٍ وَنَوْمٍ وَلِمُعَاوَدَةِ وَطْءٍ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za10","title":"بَابُ التَّيَمُّمِ","units":[{"id":"za10_1","label":"بَابُ التَّيَمُّمِ · ١","segs":[["matn","وَهُوَ بَدَلُ طَهَارَةِ الْمَاءِ، إِذَا دَخَلَ وَقْتُ فَرِيضَةٍ أَوْ أُبِيحَتْ نَافِلَةٌ وَعَدِمَ الْمَاءُ أَوْ زَادَ عَلَى ثَمَنِهِ كَثِيرًا أَوْ ثَمَنٍ يُعْجِزُهُ أَوْ خَافَ بِاسْتِعْمَالِهِ أَوْ طَلَبِهِ ضَرَرَ بَدَنِهِ أَوْ رَفِيقِهِ أَوْ حُرْمَتِهِ أَوْ مَالِهِ بِعَطَشٍ أَوْ مَرَضٍ أَوْ هَلَاكٍ وَنَحْوِهِ شُرِعَ التَّيَمُّمُ،"]]},{"id":"za10_2","label":"بَابُ التَّيَمُّمِ · ٢","segs":[["matn","وَمَنْ وَجَدَ مَاءً يَكْفِي بَعْضَ طُهْرِهِ تَيَمَّمَ بَعْدَ اسْتِعْمَالِهِ."]]},{"id":"za10_3","label":"بَابُ التَّيَمُّمِ · ٣","segs":[["matn","وَمَنْ جُرِحَ تَيَمَّمَ لَهُ وَغَسَلَ الْبَاقِيَ، وَيَجِبُ طَلَبُ الْمَاءِ فِي رَحْلِهِ وَقُرْبِهِ وَبِدِلَالَةٍ، فَإِنْ نَسِيَ قُدْرَتَهُ عَلَيْهِ وَتَيَمَّمَ أَعَادَ."]]},{"id":"za10_4","label":"بَابُ التَّيَمُّمِ · ٤","segs":[["matn","وَإِنْ نَوَى بِتَيَمُّمِهِ أَحْدَاثًا أَوْ نَجَاسَةً عَلَى بَدَنِهِ تَضُرُّهُ إِزَالَتُهَا أَوْ عَدِمَ مَا يُزِيلُهَا أَوْ خَافَ بَرْدًا أَوْ حُبِسَ فِي مِصْرٍ فَتَيَمَّمَ أَوْ عَدِمَ الْمَاءَ وَالتُّرَابَ صَلَّى وَلَمْ يُعِدْ، وَيَجِبُ التَّيَمُّمُ بِتُرَابٍ طَهُورٍ لَهُ غُبَارٌ،"]]},{"id":"za10_5","label":"بَابُ التَّيَمُّمِ · ٥","segs":[["matn","وَفُرُوضُهُ مَسْحُ وَجْهِهِ وَيَدَيْهِ إِلَى كُوعَيْهِ، وَكَذَا التَّرْتِيبُ وَالْمُوَالَاةُ فِي حَدَثٍ أَصْغَرَ: وَتُشْتَرَطُ النِّيَّةُ لِمَا يَتَيَمَّمُ لَهُ مِنْ حَدَثٍ أَوْ غَيْرِهِ، فَإِنْ نَوَى أَحَدَهَا لَمْ يُجْزِئْهُ عَنْ الْآخَرِ،"]]},{"id":"za10_6","label":"بَابُ التَّيَمُّمِ · ٦","segs":[["matn","وَإِنْ نَوَى نَفْلًا أَوْ أَطْلَقَ لَمْ يُصَلِّ بِهِ فَرْضًا، وَإِنْ نَوَاهُ صَلَّى كُلَّ وَقْتِهِ فُرُوضًا وَنَوَافِلَ."]]},{"id":"za10_7","label":"بَابُ التَّيَمُّمِ · ٧","segs":[["matn","وَيَبْطُلُ التَّيَمُّمُ بِخُرُوجِ الْوَقْتِ، وَبِمُبْطِلَاتِ الْوُضُوءِ، وَبِوُجُودِ الْمَاءِ وَلَوْ فِي الصَّلَاةِ لَا بَعْدَهَا، وَالتَّيَمُّمُ آخِرَ الْوَقْتِ لِرَاجِي الْمَاءِ أَوْلَى."]]},{"id":"za10_8","label":"بَابُ التَّيَمُّمِ · ٨","segs":[["matn","وَصِفَتُهُ أَنْ يَنْوِيَ، ثُمَّ يُسَمِّيَ، وَيَضْرِبُ التُّرَابَ بِيَدَيْهِ مُفَرَّجَتَيِ الْأَصَابِعِ يَمْسَحُ وَجْهَهُ بِبَاطِنِهِمَا وَكَفَّيْهِ بِرَاحَتَيْهِ وَيُخَلِّلُ أَصَابِعَهُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za11","title":"بَابُ إِزَالَةِ النَّجَاسَةِ","units":[{"id":"za11_1","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ١","segs":[["matn","يُجْزِئُ فِي غَسْلِ النَّجَاسَاتِ كُلِّهَا إِذَا كَانَتْ عَلَى الْأَرْضِ غَسْلَةٌ وَاحِدَةٌ تَذْهَبُ بَعَيْنِ النَّجَاسَةِ، وَعَلَى غَيْرِهَا سَبْعٌ إِحْدَاهَا بِتُرَابٍ فِي نَجَاسَةِ كَلْبٍ وَخِنْزِيرٍ وَيُجْزِئُ عَنِ التُّرَابِ أُشْنَانٌ وَنَحْوُهُ، وَفِي نَجَاسَةِ غَيْرِهِمَا سَبْعٌ بِلَا تُرَابٍ،"]]},{"id":"za11_2","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٢","segs":[["matn","وَلَا يَطْهُرُ مُتَنَجِّسٌ بِشَمْسٍ، وَلَا رِيْحٍ، وَلَا دَلْكٍ وَلَا اسْتِحَالَةٍ غَيْرَ الْخَمْرَةِ، فَإِنْ خُلِّلَتْ أَوْ تَنَجَّسَ دُهْنٌ مَائِعٌ لَمْ يَطْهُرْ، وَإِنْ خَفِيَ مَوْضِعُ نَجَاسَةٍ غَسَلَ حَتَّى يَجْزِمَ بِزَوَالِهِ، وَيَطْهُرُ بَوْلُ غُلَامٍ لَمْ يَأْكُلِ الطَّعَامَ بِنَضْحِهِ،"]]},{"id":"za11_3","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٣","segs":[["matn","وَيُعْفَى فِي غَيْرِ مَائِعٍ وَمَطْعُومٍ عَنْ يَسِيرِ دَمٍ نَجِسٍ مِنْ حَيْوَانٍ طَاهِرٍ، وَعَنْ أَثَرِ اسْتِجْمَارٍ وَلَا يَنْجُسُ الْآدَمِيُّ بِالْمَوْتِ، وَمَا لَا نَفْسَ لَهُ سَائِلَةٌ مُتَوَلِّدٌ مِنْ طَاهِرٍ، وَبَوْلُ مَا يُؤْكَلُ لَحْمُهُ وَرَوْثُهُ وَمَنِيُّهُ، وَمَنِيُّ الْآدَمِيِّ،"]]},{"id":"za11_4","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٤","segs":[["matn","وَرُطُوبَةُ فَرْجِ الْمَرْأَةِ، وَسُؤْرُ الْهِرَّةِ وَمَا دُونَهَا فِي الْخِلْقَةِ طَاهِرٌ، وَسِبَاعُ الْبَهَائِمِ وَالطَّيْرُ وَالْحِمَارُ الْأَهْلِيُّ، وَالْبَغْلُ مِنْهُ نَجِسَةٌ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za12","title":"بَابُ الْحَيْضِ","units":[{"id":"za12_1","label":"بَابُ الْحَيْضِ · ١","segs":[["matn","لَا حَيْضَ قَبْلَ تِسْعِ سِنِينَ، وَلَا بَعْدَ خَمْسِينَ، وَلَا مَعَ حَمْلٍ، وَأَقَلُّهُ يَوْمٌ وَلَيْلَةٌ وَأَكْثَرُهُ خَمْسَةَ عَشَرَ يَوْمًا، وَغَالِبُهُ سِتٌّ أَوْ سَبْعٌ، وَأَقَلُّ الطُّهْرِ بَيْنَ الْحَيْضَتَيْنِ ثَلَاثَةَ عَشَرَ، وَلَا حَدَّ لِأَكْثَرِهِ،"]]},{"id":"za12_2","label":"بَابُ الْحَيْضِ · ٢","segs":[["matn","وَتَقْضِي الْحَائِضُ الصَّوْمَ لَا الصَّلَاةَ، وَلَا يَصِحَّانِ مِنْهَا بَلْ يَحْرُمَانِ، وَيَحْرُمُ وَطْؤُهَا فِي الْفَرْجِ، فَإِنْ فَعَلَ فَعَلَيْهِ دِينَارٌ أَوْ نِصْفُهُ كَفَّارَةً، وَيَسْتَمْتِعُ مِنْهَا بِمَا دُونَهُ، وَإِذَا انْقَطَعَ الدَّمُ وَلَمْ تَغْتَسِلْ لَمْ يُبَحْ غَيْرُ الصِّيَامِ وَالطَّلَاقِ،"]]},{"id":"za12_3","label":"بَابُ الْحَيْضِ · ٣","segs":[["matn","وَالْمُبْتَدَأَةُ تَجْلِسُ أَقَلَّهُ ثُمَّ تَغْتَسِلُ وَتُصَلِّي فَإِنْ انْقَطَعَ لِأَكْثَرِهِ فَمَا دُونَ اغْتَسَلَتْ إِذَا انْقَطَعَ، فَإِنْ تَكَرَّرَ ثَلَاثًا فَحَيْضٌ وَتَقْضِي مَا وَجَبَ فِيهِ، وَإِنْ عَبَرَ أَكْثَرَهُ فَمُسْتَحَاضَةٌ،"]]},{"id":"za12_4","label":"بَابُ الْحَيْضِ · ٤","segs":[["matn","فَإِنْ كَانَ بَعْضُ دَمِهَا أَحْمَرَ وَبَعْضُهُ أَسْوَدَ وَلَمْ يَعْبُرْ أَكْثَرَهُ وَلَمْ يَنْقُصْ عَنْ أَقَلِّهِ فَهُوَ حَيْضُهَا تَجْلِسُهُ فِي الشَّهْرِ الثَّانِي، وَالْأَحْمَرُ اسْتِحَاضَةٌ، وَإِنْ لَمْ يَكُنْ دَمُهَا مُتَمَيِّزًا جَلَسَتْ غَالِبَ الْحَيْضِ مِنْ كُلِّ شَهْرٍ."]]},{"id":"za12_5","label":"بَابُ الْحَيْضِ · ٥","segs":[["matn","وَالْمُسْتَحَاضَةُ الْمُعْتَادَةُ وَلَوْ مُمَيِّزَةً تَجْلِسُ عَادَتَهَا. وَإِنْ نَسِيَتْهَا عَمِلَتْ بِالتَّمْيِيزِ الصَّالِحِ، فَإِنْ لَمْ يَكُنْ لَهَا تَمْيِيزٌ فَغَالِبُ الْحَيْضِ كَالْعَالِمَةِ بِمَوْضِعِهِ النَّاسِيَةِ لِعَدَدِهِ، وَإِنْ عَلِمَتْ عَدَدَهُ وَنَسِيَتْ مَوْضِعَهُ مِنَ الشَّهْرِ وَلَوْ فِي نِصْفِهِ جَلَسَتْهَا مِنْ أَوَّلِهِ كَمَنْ لَا عَادَةَ لَهَا وَلَا تَمْيِيزَ،"]]},{"id":"za12_6","label":"بَابُ الْحَيْضِ · ٦","segs":[["matn","وَمَنْ زَادَتْ عَادَتُهَا أَوْ تَقَدَّمَتْ أَوَ تَأَخَّرَتْ فَمَا تَكَرَّرَ ثَلَاثًا فَحَيْضٌ وَمَا نَقَصَ عَنِ الْعَادَةِ طُهْرٌ وَمَا عَادَ فِيهَا جَلَسَتْهُ، وَالصُّفْرَةُ وَالْكُدْرَةُ فِي زَمَنِ الْعَادَةِ حَيْضٌ،"]]},{"id":"za12_7","label":"بَابُ الْحَيْضِ · ٧","segs":[["matn","وَمَنْ رَأَتْ يَوْمًا دَمًا وَيَوْمًا نَقَاءً فَالدَّمُ حَيْضٌ وَالنَّقَاءُ طُهْرٌ مَا لَمْ يَعْبُرْ أَكْثَرَهُ."]]},{"id":"za12_8","label":"بَابُ الْحَيْضِ · ٨","segs":[["matn","وَالْمُسْتَحَاضَةُ وَنَحْوُهَا تَغْسِلُ فَرْجَهَا وَتَعْصِبُهُ وَتَتَوَضَّأُ لِوَقْتِ كُلِّ صَلَاةٍ وَتُصَلِّي فُرُوضًا، وَنَوَافِلَ، وَلَا تُوطَأُ إِلَّا مَعَ خَوْفِ الْعَنَتِ، وَيُسْتَحَبُّ غُسْلُهَا لِكُلِّ صَلَاةٍ، وَأَكْثَرُ مُدَّةِ النِّفَاسِ أَرْبَعُونَ يَوْمًا، وَمَتَى طَهُرَتْ قَبْلَهُ تَطَهَّرَتْ وَصَلَّتْ،"]]},{"id":"za12_9","label":"بَابُ الْحَيْضِ · ٩","segs":[["matn","وَيُكْرَهُ وَطْؤُهَا قَبْلَ الْأَرْبَعِينَ بَعْدَ التَّطْهِيرِ، فَإِنْ عَاوَدَهَا الدَّمُ فَمَشْكُوكٌ فِيهِ تَصُومُ وَتُصَلِّي، وَتَقْضِي الْوَاجِبَ، وَهُوَ كَالْحَيْضِ فِيمَا يَحِلُّ وَيَحْرُمُ وَيَجِبُ وَيَسْقُطُ غَيْرَ الْعِدَّةِ وَالْبُلُوغِ، وَإِنْ وَلَدَتْ تَوْأَمَيْنِ فَأَوَّلُ النِّفَاسِ وَآخِرُهُ مِنْ أَوَّلِهِمَا."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"za13","title":"كِتَابُ الصَّلَاةِ","units":[{"id":"za13_1","label":"كِتَابُ الصَّلَاةِ · ١","segs":[["matn","تَجِبُ عَلَى كُلِّ مُسْلِمٍ مُكَلَّفٍ إِلَّا حَائِضًا وَنُفَسَاءَ، وَيَقْضِي مَنْ زَالَ عَقْلُهُ بِنَوْمٍ أَوْ إِغْمَاءٍ أَوْ سُكْرٍ أَوْ نَحْوِهِ، وَلَا تَصِحُّ مِنْ مَجْنُونٍ وَلَا كَافِرٍ."]]},{"id":"za13_2","label":"كِتَابُ الصَّلَاةِ · ٢","segs":[["matn","فَإِنْ صَلَّى فَمُسْلِمٌ حُكْمًا، وَيُؤْمَرُ بِهَا صَغِيرٌ لِسَبْعٍ، وَيُضْرَبُ عَلَيْهَا لِعَشْرٍ، فَإِنْ بَلَغَ فِي أَثْنَائِهَا أَوْ بَعْدَهَا فِي وَقْتِهَا أَعَادَ،"]]},{"id":"za13_3","label":"كِتَابُ الصَّلَاةِ · ٣","segs":[["matn","وَيَحْرُمُ تَأْخِيرُهَا عَنْ وَقْتِهَا إِلَّا لِنَاوٍ الْجَمْعَ وَلِمُشْتَغِلٍ بِشَرْطِهَا الَّذِي يُحَصِّلُهُ قَرِيبًا وَمَنْ جَحَدَ وُجُوبَهَا كَفَرَ، وَكَذَا تَارِكُهَا تَهَاوُنًا وَدَعَاهُ إِمَامٌ أَوْ نَائِبُهُ فَأَصَرَّ وَضَاقَ وَقْتُ الثَّانِيَةِ عَنْهَا وَلَا يُقْتَلُ حَتَّى يُسْتَتَابَ ثَلَاثًا فِيهِمَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za14","title":"بَابُ الْأَذَانِ وَالْإِقَامَةِ","units":[{"id":"za14_1","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ١","segs":[["matn","هُمَا فَرْضَا كِفَايَةٍ عَلَى الرِّجَالِ الْمُقِيمِينَ لِلصَّلَوَاتِ الْمَكْتُوبَةِ، يُقَاتَلُ أَهْلُ بَلَدٍ تَرَكُوهُمَا، وَتَحْرُمُ أُجْرَتُهُمَا، لَا رَزْقٌ مِنْ بَيْتِ الْمَالِ لِعَدَمِ مُتَطَوِّعٍ، وَيَكُونُ الْمُؤَذِّنُ صَيِّتًا أَمِيْنًا عَالِمًا بِالْوَقْتِ، فَإِنْ تَشَاحَّ فِيهِ اثْنَانِ قُدِّمَ أَفْضَلُهُمَا فِيهِ،"]]},{"id":"za14_2","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٢","segs":[["matn","ثُمَّ أَفْضَلُهُمَا فِي دِينِهِ وَعَقْلِهِ، ثُمَّ مَنْ يَخْتَارُهُ الْجِيْرَانُ، ثُمَّ قُرْعَةٌ،"]]},{"id":"za14_3","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٣","segs":[["matn","وَهُوَ خَمْسَ عَشْرَةَ جُمْلَةً يُرَتِّلُهَا عَلَى عُلُوٍّ مُتَطَهِّرًا مُسْتَقْبِلَ الْقِبْلَةِ جَاعِلًا إِصْبَعَيْهِ فِي أُذُنَيْهِ غَيْرَ مُسْتَدِيرٍ مُلْتَفِتًا فِي الْحَيْعَلَةِ يَمِينًا وَشِمَالًا قَائِلًا بَعْدَهُمَا فِي أَذَانِ الصُّبْحِ الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ مَرَّتَيْنِ."]]},{"id":"za14_4","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٤","segs":[["matn","وَهِيَ إِحْدَى عَشْرَةَ يَحْدُرُهَا وَيُقِيمُ مَنْ أَذَّنَ فِي مَكَانِهِ إِنْ سَهُلَ، وَلَا يَصِحُّ إِلَّا مُرَتَّبًا مُتَوَالِيًا مِنْ عَدْلٍ وَلَوْ مُلَحَّنًا أَوْ مَلْحُونًا، وَيُجْزِئُ مِنْ مُمَيِّزٍ، وَيُبْطِلُهُمَا فَصْلٌ كَثِيرٌ، وَيَسِيرٌ مُحَرَّمٌ،"]]},{"id":"za14_5","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٥","segs":[["matn","وَلَا يُجْزِئُ قَبْلَ الْوَقْتِ إِلَّا لِفَجْرٍ بَعْدَ نِصْفِ اللَّيْلِ، وَيُسَنُّ جُلُوسُهُ بَعْدَ أَذَانِ الْمَغْرِبِ يَسِيْرًا، وَمَنْ جَمَعَ أَوْ قَضَى فَوَائِتَ أَذَّنَ لِلْأُولَى ثُمَّ أَقَامَ لِكُلِّ فَرِيضَةٍ، وَيُسَنُّ لِسَامِعِهِ مُتَابَعَتُهُ سِرًّا، وَحَوْقَلَتُهُ فِي الْحَيْعَلَةِ،"]]},{"id":"za14_6","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٦","segs":[["matn","وَقَوْلُهُ بَعْدَ فَرَاغِهِ «اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ»"]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za15","title":"بَابُ شُرُوطِ الصَّلَاةِ","units":[{"id":"za15_1","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١","segs":[["matn","شُرُوطُهَا قَبْلَهَا مِنْهَا الْوَقْتُ وَالطَّهَارَةُ مِنَ الْحَدَثِ وَالنَّجَسِ، فَوَقْتُ الظُّهْرِ مِنَ الزَّوَالِ إِلَى مُسَاوَاةِ الشَّيْءِ فَيْئَهُ بَعْدَ فَيْءِ الزَّوَالِ، وَتَعْجِيلُهَا أَفْضَلُ إِلَّا فِي شِدَّةِ حَرٍّ، وَلَوْ صَلَّى وَحْدَهُ أَوْ مَعَ غَيْمٍ لِمَنْ يُصَلِّي جَمَاعَةً."]]},{"id":"za15_2","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٢","segs":[["matn","وَيَلِيهِ وَقْتُ الْعَصْرِ إِلَى مَصِيرِ الْفَيْءِ مِثْلَيْهِ بَعْدَ فَيْءِ الزَّوَالِ، وَالضَّرُورَةُ إِلَى غُرُوبِهَا، وَيُسَنُّ تَعْجِيلُهَا، وَيَلِيهِ وَقْتُ الْمَغْرِبِ إِلَى مَغِيْبِ الْحُمْرَةِ، وَيُسَنُّ تَعْجِيلُهَا إِلَّا لَيْلَةَ جَمْعٍ لِمَنْ قَصَدَهَا مُحْرِمًا،"]]},{"id":"za15_3","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٣","segs":[["matn","وَيَلِيهِ وَقْتُ الْعِشَاءِ إِلَى الْفَجْرِ الثَّانِي وَهُوَ الْبَيَاضُ الْمُعْتَرِضُ، وَتَأْخِيرُهَا إِلَى ثُلُثِ اللَّيْلِ أَفْضَلُ إِنْ سَهُلَ، وَيَلِيهِ وَقْتُ الْفَجْرِ إِلَى طُلُوعِ الشَّمْسِ، وَتَعْجِيلُهَا أَفْضَلُ، وَتُدْرَكُ الصَّلَاةُ بِتَكْبِيرَةِ الْإِحْرَامِ،"]]},{"id":"za15_4","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٤","segs":[["matn","فِي وَقْتِهَا وَلَا يُصَلِّي قَبْلَ غَلَبَةِ ظَنِّهِ بِدُخُولِ وَقْتِهَا إِمَّا بِاجْتِهَادٍ أَوْ خَبَرِ مُتَيَقِّنٍ، فَإِنْ أَحْرَمَ بِاجْتِهَادٍ فَبَانَ قَبْلَهُ فَنَفْلٌ، وَإِلَّا فَفَرْضٌ،"]]},{"id":"za15_5","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٥","segs":[["matn","وَإِنْ أَدْرَكَ مُكَلَّفٌ مِنْ وَقْتِهَا قَدْرَ التَّحْرِيمَةِ ثُمَّ زَالَ تَكْلِيفُهُ أَوْ حَاضَتْ ثُمَّ كُلِّفَ وَطَهُرَتْ قَضَوْهَا،"]]},{"id":"za15_6","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٦","segs":[["matn","وَمَنْ صَارَ أَهْلًا لِوُجُوبِهَا قَبْلَ خُرُوجِ وَقْتِهَا لَزِمَتْهُ وَمَا يُجْمَعُ إِلَيْهَا قَبْلَهَا وَيَجِبُ فَوْرًا قَضَاءُ الْفَوَائِتِ مُرَتِّبًا وَيَسْقُطُ التَّرْتِيبُ بِنِسْيَانِهِ وَبِخَشْيَةِ خُرُوجِ وَقْتِ اخْتِيَارِ الْحَاضِرَةِ، وَمِنْهَا سَتْرُ الْعَوْرَةِ، فَيَجِبُ بِمَا لَا يَصِفُ بَشَرَتَهَا،"]]},{"id":"za15_7","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٧","segs":[["matn","وَعَوْرَةُ رَجُلٍ وَأَمَةٍ وَأُمِّ وَلَدٍ وَمُعْتَقٍ بَعْضُهَا مِنَ السُّرَّةِ إِلَى الرُّكْبَةِ، وَكُلُّ الْحُرَّةِ عَوْرَةٌ إِلَّا وَجْهَهَا."]]},{"id":"za15_8","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٨","segs":[["matn","وَتُسْتَحَبُّ صَلَاتُهُ فِي ثَوْبَيْنِ، وَيَكْفِي سَتْرُ عَوْرَتِهِ فِي النَّفْلِ وَمَعَ أَحَدِ عَاتِقَيْهِ فِي الْفَرْضِ وَصَلَاتُهَا فِي دِرْعٍ وَخِمَارٍ وَمِلْحَفَةٍ."]]},{"id":"za15_9","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٩","segs":[["matn","وَيُجْزِئُ سَتْرُ عَوْرَتِهَا، وَمَنِ انْكَشَفَ بَعْضُ عَوْرَتِهِ وَفَحُشَ، أَوْ صَلَّى فِي ثَوْبٍ مُحَرَّمٍ عَلَيْهِ أَوْ نَجِسٍ أَعَادَ لَا مَنْ حُبِسَ فِي مَحَلٍّ نَجِسٍ."]]},{"id":"za15_10","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٠","segs":[["matn","وَمَنْ وَجَدَ كِفَايَةَ عَوْرَتِهِ سَتَرَهَا، وَإِلَّا فَالْفَرْجَيْنِ، فَإِنْ لَمْ يَكْفِهِمَا فَالدُّبُرِ، وَإِنْ أُعِيرَ سُتْرَةً لَزِمَهُ قَبُولُهَا، وَيُصَلِّي الْعَارِي قَاعِدًا بِالْإِيمَاءِ اسْتِحْبَابًا فِيهِمَا، وَيَكُونُ إِمَامُهُمْ وَسَطَهُمْ، وَيُصَلِّي كُلُّ نَوْعٍ وَحْدَهُ،"]]},{"id":"za15_11","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١١","segs":[["matn","فَإِنْ شَقَّ صَلَّى الرِّجَالُ وَاسْتَدْبَرَهُمْ النِّسَاءُ ثُمَّ عَكَسُوا، فَإِنْ وَجَدَ سُتْرَةً قَرِيبَةً فِي أَثْنَاءِ الصَّلَاةِ سَتَرَ وَبَنَى وَإِلَّا ابْتَدَأَ."]]},{"id":"za15_12","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٢","segs":[["matn","وَيُكْرَهُ فِي الصَّلَاةِ السَّدْلُ، وَاشْتِمَالُ الصَّمَّاءِ، وَتَغْطِيَةُ وَجْهِهِ، وَاللِّثَامُ عَلَى فَمِهِ وَأَنْفِهِ، وَكَفُّ كُمِّهِ وَلَفُّهُ، وَشَدُّ وَسَطِهِ كَزُنَّارٍ، وَتَحْرُمُ الْخُيَلَاءُ فِي ثَوْبٍ وَغَيْرِهِ، وَالتَّصْوِيرُ وَاسْتِعْمَالُهُ."]]},{"id":"za15_13","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٣","segs":[["matn","وَيَحْرُمُ اسْتِعْمَالُ مَنْسُوجٍ أَوْ مُمَوَّهٍ بِذَهَبٍ قَبْلَ اسْتِحَالَتِهِ، وَثِيَابُ حَرِيرٍ، وَمَا هُوَ أَكْثَرُهُ ظُهُورًا عَلَى الذُّكُورِ، لَا إِذَا اسْتَوَيَا،"]]},{"id":"za15_14","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٤","segs":[["matn","أَوْ لِضَرُورَةٍ أَوْ حِكَّةٍ أَوْ مَرَضٍ أَوْ حَرْبٍ أَوْ حَشْوًا أَوْ كَانَ عَلَمًا أَرْبَعَ أَصَابِعَ فَمَا دُونَ، أَوْ رِقَاعًا أَوْ لَبِنَةَ جَيْبٍ وَسُجُفَ فِرَاءٍ."]]},{"id":"za15_15","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٥","segs":[["matn","وَيُكْرَهُ الْمُعَصْفَرُ وَالْمُزَعْفَرُ لِلرِّجَالِ، وَمِنْهَا اجْتِنَابُ النَّجَاسَاتِ، فَمَنْ حَمَلَ نَجَاسَةً لَا يُعْفَى عَنْهَا، أَوْ لَاقَاهَا بِثَوْبِهِ أَوْ بَدَنِهِ لَمْ تَصِحَّ صَلَاتُهُ، وَإِنْ طَيَّنَ أَرْضًا نَجِسَةً أَوْ فَرَشَهَا طَاهِرًا كُرِهَ وَصَحَّتْ،"]]},{"id":"za15_16","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٦","segs":[["matn","وَإِنْ كَانَتْ بِطَرَفِ مُصَلَّى مُتَّصِلٍ صَحَّتْ إِنْ لَمْ يَنْجَرَّ بِمَشْيِهِ، وَمَنْ رَأَى عَلَيْهِ نَجَاسَةً بَعْدَ صَلَاتِهِ وَجَهِلَ كَوْنَهَا فِيهَا لَمْ يُعِدْ، وَإِنْ عَلِمَ أَنَّهَا كَانَتْ فِيهَا لَكِنْ نَسِيَهَا أَوْ جَهِلَهَا أَعَادَ،"]]},{"id":"za15_17","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٧","segs":[["matn","وَمَنْ جُبِرَ عَظْمُهُ بِنَجِسٍ لَمْ يَجِبْ قَلْعُهُ مَعَ الضَّرَرِ وَمَا سَقَطَ مِنْهُ مِنْ عُضْوٍ أَوْ سِنٍّ فَطَاهِرٌ، وَلَا تَصِحُّ الصَّلَاةُ فِي مَقْبَرَةٍ وَحُشٍّ وَحَمَّامٍ وَأَعْطَانِ إِبِلٍ وَمَغْصُوبٍ وَأَسْطِحَتِهَا وَتَصِحُّ إِلَيْهَا،"]]},{"id":"za15_18","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٨","segs":[["matn","وَلَا تَصِحُّ الْفَرِيضَةُ فِي الْكَعْبَةِ وَلَا فَوْقَهَا، وَتَصِحُّ النَّافِلَةُ بِاسْتِقْبَالِ شَاخِصٍ مِنْهَا."]]},{"id":"za15_19","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٩","segs":[["matn","وَمِنْهَا اسْتِقْبَالُ الْقِبْلَةِ، فَلَا تَصِحُّ بِدُونِهِ إِلَّا لِعَاجِزٍ وَمُتَنَفِّلٍ رَاكِبٍ سَائِرٍ فِي سَفَرٍ، وَيَلْزَمُهُ افْتِتَاحُ الصَّلَاةِ إِلَيْهَا، وَمَاشٍ وَيَلْزَمُهُ الِافْتِتَاحُ وَالرُّكُوعُ وَالسُّجُودُ إِلَيْهَا، وَفَرْضُ مَنْ قَرُبَ مِنَ الْقِبْلَةِ إِصَابَةُ عَيْنِهَا،"]]},{"id":"za15_20","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٢٠","segs":[["matn","وَمَنْ بَعُدَ جِهَتِهَا فَإِنْ أَخْبَرَهُ ثِقَةٌ بِيَقِينٍ أَوْ وَجَدَ مَحَارِيبَ إِسْلَامِيَّةً عَمِلَ بِهَا، وَيُسْتَدَلُّ عَلَيْهَا فِي السَّفَرِ بِالْقُطْبِ وَالشَّمْسِ وَالْقَمَرِ وَمَنَازِلِهِمَا، وَإِنْ اجْتَهَدَ مُجْتَهِدَانِ فَاخْتَلَفَا جِهَةً لَمْ يَتْبَعْ أَحَدُهُمَا الْآخَرَ، وَيَتْبَعُ الْمُقَلِّدُ أَوْثَقَهُمَا عِنْدَهُ،"]]},{"id":"za15_21","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٢١","segs":[["matn","وَمَنْ صَلَّى بِغَيْرِ اجْتِهَادٍ وَلَا تَقْلِيدٍ قَضَى إِنْ وَجَدَ مَنْ يُقَلِّدُهُ، وَيَجْتَهِدُ الْعَارِفُ بِأَدِلَّةِ الْقِبْلَةِ لِكُلِّ صَلَاةٍ، وَيُصَلِّي بِالثَّانِي، وَلَا يَقْضِي مَا صَلَّى بِالْأَوَّلِ، وَمِنْهَا النِّيَّةُ فَيَجِبُ أَنْ يَنْوِيَ عَيْنَ صَلَاةٍ مُعَيَّنَةٍ،"]]},{"id":"za15_22","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٢٢","segs":[["matn","وَلَا يُشْتَرَطُ فِي الْفَرْضِ وَالْأَدَاءِ وَالْقَضَاءِ وَالنَّفْلِ وَالْإِعَادَةِ نِيَّتُهُنَّ، وَيَنْوِي مَعَ التَّحْرِيمَةِ، وَلَهُ تَقْدِيمُهَا عَلَيْهَا بِزَمَنٍ يَسِيرٍ فِي الْوَقْتِ، فَإِنْ قَطَعَهَا فِي أَثْنَاءِ الصَّلَاةِ أَوْ تَرَدَّدَ بَطَلَتْ،"]]},{"id":"za15_23","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٢٣","segs":[["matn","وَإِنْ قَلَبَ مُنْفَرِدٌ فَرْضَهُ نَفْلًا فِي وَقْتِهِ الْمُتَّسِعِ جَازَ، وَإِنِ انْتَقَلَ بِنِيَّةٍ مِنْ فَرْضٍ إِلَى فَرْضٍ بَطَلَا، وَيَجِبُ نِيَّةُ الْإِمَامَةِ وَالِائْتِمَامِ، وَإِنْ نَوَى الْمُنْفَرِدُ الِائْتِمَامَ لَمْ يَصِحَّ كَنِيَّةُ إِمَامَتِهِ فَرْضًا،"]]},{"id":"za15_24","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٢٤","segs":[["matn","وَإِنْ انْفَرَدَ مُؤْتَمٌّ بِلَا عُذْرٍ بَطَلَتْ، وَتَبْطُلُ صَلَاةُ مَأْمُومٍ بِبُطْلَانِ صَلَاةِ إِمَامِهِ فَلَا اسْتِخْلَافٍ، وَإِنْ أَحْرَمَ إِمَامُ الْحَيِّ بِمَنْ أَحْرَمَ بِهِمْ نَائِبُهُ وَعَادَ النَّائِبُ مُؤْتَمًّا صَحَّ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za16","title":"بَابُ صِفَةِ الصَّلَاةِ","units":[{"id":"za16_1","label":"بَابُ صِفَةِ الصَّلَاةِ · ١","segs":[["matn","يُسَنُّ الْقِيَامُ عِنْدَ «قَدْ» مِنْ إِقَامَتِهَا وَتَسْوِيَةُ الصَّفِّ، وَيَقُولُ «اللَّهُ أَكْبَرُ» رَافِعًا يَدَيْهِ مَضْمُومَةَ الْأَصَابِعِ مَمْدُودَةً حَذْوَ مَنْكِبَيْهِ كَالسُّجُودِ، وَيُسْمِعُ الْإِمَامُ مَنْ خَلْفَهُ كَقِرَاءَتِهِ فِي أَوَّلَتَيْ غَيْرِ الظُّهْرَيْنِ، وَغَيْرُهُ نَفْسَهُ،"]]},{"id":"za16_2","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢","segs":[["matn","ثُمَّ يَقْبِضُ كُوعَ يُسْرَاهُ تَحْتَ سُرَّتِهِ وَيَنْظُرُ مَسْجِدَهُ ثُمَّ يَقُولُ: «سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ» ثُمَّ يَسْتَعِيذُ ثُمَّ يُبَسْمِلُ سِرًّا وَلَيْسَتْ مِنَ الْفَاتِحَةِ، ثُمَّ يَقْرَأُ الْفَاتِحَةَ،"]]},{"id":"za16_3","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣","segs":[["matn","فَإِنْ قَطَعَهَا بِذِكْرٍ أَوْ سُكُوتٍ غَيْرِ مَشْرُوعَيْنِ وَطَالَ أَوْ تَرَكَ مِنْهَا تَشْدِيدَةً أَوْ حَرْفًا أَوْ تَرْتِيبًا لَزِمَ غَيْرَ مَأْمُومٍ إِعَادَتَهَا،"]]},{"id":"za16_4","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤","segs":[["matn","وَيَجْهَرُ الْكُلُّ بِآمِينَ فِي الْجَهْرِيَّةِ ثُمَّ يَقْرَأُ بَعْدَهَا سُورَةً تَكُونُ فِي الصُّبْحِ مِنْ طِوَالِ الْمُفَصَّلِ ق وَفِي الْمَغْرِبِ مِنْ قِصَارِهِ وَفِي الْبَاقِي مِنْ أَوْسَاطِهِ، وَلَا تَصِحُّ الصَّلَاةُ بِقِرَاءَةٍ خَارِجَةٍ عَنْ مُصْحَفِ عُثْمَانَ،"]]},{"id":"za16_5","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥","segs":[["matn","ثُمَّ يَرْكَعُ مُكَبِّرًا رَافِعًا يَدَيْهِ وَيَضَعُهُمَا عَلَى رُكْبَتَيْهِ مُفَرَّجَتَيْ الْأَصَابِعِ مُسْتَوِيًا ظَهْرُهُ وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْعَظِيمِ» ثُمَّ يَرْفَعُ رَأْسَهُ وَيَدَيْهِ قَائِلًا إِمَامٌ وَمُنْفَرِدٌ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَبَعْدَ قِيَامِهِمَا «رَبَّنَا وَلَكَ الْحَمْدُ،»"]]},{"id":"za16_6","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦","segs":[["matn","«مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ» وَمَأْمُومٌ فِي رَفْعِهِ «رَبَّنَا وَلَكَ الْحَمْدُ» فَقَطْ، ثُمَّ يَخِرُّ مُكَبِّرًا سَاجِدًا عَلَى سَبْعَةِ أَعْضَاءٍ؛"]]},{"id":"za16_7","label":"بَابُ صِفَةِ الصَّلَاةِ · ٧","segs":[["matn","رِجْلَيْهِ ثُمَّ رُكْبَتَيْهِ ثُمَّ يَدَيْهِ ثُمَّ جَبْهَتِهِ مَعَ أَنْفِهِ وَلَوْ مَعَ حَائِلٍ لَيْسَ مِنْ أَعْضَاءِ سُجُودِهِ، وَيُجَافِي عَضُدَيْهِ عَنْ جَنْبَيْهِ وَبَطْنَهُ عَنْ فَخِذَيْهِ،"]]},{"id":"za16_8","label":"بَابُ صِفَةِ الصَّلَاةِ · ٨","segs":[["matn","وَيُفَرِّقُ رُكْبَتَيْهِ وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْأَعْلَى» ثُمَّ يَرْفَعُ رَأْسَهُ مُكَبِّرًا وَيَجْلِسُ مُفْتَرِشًا يُسْرَاهُ نَاصِبًا يُمْنَاهُ وَيَقُولُ: «رَبِّ اغْفِرْ لِي» وَيَسْجُدُ الثَّانِيَةَ كَالْأُولَى، ثُمَّ يَرْفَعُ مُكَبِّرًا نَاهِضًا عَلَى صُدُورِ قَدَمَيْهِ مُعْتَمِدًا عَلَى رُكْبَتَيْهِ إِنْ سَهُلَ،"]]},{"id":"za16_9","label":"بَابُ صِفَةِ الصَّلَاةِ · ٩","segs":[["matn","وَيُصَلِّي الثَّانِيَةَ كَذَلِكَ مَا عَدَا التَّحْرِيمَةَ وَالِاسْتِفْتَاحَ وَالتَّعَوُّذَ وَتَجْدِيدَ النِّيَّةِ، ثُمَّ يَجْلِسُ مُفْتَرِشًا وَيَدَاهُ عَلَى فَخِذَيْهِ يَقْبِضُ خِنْصَرَ الْيُمْنَى وَبِنْصَرَهَا وَيُحَلِّقُ إِبْهَامَهَا مَعَ الْوُسْطَى وَيُشِيرُ بِسَبَّابَتِهَا فِي تَشَهُّدِهِ وَيَبْسُطُ الْيُسْرَى وَيَقُولُ «التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ،»"]]},{"id":"za16_10","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٠","segs":[["matn","«السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ» هَذَا التَّشَهُّدُ الْأَوَّلُ."]]},{"id":"za16_11","label":"بَابُ صِفَةِ الصَّلَاةِ · ١١","segs":[["matn","ثُمَّ يَقُولُ «اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ،»"]]},{"id":"za16_12","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٢","segs":[["matn","«وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ» وَيَسْتَعِيذُ مِنْ عَذَابِ جَهَنَّمَ وَعَذَابِ الْقَبْرِ وَفِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَفِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَيَدْعُوَ بِمَا وَرَدَ،"]]},{"id":"za16_13","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٣","segs":[["matn","ثُمَّ يُسَلِّمُ عَنْ يَمِينِهِ «السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ» وَعَنْ يَسَارِهِ كَذَلِكَ، وَإِنْ كَانَ فِي ثُلَاثِيَّةٍ أَوْ رُبَاعِيَّةٍ نَهَضَ مُكَبِّرًا بَعْدَ التَّشَهُّدِ الْأَوَّلِ وَصَلَّى مَا بَقِيَ كَالثَّانِيَةِ بِالْحَمْدِ فَقَطْ ثُمَّ يَجْلِسُ فِي تَشَهُّدِهِ الْأَخِيرِ مُتَوَرِّكًا."]]},{"id":"za16_14","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٤","segs":[["matn","وَالْمَرْأَةُ مِثْلُهُ لَكِنْ تَضُمُّ نَفْسَهَا وَتُسْدِلُ رِجْلَيْهَا فِي جَانِبِ يَمِينِهَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za17","title":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ","units":[{"id":"za17_1","label":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ · ١","segs":[["matn","وَيُكْرَهُ فِي الصَّلَاةِ الْتِفَاتُهُ وَرَفْعُ بَصَرِهِ إِلَى السَّمَاءِ وَتَغْمِيضُ عَيْنَيْهِ وَإِقْعَاؤُهْ وَافْتِرَاشُ ذِرَاعَيْهِ سَاجِدًا وَعَبَثُهُ وَتَخَصُّرُهُ وَتَرَوُّحُهُ وَفَرْقَعَةُ أَصَابِعِهِ وَتَشْبِيكُهَا، وَأَنْ يَكُونَ حَاقِنًا أَوْ بِحَضْرَةِ طَعَامٍ يَشْتَهِيهِ، وَتَكْرَارُ الْفَاتِحَةِ لَا جَمْعُ سُوَرٍ فِي فَرْضٍ كَنَفْلٍ،"]]},{"id":"za17_2","label":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ · ٢","segs":[["matn","وَلَهُ رَدُّ الْمَارِّ بَيْنَ يَدَيْهِ وَعَدُّ الْآيِ وَالْفَتْحُ عَلَى إِمَامِهِ، وَلُبْسُ الثَّوْبِ وَالْعِمَامَةِ وَقَتْلُ حَيَّةٍ وَعَقْرَبٍ وَقَمْلٍ، فَإِنْ أَطَالَ الْفِعْلَ عُرْفًا مِنْ غَيْرِ ضَرُورَةٍ وَلَا تَفْرِيقٍ بَطَلَتْ وَلَوْ سَهْوًا وَيُبَاحُ قِرَاءَةُ أَوَاخِرِ السُّوَرِ وَأَوْسَاطُهُا،"]]},{"id":"za17_3","label":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ · ٣","segs":[["matn","وَإِذَا نَابَهُ شَيْءٌ سَبَّحَ رَجُلٌ وَصَفَّقَتْ امْرَأَةٌ بِبَطْنِ كَفِّهَا عَلَى ظَهْرِ الْأُخْرَى، وَيَبْصُقُ فِي الصَّلَاةِ عَنْ يَسَارِهِ وَفِي الْمَسْجِدِ فِي ثَوْبِهِ، وَتُسَنُّ صَلَاتُهُ إِلَى سُتْرَةٍ قَائِمَةٍ كَآخِرَةِ الرَّحْلِ، فَإِنْ لَمْ يَجِدْ شَاخِصًا فَإِلَى خَطٍّ،"]]},{"id":"za17_4","label":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ · ٤","segs":[["matn","وَتَبْطُلُ بِمُرُورِ كَلْبٍ أَسْوَدَ بَهِيمٍ فَقَطْ، وَلَهُ التَّعَوُّذُ عِنْدَ آيَةِ وَعِيدٍ، وَالسُّؤَالُ عِنْدَ آيَةِ رَحْمَةٍ وَلَوْ فِي فَرْضٍ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za18","title":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ (٢)","units":[{"id":"za18_1","label":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ (٢) · ١","segs":[["matn","أَرْكَانُهَا: الْقِيَامُ وَالتَّحْرِيمَةُ وَالْفَاتِحَةُ وَالرُّكُوعُ وَالِاعْتِدَالُ عَنْهُ وَالسُّجُودُ عَلَى الْأَعْضَاءِ السَّبْعَةِ وَالِاعْتِدَالُ عَنْهُ، وَالْجُلُوسُ بَيْنَ السَّجْدَتَيْنِ وَالطُّمَأْنِينَةُ فِي الْكُلِّ وَالتَّشَهُّدُ الْأَخِيرُ وَجَلْسَتُهُ، وَالصَّلَاةُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ، وَالتَّرْتِيبُ وَالتَّسْلِيمُ."]]},{"id":"za18_2","label":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَوَاجِبَاتُهَا التَّكْبِيرُ غَيْرُ التَّحْرِيمَةِ وَالتَّسْمِيعُ وَالتَّحْمِيدُ وَتَسْبِيحَتَا الرُّكُوعِ وَالسُّجُودِ، وَسُؤَالُ الْمَغْفِرَةِ مَرَّةً مَرَّةً، وَيُسَنُّ ثَلَاثًا، وَالتَّشَهُّدُ الْأَوَّلُ وَجَلْسَتُهُ، وَمَا عَدَا الشَّرَائِطَ وَالْأَرْكَانَ وَالْوَاجِبَاتِ الْمَذْكُورَةَ سُنَّةٌ، فَمَنْ تَرَكَ شَرْطًا لِغَيْرِ عُذْرٍ غَيْرَ النِّيَّةِ،"]]},{"id":"za18_3","label":"بَابُ صِفَةِ الصَّلَاةِ · فَصْلٌ (٢) · ٣","segs":[["matn","فَإِنَّهَا لَا تَسْقُطُ بِحَالٍ أَوْ تَعَمَّدَ تَرْكَ رُكْنٍ أَوْ وَاجِبٍ بَطَلَتْ صَلَاتُهُ، بِخِلَافِ الْبَاقِي وَمَا عَدَا ذَلِكَ سُنَنُ أَقْوَالٍ وَأَفْعَالٍ، وَلَا يُشْرَعُ السُّجُودُ لِتَرْكِهِ، وَإِنْ سَجَدَ فَلَا بَأْسَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za19","title":"بَابُ سُجُودِ السَّهْوِ","units":[{"id":"za19_1","label":"بَابُ سُجُودِ السَّهْوِ · ١","segs":[["matn","يُشْرَعُ لِزِيَادَةٍ وَنَقْصٍ وَشَكٍّ، لَا فِي عَمْدٍ فِي الْفَرْضِ وَالنَّافِلَةِ، فَمَتَى زَادَ فِعْلًا مِنْ جِنْسِ الصَّلَاةِ؛ قِيَامًا أَوْ قُعُودًا أَوْ رُكُوعًا أَوْ سُجُودًا عَمْدًا بَطَلَتْ، وَسَهْوًا يَسْجُدُ لَهُ،"]]},{"id":"za19_2","label":"بَابُ سُجُودِ السَّهْوِ · ٢","segs":[["matn","وَإِنْ زَادَ رَكْعَةً فَلَمْ يَعْلَمْ حَتَّى فَرَغَ مِنْهَا سَجَدَ، وَإِنْ عَلِمَ فِيهَا جَلَسَ فِي الْحَالِ فَيَتَشَهَّدَ إِنْ لَمْ يَكُنْ تَشَهَّدَ وَسَجَدَ وَسَلَّمَ،"]]},{"id":"za19_3","label":"بَابُ سُجُودِ السَّهْوِ · ٣","segs":[["matn","وَإِنْ سَبَّحَ بِهِ ثِقَتَانِ فَأَصَرَّ وَلَمْ يَجْزِمْ بِصَوَابِ نَفْسِهِ بَطَلَتْ صَلَاتُهُ وَصَلَاةُ مَنْ تَبِعَهُ عَالِمًا، لَا جَاهِلًا أَوْ نَاسِيًا وَلَا مَنْ فَارَقَهُ، وَعَمَلٌ مُسْتَكْثَرٌ عَادَةً مِنْ غَيْرِ جِنْسِ الصَّلَاةِ يُبْطِلُهَا عَمْدُهُ وَسَهْوُهُ،"]]},{"id":"za19_4","label":"بَابُ سُجُودِ السَّهْوِ · ٤","segs":[["matn","وَلَا يُشْرَعُ لِيَسِيرِهِ سُجُودٌ، وَلَا تَبْطُلُ بِيَسِيرِ أَكْلٍ وَشُرْبٍ سَهْوًا، وَلَا نَفْلٌ بِيَسِيرِ شُرْبٍ عَمْدًا،"]]},{"id":"za19_5","label":"بَابُ سُجُودِ السَّهْوِ · ٥","segs":[["matn","وَإِنْ أَتَى بِقَوْلٍ مَشْرُوعٍ فِي غَيْرِ مَوْضِعِهِ كَقِرَاءَةٍ فِي سُجُودٍ وَقُعُودٍ وَتَشَهُّدٍ فِي قِيَامٍ وَقِرَاءَةِ سُورَةٍ فِي الْأَخِيرَتَيْنِ لَمْ تَبْطُلْ وَلَمْ يَجِبْ لَهُ سُجُودٌ، بَلْ يُشْرَعُ، وَإِنْ سَلَّمَ قَبْلَ إِتْمَامِهَا عَمْدًا بَطَلَتْ،"]]},{"id":"za19_6","label":"بَابُ سُجُودِ السَّهْوِ · ٦","segs":[["matn","وَإِنْ كَانَ سَهْوًا ثُمَّ ذَكَرَ قَرِيبًا أَتَّمَّهَا وَسَجَدَ، فَإِنْ طَالَ الْفَصْلُ أَوْ تَكَلَّمَ لِغَيْرِ مَصْلَحَتِهَا بَطَلَتْ كَكَلَامِهِ فِي صُلْبِهَا، وَلِمَصْلَحَتِهَا إِنْ كَانَ يَسِيرًا لَمْ تَبْطُلْ، وَقَهْقَهَةٌ كَكَلَامٍ،"]]},{"id":"za19_7","label":"بَابُ سُجُودِ السَّهْوِ · ٧","segs":[["matn","وَإِنْ نَفَخَ أَوْ انْتَحَبَ مِنْ غَيْرِ خَشْيَةِ اللَّهِ تَعَالَى أَوْ تَنَحْنَحَ مِنْ غَيْرِ حَاجَةٍ فَبَانَ حَرْفَانِ بَطَلَتْ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za20","title":"بَابُ سُجُودِ السَّهْوِ · فَصْلٌ","units":[{"id":"za20_1","label":"بَابُ سُجُودِ السَّهْوِ · فَصْلٌ · ١","segs":[["matn","وَمَنْ تَرَكَ رُكْنًا فَذَكَرَهُ بَعْدَ شُرُوعِهِ فِي قِرَاءَةِ رَكْعَةٍ أُخْرَى بَطَلَتِ الَّتِي تَرَكَهُ مِنْهَا، وَقَبْلَهُ يَعُودُ وُجُوبًا فَيَأْتِي بِهِ وَبِمَا بَعْدَهُ، وَإِنْ عَلِمَ بَعْدَ السَّلَامِ فَكَتَرْكِ رَكْعَةٍ كَامِلَةٍ،"]]},{"id":"za20_2","label":"بَابُ سُجُودِ السَّهْوِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ نَسِيَ التَّشَهُّدَ الْأَوَّلَ وَنَهَضَ لَزِمَهُ الرُّجُوعُ مَا لَمْ يَنْتَصِبْ قَائِمًا، فَإِنْ اسْتَتَمَّ قَائِمًا كُرِهَ رُجُوعُهُ، وَإِنْ لَمْ يَنْتَصِبْ لَزِمَهُ الرُّجُوعُ، وَإِنْ شَرَعَ فِي الْقِرَاءَةِ حَرُمَ الرُّجُوعُ وَعَلَيْهِ السُّجُودُ لِلْكُلِّ،"]]},{"id":"za20_3","label":"بَابُ سُجُودِ السَّهْوِ · فَصْلٌ · ٣","segs":[["matn","وَمَنْ شَكَّ فِي عَدَدِ الرَّكَعَاتِ أَخَذَ بِالْأَقَلِّ، وَإِنْ شَكَّ فِي تَرْكِ رُكْنٍ فَكَتَرْكِهِ، وَلَا يَسْجُدُ لِشَكِّهِ فِي تَرْكِ وَاجِبٍ أَوْ زِيَادَةٍ، وَلَا سُجُودَ عَلَى مَأْمُومٍ إِلَّا تَبَعًا لِإِمَامِهِ، وَسُجُودُ السَّهْوِ لِمَا يُبْطِلُ عَمْدُهُ وَاجِبٌ."]]},{"id":"za20_4","label":"بَابُ سُجُودِ السَّهْوِ · فَصْلٌ · ٤","segs":[["matn","وَتَبْطُلُ بِتَرْكِ سُجُودٍ أَفْضَلِيَّتُهُ قَبْلَ السَّلَامِ فَقَطْ، وَإِنْ نَسِيَهُ وَسَلَّمَ سَجَدَ إِنْ قَرُبَ زَمَنُهُ، وَمَنْ سَهَا مِرَارًا كَفَاهُ سَجْدَتَانِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za21","title":"بَابُ صَلَاةِ التَّطَوُّعِ","units":[{"id":"za21_1","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١","segs":[["matn","آكَدُهَا كُسُوفٌ ثُمَّ اسْتِسْقَاءٌ ثُمَّ تَرَاوِيْحُ ثُمَّ وِتْرٌ يُفْعَلُ بَيْنَ الْعِشَاءِ وَالْفَجْرِ، وَأَقَلُّهُ رَكْعَةٌ وَأَكْثَرُهُ إِحْدَى عَشْرَةَ مَثْنَى مَثْنَى، وَيُوتِرُ بِوَاحِدَةٍ، وَإِنْ أَوْتَرَ بِخَمْسٍ أَوْ سَبْعٍ لَمْ يَجْلِسْ إِلَّا فِي آخِرِهَا،"]]},{"id":"za21_2","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٢","segs":[["matn","وَبِتِسْعٍ يَجْلِسُ عَقِبَ الثَّامِنَةِ وَيَتَشَهَّدُ وَلَا يُسَلِّمُ ثُمَّ يُصَلِّي التَّاسِعَةَ وَيَتَشَهَّدُ وَيُسَلِّمُ، وَأَدْنَى الْكَمَالِ ثَلَاثُ رَكَعَاتٍ بِسَلَامَيْنِ يَقْرَأُ فِي الْأُولَى بِسَبِّحْ وَفِي الثَّانِيَةِ بِالْكَافِرُونَ وَفِي الثَّالِثَةِ الْإِخْلَاصِ،"]]},{"id":"za21_3","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٣","segs":[["matn","وَيَقْنُتُ فِيهَا بَعْدَ الرُّكُوعِ وَيَقُولُ: «اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيْمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ،»"]]},{"id":"za21_4","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٤","segs":[["matn","«إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.»"]]},{"id":"za21_5","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٥","segs":[["matn","«اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِعَفْوِكَ مِنْ عُقُوبَتِكَ، وَبِكَ مِنْكَ، لَا نُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ، اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، وَيَمْسَحُ وَجْهَهُ بِيَدَيْهِ،»"]]},{"id":"za21_6","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٦","segs":[["matn","«وَيُكْرَهُ قُنُوتُهُ فِي غَيْرِ الْوِتْرِ إِلَّا أَنْ تَنْزِلَ بِالْمُسْلِمِينَ نَازِلَةٌ غَيْرَ الطَّاعُونَ فَيَقْنُتُ الْإِمَامُ فِي الْفَرَائِضِ.»"]]},{"id":"za21_7","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٧","segs":[["matn","«» وَالتَّرَاوِيحُ عِشْرُونَ رَكْعَةً تُفْعَلُ فِي جَمَاعَةٍ مَعَ الْوِتْرِ بَعْدَ الْعِشَاءِ فِي رَمَضَانَ وَيُوتِرُ الْمُتَهَجِّدُ بَعْدَهُ فَإِنْ تَبِعَ إِمَامَهُ شَفَعَهُ بِرَكْعَةٍ، وَيُكْرَهُ التَّنَفُّلُ بَيْنَهَا لَا التَّعْقِيبُ بَعْدَهَا فِي جَمَاعَةٍ."]]},{"id":"za21_8","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٨","segs":[["matn","ثُمَّ السُّنَنُ الرَّاتِبَةُ رَكْعَتَانِ قَبْلَ الظُّهْرِ وَرَكْعَتَانِ بَعْدَهَا وَرَكْعَتَانِ بَعْدَ الْمَغْرِبِ وَرَكْعَتَانِ بَعْدَ الْعِشَاءِ وَرَكْعَتَانِ قَبْلَ الْفَجْرِ وَهُمَا آكَدُهَا، وَمَنْ فَاتَهُ شَيْءٌ مِنْهَا سُنَّ لَهُ قَضَاؤُهُ."]]},{"id":"za21_9","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٩","segs":[["matn","وَصَلَاةُ اللَّيْلِ أَفْضَلُ مِنْ صَلَاةِ النَّهَارِ وَأَفْضَلُهَا ثُلُثُ اللَّيْلِ بَعْدَ نِصْفِهِ، وَصَلَاةُ لَيْلٍ وَنَهَارٍ مَثْنَى مَثْنَى وَإِنْ تَطَوَّعَ فِي النَّهَارِ بِأَرْبَعٍ كَالظُّهْرِ فَلَا بَأْسَ، وَأَجْرُ صَلَاةِ قَاعِدٍ عَلَى نِصْفِ أَجْرِ صَلَاةِ قَائِمٍ."]]},{"id":"za21_10","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٠","segs":[["matn","وَتُسَنُّ صَلَاةُ الضُّحَى وَأَقَلُّهَا رَكْعَتَانِ وَأَكْثَرُهَا ثَمَانٌ، وَوَقْتُهَا مِنْ خُرُوجِ وَقْتِ النَّهْيِ إِلَى قُبَيْلِ الزَّوَالِ."]]},{"id":"za21_11","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١١","segs":[["matn","وَسُجُودُ التِّلَاوَةِ صَلَاةٌ وَيُسَنُّ لِلْقَارِئِ وَالْمُسْتَمِعِ دُونَ السَّامِعِ، وَإِنْ لَمْ يَسْجُدِ الْقَارِئُ لَمْ يَسْجُدْ، وَهُوَ أَرْبَعَ عَشْرَةَ سَجْدَةً فِي الْحَجِّ مِنْهَا اثْنَتَانِ، وَيُكَبِّرُ إِذَا سَجَدَ وَإِذَا رَفَعَ وَيَجْلِسُ وَيُسَلِّمُ وَلَا يَتَشَهَّدُ،"]]},{"id":"za21_12","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٢","segs":[["matn","وَيُكْرَهُ لِلْإِمَامِ قِرَاءَةُ سَجْدَةٍ فِي صَلَاةِ سِرٍّ وَسُجُودُهُ فِيهَا، وَيَلْزَمُ الْمَأْمُومَ مُتَابَعَتُهُ فِي غَيْرِهَا، وَيُسْتَحَبُّ سُجُودُ الشُّكْرِ عِنْدَ تَجَدُّدِ النِّعَمِ وَانْدِفَاعِ النِّقَمِ، وَتَبْطُلُ بِهِ صَلَاةُ غَيْرِ جَاهِلٍ وَنَاسٍ،"]]},{"id":"za21_13","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٣","segs":[["matn","وَأَوْقَاتُ النَّهْيِ خَمْسَةٌ مِنْ طُلُوعِ الْفَجْرِ الثَّانِي إِلَى طُلُوعِ الشَّمْسِ، وَمِنْ طُلُوعِهَا حَتَّى تَرْتَفِعَ قِيدَ رُمْحٍ، وَعِنْدَ قِيَامِهَا حَتَّى تَزُولَ، وَمِنْ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِهَا، وَإِذَا شَرَعَتْ فِيهِ حَتَّى يَتِمَّ،"]]},{"id":"za21_14","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٤","segs":[["matn","وَيَجُوزُ قَضَاءُ الْفَرَائِضِ فِيهَا وَفِي الْأَوْقَاتِ الثَّلَاثَةِ فِعْلُ رَكْعَتَيْ الطَّوَافِ، وَإِعَادَةُ جَمَاعَةٍ، وَيَحْرُمُ تَطَوُّعٌ بِغَيْرِهَا فِي شَيْءٍ مِنَ الْأَوْقَاتِ الْخَمْسَةِ حَتَّى مَا لَهُ سَبَبٌ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za22","title":"بَابُ صَلَاةِ الْجَمَاعَةِ","units":[{"id":"za22_1","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١","segs":[["matn","تَلْزَمُ الرِّجَالَ لِلصَّلَوَاتِ الْخَمْسِ لَا شَرْطٌ، وَلَهُ فِعْلُهَا فِي بَيْتِهِ، وَتُسْتَحَبُّ صَلَاةُ أَهْلِ الثَّغْرِ فِي مَسْجِدٍ وَاحِدٍ، وَالْأَفْضَلُ لِغَيْرِهِمْ فِي الْمَسْجِدِ الَّذِي لَا تُقَامُ فِيهِ الْجَمَاعَةُ إِلَّا بِحُضُورِهِ ثُمَّ مَا كَانَ أَكْثَرَ جَمَاعَةً،"]]},{"id":"za22_2","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٢","segs":[["matn","ثُمَّ الْمَسْجِدُ الْعَتِيْقُ، وَأَبْعَدُ أَوْلَى مِنْ أَقْرَبَ، وَيَحْرُمُ أَنْ يَؤُمَّ فِي مَسْجِدٍ قَبْلَ إِمَامِهِ الرَّاتِبِ إِلَّا بِإِذْنِهِ أَوْ عُذْرِهِ، وَمَنْ صَلَّى ثُمَّ أُقِيمَ فَرْضٌ سُنَّ أَنْ يُعِيدَهَا إِلَّا الْمَغْرِبَ،"]]},{"id":"za22_3","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٣","segs":[["matn","وَلَا تُكْرَهُ إِعَادَةُ جَمَاعَةٍ فِي غَيْرِ مَسْجِدَيْ مَكَّةَ وَالْمَدِينَةِ."]]},{"id":"za22_4","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٤","segs":[["matn","وَإِذَا أُقِيمَتِ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةَ، فَإِنْ كَانَ فِي نَافِلَةٍ أَتَمَّهَا إِلَّا أَنْ يَخْشَى فَوَاتَ الْجَمَاعَةِ فَيَقْطَعَهَا، وَمَنْ كَبَّرَ قَبْلَ سَلَامِ إِمَامِهِ لَحِقَ الْجَمَاعَةَ، وَإِنْ لَحِقَهُ رَاكِعًا دَخَلَ مَعَهُ فِي الرَّكْعَةِ وَأَجْزَأَتْهُ التَّحْرِيمَةُ."]]},{"id":"za22_5","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٥","segs":[["matn","وَلَا قِرَاءَةَ عَلَى مَأْمُومٍ، وَيُسْتَحَبُّ فِي إِسْرَارِ إِمَامِهِ وَسُكُوتِهِ وَإِذَا لَمْ يَسْمَعْهُ لِبُعْدٍ لَا لِطَرَشٍ، وَيَسْتَفْتِحُ وَيَسْتَعِيذُ فِيمَا يَجْهَرُ فِيهِ إِمَامُهُ، وَمَنْ رَكَعَ أَوْ سَجَدَ قَبْلَ إِمَامِهِ فَعَلَيْهِ أَنْ يَرْفَعَ لِيَأْتِيَ بِهِ بَعْدَهُ،"]]},{"id":"za22_6","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٦","segs":[["matn","فَإِنْ لَمْ يَفْعَلْ عَمْدًا بَطَلَتْ، وَإِنْ رَكَعَ وَرَفَعَ قَبْلَ رُكُوعِ إِمَامِهِ عَالِمًا عَمْدًا بَطَلَتْ، وَإِنْ كَانَ جَاهِلًا أَوْ نَاسِيًا بَطَلَتِ الرَّكْعَةُ فَقَطْ، وَإِنْ رَكَعَ وَرَفَعَ قَبْلَ رُكُوعِهِ ثُمَّ سَجَدَ قَبْلَ رَفْعِهِ بَطَلَتْ إِلَّا الْجَاهِلُ وَالنَّاسِيَ،"]]},{"id":"za22_7","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٧","segs":[["matn","وَيُصَلِّي تِلْكَ الرَّكْعَةَ قَضَاءً، وَيُسَنُّ لِإِمَامٍ التَّخْفِيفُ مَعَ الْإِتْمَامِ وَتَطْوِيلُ الرَّكْعَةِ الْأُولَى أَكْثَرَ مِنَ الثَّانِيَةِ، وَيُسْتَحَبُّ انْتِظَارُ دَاخِلٍ مَا لَمْ يَشُقَّ عَلَى مَأْمُومٍ، وَإِذَا اسْتَأْذَنَتِ الْمَرْأَةُ إِلَى الْمَسْجِدِ كُرِهَ مَنْعُهَا، وَبَيْتُهَا خَيْرٌ لَهَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za23","title":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ","units":[{"id":"za23_1","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ · ١","segs":[["matn","الْأَوْلَى بِالْإِمَامَةِ الْأَقْرَأُ الْعَالِمُ فِقْهَ صَلَاتِهِ، ثُمَّ الْأَفْقَهُ، ثُمَّ الْأَسَنُّ، ثُمَّ الْأَشْرَفُ، ثُمَّ الْأَقْدَمُ هِجْرَةً، ثُمَّ الْأَتْقَى ثُمَّ مَنْ قَرَعَ، وَسَاكِنُ الْبَيْتِ وَإِمَامُ الْمَسْجِدِ أَحَقُّ إِلَّا مِنْ ذِي سُلْطَانٍ،"]]},{"id":"za23_2","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ · ٢","segs":[["matn","وَحُرٌّ وَحَاضِرٌ وَمُقِيمٌ وَبَصِيرٌ وَمَخْتُونٌ وَمَنْ لَهُ ثِيَابٌ أَوْلَى مِنْ ضِدِّهِمْ، وَلَا تَصِحُّ خَلْفَ فَاسِقٍ كَكَافِرٍ، وَلَا خَلْفَ امْرَأَةٍ، وَخُنْثَى لِلرِّجَالِ وَلَا صَبِيٍّ لِبَالِغٍ، وَأَخْرَسَ وَلَا عَاجِزٍ عَنْ رُكُوعٍ أَوْ سُجُودٍ أَوْ قُعُودٍ أَوْ قِيَامٍ،"]]},{"id":"za23_3","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ · ٣","segs":[["matn","إِلَّا إِمَامَ الْحَيِّ الْمَرْجُوَّ زَوَالُ عِلَّتِهِ، وَيُصَلُّونَ وَرَاءَهُ جُلُوسًا نَدْبًا فَإِنْ ابْتَدَأَ بِهِمْ قَائِمًا ثُمَّ اعْتَلَّ فَجَلَسَ أَتَمُّوا خَلْفَهُ قِيَامًا وُجُوبًا."]]},{"id":"za23_4","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ · ٤","segs":[["matn","وَتَصِحُّ خَلْفَ مَنْ بِهِ سَلَسُ البَّوْلِ بِمِثْلِهِ، وَلَا تَصِحُّ خَلْفَ مُحْدِثٍ وَلَا مُتَنَجِّسٍ يَعْلَمُ ذَلِكَ، فَإِنْ جَهِلَ هُوَ وَالْمَأْمُومُ حَتَّى انْقَضَتْ صَحَّتْ لِمَأْمُومٍ وَحْدَهُ، وَلَا إِمَامَةُ الْأُمِّيِّ وَهُوَ مَنْ لَا يُحْسِنُ الْفَاتِحَةَ،"]]},{"id":"za23_5","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ · ٥","segs":[["matn","أَوْ يُدْغِمُ فِيهَا مَا لَا يُدْغَمُ، أَوْ يُبَدِّلُ حَرْفًا أَوْ يَلْحَنُ فِيهَا لَحْنًا يُحِيلُ الْمَعْنَى، إِلَّا بِمِثْلِهِ، وَإِنْ قَدَرَ عَلَى إِصْلَاحِهِ لَمْ تَصِحَّ صَلَاتُهُ، وَتُكْرَهُ إِمَامَةُ اللَّحَّانِ وَالْفَأْفَاءِ وَالتَّمْتَامِ وَمَنْ لَا يُفْصِحُ بِبَعْضِ الْحُرُوفِ،"]]},{"id":"za23_6","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ · ٦","segs":[["matn","وَأَنْ يَؤُمَّ أَجْنَبِيَّةً فَأَكْثَرَ لَا رَجُلَ مَعَهُنَّ، أَوْ قَوْمًا أَكْثَرُهُمْ يَكْرَهُهُ بِحَقٍّ، وَتَصِحُّ إِمَامَةُ وَلَدِ الزِّنَا وَالْجُنْدِيِّ إِذَا سَلِمَ دِينُهُمَا، وَمَنْ يُؤَدِّي الصَّلَاةَ بِمَنْ يَقْضِيهَا، وَعَكْسُهُ لَا مُفْتَرِضٍ بِمُتَنَفِّلٍ،"]]},{"id":"za23_7","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ · ٧","segs":[["matn","وَلَا مَنْ يُصَلِّي الظُّهْرَ بِمَنْ يُصَلِّي الْعَصْرَ أَوْ غَيْرَهَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za24","title":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٢)","units":[{"id":"za24_1","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٢) · ١","segs":[["matn","يَقِفُ الْمَأْمُومُونَ خَلْفَ الْإِمَامِ، وَيَصِحُّ مَعَهُ عَنْ يَمِينِهِ أَوْ عَنْ جَانِبَيْهِ، لَا قُدَّامَهُ وَلَا عَنْ يَسَارِهِ فَقَطْ، وَلَا الْفَذُّ خَلْفَهُ أَوْ خَلْفَ الصَّفِّ إِلَّا أَنْ يَكُونَ امْرَأَةً، وَإِمَامَةُ النِّسَاءِ تَقِفُ فِي صَفِّهِنَّ،"]]},{"id":"za24_2","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَيَلِيهِ الرِّجَالُ ثُمَّ الصِّبْيَانُ ثُمَّ النِّسَاءُ كَجَنَائِزِهِمْ، وَمَنْ لَمْ يَقِفْ مَعَهُ إِلَّا كَافِرٌ أَوْ امْرَأَةٌ أَوْ مَنْ عَلِمَ حَدَثَهُ أَحَدُهُمَا أَوْ صَبِيٌّ فِي فَرْضٍ فَفَذٌّ."]]},{"id":"za24_3","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَمَنْ وَجَدَ فُرْجَةً دَخَلَهَا وَإِلَّا عَنْ يَمِينِ الْإِمَامِ، فَإِنْ لَمْ يُمْكِنْهُ فَلَهُ أَنْ يُنَبِّهَ مَنْ يَقُومُ مَعَهُ."]]},{"id":"za24_4","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٢) · ٤","segs":[["matn","فَإِنْ صَلَّى فَذًّا رَكْعَةٌ لَمْ تَصِحَّ، وَإِنْ رَكَعَ فَذًّا ثُمَّ دَخَلَ فِي الصَّفِّ أَوْ وَقَفَ مَعَهُ آخَرُ قَبْلَ سُجُودِ الْإِمَامِ صَحَّتْ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za25","title":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٣)","units":[{"id":"za25_1","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٣) · ١","segs":[["matn","يَصِحُّ اقْتِدَاءُ الْمَأْمُومِ بِالْإِمَامِ فِي الْمَسْجِدِ وَإِنْ لَمْ يَرَهُ وَلَا مَنْ وَرَاءَهُ إِذَا سَمِعَ التَّكْبِيرَ، وَكَذَا خَارِجَهُ إِنْ رَأَى الْإِمَامَ أَوْ الْمَأْمُومِينَ، وَتَصِحُّ خَلْفَ إِمَامٍ عَالٍ عَنْهُمْ وَيُكْرَهُ إِذَا كَانَ الْعُلُوُّ ذِرَاعًا فَأَكْثَرَ،"]]},{"id":"za25_2","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٣) · ٢","segs":[["matn","كَإِمَامَتِهِ فِي الطَّاقِ وَتَطَوُّعِهِ مَوْضِعَ الْمَكْتُوبَةِ إِلَّا مِنْ حَاجَةٍ، وَإِطَالَةُ قُعُودِهِ بَعْدَ الصَّلَاةِ مُسْتَقْبِلَ الْقِبْلَةِ، فَإِنْ كَانَ ثَمَّ نِسَاءٌ لَبِثَ قَلِيلًا لِيَنْصَرِفْنَ، وَيُكْرَهُ وُقُوفُهُمْ بَيْنَ السَّوَارِي إِذَا قَطَعْنَ الصُّفُوفَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za26","title":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٤)","units":[{"id":"za26_1","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٤) · ١","segs":[["matn","وَيُعْذَرُ بِتَرْكِ جُمُعَةٍ وَجَمَاعَةٍ مَرِيضٌ وَمُدَافِعٌ أَحَدَ الْأَخْبَثَيْنِ، وَمَنْ بِحَضْرَةِ طَعَامٍ مُحْتَاجٌ إِلَيْهِ، وَخَائِفٌ مِنْ ضَيَاعِ مَالِهِ أَوْ فَوَاتِهِ أَوْ ضَرَرٍ فِيهِ،"]]},{"id":"za26_2","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · فَصْلٌ (٤) · ٢","segs":[["matn","أَوْ مَوْتِ قَرِيبِهِ أَوْ عَلَى نَفْسِهِ مِنْ ضَرَرٍ أَوْ سُلْطَانٍ أَوْ مُلَازَمَةِ غَرِيمٍ وَلَا شَيْءَ مَعَهُ، أَوْ مِنْ فَوَاتِ رُفْقَةٍ، أَوْ غَلَبَةِ نُعَاسٍ، أَوْ أَذًى بِمَطَرٍ وَوَحْلٍ، وَبِرِيحٍ بَارِدَةٍ شَدِيدَةٍ فِي لَيْلَةٍ مُظْلِمَةٍ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za27","title":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ","units":[{"id":"za27_1","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١","segs":[["matn","تَلْزَمُ الْمَرِيضَ الصَّلَاةُ قَائِمًا، فَإِنْ لَمْ يَسْتَطِعْ فَقَاعِدًا، فَإِنْ عَجَزَ فَعَلَى جَنْبِهِ، فَإِنْ صَلَّى مُسْتَلْقِيًا، وَرِجْلَاهُ إِلَى الْقِبْلَةِ صَحَّ، وَيُومِئُ، رَاكِعًا وَسَاجِدًا وَيَخْفِضُهُ عَنْ الرُّكُوعِ، فَإِنْ عَجَزَ أَوْمَأَ بِعَيْنِهِ،"]]},{"id":"za27_2","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٢","segs":[["matn","فَإِنْ قَدَرَ أَوْ عَجَزَ فِي أَثْنَائِهَا انْتَقَلَ إِلَى الْآخَرِ، وَإِنْ قَدَرَ عَلَى قِيَامٍ وَقُعُودٍ دُونَ رُكُوعٍ وَسُجُودٍ أَوْمَأَ بِرُكُوعٍ قَائِمًا وَسُجُودٍ قَاعِدًا وَلِمَرِيضٍ الصَّلَاةُ مُسْتَلْقِيًا مَعَ الْقُدْرَةِ عَلَى الْقِيَامِ لِمُدَاوَاةٍ بِقَوْلِ طَبِيبٍ مُسْلِمٍ،"]]},{"id":"za27_3","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٣","segs":[["matn","وَلَا تَصِحُّ صَلَاتُهُ قَاعِدًا فِي السَّفِينَةِ وَهُوَ قَادِرٌ عَلَى الْقِيَامِ، وَيَصِحُّ الْفَرْضُ عَلَى الرَّاحِلَةِ خَشْيَةَ التَّأَذِّي بِالْوَحْلِ لَا لِلْمَرَضِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za28","title":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ","units":[{"id":"za28_1","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ · ١","segs":[["matn","مَنْ سَافَرَ سَفَرًا مُبَاحًا أَرْبَعَةَ بُرُدٍ سُنَّ لَهُ قَصْرُ رُبَاعِيَّةٍ رَكْعَتَيْنِ إِذَا فَارَقَ عَامِرَ قَرْيَتِهِ أَوْ خِيَامَ قَوْمِهِ، وَإِنْ أَحْرَمَ ثُمَّ سَافَرَ،"]]},{"id":"za28_2","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ · ٢","segs":[["matn","أَوْ سَفَرًا ثُمَّ أَقَامَ أَوْ ذَكَرَ صَلَاةَ حَضَرٍ فِي سَفَرٍ أَوْ عَكْسَهَا أَوْ ائْتَمَّ بِمُقِيْمٍ أَوْ بِمَنْ يَشُكُّ فِيهِ، أَوْ أَحْرَمَ بِصَلَاةٍ يَلْزَمُهُ إِتْمَامُهَا فَفَسَدَتْ وَأَعَادَهَا، أَوْ لَمْ يَنْوِ الْقَصْرَ عِنْدَ إِحْرَامِهَا،"]]},{"id":"za28_3","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ · ٣","segs":[["matn","أَوْ شَكَّ فِي نِيَّتِهِ، أَوْ نَوَى إِقَامَةَ أَكْثَرَ مِنْ أَرْبَعَةِ أَيَّامٍ، أَوْ مَلَّاحًا مَعَهُ أَهْلُهُ لَا يَنْوِي الْإِقَامَةَ بِبَلَدٍ لَزِمَهُ أَنْ يُتِمَّ."]]},{"id":"za28_4","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ · ٤","segs":[["matn","وَإِنْ كَانَ لَهُ طَرِيقَانِ فَسَلَكَ أَبْعَدَهُمَا، أَوْ ذَكَرَ صَلَاةَ سَفَرٍ فِي آخَرَ قَصَرَ، وَإِنْ حُبِسَ وَلَمْ يَنْوِ إِقَامَةً أَوْ أَقَامَ لِقَضَاءِ حَاجَةٍ بِلَا نِيَّةِ إِقَامَةٍ قَصَرَ أَبَدًا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za29","title":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ (٢)","units":[{"id":"za29_1","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ (٢) · ١","segs":[["matn","يَجُوزُ الْجَمْعُ بَيْنَ الظُّهْرَيْنِ وَبَيْنَ الْعِشَاءَيْنِ فِي وَقْتِ إِحْدَاهُمَا فِي سَفَرِ قَصْرٍ، وَلِمَرِيضٍ يَلْحَقُهُ بِتَرْكِهِ مَشَقَّةٌ، وَبَيْنَ الْعِشَاءَيْنِ لِمَطَرٍ يَبُلُّ الثِّيَابِ وَلِوَحَلٍ وَرِيحٍ شَدِيدَةٍ بَارِدَةٍ وَلَوْ صَلَّى فِي بَيْتِهِ أَوْ فِي مَسْجِدِ طَرِيقِهِ تَحْتَ سَابَاطٍ،"]]},{"id":"za29_2","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَالْأَفْضَلُ فِعْلُ الْأَرْفَقِ بِهِ مِنْ تَأْخِيرٍ وَتَقْدِيمٍ، فَإِنْ جَمَعَ فِي وَقْتِ الْأُولَى اشْتَرَطَ نِيَّةُ الْجَمْعِ عِنْدَ إِحْرَامِهَا وَلَا يُفَرِّقَ بَيْنَهُمَا إِلَّا بِمِقْدَارِ إِقَامَةٍ وَوُضُوءٍ خَفِيفٍ، وَيَبْطُلُ بِرَاتِبَةٍ بَيْنَهُمَا،"]]},{"id":"za29_3","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَأَنْ يَكُونَ الْعُذْرُ مَوْجُودًا عِنْدَ افْتِتَاحِهِمَا وَسَلَامِ الْأُولَى، وَإِنْ جَمَعَ فِي وَقْتِ الثَّانِيَةِ اشْتُرِطَ نِيَّةُ الْجَمْعِ فِي وَقْتِ الْأُولَى إِنْ لَمْ يَضِقْ عَنْ فِعْلِهَا وَاسْتِمْرَارِ الْعُذْرِ إِلَى دُخُولِ وَقْتِ الثَّانِيَةِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za30","title":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ (٣)","units":[{"id":"za30_1","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · فَصْلٌ (٣) · ١","segs":[["matn","وَصَلَاةُ الْخَوْفِ صَحَّتْ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصِفَاتٍ كُلُّهَا جَائِزَةٌ، وَيُسْتَحَبُّ أَنْ يَحْمِلَ مَعَهُ فِي صَلَاتِهَا مِنَ السِّلَاحِ مَا يَدْفَعُ بِهِ عَنْ نَفْسِهِ وَلَا يُثْقِلُهُ كَسَيْفٍ وَنَحْوِهِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za31","title":"بَابُ صَلَاةِ الْجُمُعَةِ","units":[{"id":"za31_1","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ١","segs":[["matn","تَلْزَمُ كُلَّ ذَكَرٍ حُرٍّ مُكَلَّفٍ مُسْلِمٍ مُسْتَوْطِنٍ بِبِنَاءٍ اسْمُهُ وَاحِدٌ وَلَوْ تَفَرَّقَ لَيْسَ بَيْنَهُ وَبَيْنَ الْمَسْجِدِ أَكْثَرُ مِنْ فَرْسَخٍ، وَلَا تَجِبُ عَلَى مُسَافِرٍ سَفَرَ قَصْرٍ وَلَا عَبْدٍ وَامْرَأَةٍ،"]]},{"id":"za31_2","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٢","segs":[["matn","وَمَنْ حَضَرَهَا مِنْهُمْ أَجْزَأَتْهُ وَلَمْ تَنْعَقِدْ بِهِ وَلَمْ يَصِحَّ أَنْ يَؤُمَّ فِيهَا، وَمَنْ سَقَطَتْ عَنْهُ لِعُذْرٍ وَجَبَتْ عَلَيْهِ وَانْعَقَدَتْ بِهِ، وَمَنْ صَلَّى الظُّهْرَ مِمَّنْ عَلَيْهِ حُضُورُ الْجُمُعَةِ قَبْلَ صَلَاةِ الْإِمَامِ لَمْ تَصِحَّ،"]]},{"id":"za31_3","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٣","segs":[["matn","وَتَصِحُّ مِمَّنْ لَا تَجِبُ عَلَيْهِ، وَالْأَفْضَلُ حَتَّى يُصَلِّيَ الْإِمَامُ، وَلَا يَجُوزُ لِمَنْ تَلْزَمُهُ السَّفَرُ فِي يَوْمِهَا بَعْدَ الزَّوَالِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za32","title":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ","units":[{"id":"za32_1","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ · ١","segs":[["matn","يُشْتَرَطُ لِصِحَّتِهَا شُرُوطٌ لَيْسَ مِنْهَا إِذْنُ الْإِمَامِ: أَحَدُهَا الْوَقْتُ، وَأَوَّلُهُ أَوَّلُ وَقْتِ صَلَاةِ الْعِيدِ وَآخِرُهُ آخِرُ وَقْتِ صَلَاةِ الظُّهْرِ، فَإِنْ خَرَجَ وَقْتُهَا قَبْلَ التَّحْرِيمَةِ صَلَّوْا ظُهْرًا وَإِلَّا فَجُمُعَةً."]]},{"id":"za32_2","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ · ٢","segs":[["matn","الثَّانِي: حُضُورُ أَرْبَعِينَ مِنْ أَهْلِ وُجُوبِهَا. بِقَرْيَةٍ مُسْتَوْطِنِينَ، وَتَصِحُّ فِيمَا قَارَبَ الْبُنْيَانَ مِنَ الصَّحْرَاءِ، فَإِنْ نَقَصُوا قَبْلَ إِتْمَامِهَا اسْتَأْنَفُوا ظُهْرًا، وَمَنْ أَدْرَكَ مَعَ الْإِمَامِ مِنْهَا رَكْعَةً أَتَمَّهَا جُمُعَةً وَإِنْ أَدْرَكَ أَقَلَّ مِنْ ذَلِكَ أَتَمَّهَا ظُهْرًا إِذَا كَانَ نَوَى الظُّهْرَ،"]]},{"id":"za32_3","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ · ٣","segs":[["matn","وَيُشْتَرَطُ تَقَدُّمُ خُطْبَتَيْنِ، مِنْ شَرْطِ صِحَّتِهِمَا حَمْدُ اللَّهِ، وَالصَّلَاةُ عَلَى رَسُولِهِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقِرَاءَةُ آيَةٍ، وَالْوَصِيَّةُ بِتَقْوَى اللَّهِ عَزَّ وَجَلَّ، وَحُضُورُ الْعَدَدِ الْمُشْتَرَطِ،"]]},{"id":"za32_4","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ · ٤","segs":[["matn","وَلَا يُشْتَرَطُ لَهُمَا الطَّهَارَةُ وَلَا أَنْ يَتَوَلَّاهُمَا مَنْ يَتَوَلَّى الصَّلَاةَ،"]]},{"id":"za32_5","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ · ٥","segs":[["matn","وَمِنْ سُنَنِهِمَا أَنْ يَخْطُبَ عَلَى مِنْبَرٍ أَوْ مَوْضِعٍ عَالٍ وَيُسَلِّمَ عَلَى الْمَأْمُومِينَ إِذَا أَقْبَلَ عَلَيْهِمْ ثُمَّ يَجْلِسَ إِلَى فَرَاغِ الْأَذَانِ وَيَجْلِسَ بَيْنَ الْخُطْبَتَيْنِ وَيَخْطُبَ قَائِمًا وَيَعْتَمِدَ عَلَى سَيْفٍ أَوْ قَوْسٍ أَوْ عَصَا وَيَقْصِدَ تِلْقَاءَ وَجْهِهِ وَيُقَصِّرَ الْخُطْبَةَ وَيَدْعُوَ لِلْمُسْلِمِينَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za33","title":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ (٢)","units":[{"id":"za33_1","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ (٢) · ١","segs":[["matn","وَالْجُمُعَةُ رَكْعَتَانِ، يُسَنُّ أَنْ يَقْرَأَ جَهْرًا فِي الْأُولَى بِالْجُمُعَةِ وَفِي الثَّانِيَةِ بِالْمُنَافِقِينَ، وَتَحْرُمُ إِقَامَتُهَا فِي أَكْثَرَ مِنْ مَوْضِعٍ مِنَ الْبَلَدِ إِلَّا لِحَاجَةٍ، فَإِنْ فَعَلُوا فَالصَّحِيحَةُ مَا بَاشَرَهَا الْإِمَامُ أَوْ أَذِنَ فِيهَا،"]]},{"id":"za33_2","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ (٢) · ٢","segs":[["matn","فَإِنِ اسْتَوَيَا فِي إِذْنٍ أَوْ عَدَمِهِ فَالثَّانِيَةُ بَاطِلَةٌ وَإِنْ وَقَعَتَا مَعًا أَوْ جُهِلَتِ الْأُولَى بَطَلَتَا، وَأَقَلُّ السُّنَّةِ بَعْدَ الْجُمُعَةِ رَكْعَتَانِ وَأَكْثَرُهَا سِتٌّ وَيُسَنُّ أَنْ يَغْتَسِلَ وَتَقَدَّمَ وَيَتَنَظَّفَ وَيَتَطَيَّبَ وَيَلْبَسَ أَحْسَنَ ثِيَابِهِ وَيُبَكِّرَ إِلَيْهَا مَاشِيًا،"]]},{"id":"za33_3","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَيَدْنُوَ مِنَ الْإِمَامِ وَيَقْرَأَ سُورَةَ الْكَهْفِ فِي يَوْمِهَا وَيُكْثِرَ الدُّعَاءَ وَيُكْثِرَ الصَّلَاةَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا يَتَخَطَّى رِقَابَ النَّاسِ إِلَّا أَنْ يَكُونَ إِمَامًا أَوْ إِلَى فُرْجَةٍ،"]]},{"id":"za33_4","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ (٢) · ٤","segs":[["matn","وَحَرُمَ أَنْ يُقِيمَ غَيْرَهُ فَيَجْلِسَ مَكَانَهُ إِلَّا مَنْ قَدَّمَ صَاحِبًا لَهُ فَجَلَسَ فِي مَوْضِعٍ يَحْفَظُهُ لَهُ، وَحَرُمَ رَفْعُ مُصَلًّى مَفْرُوشٍ مَا لَمْ تَحْضُرِ الصَّلَاةُ،"]]},{"id":"za33_5","label":"بَابُ صَلَاةِ الْجُمُعَةِ · فَصْلٌ (٢) · ٥","segs":[["matn","وَمَنْ قَامَ مِنْ مَوْضِعِهِ لِعَارِضٍ لَحِقَهُ ثُمَّ عَادَ إِلَيْهِ قَرِيبًا فَهُوَ أَحَقُّ بِهِ، وَمَنْ دَخَلَ وَالْإِمَامُ يَخْطُبُ لَمْ يَجْلِسْ حَتَّى يُصَلِّيَ رَكْعَتَيْنِ يُوجِزُ فِيهِمَا، وَلَا يَجُوزُ الْكَلَامُ وَالْإِمَامُ يَخْطُبُ إِلَّا لَهُ أَوْ لِمَنْ يُكَلِّمُهُ، وَيَجُوزُ قَبْلَ الْخُطْبَةِ وَبَعْدَهَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za34","title":"بَابُ صَلَاةِ الْعِيدَيْنِ","units":[{"id":"za34_1","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ١","segs":[["matn","وَهِيَ فَرْضُ كِفَايَةٍ إِذَا تَرَكَهَا أَهْلُ بَلَدٍ قَاتَلَهُمُ الْإِمَامُ، وَوَقْتُهَا كَصَلَاةِ الضُّحَى وَآخِرُهُ الزَّوَالُ، فَإِنْ لَمْ يُعْلَمْ بِالْعِيدِ إِلَّا بَعْدَهُ صَلَّوْا مِنَ الْغَدِ، وَتُسَنُّ فِي صَحْرَاءَ، وَتَقْدِيمُ صَلَاةِ الْأَضْحَى وَعَكْسُهُ الْفِطْرُ،"]]},{"id":"za34_2","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٢","segs":[["matn","وَأَكْلُهُ قَبْلَهَا وَعَكْسُهُ فِي الْأَضْحَى إِنْ ضَحَّى، وَتُكْرَهُ فِي الْجَامِعِ بِلَا عُذْرٍ، وَيُسَنُّ تَبْكِيرُ مَأْمُومٍ إِلَيْهَا مَاشِيًا بَعْدَ الصُّبْحِ، وَتَأَخُّرُ إِمَامٍ إِلَى وَقْتِ الصَّلَاةِ عَلَى أَحْسَنِ هَيْئَةٍ إِلَّا الْمُعْتَكِفَ فَفِي ثِيَابِ اعْتِكَافِهِ،"]]},{"id":"za34_3","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٣","segs":[["matn","وَمِنْ شَرْطِهَا اسْتِيطَانٌ وَعَدَدُ الْجُمُعَةِ، لَا إِذْنُ إِمَامٍ، وَيُسَنُّ أَنْ يَرْجِعَ مِنْ طَرِيقٍ آخَرَ، وُيَصَلِّيهَا رَكْعَتَيْنِ قَبْلَ الْخُطْبَةِ يُكَبِّرُ فِي الْأُولَى بَعْدَ الِاسْتِفْتَاحِ وَقَبْلَ التَّعَوُّذِ وَالْقِرَاءَةِ سِتًّا، وَفِي الثَّانِيَةِ قَبْلَ الْقِرَاءَةِ خَمْسًا،"]]},{"id":"za34_4","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٤","segs":[["matn","يَرْفَعُ يَدَيْهِ مَعَ كُلِّ تَكْبِيرَةٍ، وَيَقُولُ: «اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا، وَصَلَّى اللَّهُ عَلَى مُحَمَّدٍ النَّبِيِّ وَآلِهِ وَسَلَّمَ تَسْلِيمًا كَثِيرًا، وَإِنْ أَحَبَّ قَالَ غَيْرَ ذَلِكَ.»"]]},{"id":"za34_5","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٥","segs":[["matn","«ثُمَّ يَقْرَأُ جَهْرًا فِي الْأُولَى بَعْدَ الْفَاتِحَةِ بِسَبِّحْ وَبِالْغَاشِيَةِ فِي الثَّانِيَةِ، فَإِذَا سَلَّمَ خَطَبَ خُطْبَتَيْنِ كَخُطْبَتَيِ الْجُمُعَةِ يَسْتَفْتِحُ الْأُولَى بِتِسْعِ تَكْبِيرَاتٍ وَالثَّانِيَةَ بِسَبْعٍ، يَحُثُّهُمْ فِي الْفِطْرِ عَلَى الصَّدَقَةِ وَيُبَيِّنُ لَهُمْ مَا يُخْرِجُونَ،»"]]},{"id":"za34_6","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٦","segs":[["matn","«وَيُرَغِّبُهُمْ فِي الْأَضْحَى فِي الْأُضْحِيَّةِ وَيُبَيِّنُ لَهُمْ حُكْمَهَا، وَالتَّكْبِيرَاتُ الزَّوَائِدُ وَالذِّكْرُ بَيْنَهَا وَالْخُطْبَتَانِ سُنَّةٌ، وَيُكْرَهُ التَّنَفُّلُ قَبْلَ الصَّلَاةِ وَبَعْدَهَا فِي مَوْضِعِهَا، وَيُسَنُّ لِمَنْ فَاتَتْهُ أَوْ بَعْضُهَا قَضَاؤُهَا عَلَى صِفَتِهَا، وَيُسَنُّ التَّكْبِيرُ الْمُطْلَقُ فِي لَيْلَتَيِ الْعِيدَيْنِ،»"]]},{"id":"za34_7","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٧","segs":[["matn","«وَفِي فِطْرٍ آكَدُ، وَفِي كُلِّ عَشْرِ ذِي الْحِجَّةِ وَالْمُقَيَّدُ عَقِبَ كُلِّ فَرِيضَةٍ فِي جَمَاعَةٍ مِنْ صَلَاةِ الْفَجْرِ يَوْمَ عَرَفَةَ، وَلِلْمُحْرِمِ مِنْ صَلَاةِ الظُّهْرِ يَوْمَ النَّحْرِ إِلَى عَصْرِ آخِرِ أَيَّامِ التَّشْرِيقِ،»"]]},{"id":"za34_8","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٨","segs":[["matn","«وَإِنْ نَسِيَهُ قَضَاهُ مَا لَمْ يُحْدِثْ أَوْ يَخْرُجْ مِنَ الْمَسْجِدِ، وَلَا يُسَنُّ عَقِبَ صَلَاةِ عِيدٍ، وَصِفَتُهُ شَفْعًا» اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، وَلِلَّهِ الْحَمْدُ"]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za35","title":"بَابُ صَلَاةِ الْكُسُوفِ","units":[{"id":"za35_1","label":"بَابُ صَلَاةِ الْكُسُوفِ · ١","segs":[["matn","تُسَنُّ جَمَاعَةً وَفُرَادَى إِذَا كَسَفَ أَحَدُ النَّيِّرَيْنِ رَكْعَتَيْنِ،"]]},{"id":"za35_2","label":"بَابُ صَلَاةِ الْكُسُوفِ · ٢","segs":[["matn","يَقْرَأُ فِي الْأُولَى جَهْرًا بَعْدَ الْفَاتِحَةِ سُورَةً طَوِيلَةً ثُمَّ يَرْكَعُ طَوِيلًا ثُمَّ يَرْفَعُ وَيُسَمِّعُ وَيُحَمِّدُ ثُمَّ يَقْرَأُ الْفَاتِحَةَ وَسُورَةً طَوِيلَةً دُونَ الْأُولَى ثُمَّ يَرْكَعُ فَيُطِيلُ وَهُوَ دُونَ الْأَوَّلِ"]]},{"id":"za35_3","label":"بَابُ صَلَاةِ الْكُسُوفِ · ٣","segs":[["matn","ثُمَّ يَرْفَعُ ثُمَّ يَسْجُدُ سَجْدَتَيْنِ طَوِيلَتَيْنِ ثُمَّ يُصَلِّي الثَّانِيَةَ كَالْأُولَى لَكِنْ دُونَهَا فِي كُلِّ مَا يَفْعَلُ ثُمَّ يَتَشَهَّدُ وَيُسَلِّمُ فَإِنْ تَجَلَّى الْكُسُوفُ فِيهَا أَتَمَّهَا خَفِيفَةً،"]]},{"id":"za35_4","label":"بَابُ صَلَاةِ الْكُسُوفِ · ٤","segs":[["matn","وَإِنْ غَابَتِ الشَّمْسُ كَاسِفَةً أَوْ طَلَعَتْ وَالْقَمَرُ خَاسِفٌ أَوْ كَانَتْ آيَةً غَيْرَ الزَّلْزَلَةِ لَمْ يُصَلِّ."]]},{"id":"za35_5","label":"بَابُ صَلَاةِ الْكُسُوفِ · ٥","segs":[["matn","وَإِنْ أَتَى فِي كُلِّ رَكْعَةٍ بِثَلَاثِ رُكُوعَاتٍ أَوْ أَرْبَعٍ أَوْ خَمْسٍ جَازَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za36","title":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ","units":[{"id":"za36_1","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ١","segs":[["matn","إِذَا أَجْدَبَتِ الْأَرْضُ وَقَحَطَ الْمَطَرُ صَلَّوْهَا جَمَاعَةً وَفُرَادَى، وَصِفَتُهَا فِي مَوْضِعِهَا وَأَحْكَامُهُا كَعِيدٍ."]]},{"id":"za36_2","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٢","segs":[["matn","وَإِذَا أَرَادَ الْإِمَامُ الْخُرُوجَ لَهَا وَعَظَ النَّاسَ وَأَمَرَهُمْ بِالتَّوْبَةِ مِنَ الْمَعَاصِي وَالْخُرُوجِ مِنَ الْمَظَالِمِ وَتَرْكِ التَّشَاحُنِ وَالصِّيَامِ وَالصَّدَقَةِ وَيَعِدُهُمْ يَوْمًا يَخْرُجُونَ فِيهِ وَيَتَنَظَّفُ وَلَا يَتَطَيَّبُ وَيَخْرُجُ مُتَوَاضِعًا مُتَخَشِّعًا مُتَذَلِّلًا مُتَضَرِّعًا وَمَعَهُ أَهْلُ الدِّينِ وَالصَّلَاحِ وَالشُّيُوخُ وَالصِّبْيَانُ الْمُمَيِّزُونَ،"]]},{"id":"za36_3","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٣","segs":[["matn","وَإِنْ خَرَجَ أَهْلُ الذِّمَّةِ مُنْفَرِدِينَ عَنِ الْمُسْلِمِينَ لَا بِيَوْمٍ لَمْ يُمْنَعُوا، فَيُصَلِّي بِهِمْ ثُمَّ يَخْطُبُ وَاحِدَةً يَفْتَتِحُهَا بِالتَّكْبِيرِ كَخُطْبَةِ الْعِيدِ وَيُكْثِرُ فِيهَا الِاسْتِغْفَارَ وَقِرَاءَةَ الْآيَاتِ الَّتِي فِيهَا الْأَمْرُ بِهِ،"]]},{"id":"za36_4","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٤","segs":[["matn","وَيَرْفَعُ يَدَيْهِ فَيَدْعُوَ بِدُعَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمِنْهُ: «اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا» إِلَى آخِرِهِ وَإِنْ سُقُوا قَبْلَ خُرُوجِهِمْ شَكَرُوا اللَّهَ وَسَأَلُوهُ الْمَزِيدَ مِنْ فَضْلِهِ."]]},{"id":"za36_5","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٥","segs":[["matn","وَيُنَادَى الصَّلَاةُ جَامِعَةٌ، وَلَيْسَ مِنْ شَرْطِهَا إِذْنُ الْإِمَامِ، وَيُسَنُّ أَنْ يَقِفَ فِي أَوَّلِ الْمَطَرِ وَإِخْرَاجُ رَحْلِهِ وَثِيَابِهِ لِيُصِيبَهَا."]]},{"id":"za36_6","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٦","segs":[["matn","وَإِذَا زَادَتِ الْمِيَاهُ وَخِيفَ مِنْهَا سُنَّ أَنْ يَقُولَ «اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللَّهُمَّ عَلَى الظِّرَابِ وَالْآكَامِ وَبُطُونِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ، رَبَّنَا لَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ» الْآيَةَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"za37","title":"كِتَابُ الْجَنَائِزِ","units":[{"id":"za37_1","label":"كِتَابُ الْجَنَائِزِ · ١","segs":[["matn","تُسَنُّ عِيَادَةُ الْمَرِيضِ وَتَذْكِيرُهُ التَّوْبَةَ وَالْوَصِيَّةَ، وَإِذَا نُزِلَ بِهِ سُنَّ تَعَاهُدُ بَلِّ حَلْقِهِ بِمَاءٍ أَوْ شَرَابٍ وَنَدَّى شَفَتَيْهِ بِقُطْنَةٍ وَتَلْقِينُهُ «لَا إِلَٰهَ إِلَّا اللَّهُ» مَرَّةً وَلَمْ يَزِدْ عَلَى ثَلَاثٍ إِلَّا أَنْ يَتَكَلَّمَ بَعْدَهُ فَيُعِيدُ تَلْقِينَهُ بِرِفْقٍ،"]]},{"id":"za37_2","label":"كِتَابُ الْجَنَائِزِ · ٢","segs":[["matn","وَيَقْرَأُ عِنْدَهُ يَس وَيُوَجِّهُهُ إِلَى الْقِبْلَةِ، فَإِذَا مَاتَ سُنَّ تَغْمِيضُهُ وَشَدُّ لَحْيَيْهِ وَتَلْيِينُ مَفَاصِلِهِ وَخَلْعُ ثِيَابِهِ وَسَتْرُهُ بِثَوْبٍ وَوَضْعُ حَدِيدَةٍ عَلَى بَطْنِهِ،"]]},{"id":"za37_3","label":"كِتَابُ الْجَنَائِزِ · ٣","segs":[["matn","وَوَضْعُهُ عَلَى سَرِيرِ غُسْلِهِ مُتَوَجِّهًا مُنْحَدِرًا نَحْوَ رِجْلَيْهِ وَإِسْرَاعُ تَجْهِيزِهِ إِنْ مَاتَ غَيْرَ فَجْأَةٍ، وَإِنْفَاذُ وَصِيَّتِهِ، وَيَجِبُ فِي قَضَاءِ دَيْنِهِ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"za38","title":"كِتَابُ الْجَنَائِزِ · فَصْلٌ","units":[{"id":"za38_1","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ١","segs":[["matn","غَسْلُ الْمَيِّتِ وَتَكْفِينُهُ وَالصَّلَاةُ عَلَيْهِ وَدَفْنُهُ فَرْضُ كِفَايَةٍ، وَأَوْلَى النَّاسِ بِغُسْلِهِ وَصِيُّهُ ثُمَّ أَبُوهُ ثُمَّ جَدُّهُ ثُمَّ الْأَقْرَبُ فَالْأَقْرَبُ مِنْ عَصَبَاتِهِ ثُمَّ ذَوُو أَرْحَامِهِ، وَبِأُنْثَى وَصِيَّتُهَا ثُمَّ الْقُرْبَى فَالْقُرْبَى مِنْ نِسَائِهَا،"]]},{"id":"za38_2","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٢","segs":[["matn","وَلِكُلٍّ وَاحِدٍ مِنَ الزَّوْجَيْنِ غَسْلُ صَاحِبِهِ، وَكَذَا سَيِّدٌ مَعَ سُرِّيَّتِهِ، وَلِرَجُلٍ وَامْرَأَةٍ غَسْلُ مَنْ لَهُ دُونَ سَبْعِ سِنِينَ فَقَطْ، وَإِنْ مَاتَ رَجُلٌ بَيْنَ نِسْوَةٍ أَوْ عَكْسُهُ يُمِّمَتْ كَخُنْثَى مُشْكِلٍ،"]]},{"id":"za38_3","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٣","segs":[["matn","وَيَحْرُمُ أَنْ يُغَسِّلَ مُسْلِمٌ كَافِرًا أَوْ يَدْفِنَهُ بَلْ يُوَارَى لِعَدَمِ وَإِذَا أَخَذَ فِي غَسْلِهِ سَتَرَ عَوْرَتَهُ وَجَرَّدَهُ وَسَتَرَهُ عَنِ الْعُيُونِ، وَيُكْرَهُ لِغَيْرِ مُعِينٍ فِي غَسْلِهِ حُضُورُهُ،"]]},{"id":"za38_4","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٤","segs":[["matn","ثُمَّ يَرْفَعُ رَأْسَهُ إِلَى قُرْبِ جُلُوسِهِ وَيَعْصِرُ بَطْنَهُ بِرِفْقٍ وَيُكْثِرُ صَبَّ الْمَاءِ حِينَئِذٍ ثُمَّ يَلُفُّ عَلَى يَدِهِ خِرْقَةً فَيُنَجِّيهِ، وَلَا يَحِلُّ مَسُّ عَوْرَةِ مَنْ لَهُ سَبْعُ سِنِينَ، وَيُسْتَحَبُّ أَنْ لَا يَمَسَّ سَائِرَهُ إِلَّا بِخِرْقَةٍ،"]]},{"id":"za38_5","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٥","segs":[["matn","ثُمَّ يُوَضِّيهِ نَدْبًا وَلَا يُدْخِلُ الْمَاءَ فِي فِيهِ وَلَا فِي أَنْفِهِ،"]]},{"id":"za38_6","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٦","segs":[["matn","وَيُدْخِلُ إِصْبَعَيْهِ مَبْلُولَتَيْنِ بِالْمَاءِ بَيْنَ شَفَتَيْهِ فَيَمْسَحُ أَسْنَانَهُ وَفِي مِنْخَرَيْهِ فَيُنَظِّفُهُمَا وَلَا يُدْخِلُهُمَا الْمَاءَ ثُمَّ يَنْوِي غُسْلَهُ وَيُسَمِّي وَيَغْسِلُ بِرَغْوَةِ السِّدْرِ رَأْسَهُ وَلِحْيَتَهُ فَقَطْ"]]},{"id":"za38_7","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٧","segs":[["matn","ثُمَّ يَغْسِلُ شِقَّهُ الْأَيْمَنَ ثُمَّ الْأَيْسَرَ ثُمَّ كُلَّهُ ثَلَاثًا يُمِرُّ فِي كُلِّ مَرَّةٍ يَدَهُ عَلَى بَطْنِهِ فَإِنْ لَمْ يَنْقَ بِثَلَاثٍ زِيدَ حَتَّى يَنْقَى،"]]},{"id":"za38_8","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٨","segs":[["matn","وَلَوْ جَاوَزَ السَّبْعَ وَيَجْعَلُ فِي الْغَسْلَةِ الْأَخِيرَةِ كَافُورًا، وَالْمَاءُ الْحَارُّ وَالْأُشْنَانَ، وَالْخِلَالُ يُسْتَعْمَلُ إِذَا احْتِيجَ إِلَيْهِ، وَيَقُصُّ شَارِبَهُ وَيُقَلِّمُ أَظْفَارَهُ وَلَا يُسَرِّحُ شَعْرَهُ ثُمَّ يُنَشَّفُ بِثَوْبٍ."]]},{"id":"za38_9","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ٩","segs":[["matn","وَيُضَفَّرُ شَعْرُهَا ثَلَاثَةَ قُرُونٍ وَيُسْدَلُ وَرَاءَهَا. وَإِنْ خَرَجَ مِنْهُ شَيْءٌ بَعْدَ سَبْعٍ حُشِيَ بِقُطْنٍ فَإِنْ لَمْ يَسْتَمْسِكْ فَبِطِينٍ حُرٍّ، ثُمَّ يُغْسَلُ الْمَحَلُّ وَيُوَضَّأُ، وَإِنْ خَرَجَ بَعْدَ تَكْفِينِهِ لَمْ يُعَدِ الْغَسْلُ،"]]},{"id":"za38_10","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ١٠","segs":[["matn","وَمُحْرِمٌ مَيِّتٌ كَحَيٍّ يُغَسَّلُ بِمَاءٍ وَسِدْرٍ وَلَا يُقَرَّبُ طِيبًا وَلَا يُلْبَسُ ذَكَرٌ مَخِيطًا وَلَا يُغَطَّى رَأْسُهُ وَلَا وَجْهُ أُنْثَى، وَلَا يُغَسَّلُ شَهِيدٌ إِلَّا أَنْ يَكُونَ جُنُبًا وَيُدْفَنُ فِي ثِيَابِهِ بَعْدَ نَزْعِ السِّلَاحِ وَالْجُلُودِ عَنْهُ،"]]},{"id":"za38_11","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ١١","segs":[["matn","وَإِنْ سُلِبَهَا كُفِّنَ بِغَيْرِهَا وَلَا يُصَلَّى عَلَيْهِ، وَإِنْ سَقَطَ مِنْ دَابَّتِهِ أَوْ وُجِدَ مَيِّتًا وَلَا أَثَرَ بِهِ أَوْ حُمِلَ فَأَكَلَ أَوْ طَالَ بَقَاؤُهُ عُرْفًا غُسِّلَ وَصُلِّيَ عَلَيْهِ، وَالسِّقْطُ إِذَا بَلَغَ أَرْبَعَةَ أَشْهُرٍ غُسِّلَ وَصُلِّيَ عَلَيْهِ،"]]},{"id":"za38_12","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ · ١٢","segs":[["matn","وَمَنْ تَعَذَّرَ غَسْلُهُ يُمِّمَ، وَعَلَى الْغَاسِلِ سَتْرُ مَا رَآهُ إِنْ لَمْ يَكُنْ حَسَنًا."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"za39","title":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٢)","units":[{"id":"za39_1","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٢) · ١","segs":[["matn","يَجِبُ تَكْفِينُهُ فِي مَالِهِ مُقَدَّمًا عَلَى دَيْنٍ وَغَيْرِهِ، فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ فَعَلَى مَنْ تَلْزَمُهُ نَفَقَتُهُ إِلَّا الزَّوْجَ لَا يَلْزَمُهُ كَفَنُ امْرَأَتِهِ،"]]},{"id":"za39_2","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَيُسْتَحَبُّ تَكْفِينُ رَجُلٍ فِي ثَلَاثِ لَفَائِفَ بِيضٍ تُجَمَّرُ ثُمَّ تُبْسَطُ بَعْضُهَا فَوْقَ بَعْضٍ وَيُجْعَلُ الْحَنُوطُ فِيمَا بَيْنَهَا ثُمَّ يُوضَعُ عَلَيْهَا مُسْتَلْقِيًا وَيُجْعَلُ مِنْهُ فِي قُطْنٍ بَيْنَ أَلْيَتَيْهِ وَيُشَدُّ فَوْقَهَا خِرْقَةٌ مَشْقُوقَةُ الطَّرَفِ كَالتُّبَّانِ تَجْمَعُ أَلْيَتَيْهِ وَمَثَانَتَهُ،"]]},{"id":"za39_3","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَيُجْعَلُ الْبَاقِي عَلَى مَنَافِذِ وَجْهِهِ وَمَوَاضِعِ سُجُودِهِ، وَإِنْ طُيِّبَ كُلُّهُ فَحَسَنٌ، ثُمَّ يُرَدُّ طَرَفُ اللِّفَافَةِ الْعُلْيَا عَلَى شِقِّهِ الْأَيْمَنِ وَيُرَدُّ طَرَفُهَا الْآخَرُ فَوْقِهِ ثُمَّ الثَّانِيَةُ وَالثَّالِثَةُ كَذَلِكَ،"]]},{"id":"za39_4","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٢) · ٤","segs":[["matn","وَيُجْعَلُ أَكْثَرُ الْفَاضِلِ عِنْدَ رَأْسِهِ ثُمَّ يَعْقِدُهَا وَتُحَلُّ فِي الْقَبْرِ وَإِنْ كُفِّنَ فِي قَمِيصٍ وَمِئْزَرٍ وَلِفَافَةٍ جَازَ."]]},{"id":"za39_5","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٢) · ٥","segs":[["matn","وَتُكَفَّنُ الْمَرْأَةُ فِي خَمْسَةِ أَثْوَابٍ: إِزَارٍ وَخِمَارٍ وَقَمِيصٍ وَلِفَافَتَيْنِ، وَالْوَاجِبُ ثَوْبٌ يَسْتُرُ جَمِيعَهُ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"za40","title":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣)","units":[{"id":"za40_1","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ١","segs":[["matn","السُّنَّةُ أَنْ يَقُومَ الْإِمَامُ عِنْدَ صَدْرِهِ وَعِنْدَ وَسَطِهَا، وَيُكَبِّرُ أَرْبَعًا يَقْرَأُ فِي الْأُولَى بَعْدَ التَّعَوُّذِ الْفَاتِحَةَ، وَيُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الثَّانِيَةِ كَالتَّشَهُّدِ،"]]},{"id":"za40_2","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ٢","segs":[["matn","وَيَدْعُو فِي الثَّالِثَةِ فَيَقُولُ: «اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَشَاهِدِنَا وَغَائِبِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا، إِنَّكَ تَعْلَمُ مُنْقَلَبَنَا وَمَثْوَانَا وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ وَالسُّنَّةِ،»"]]},{"id":"za40_3","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ٣","segs":[["matn","«وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَيْهِمَا، اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ وَأَكْرِمْ نُزُلَهُ وَأَوْسِعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ،»"]]},{"id":"za40_4","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ٤","segs":[["matn","«وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ وَأَدْخِلْهُ الْجَنَّةَ وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ النَّارِ وَافْسَحْ لَهُ فِي قَبْرِهِ وَنَوِّرْ لَهُ فِيهِ، وَإِنْ كَانَ صَغِيرًا قَالَ:» اللَّهُمَّ اجْعَلْهُ ذُخْرًا لِوَالِدَيْهِ،"]]},{"id":"za40_5","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ٥","segs":[["matn","وَفَرَطًا وَأَجْرًا وَشَفِيعًا مُجَابًا، اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجُورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ سَلَفِ الْمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ،"]]},{"id":"za40_6","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ٦","segs":[["matn","وَيَقِفُ بَعْدَ الرَّابِعَةِ قَلِيلًا وَيُسَلِّمُ وَاحِدَةً عَنْ يَمِينِهِ وَيَرْفَعُ يَدَيْهِ مَعَ كُلِّ تَكْبِيرَةٍ، وَوَاجِبُهَا قِيَامٌ وَتَكْبِيرَاتٌ وَالْفَاتِحَةُ وَالصَّلَاةُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَدَعْوَةٌ لِلْمَيِّتِ وَالسَّلَامُ، وَمَنْ فَاتَهُ شَيْءٌ مِنَ التَّكْبِيرِ قَضَاهُ عَلَى صِفَتِهِ،"]]},{"id":"za40_7","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ٧","segs":[["matn","وَمَنْ فَاتَتْهُ الصَّلَاةُ عَلَيْهِ صَلَّى عَلَى الْقَبْرِ. وَعَلَى غَائِبٍ بِالنِّيَّةِ إِلَى شَهْرٍ."]]},{"id":"za40_8","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٣) · ٨","segs":[["matn","وَلَا يُصَلِّيَ الْإِمَامُ عَلَى الْغَالِّ وَلَا عَلَى قَاتِلِ نَفْسِهِ، وَلَا بَأْسَ بِالصَّلَاةِ عَلَيْهِ فِي الْمَسْجِدِ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"za41","title":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٤)","units":[{"id":"za41_1","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٤) · ١","segs":[["matn","يُسَنُّ التَّرْبِيعُ فِي حَمْلِهِ وَيُبَاحُ بَيْنَ الْعَمُودَيْنِ، وَيُسَنُّ الْإِسْرَاعُ بِهَا وَكَوْنُ الْمُشَاةِ أَمَامَهَا وَالرُّكْبَانِ خَلْفَهَا، وَيُكْرَهُ جُلُوسُ تَابِعِهَا حَتَّى تُوضَعَ، وَيُسَجَّى قَبْرُ امْرَأَةٍ فَقَطْ،"]]},{"id":"za41_2","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٤) · ٢","segs":[["matn","وَاللَّحْدُ أَفْضَلُ مِنَ الشَّقِّ وَيَقُولُ مُدْخِلُهُ «بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ» وَيَضَعُهُ فِي لَحْدِهِ عَلَى شِقِّهِ الْأَيْمَنِ مُسْتَقْبِلَ الْقِبْلَةِ،"]]},{"id":"za41_3","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٤) · ٣","segs":[["matn","وَيُرْفَعُ الْقَبْرُ عَنِ الْأَرْضِ قَدْرَ شِبْرٍ مُسَنَّمًا وَيُكْرَهُ تَجْصِيصُهُ وَالْبِنَاءُ وَالْكِتَابَةُ وَالْجُلُوسُ وَالْوَطْءُ عَلَيْهِ وَالِاتِّكَاءُ إِلَيْهِ، وَيَحْرُمُ فِيهِ دَفْنُ اثْنَيْنِ فَأَكْثَرَ إِلَّا لِضَرُورَةٍ، وَيُجْعَلُ بَيْنَ كُلِّ اثْنَيْنِ حَاجِزٌ مِنْ تُرَابٍ، وَلَا تُكْرَهُ الْقِرَاءَةُ عَلَى الْقَبْرِ،"]]},{"id":"za41_4","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٤) · ٤","segs":[["matn","وَأَيُّ قُرْبَةٍ فَعَلَهَا وَجَعَلَ ثَوَابَهَا لِمَيِّتٍ مُسْلِمٍ أَوْ حَيٍّ نَفَعَهُ ذَلِكَ، وَيُسَنُّ أَنْ يُصْلَحَ لِأَهْلِ الْمَيِّتِ طَعَامٌ يُبْعَثُ بِهِ إِلَيْهِمْ، وَيُكْرَهُ لَهُمْ فِعْلُهُ لِلنَّاسِ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"za42","title":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٥)","units":[{"id":"za42_1","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٥) · ١","segs":[["matn","تُسَنُّ زِيَارَةُ الْقُبُورِ إِلَّا لِنِسَاءٍ وَأَنْ يَقُولَ إِذَا زَارَهَا أَوْ مَرَّ بِهَا: «السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ، يَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنْكُمْ وَالْمُسْتَأْخِرِينَ، نَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ،»"]]},{"id":"za42_2","label":"كِتَابُ الْجَنَائِزِ · فَصْلٌ (٥) · ٢","segs":[["matn","«اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ، وَلَا تَفْتِنَّا بَعْدَهُمْ، وَاغْفِرْ لَنَا وَلَهُمْ» وَتُسَنُّ تَعْزِيَةُ الْمُصَابِ بِالْمَيِّتِ، وَيَجُوزُ الْبُكَاءُ عَلَى الْمَيِّتِ، وَيَحْرُمُ النَّدْبُ وَالنِّيَاحَةُ وَشَقُّ الثَّوْبِ وَلَطْمُ الْخَدِّ وَنَحْوُهُ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"za43","title":"كِتَابُ الزَّكَاةِ","units":[{"id":"za43_1","label":"كِتَابُ الزَّكَاةِ · ١","segs":[["matn","تَجِبُ بِشُرُوطٍ خَمْسَةٍ؛ حُرِّيَّةٌ، وَإِسْلَامٌ، وَمِلْكُ نِصَابٍ، وَاسْتِقْرَارُهُ، وَمُضِيُّ الْحَوْلِ فِي غَيْرِ الْمُعَشَّرِ، إِلَّا نِتَاجَ السَّائِمَةِ، وَرِبْحَ التِّجَارَةِ وَلَوْ لَمْ يَبْلُغْ نِصَابًا، فَإِنَّ حَوْلَهُمَا حَوْلُ أَصْلِهِمَا إِنْ كَانَ نِصَابًا، وَإِلَّا فَمِنْ كَمَالِهِ،"]]},{"id":"za43_2","label":"كِتَابُ الزَّكَاةِ · ٢","segs":[["matn","وَمَنْ كَانَ لَهُ دَيْنٌ أَوْ حَقٌّ مِنْ صَدَاقٍ وَغَيْرِهِ عَلَى مَلِيءٍ أَوْ غَيْرِهِ أَدَّى زَكَاتَهُ إِذَا قَبَضَهُ لِمَا مَضَى، وَلَا زَكَاةَ فِي مَالِ مَنْ عَلَيْهِ دَيْنٌ يُنْقِصُ النِّصَابَ، وَلَوْ كَانَ الْمَالُ ظَاهِرًا، وَكَفَّارَةٌ كَدَيْنٍ،"]]},{"id":"za43_3","label":"كِتَابُ الزَّكَاةِ · ٣","segs":[["matn","وَإِنْ مَلَكَ نِصَابًا صِغَارًا انْعَقَدَ حَوْلُهُ حِينَ مَلَكَهُ، وَإِنْ نَقَصَ النِّصَابَ فِي بَعْضِ الْحَوْلِ أَوْ بَاعَهُ أَوْ أَبْدَلَهُ بِغَيْرِ جِنْسِهِ لَا فِرَارًا مِنَ الزَّكَاةِ انْقَطَعَ الْحَوْلُ، وَإِنْ أَبْدَلَهُ بِجِنْسِهِ بَنَى عَلَى حَوْلِهِ،"]]},{"id":"za43_4","label":"كِتَابُ الزَّكَاةِ · ٤","segs":[["matn","وَتَجِبُ الزَّكَاةُ فِي عَيْنِ الْمَالِ فِي وَلَهَا تَعَلُّقٌ بِالذِّمَّةِ، وَلَا يُعْتَبَرُ فِي وُجُوبِهَا إِمْكَانُ الْأَدَاءِ وَلَا بَقَاءُ الْمَالِ، وَالزَّكَاةُ كَالدَّيْنِ فِي التَّرِكَةِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za44","title":"بَابُ زَكَاةِ بَهِيمَةِ الْأَنْعَامِ","units":[{"id":"za44_1","label":"بَابُ زَكَاةِ بَهِيمَةِ الْأَنْعَامِ · ١","segs":[["matn","تَجِبُ فِي إِبِلٍ وَبَقَرٍ وَغَنَمٍ إِذَا كَانَتْ سَائِمَةً الْحَوْلَ أَوْ أَكْثَرَهُ، فَيَجِبُ فِي خَمْسٍ وَعِشْرِينَ مِنَ الْإِبِلِ بِنْتُ مُخَاضٍ، وَفِيمَا دُونَهَا فِي كُلِّ خَمْسٍ شَاةٌ، وَفِي سِتٍّ وَثَلَاثِينَ بِنْتُ لَبُونٍ، وَفِي سِتٍّ وَأَرْبَعِينَ حِقَّةٌ،"]]},{"id":"za44_2","label":"بَابُ زَكَاةِ بَهِيمَةِ الْأَنْعَامِ · ٢","segs":[["matn","وَفِي إِحْدَى وَسِتِّينَ جَذَعَةٌ، وَفِي سِتٍّ وَسَبْعِينَ بِنْتَا لَبُونٍ، وَفِي إِحْدَى وَتِسْعِينَ حِقَّتَانِ، فَإِذَا زَادَتْ عَنْ مِائَةٍ وَعِشْرِينَ وَاحِدَةً فَثَلَاثُ بَنَاتِ لَبُونٍ، ثُمَّ فِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ، وَفِي كُلِّ خَمْسِينَ حِقَّةٌ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za45","title":"بَابُ زَكَاةِ بَهِيمَةِ الْأَنْعَامِ · فَصْلٌ","units":[{"id":"za45_1","label":"بَابُ زَكَاةِ بَهِيمَةِ الْأَنْعَامِ · فَصْلٌ · ١","segs":[["matn","وَيَجِبُ فِي ثَلَاثِينَ مِنَ الْبَقَرِ تَبِيعٌ أَوْ تَبِيعَةٌ، وَفِي أَرْبَعِينَ مُسِنَّةٌ، ثُمَّ فِي كُلِّ ثَلَاثِينَ تَبِيعٌ، وَفِي كُلِّ أَرْبَعِينَ مُسِنَّةٌ، وَيُجْزِئُ الذَّكَرُ هُنَا، وَابْنُ لَبُونٍ مَكَانَ بِنْتِ مَخَاضٍ، وَإِذَا كَانَ النِّصَابُ كُلُّهُ ذُكُورًا."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za46","title":"بَابُ زَكَاةِ بَهِيمَةِ الْأَنْعَامِ · فَصْلٌ (٢)","units":[{"id":"za46_1","label":"بَابُ زَكَاةِ بَهِيمَةِ الْأَنْعَامِ · فَصْلٌ (٢) · ١","segs":[["matn","وَيَجِبُ فِي أَرْبَعِينَ مِنَ الْغَنَمِ شَاةٌ، وَفِي مِائَةٍ وَإِحْدَى وَعِشْرِينَ شَاتَانِ، وَفِي مِائَتَيْنِ وَوَاحِدَةٍ ثَلَاثُ شِيَاهٍ، ثُمَّ فِي كُلِّ مِائَةٍ شَاةٌ، وَالْخُلْطَةُ تُصَيِّرُ الْمَالَيْنِ كَالْوَاحِدِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za47","title":"بَابُ زَكَاةِ الْحُبُوبِ وَالثِّمَارِ","units":[{"id":"za47_1","label":"بَابُ زَكَاةِ الْحُبُوبِ وَالثِّمَارِ · ١","segs":[["matn","تَجِبُ فِي الْحُبُوبِ كُلِّهَا وَلَوْ لَمْ تَكُنْ قُوتًا، وَفِي كُلِّ ثَمَرٍ يُكَالُ وَيُدَّخَرُ كَتَمْرٍ وَزَبِيبٍ، وَيُعْتَبَرُ بُلُوغُ نِصَابٍ قَدْرُهُ أَلْفٌ وَسِتُّمِائَةِ رَطْلٍ عِرَاقِيٍّ، وَتُضَمُّ ثَمَرَةُ الْعَامِ الْوَاحِدِ بَعْضُهَا إِلَى بَعْضٍ فِي تَكْمِيلِ النِّصَابِ،"]]},{"id":"za47_2","label":"بَابُ زَكَاةِ الْحُبُوبِ وَالثِّمَارِ · ٢","segs":[["matn","لَا جِنْسٌ إِلَى آخَرَ، وَيُعْتَبَرُ أَنْ يَكُونَ النِّصَابُ مَمْلُوكًا لَهُ وَقْتَ وُجُوبِ الزَّكَاةَ، فَلَا تَجِبُ فِيمَا يَكْتَسِبُهُ اللَّقَّاطُ أَوْ يَأْخُذُهُ بِحَصَادِهِ، وَلَا فِيمَا يَجْتَنِيهِ مِنَ الْمُبَاحِ كَالْبُطْمِ وَالزَّعْبَلِ وَبِزْرِ قَطُونَا وَلَوْ نَبَتَ فِي أَرْضِهِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za48","title":"بَابُ زَكَاةِ الْحُبُوبِ وَالثِّمَارِ · فَصْلٌ","units":[{"id":"za48_1","label":"بَابُ زَكَاةِ الْحُبُوبِ وَالثِّمَارِ · فَصْلٌ · ١","segs":[["matn","يَجِبُ عُشْرٌ فِيمَا سُقِيَ بِلَا مُؤْنَةٍ، وَنِصْفُهُ مَعَهَا وَثَلَاثَةُ أَرْبَاعِهِ بِهِمَا، فَإِنْ تَفَاوَتَا فَبِأَكْثَرِهِمَا نَفْعًا، وَمَعَ الْجَهْلِ الْعُشْرُ، وَإِذَا اشْتَدَّ الْحَبُّ وَبَدَا صَلَاحُ الثَّمَرِ وَجَبَتِ الزَّكَاةُ، وَلَا يَسْتَقِرُّ الْوُجُوبُ إِلَّا بِجَعْلِهَا فِي الْبَيْدَرِ،"]]},{"id":"za48_2","label":"بَابُ زَكَاةِ الْحُبُوبِ وَالثِّمَارِ · فَصْلٌ · ٢","segs":[["matn","فَإِنْ تَلِفَتْ قَبْلَهُ بِغَيْرِ تَعَدٍّ مِنْهُ سَقَطَتْ، وَيَجِبُ الْعُشْرُ عَلَى مُسْتَأْجِرِ الْأَرْضِ دُونَ مَالِكِهَا، وَإِذَا أَخَذَ مِنْ مِلْكِهِ أَوْ مَوَاتٍ مِنَ الْعَسَلِ مِائَةً وَسِتِّينَ رِطْلًا عِرَاقِيًّا فَفِيهِ عُشْرُهُ."]]},{"id":"za48_3","label":"بَابُ زَكَاةِ الْحُبُوبِ وَالثِّمَارِ · فَصْلٌ · ٣","segs":[["matn","وَالرِّكَازُ مَا وُجِدَ مِنْ دِفْنِ الْجَاهِلِيَّةِ، فِيهِ الْخُمُسُ فِي قَلِيلِهِ وَكَثِيرِهِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za49","title":"بَابُ زَكَاةِ النَّقْدَيْنِ","units":[{"id":"za49_1","label":"بَابُ زَكَاةِ النَّقْدَيْنِ · ١","segs":[["matn","يَجِبُ فِي الذَّهَبِ إِذَا بَلَغَ عِشْرِينَ مِثْقَالًا، وَفِي الْفِضَّةِ إِذَا بَلَغَتْ مِائَتَيْ دِرْهَمٍ رُبْعُ الْعُشْرِ مِنْهُمَا، وَيُضَمُّ الذَّهَبُ إِلَى الْفِضَّةِ فِي تَكْمِيلِ النِّصَابِ، وَتُضَمُّ قِيمَةُ الْعُرُوضِ إِلَى كُلٍّ مِنْهُمَا،"]]},{"id":"za49_2","label":"بَابُ زَكَاةِ النَّقْدَيْنِ · ٢","segs":[["matn","وَيُبَاحُ لِلذَّكَرِ مِنَ الْفِضَّةِ الْخَاتَمُ وَقَبِيعَةُ السَّيْفِ وَحِلْيَةُ الْمِنْطَقَةِ وَنَحْوِهِ، وَمِنَ الذَّهَبِ قَبِيعَةُ السَّيْفِ وَمَا دَعَتْ إِلَيْهِ ضَرُورَةٌ كَأَنْفٍ وَنَحْوِهِ، وَيُبَاحُ لِلنِّسَاءِ مِنَ الذَّهَبِ وَالْفِضَّةِ مَا جَرَتْ عَادَتُهُنَّ بِلُبْسِهِ وَلَوْ كَثُرَ،"]]},{"id":"za49_3","label":"بَابُ زَكَاةِ النَّقْدَيْنِ · ٣","segs":[["matn","وَلَا زَكَاةَ فِي حُلِيِّهِمَا الْمُعَدِّ لِلِاسْتِعْمَالِ أَوِ الْعَارِيَّةِ، وَإِنْ أُعِدَّ لِلْكِرَى أَوْ النَّفَقَةِ أَوْ كَانَ مُحَرَّمًا فَفِيهِ الزَّكَاةُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za50","title":"بَابُ زَكَاةِ الْعُرُوضِ","units":[{"id":"za50_1","label":"بَابُ زَكَاةِ الْعُرُوضِ · ١","segs":[["matn","إِذَا مَلَكَهَا بِفِعْلِهِ بِنِيَّةِ التِّجَارَةِ وَبَلَغَتْ قِيمَتُهَا نِصَابًا زَكَّى قِيمَتَهَا، فَإِنْ مَلَكَهَا بِإِرْثٍ أَوْ بِفِعْلِهِ بِغَيْرِ نِيَّةِ التِّجَارَةِ ثُمَّ نَوَاهَا لَمْ تَصِرْ لَهَا، وَتُقَوَّمُ عِنْدَ الْحَوْلِ بِالْأَحَظِّ لِلْفُقَرَاءِ مِنْ عَيْنٍ أَوْ وَرِقٍ،"]]},{"id":"za50_2","label":"بَابُ زَكَاةِ الْعُرُوضِ · ٢","segs":[["matn","وَلَا يُعْتَبَرُ مَا اشْتُرِيَتْ بِهِ، وَإِنِ اشْتَرَى عَرَضًا بِنِصَابٍ مِنْ أَثْمَانٍ أَوْ عُرُوضٍ بَنَى عَلَى حَوْلِهِ، وَإِنِ اشْتَرَاهُ بِسَائِمَةٍ لَمْ يَبْنِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za51","title":"بَابُ زَكَاةِ الْفِطْرِ","units":[{"id":"za51_1","label":"بَابُ زَكَاةِ الْفِطْرِ · ١","segs":[["matn","تَجِبُ عَلَى كُلِّ مُسْلِمٍ فَضَلَ لَهُ يَوْمَ الْعِيدِ وِلِيْلَتَهُ صَاعٌ عَنْ قُوتِهِ وَقُوتِ عِيَالِهِ وَحَوَائِجِهِ الْأَصْلِيَّةِ وَلَا يَمْنَعُهَا الدَّيْنُ إِلَّا بِطَلَبِهِ، فَيُخْرِجُ عَنْ نَفْسِهِ، وَمُسْلِمٍ يَمُونُهُ وَلَوْ شَهْرَ رَمَضَانَ،"]]},{"id":"za51_2","label":"بَابُ زَكَاةِ الْفِطْرِ · ٢","segs":[["matn","فَإِنْ عَجَزَ عَنِ الْبَعْضِ بَدَأَ بِنَفْسِهِ فَامْرَأَتِهِ فَرَقِيقِهِ فَأُمِّهِ فَأَبِيهِ فَوَلَدِهِ فَأَقْرَبَ فِي مِيرَاثٍ، وَالْعَبْدُ بَيْنَ شُرَكَاءَ عَلَيْهِمْ صَاعٌ، وَيُسْتَحَبُّ عَنِ الْجَنِينِ، وَلَا تَجِبُ لِنَاشِزٍ، وَمَنْ لَزِمَتْ غَيْرَهُ فِطْرَتُهُ فَأَخْرَجَ عَنْ نَفْسِهِ بِغَيْرِ إِذْنِهِ أَجْزَأَتْ،"]]},{"id":"za51_3","label":"بَابُ زَكَاةِ الْفِطْرِ · ٣","segs":[["matn","وَتَجِبُ بِغُرُوبِ الشَّمْسِ لَيْلَةَ الْفِطْرِ، فَمَنْ أَسْلَمَ بَعْدَهُ أَوْ مَلَكَ عَبْدًا أَوْ زَوْجَةً أَوْ وُلِدَ لَهُ وَلَدٌ لَمْ تَلْزَمْهُ فِطْرَتُهُ، وَقَبْلَهُ تَلْزَمُ، وَيَجُوزُ إِخْرَاجُهَا قَبْلَ الْعِيدِ بِيَوْمَيْنِ فَقَطْ، وَيَوْمَ الْعِيدِ قَبْلَ الصَّلَاةِ أَفْضَلُ، وَتُكْرَهُ فِي بَاقِيهِ، وَيَقْضِيهَا بَعْدَ يَوْمِهِ آثِمًا."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za52","title":"بَابُ زَكَاةِ الْفِطْرِ · فَصْلٌ","units":[{"id":"za52_1","label":"بَابُ زَكَاةِ الْفِطْرِ · فَصْلٌ · ١","segs":[["matn","وَيَجِبُ صَاعٌ مِنْ بُرٍّ أَوْ شَعِيرٍ أَوْ دَقِيقِهِمَا أَوْ سَوِيقِهِمَا أَوْ تَمْرٍ أَوْ زَبِيبٍ أَوْ أَقِطٍ، فَإِنْ عَدِمَ الْخَمْسَةَ أَجْزَأَ كُلُّ حَبٍّ وَثَمَرٍ يُقْتَاتُ، لَا مَعِيبٌ وَلَا خُبْزٌ، وَيَجُوزُ أَنْ يُعْطِيَ الْجَمَاعَةَ مَا يَلْزَمُ الْوَاحِدَ وَعَكْسُهُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za53","title":"بَابُ إِخْرَاجِ الزَّكَاةِ","units":[{"id":"za53_1","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ١","segs":[["matn","وَيَجِبُ عَلَى الْفَوْرِ مَعَ إِمْكَانِهِ إِلَّا لِضَرَرٍ، فَإِنْ مَنَعَهَا جَحْدًا لِوُجُوبِهَا كَفَرَ عَارِفٌ بِالْحُكْمِ وَأُخِذَتْ وَقُتِلَ، أَوْ بُخْلًا أُخِذَتْ مِنْهُ وَعُزِّرَ، وَتَجِبُ فِي مَالِ صَبِيٍّ وَمَجْنُونٍ فَيُخْرِجُهَا وَلِيُّهُمَا، وَلَا يَجُوزُ إِخْرَاجُهَا إِلَّا بِنِيَّةٍ،"]]},{"id":"za53_2","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٢","segs":[["matn","وَالْأَفْضَلُ أَنْ يُفَرِّقَهَا بِنَفْسِهِ وَيَقُولُ عِنْدَ دَفْعِهَا هُوَ وَآخِذُهَا مَا وَرَدَ، وَالْأَفْضَلُ إِخْرَاجُ زَكَاةِ كُلِّ مَالٍ فِي فُقَرَاءِ بَلَدِهِ، وَلَا يَجُوزُ نَقْلُهَا إِلَى مَا تُقْصَرُ فِيهِ الصَّلَاةُ، فَإِنْ فَعَلَ أَجْزَأَتْ،"]]},{"id":"za53_3","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٣","segs":[["matn","إِلَّا أَنْ يَكُونَ فِي بَلَدٍ لَا فُقَرَاءَ فِيهِ فَيُفَرِّقُهَا فِي أَقْرَبِ الْبِلَادِ إِلَيْهِ، فَإِنْ كَانَ فِي بَلَدٍ وَمَالُهُ فِي آخَرَ أَخْرَجَ زَكَاةَ الْمَالِ فِي بَلَدِهِ، وَفِطْرَتَهَ فِي بَلَدٍ هُوَ فِيهِ، وَيَجُوزُ تَعْجِيلُ الزَّكَاةِ لِحَوْلَيْنِ فَأَقَلَّ وَلَا يُسْتَحَبُّ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za54","title":"بَابٌ","units":[{"id":"za54_1","label":"بَابٌ · ١","segs":[["matn","أَهْلُ الزَّكَاةِ ثَمَانِيَةٌ، الْفُقَرَاءُ، وَهُمْ مَنْ لَا يَجِدُونَ شَيْئًا أَوْ يَجِدُونَ بَعْضَ الْكِفَايَةِ، وَالْمَسَاكِينُ يَجِدُونَ أَكْثَرَهَا أَوْ نِصْفَهَا، وَالْعَامِلُونَ عَلَيْهَا وَهُمْ جُبَاتُهَا وَحُفَّاظُهَا،"]]},{"id":"za54_2","label":"بَابٌ · ٢","segs":[["matn","الرَّابِعُ: الْمُؤَلَّفَةُ قُلُوبُهُمْ مِمَّنْ يُرْجَى إِسْلَامُهُ أَوْ كَفُّ شَرِّهِ أَوْ يُرْجَى بِعَطِيَّتِهِ قُوَّةُ إِيمَانِهِ، الْخَامِسُ: الرِّقَابُ وَهُمْ الْمُكَاتَبُونَ، وَيُفَكُّ مِنْهَا الْأَسِيرُ الْمُسْلِمُ، السَّادِسُ: الْغَارِمُ لِإِصْلَاحِ ذَاتِ الْبَيْنِ وَلَوْ مَعَ غِنًى، أَوْ لِنَفْسِهِ مَعَ الْفَقْرِ،"]]},{"id":"za54_3","label":"بَابٌ · ٣","segs":[["matn","السَّابِعُ: فِي سَبِيلِ اللَّهِ وَهُمُ الْغُزَاةُ الْمُتَطَوِّعَةُ الَّذِينَ لَا دِيوَانَ لَهُمْ، الثَّامِنُ ابْنُ السَّبِيلِ الْمُسَافِرُ الْمُنْقَطِعُ بِهِ دُونَ الْمُنْشِئِ لِلسَّفَرِ مِنْ بَلَدِهِ فَيُعْطَى مَا يُوَصِّلُهُ إِلَى بَلَدِهِ، وَمَنْ كَانَ ذَا عِيَالٍ أَخَذَ مَا يَكْفِيهِمْ،"]]},{"id":"za54_4","label":"بَابٌ · ٤","segs":[["matn","وَيَجُوزُ صَرْفُهَا إِلَى صِنْفٍ وَاحِدٍ، وَيُسَنُّ إِلَى أَقَارِبِهِ الَّذِينَ لَا تَلْزَمُهُ مُؤْنَتُهُمْ:"]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za55","title":"بَابٌ · فَصْلٌ","units":[{"id":"za55_1","label":"بَابٌ · فَصْلٌ · ١","segs":[["matn","وَلَا تُدْفَعُ إِلَى هَاشِمِيٍّ وَمُطَّلِبِيٍّ وَمَوَالِيهِمَا، وَلَا إِلَى فَقِيرَةٍ تَحْتَ غَنِيٍّ مُنْفِقٍ، وَلَا إِلَى فَرْعِهِ وَأَصْلِهِ، وَلَا إِلَى عَبْدٍ وَزَوْجٍ، وَإِنْ أَعْطَاهَا لِمَنْ ظَنَّهُ غَيْرَ أَهْلٍ فَبَانَ أَهْلًا أَوْ بِالْعَكْسِ لَمْ يُجْزِئْهُ، إِلَّا لِغَنِيٍّ ظَنَّهُ فَقِيرًا."]]},{"id":"za55_2","label":"بَابٌ · فَصْلٌ · ٢","segs":[["matn","وَصَدَقَةُ التَّطَوُّعِ مُسْتَحَبَّةٌ، وَفِي رَمَضَانَ وَأَوْقَاتِ الْحَاجَاتِ أَفْضَلُ، وَتُسَنُّ بِالْفَاضِلِ عَنْ كِفَايَتِهِ وَمَنْ يَمُونُهُ، وَيَأْثَمُ بِمَا يُنْقِصُهَا."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"za56","title":"كِتَابُ الصِّيَامِ","units":[{"id":"za56_1","label":"كِتَابُ الصِّيَامِ · ١","segs":[["matn","يَجِبُ صَوْمُ رَمَضَانَ بِرُؤْيَةِ هِلَالِهِ، فَإِنْ لَمْ يُرَ مَعَ صَحْوٍ لَيْلَةَ الثَّلَاثِينَ أَصْبَحُوا مُفْطِرِينَ وَإِنْ حَالَ دُونَهُ غَيْمٌ أَوْ قَتَرٌ فَظَاهِرُ الْمَذْهَبِ يَجِبُ صَوْمُهُ، وَإِنْ رُؤِيَ نَهَارًا فَهْوَ لِلَّيْلَةِ الْمُقْبِلَةِ،"]]},{"id":"za56_2","label":"كِتَابُ الصِّيَامِ · ٢","segs":[["matn","وَإِذَا رَآهُ أَهْلُ بَلَدٍ لَزِمَ النَّاسَ كُلَّهُمُ الصَّوْمُ، وَيُصَامُ بِرُؤْيَةِ عَدْلٍ وَلَوْ أُنْثَى، فَإِنْ صَامُوا بِشَهَادَةِ وَاحِدٍ ثَلَاثِينَ يَوْمًا فَلَمْ يُرَ الْهِلَالُ أَوْ صَامُوا لِأَجْلِ غَيْمٍ لَمْ يُفْطِرُوا،"]]},{"id":"za56_3","label":"كِتَابُ الصِّيَامِ · ٣","segs":[["matn","وَمَنْ رَأَى وَحْدَهُ هِلَالَ رَمَضَانَ وَرُدَّ قَوْلُهُ أَوْ رَأَى هِلَالَ شَوَّالٍ صَامَ."]]},{"id":"za56_4","label":"كِتَابُ الصِّيَامِ · ٤","segs":[["matn","وَيَلْزَمُ الصَّوْمُ لِكُلِّ مُسْلِمٍ مُكَلَّفٍ قَادِرٍ. وَإِذَا قَامَتْ الْبَيِّنَةُ فِي أَثْنَاءِ النَّهَارِ وَجَبَ الْإِمْسَاكُ وَالْقَضَاءُ عَلَى كُلِّ مَنْ صَارَ فِي أَثْنَائِهِ أَهْلًا لِوُجُوبِهِ، وَكَذَا حَائِضٌ وَنُفَسَاءُ طَهُرَتَا، وَمُسَافِرٌ قَدِمَ مُفْطِرًا،"]]},{"id":"za56_5","label":"كِتَابُ الصِّيَامِ · ٥","segs":[["matn","وَمَنْ أَفْطَرَ لِكِبَرٍ أَوْ مَرَضٍ لَا يُرْجَى بُرْؤُهُ أَطْعَمَ لِكُلِّ يَوْمٍ مِسْكِينًا، وَسُنَّ لِمَرِيضٍ يَضُرُّهُ، وَلِمُسَافِرٍ يَقْصُرُ، وَإِنْ نَوَى حَاضِرٌ صَوْمَ يَوْمٍ ثُمَّ سَافَرَ فِي أَثْنَائِهِ فَلَهُ الْفِطْرُ،"]]},{"id":"za56_6","label":"كِتَابُ الصِّيَامِ · ٦","segs":[["matn","وَإِنْ أَفْطَرَتْ حَامِلٌ أَوْ مُرْضِعٌ خَوْفًا عَلَى أَنْفُسِهِمَا قَضَتَاهُ فَقَطْ، وَعَلَى وَلَدَيْهِمَا قَضَتَا وَأَطْعَمَتَا لِكُلِّ يَوْمٍ مِسْكِينًا، وَمَنْ نَوَى الصَّوْمَ ثُمَّ جُنَّ أَوْ أُغْمِيَ عَلَيْهِ جَمِيعَ النَّهَارِ وَلَمْ يُفِقْ جُزْءًا مِنْهُ لَمْ يَصِحَّ صَوْمُهُ،"]]},{"id":"za56_7","label":"كِتَابُ الصِّيَامِ · ٧","segs":[["matn","لَا إِنْ نَامَ جَمِيعَ النَّهَارِ، وَيَلْزَمُ الْمُغْمَى عَلَيْهِ الْقَضَاءُ فَقَطْ وَيَجِبُ تَعْيِينُ النِّيَّةِ مِنْ اللَّيْلِ لِصَوْمِ كُلِّ يَوْمٍ وَاجِبٍ، لَا نِيَّةَ الْفَرْضِيَّةِ، وَيَصِحُّ النَّفْلُ بِنِيَّةٍ مِنْ النَّهَارِ قَبْلَ الزَّوَالِ وَبَعْدَهُ،"]]},{"id":"za56_8","label":"كِتَابُ الصِّيَامِ · ٨","segs":[["matn","وَلَوْ نَوَى إِنْ كَانَ غَدًا مِنْ رَمَضَانَ فَهُوَ فَرْضِي لَمْ يُجْزِئْهُ، وَمَنْ نَوَى الْإِفْطَارَ أَفْطَرَ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"za57","title":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ","units":[{"id":"za57_1","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · ١","segs":[["matn","مَنْ أَكَلَ أَوْ شَرِبَ أَوْ اسْتَعَطَ أَوِ احْتَقَنَ أَوِ اكْتَحَلَ بِمَا يَصِلُ إِلَى حَلْقِهِ، أَوْ أَدْخَلَ إِلَى جَوْفِهِ شَيْئًا غَيْرَ إِحْلِيلِهِ،"]]},{"id":"za57_2","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · ٢","segs":[["matn","أَوِ اسْتَقَاءَ أَوْ اسْتَمْنَى أَوْ بَاشَرَ فَأَمْنَى أَوْ أَمْذَى أَوْ كَرَّرَ النَّظَرَ فَأَنْزَلَ أَوْ حَجَمَ أَوْ احْتَجَمَ وَظَهَرَ دَمٌ عَامِدًا ذَاكِرًا لِصَوْمِهِ فَسَدَ لَا نَاسِيًا أَوْ مُكْرَهًا، أَوْ طَارَ إِلَى حَلْقِهِ ذُبَابٌ أَوْ غُبَارٌ،"]]},{"id":"za57_3","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · ٣","segs":[["matn","أَوْ فَكَّرَ فَأَنْزَلَ أَوْ احْتَلَمَ أَوْ أَصْبَحَ فِي فِيهِ طَعَامٌ فَلَفَظَهُ، أَوْ اغْتَسَلَ أَوْ تَمَضْمَضَ أَوْ اسْتَنْثَرَ أَوْ زَادَ عَلَى الثَّلَاثِ أَوْ بَالَغَ فَدَخَلَ الْمَاءُ حَلْقَهُ لَمْ يَفْسُدْ،"]]},{"id":"za57_4","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · ٤","segs":[["matn","وَمَنْ أَكَلَ شَاكًّا فِي طُلُوعِ فَجْرِ صَحَّ صَوْمُهُ، لَا إِنْ أَكَلَ شَاكًّا فِي غُرُوبِ الشَّمْسِ أَوْ مُعْتَقِدًا أَنَّهُ لَيْلٌ فَبَانَ نَهَارًا."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"za58","title":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · فَصْلٌ","units":[{"id":"za58_1","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · فَصْلٌ · ١","segs":[["matn","وَمَنْ جَامَعَ فِي نَهَارِ رَمَضَانَ فِي قُبُلٍ أَوْ دُبُرٍ فَعَلَيْهِ الْقَضَاءُ وَالْكَفَّارَةُ، وَإِنْ جَامَعَ دُونَ الْفَرْجِ فَأَنْزَلَ أَوْ كَانَتِ الْمَرْأَةُ مَعْذُورَةً أَوْ جَامَعَ مَنْ نَوَى الصَّوْمَ فِي سَفَرِهِ أَفْطَرَ وَلَا كَفَّارَةَ،"]]},{"id":"za58_2","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ جَامَعَ فِي يَوْمَيْنِ أَوْ كَرَّرَهُ فِي يَوْمٍ وَلَمْ يُكَفِّرْ فَكَفَّارَةٌ وَاحِدَةٌ فِي الثَّانِيَةِ، وَفِي الْأُولَى اثْنَتَانِ، وَإِنْ جَامَعَ ثُمَّ كَفَّرَ ثُمَّ جَامَعَ فِي يَوْمِهِ فَكَفَّارَةٌ ثَانِيَةٌ، وَكَذَلِكَ مَنْ لَزِمَهُ الْإِمْسَاكُ إِذَا جَامَعَ،"]]},{"id":"za58_3","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ وَيُوجِبُ الْكَفَّارَةَ · فَصْلٌ · ٣","segs":[["matn","وَمَنْ جَامَعَ وَهُوَ مُعَافَى ثُمَّ مَرِضَ أَوْ جُنَّ أَوْ سَافَرَ لَمْ تَسْقُطْ، وَلَا تَجِبُ الْكَفَّارَةُ بِغَيْرِ الْجِمَاعِ فِي صِيَامِ رَمَضَانَ، وَهِيَ عِتْقُ رَقْبَةٍ، فَإِنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ، فَإِنْ لَمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا، فَإِنْ لَمْ يَجِدْ سَقَطَتْ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"za59","title":"بَابُ مَا يُكْرَهُ وَيُسْتَحَبُّ وَحُكْمُ الْقَضَاءِ","units":[{"id":"za59_1","label":"بَابُ مَا يُكْرَهُ وَيُسْتَحَبُّ وَحُكْمُ الْقَضَاءِ · ١","segs":[["matn","يُكْرَهُ جَمْعُ رِيقِهِ فَيَبْتَلِعَهُ، وَيَحْرُمُ بَلْعُ النُّخَامَةِ وَيُفْطِرُ بِهَا فَقَطْ إِنْ وَصَلَتْ إِلَى فَمِهِ وَيُكْرَهُ ذَوْقُ طَعَامٍ بِلَا حَاجِةٍ، وَمَضْغُ عِلْكٍ قَوِيٍّ، وَإِنْ وَجَدَ طَعْمَهَمَا فِي حَلْقِهِ أَفْطَرَ وَيَحْرُمُ الْعِلْكُ الْمُتَحَلِّلُ إِنْ بَلَعَ رِيقَهُ،"]]},{"id":"za59_2","label":"بَابُ مَا يُكْرَهُ وَيُسْتَحَبُّ وَحُكْمُ الْقَضَاءِ · ٢","segs":[["matn","وَتُكْرَهُ الْقُبْلَةُ لِمَنْ تُحَرِّكُ شَهْوَتَهُ، وَيَجِبُ اجْتِنَابُ كَذِبٍ وَغِيبَةٍ وَشَتْمٍ، وَسُنَّ لِمَنْ شُتِمَ قَوْلُهُ: «إِنِّي صَائِمٌ، وَتَأْخِيرُ سُحُورٍ وَتَعْجِيلُ فِطْرٍ عَلَى رُطَبٍ، فَإِنْ عُدِمَ فَتَمْرٌ، فَإِنْ عُدِمَ فَمَاءٌ، وَقَوْلُ مَا وَرَدَ.»"]]},{"id":"za59_3","label":"بَابُ مَا يُكْرَهُ وَيُسْتَحَبُّ وَحُكْمُ الْقَضَاءِ · ٣","segs":[["matn","«وَيُسْتَحَبُّ الْقَضَاءُ مُتَتَابِعًا، وَلَا يَجُوزُ إِلَى رَمَضَانَ آخَرَ مِنْ غَيْرِ عُذْرٍ، فَإِنْ فَعَلَ فَعَلَيْهِ مَعَ الْقَضَاءِ إِطْعَامُ مِسْكِينٍ لِكُلِّ يَوْمٍ، وَإِنْ مَاتَ، وَلَوْ بَعْدَ رَمَضَانَ آخَرَ، وَإِنْ مَاتَ وَعَلَيْهِ صَوْمٌ أَوْ حَجٌّ أَوْ اعْتِكَافٌ أَوْ صَلَاةُ نَذْرٍ اسْتُحِبَّ لِوَلِيِّهِ قَضَاؤُهُ. »"]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"za60","title":"بَابُ صَوْمِ التَّطَوُّعِ","units":[{"id":"za60_1","label":"بَابُ صَوْمِ التَّطَوُّعِ · ١","segs":[["matn","يُسَنُّ صِيَامُ أَيَّامِ الْبِيضِ، وَالِاثْنَيْنِ وَالْخَمِيسِ، وَسِتٍّ مِنْ شَوَّالٍ، وَشَهْرِ الْمُحَرَّمِ وَآكَدُهُ الْعَاشِرُ ثُمَّ التَّاسِعُ وَتِسْعِ ذِي الْحِجَّةِ، وَيَوْمِ عَرَفَةَ لِغَيْرِ حَاجٍّ بِهَا، وَأَفْضَلُهُ صَوْمُ يَوْمٍ وَفِطْرُ يَوْمٍ، وَيُكْرَهُ إِفْرَادُ رَجَبٍ وَالْجُمُعَةِ وَالسَّبْتِ وَالشَّكِّ،"]]},{"id":"za60_2","label":"بَابُ صَوْمِ التَّطَوُّعِ · ٢","segs":[["matn","وَيَحْرُمُ صَوْمُ الْعِيدَيْنِ وَلَوْ فِي فَرْضٍ، وَصِيَامُ أَيَّامِ التَّشْرِيقِ إِلَّا عَنْ دَمِ مُتْعَةٍ وَقِرَانٍ، وَمَنْ دَخَلَ فِي فَرْضٍ مُوَسَّعٍ حَرُمَ قَطْعُهُ، وَلَا يَلْزَمُ فِي النَّفْلِ، وَلَا قَضَاءُ فَاسِدِهِ إِلَّا الْحَجُّ،"]]},{"id":"za60_3","label":"بَابُ صَوْمِ التَّطَوُّعِ · ٣","segs":[["matn","وَتُرْجَى لَيْلَةُ الْقَدْرِ فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ، وَأَوْتَارُهُ آكَدُ، وَلَيْلَةُ سَبْعٍ وَعِشْرِينَ أَبْلَغُ، وَيَدْعُو فِيهَا بِمَا وَرَدَ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"za61","title":"بَابُ الِاعْتِكَافِ","units":[{"id":"za61_1","label":"بَابُ الِاعْتِكَافِ · ١","segs":[["matn","هُوَ لُزُومُ مَسْجِدٍ لِطَاعَةِ اللَّهِ تَعَالَى مَسْنُونٌ، وَيَصِحُّ بِلَا صَوْمٍ وَيَلْزَمَانِ بِالنَّذْرِ، وَلَا يَصِحُّ إِلَّا فِي مَسْجِدٍ يُجَمَّعُ فِيهِ إِلَّا الْمَرْأَةُ فَفِي كُلِّ مَسْجِدٍ سِوَى مَسْجِدِ بَيْتِهَا،"]]},{"id":"za61_2","label":"بَابُ الِاعْتِكَافِ · ٢","segs":[["matn","وَمَنْ نَذَرَهُ أَوِ الصَّلَاةَ فِي مَسْجِدٍ غَيْرِ الثَّلَاثَةِ وَأَفْضَلُهَا الْحَرَامُ، فَمَسْجِدُ الْمَدِينَةِ، فَالْأَقْصَى لَمْ يَلْزَمْهُ فِيهِ، وَإِنْ عَيَّنَ الْأَفْضَلَ لَمْ يُجْزِ فِيمَا دُونَهُ، وَعَكْسُهُ بِعَكْسِهِ،"]]},{"id":"za61_3","label":"بَابُ الِاعْتِكَافِ · ٣","segs":[["matn","وَمَنْ نَذَرَ زَمَنًا مُعَيَّنًا دَخَلَ مُعْتَكَفَهُ قَبْلَ لَيْلَتِهِ الْأُولَى وَخَرَجَ بَعْدَ آخِرِهِ، وَلَا يَخْرُجُ الْمُعْتَكِفُ إِلَّا لِمَا لَابُدَّ مِنْهُ، وَلَا يَعُودُ مَرِيضًا، وَلَا يَشْهَدُ جَنَازَةً إِلَّا أَنْ يَشْتَرِطَهُ، وَإِنْ وَطِئَ فِي فَرْجٍ فَسَدَ اعْتِكَافُهُ، وَيُسْتَحَبُّ اشْتِغَالُهُ بِالْقُرَبِ وَاجْتِنَابُ مَا لَا يَعْنِيهِ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"za62","title":"كِتَابُ الْمَنَاسِكِ","units":[{"id":"za62_1","label":"كِتَابُ الْمَنَاسِكِ · ١","segs":[["matn","الْحَجُّ وَالْعُمْرَةُ وَاجِبَانِ عَلَى الْمُسْلِمِ الْحُرِّ الْمُكَلَّفِ الْقَادِرِ فِي عُمُرِهِ مَرَّةً عَلَى الْفَوْرِ، فَإِنْ زَالَ الرِّقُّ وَالْجُنُونُ وَالصِّبَا فِي الْحَجِّ بِعَرَفَةَ وَفِي الْعُمْرَةِ قَبْلَ طَوَافِهَا صَحَّ فَرْضًا، وَفِعْلُهُمَا مِنْ الصَّبِيِّ وَالْعَبْدِ نَفْلًا،"]]},{"id":"za62_2","label":"كِتَابُ الْمَنَاسِكِ · ٢","segs":[["matn","وَالْقَادِرُ مَنْ أَمْكَنَهُ الرُّكُوبُ وَوَجَدَ زَادًا وَرَاحِلَةً صَالِحَيْنِ لِمِثْلِهِ بَعْدَ قَضَاءِ الْوَاجِبَاتِ وَالنَّفَقَاتِ الشَّرْعِيَّةِ وَالْحَوَائِجِ الْأَصْلِيَّةِ،"]]},{"id":"za62_3","label":"كِتَابُ الْمَنَاسِكِ · ٣","segs":[["matn","وَإِنْ أَعْجَزَهُ كِبَرٌ أَوْ مَرَضٌ لَا يُرْجَى بُرْؤُهُ لَزِمَهُ أَنْ يُقِيمَ مَنْ يَحُجُّ وَيَعَتَمِرُ عَنْهُ مِنْ حَيْثُ وَجَبَا وَيُجْزِئُ عَنْهُ، وَإِنْ عُوفِيَ بَعْدَ الْإِحْرَامِ،"]]},{"id":"za62_4","label":"كِتَابُ الْمَنَاسِكِ · ٤","segs":[["matn","وَيُشْتَرَطُ لِوُجُوبِهِ عَلَى الْمَرْأَةِ وُجُودُ مَحْرَمِهَا وَهُوَ زَوْجُهَا أَوْ مَنْ تَحْرُمُ عَلَيْهِ عَلَى التَّأْبِيدِ بِنَسَبٍ أَوْ سَبَبٍ مُبَاحٍ، وَإِنْ مَاتَ مَنْ لَزِمَاهُ أُخْرِجَا مِنْ تَرِكَتِهِ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za63","title":"بَابُ الْمَوَاقِيتِ","units":[{"id":"za63_1","label":"بَابُ الْمَوَاقِيتِ · ١","segs":[["matn","وَمِيقَاتُ أَهْلِ الْمَدِينَةِ ذُو الْحُلَيْفَةِ، وَأَهْلِ الشَّامِ وَمِصْرَ وَالْمَغْرِبِ الْجُحْفَةُ، وَأَهْلِ الْيَمَنِ يَلَمْلَمُ، وَأَهْلِ نَجْدٍ قَرْنٌ، وَأَهْلِ الْمَشْرِقِ ذَاتُ عِرْقٍ، وَهِيَ لِأَهْلِهَا وَلِمَنْ مَرَّ عَلَيْهَا مِنْ غَيْرِهِمْ، وَمَنْ حَجَّ مِنْ أَهْلِ مَكَّةَ فَمِنْهَا،"]]},{"id":"za63_2","label":"بَابُ الْمَوَاقِيتِ · ٢","segs":[["matn","وَعُمْرَتُهُ مِنْ الْحِلِّ، وَأَشْهُرُ الْحَجِّ شَوَّالٌ وَذُو الْقَعْدَةِ وَعَشْرٌ مِنْ ذِي الْحِجَّةِ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za64","title":"بَابٌ","units":[{"id":"za64_1","label":"بَابٌ · ١","segs":[["matn","الْإِحْرَامُ نِيَّةُ النُّسُكِ، سُنَّ لِمُرِيدِهِ غُسْلٌ أَوْ تَيَمُّمٌ لِعَدَمٍ وَتَنَظُّفٌ، وَتَطَيُّبٌ، وَتَجَرُّدٌ مِنْ مَخِيْطٍ، وَيَحْرُمُ فِي إِزَارٍ وَرِدَاءٍ أَبْيَضَيْنِ، وَإِحْرَامٌ عَقِبَ رَكْعَتَيْنِ وَنِيَّتُهُ شَرْطٌ، وَيُسْتَحَبُّ قَوْلُهُ: «اللَّهُمَّ إِنِّي أُرِيدُ نُسُكَ كَذَا فَيَسِّرْهُ لِي،»"]]},{"id":"za64_2","label":"بَابٌ · ٢","segs":[["matn","«وَإِنْ حَبَسَنِي حَابِسٌ فَمَحِلِّي حَيْثُ حَبَسْتَنِي، وَأَفْضَلُ الْأَنْسَاكِ التَّمَتُّعُ، وَصِفَتُهُ أَنْ يُحْرِمَ بِالْعُمْرَةِ فِي أَشْهُرِ الْحَجِّ وَيَفْرُغَ مِنْهَا ثُمَّ يُحْرِمَ بِالْحَجِّ فِي عَامِهِ، وَعَلَى الْأُفُقِيِّ دَمٌ،»"]]},{"id":"za64_3","label":"بَابٌ · ٣","segs":[["matn","«وَإِنْ حَاضَتْ الْمَرْأَةُ فَخَشِيَتْ فَوَاتَ الْحَجِّ أَحْرَمَتْ بِهِ وَصَارَتْ قَارِنَةً، وَإِذَا اسْتَوَى عَلَى رَاحِلَتِهِ قَالَ:» لَبَّيْكَ اللَّهُمْ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ، يُصَوِّتُ بِهَا الرَّجُلُ وَتُخْفِيهَا الْمَرْأَةُ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za65","title":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ","units":[{"id":"za65_1","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ١","segs":[["matn","وَهِيَ تِسْعَةٌ: حَلْقُ الشَّعْرِ وَتَقْلِيمُ الْأَظْفَارِ، فَمَنْ حَلَقَ أَوْ قَلَّمَ ثَلَاثَةً فَعَلَيْهِ دَمٌ، وَمَنْ غَطَّى رَأْسَهُ بِمُلَاصِقٍ فَدَى، وَإِنْ لَبِسَ ذَكَرٌ مَخِيْطًا فَدَى،"]]},{"id":"za65_2","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٢","segs":[["matn","وَإِنْ طَيَّبَ بَدَنَهُ أَوْ ثَوْبَهُ أَوْ ادَّهَنَ بِمُطَيَّبٍ أَوْ شَمَّ طِيبًا أَوْ تَبَخَّرَ بِعُودٍ وَنَحْوِهِ فَدَى، وَإِنْ قَتَلَ صَيْدًا مَأْكُولًا بَرِّيًّا أَصْلًا وَلَوْ تَوَلَّدَ مِنْهُ وَمِنْ غَيْرِهِ أَوْ تَلِفَ فِي يَدِهِ فَعَلَيْهِ جَزَاؤُهُ،"]]},{"id":"za65_3","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٣","segs":[["matn","وَلَا يَحْرُمُ حَيْوَانٌ إِنْسِيٌّ، وَلَا صَيْدُ الْبَحْرِ، وَلَا قَتْلُ مُحَرَّمِ الْأَكْلِ وَلَا الصَّائِلُ، وَيَحْرُمُ عَقْدُ نِكَاحٍ وَلَا يَصِحُّ وَلَا فِدْيَةَ، وَتَصِحُّ الرَّجْعَةُ، وَإِنْ جَامَعَ الْمُحْرِمُ قَبْلَ التَّحَلُّلِ الْأَوَّلِ فَسَدَ نُسُكُهُمَا وَيَمْضِيَانِ فِيهِ وَيَقْضِيَانِهِ ثَانِيَ عَامٍ،"]]},{"id":"za65_4","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٤","segs":[["matn","وَتَحْرُمُ الْمُبَاشَرَةُ، فَإِنْ فَعَلَ فَأَنْزَلَ لَمْ يَفْسُدْ حَجُّهُ وَعَلَيْهِ بَدَنَةٌ لَكِنْ يُحْرِمُ مِنَ الْحِلِّ لِطَوَافِ الْفَرْضِ، وَإِحْرَامُ الْمَرْأَةِ كَالرَّجُلِ إِلَّا فِي اللِّبَاسِ وَتَجْتَنِبُ الْبُرْقُعَ وَالْقُفَّازَيْنِ وَتَغْطِيَةَ وَجْهِهَا وَيُبَاحُ لَهَا التَّحَلِّيَ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za66","title":"بَابُ الْفِدْيَةِ","units":[{"id":"za66_1","label":"بَابُ الْفِدْيَةِ · ١","segs":[["matn","يُخَيَّرُ، بِفِدْيَةِ حَلْقٍ وَتَقْلِيمٍ وَتَغْطِيَةِ رَأْسٍ وَطِيبٍ بَيْنَ صِيَامِ ثَلَاثَةِ أَيَّامٍ، أَوْ إِطْعَامِ سِتَّةِ مَسَاكِينَ، لِكُلِّ مِسْكِينٍ مُدُّ بُرٍّ أَوْ نِصْفُ صَاعِ تَمْرٍ أَوْ شَعِيرٍ أَوْ ذَبْحُ شَاةٍ،"]]},{"id":"za66_2","label":"بَابُ الْفِدْيَةِ · ٢","segs":[["matn","وَبِجَزَاءِ صَيْدٍ بَيْنَ مِثْلٍ إِنْ كَانَ أَوْ تَقْوِيمِهِ بِدَرَاهِمَ يَشْتَرِي بِهَا طَعَامًا فَيُطْعِمُ كُلَّ مِسْكِيْنٍ مُدًّا، أَوْ يَصُومُ عَنْ كُلِّ مُدٍّ يَوْمًا، وَبِمَا لَا مِثْلَ لَهُ بَيْنَ إِطْعَامٍ وَصِيْامٍ، وَأَمَّا دَمُ مُتْعَةٍ وَقِرَانٍ فَيَجِبُ الْهَدْيُ،"]]},{"id":"za66_3","label":"بَابُ الْفِدْيَةِ · ٣","segs":[["matn","فَإِنْ عَدِمَهُ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ، وَالْأَفْضَلُ كَوْنُ آخِرِهَا يَوْمَ عَرَفَةَ، وَسَبْعَةٍ إِذَا رَجَعَ إِلَى أَهْلِهِ، وَالْمُحْصَرُ إِذَا لَمْ يَجِدْ هَدْيًا صَامَ عَشَرَةً ثُمَّ حَلَّ، وَيَجِبُ بِوَطْءٍ فِي فَرْجٍ فِي الْحَجِّ بَدَنَةٌ، وَفِي الْعُمْرَةِ شَاةٌ، وَإِنْ طَاوَعَتْهُ زَوْجَتُهُ لَزِمَاهَا."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za67","title":"بَابُ الْفِدْيَةِ · فَصْلٌ","units":[{"id":"za67_1","label":"بَابُ الْفِدْيَةِ · فَصْلٌ · ١","segs":[["matn","وَمَنْ كَرَّرَ مَحْظُورًا مِنْ جِنْسٍ وَلَمْ يَفْدِ فَدَى مَرَّةً بِخِلَافِ صَيْدٍ، وَمَنْ فَعَلَ مَحْظُورًا مِنْ أَجْنَاسٍ فَدَى لِكُلٍّ مَرَّةً رَفَضَ إِحْرَامَهُ أَوْ لَا، وَيَسْقُطُ بِنِسْيَانٍ فِدْيَةُ لُبْسٍ وَطِيبٍ، وَتَغْطِيَةِ رَأْسٍ دُونَ وَطْءٍ، وَصَيْدٍ وَتَقْلِيمٍ وَحِلَاقٍ،"]]},{"id":"za67_2","label":"بَابُ الْفِدْيَةِ · فَصْلٌ · ٢","segs":[["matn","وَكُلُّ هَدْيٍ أَوْ إِطْعَامٍ لِمَسَاكِينِ الْحَرَمِ، وَفِدْيَةُ الْأَذَى وَاللُّبْسِ وَنَحْوِهِمَا وَدَمُ الْإِحْصَارِ حَيْثُ وُجِدَ سَبَبُهُ، وَيُجْزِئُ الصَّوْمُ بِكُلِّ مَكَانٍ، وَالدَّمُ شَاةٌ أَوْ سُبُعُ بَدَنَةٍ وَتُجْزِئُ عَنْهَا بَقَرَةٌ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za68","title":"بَابُ جَزَاءِ الصَّيْدِ","units":[{"id":"za68_1","label":"بَابُ جَزَاءِ الصَّيْدِ · ١","segs":[["matn","فِي النَّعَامَةِ بَدَنَةٌ وَحِمَارِ الْوَحْشِ وَبَقَرَتِهِ وَالْإِيَّلِ وَالثَّيْتَلِ وَالْوَعْلِ بَقَرَةٌ، وَالضَّبُعِ كَبْشٌ، وَالْغَزَالَةِ عَنْزٌ، وَالْوَبْرِ وَالضَّبِّ جَدْيٌ، وَالْيَرْبُوعِ جَفْرَةٌ، وَالْأَرْنَبِ عَنَاقٌ وَالْحَمَامَةِ شَاةٌ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za69","title":"بَابُ صَيْدِ الْحَرَمِ","units":[{"id":"za69_1","label":"بَابُ صَيْدِ الْحَرَمِ · ١","segs":[["matn","يَحْرُمُ صَيْدُهُ عَلَى الْمُحْرِمِ وَالْحَلَالِ، وَحُكْمُ صَيْدِهِ كَصَيْدِ الْمُحْرِمِ، وَيَحْرُمُ قَطْعُ شَجَرِهِ وَحَشِيشِهِ الْأَخْضَرَيْنِ إِلَّا الْإِذْخِرَ، وَيَحْرُمُ صَيْدُ الْمَدِيْنَةِ وَلَا جَزَاءَ، فِيهِ وَيُبَاحُ الْحَشِيشُ لِلْعَلَفِ وَآلَةِ الْحَرْثِ وَنَحْوِهِ، وَحَرَمُهَا مَا بَيْنَ عَيْرٍ إِلَى ثَوْرٍ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za70","title":"بَابُ دُخُولِ مَكَّةَ","units":[{"id":"za70_1","label":"بَابُ دُخُولِ مَكَّةَ · ١","segs":[["matn","يُسَنُّ مِنْ أَعْلَاهَا وَالْمَسْجِدِ مِنْ بَابِ بَنِي شَيْبَةَ، فَإِذَا رَأَى الْبَيْتَ رَفَعَ يَدَيْهِ وَقَالَ مَا وَرَدَ، ثُمَّ يَطُوفُ مُضْطَبِعًا، يَبْتَدِئُ الْمُعْتَمِرُ بِطَوَافِ الْعُمْرَةِ، وَالْقَارِنُ وَالْمُفْرِدُ لِلْقُدُومِ، فَيُحَاذِي الْحَجَرَ الْأَسْوَدَ، بِكُلِّهِ وَيَسْتَلِمُهُ وَيُقَبِّلُهُ،"]]},{"id":"za70_2","label":"بَابُ دُخُولِ مَكَّةَ · ٢","segs":[["matn","فَإِنْ شَقَّ قَبَّلَ يَدَهُ، فَإِنْ شَقَّ اللَّمْسُ أَشَارَ إِلَيْهِ وَيَقُولُ مَا وَرَدَ، وَيَجْعَلُ الْبَيْتَ عَنْ يَسَارِهِ وَيَطُوفُ سَبْعًا يَرْمُلُ الْأُفُقِيُّ فِي هَذَا الطَّوَافِ ثَلَاثًا ثُمَّ يَمْشِي أَرْبَعًا وَيَسْتَلِمُ الْحَجَرَ وَالرُّكْنَ الْيَمَانِيَّ كُلَّ مَرَّةٍ،"]]},{"id":"za70_3","label":"بَابُ دُخُولِ مَكَّةَ · ٣","segs":[["matn","وَمَنْ تَرَكَ شَيْئًا مِنْ الطَّوَافِ أَوْ لَمْ يَنْوِهِ أَوْ نُسُكَهُ أَوْ طَافَ عَلَى الشَّاذَرْوَانِ أَوْ جِدَارِ الْحِجْرِ أَوْ عُرْيَانٌ أَوْ نَجِسًا لَمْ يَصِحَّ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ خَلْفَ الْمَقَامِ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za71","title":"بَابُ دُخُولِ مَكَّةَ · فَصْلٌ","units":[{"id":"za71_1","label":"بَابُ دُخُولِ مَكَّةَ · فَصْلٌ · ١","segs":[["matn","ثُمَّ يَسْتَلِمُ الْحَجَرَ، وَيَخْرُجُ إِلَى الصَّفَا مِنْ بَابِهِ فَيَرْقَاهُ حَتَّى يَرَى الْبَيْتَ وَيُكَبِّرُ ثَلَاثًا وَيَقُولُ مَا وَرَدَ، ثُمَّ يَنْزِلُ مَاشِيًا إِلَى الْعَلَمِ الْأَوَّلِ، ثُمَّ يَسْعَى شَدِيدًا إِلَى الْآخَرِ،"]]},{"id":"za71_2","label":"بَابُ دُخُولِ مَكَّةَ · فَصْلٌ · ٢","segs":[["matn","ثُمَّ يَمْشِي وَيَرْقَى الْمَرْوَةَ وَيَقُولُ مَا قَالَهُ عَلَى الصَّفَا، ثُمَّ يَنْزِلُ فَيَمْشِي فِي مَوْضِعِ مَشْيِهِ وَيَسْعَى فِي مَوْضِعِ سَعْيِهِ إِلَى الصَّفَا يَفْعَلُ ذَلِكَ سَبْعًا: ذَهَابُهُ سَعْيَةٌ وَرُجُوعُهُ سَعْيَةٌ، فَإِنْ بَدَأَ بِالْمَرْوَةِ سَقَطَ الشَّوْطُ الْأَوَّلُ،"]]},{"id":"za71_3","label":"بَابُ دُخُولِ مَكَّةَ · فَصْلٌ · ٣","segs":[["matn","وَتُسَنُّ فِيهُ الطَّهَارَةُ وَالسِّتَارَةُ وَالْمُوَالَاةُ، ثُمَّ إِنْ كَانَ مُتَمَتِّعًا لَا هَدْيَ مَعَهُ قَصَّرَ مِنْ شَعْرِهِ وَتَحَلَّلَ، وَإِلَّا حَلَّ إِذَا حَجَّ وَالْمُتَمَتِّعُ إِذَا شَرَعَ فِي الطَّوَافِ قَطَعَ التَّلْبِيَةَ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za72","title":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ","units":[{"id":"za72_1","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ١","segs":[["matn","يُسَنُّ لِلْمُحِلِّينَ بِمَكَّةَ الْإِحْرَامُ بِالْحَجِّ يَوْمَ التَّرْوِيَةِ قَبْلَ الزَّوَالِ مِنْهَا وَيُجْزِئُ مِنْ بَقِيَّةِ الْحَرَمِ، وَيَبِيتُ بِمِنًى، فَإِذَا طَلَعَتِ الشَّمْسُ سَارَ إِلَى عَرَفَةَ، وَكُلُّهَا مَوْقِفٌ إِلَّا بَطْنَ عُرَنَةَ، وَسُنَّ أَنْ يَجْمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ،"]]},{"id":"za72_2","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ٢","segs":[["matn","وَيَقِفَ رَاكِبًا عِنْدَ الصَّخَرَاتِ وَجَبَلِ الرَّحْمَةِ وَيُكْثِرُ مِنْ الدُّعَاءِ وَمِمَّا وَرَدَ،"]]},{"id":"za72_3","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ٣","segs":[["matn","وَمَنْ وَقَفَ وَلَوْ لَحْظَةً مِنْ فَجْرِ يَوْمِ عَرَفَةَ إِلَى فَجْرِ يَوْمِ النَّحْرِ وَهُوَ أَهْلٌ لَهُ صَحَّ حَجُّهُ وَإِلَّا فَلَا وَمَنْ وَقَفَ نَهَارًا وَدَفَعَ قَبْلَ الْغُرُوبِ وَلَمْ يَعُدْ قَبْلَهُ فَعَلَيْهِ دَمٌ وَمَنْ وَقَفَ لَيْلًا فَقَطْ فَلَا،"]]},{"id":"za72_4","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ٤","segs":[["matn","ثُمَّ يَدْفَعُ بَعْدَ الْغُرُوبِ إِلَى مُزْدَلِفَةَ بِسَكِينَةٍ وَيُسْرِعُ فِي الْفَجْوَةِ وَيَجْمَعُ بِهَا بَيْنَ الْعِشَاءَيْنِ وَيَبِيتُ بِهَا، وَلَهُ الدَّفْعُ بَعْدَ نِصْفِ اللَّيْلِ، وَقَبْلَهُ فِيهِ دَمٌ، كَوُصُولِهِ إِلَيْهَا بَعْدَ الْفَجْرِ لَا قَبْلَهُ،"]]},{"id":"za72_5","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ٥","segs":[["matn","فَإِذَا صَلَّى الصُّبْحَ أَتَى الْمَشْعَرَ الْحَرَامَ فَرَقَاهُ، أَوْ يَقِفُ عَنْدَهُ وَيَحْمَدُ اللَّهَ وَيُكَبِّرُهُ وَيَقْرَأُ: ﴿فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ﴾ الْآيَتَيْنِ، وَيَدْعُو حَتَّى يُسْفِرَ،"]]},{"id":"za72_6","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ٦","segs":[["matn","فَإِذَا بَلَغَ مُحَسِّرًا أَسَرَعَ رَمْيَةَ حَجَرٍ وَأَخَذَ الْحَصَا وَعَدَدُهُ سَبْعُونَ بَيْنَ الْحِمِّصِ وَالْبُنْدُقِ فَإِذَا وَصَلَ إِلَى مِنَى وَهِيَ مِنْ وَادِي مُحَسِّرٍ إِلَى جَمْرَةِ الْعَقَبَةِ رَمَاهَا بِسَبْعِ حَصَيَاتٍ مُتَعَاقِبَاتٍ يَرْفَعُ يَدَهُ حَتَى يُرَى بَيَاضُ إِبْطِهِ وَيُكَبِّرُ مَعَ كُلِّ حَصَاةٍ،"]]},{"id":"za72_7","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ٧","segs":[["matn","وَلَا يُجْزِئُ الرَّمْيُ بِغَيْرِهَا، وَلَا بِهَا ثَانِيًا، وَلَا يَقِفُ، وَيَقْطَعُ التَّلْبِيَةَ قَبْلَهَا، وَيَرْمِي بَعْدَ طُلُوعِ الشَّمْسِ وَيُجْزِئُ بَعْدَ نِصْفِ اللَّيْلِ ثُمَّ يَنْحَرُ هَدْيًا إِنْ كَانَ مَعَهُ، وَيَحْلِقُ أَوْ يُقَصِّرُ مِنْ جَمِيعِ شَعْرِهِ،"]]},{"id":"za72_8","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · ٨","segs":[["matn","وَتُقَصِّرُ مِنْهُ الْمَرْأَةُ أُنْمُلَةً، ثُمَّ قَدْ حَلَّ لَهُ كُلُّ شَيْءٍ إِلَّا النِّسَاءَ، وَالْحِلَاقُ وَالتَّقْصِيرُ نُسُكٌ، لَا يَلْزَمُ بِتَأْخِيرِهِ دَمٌ، وَلَا بِتَقْدِيمِهِ عَلَى الرَّمْيِ وَالنَّحْرِ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za73","title":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ","units":[{"id":"za73_1","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ١","segs":[["matn","ثُمَّ يُفِيضُ إِلَى مَكَّةَ، وَيَطُوفُ الْقَارِنُ وَالْمُفْرِدُ بِنِيَّةِ الْفَرِيضَةِ طَوَافَ الزِّيَارَةِ، وَأَوَّلُ وَقْتِهِ بَعْدَ نِصْفِ لَيْلَةِ النَّحْرِ، وَيُسَنُّ فِي يَوْمِهِ وَلَهُ تَأْخِيرُهُ،"]]},{"id":"za73_2","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٢","segs":[["matn","ثُمَّ يَسْعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ إِنْ كَانَ مُتَمَتِّعًا أَوْ غَيْرَهُ وَلَمْ يَكُنْ سَعَى مَعَ طَوَافِ الْقُدُومِ، ثُمَّ قَدْ حَلَّ لَهُ كُلُّ شَيْءٍ ثُمَ يَشْرَبُ مِنْ مَاءِ زَمْزَمَ لِمَا أَحَبَّ، وَيَتَضَلَّعُ مِنْهُ وَيَدْعُو بِمَا وَرَدَ."]]},{"id":"za73_3","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٣","segs":[["matn","ثُمَّ يَرْجِعُ فَيَبِيتُ بِمِنًى ثَلَاثَ لَيَالٍ فَيَرْمِي الْجَمْرَةَ الْأُولَى، وَتَلِيَ مَسْجِدَ الْخَيْفِ سَبْعَ حَصَيَاتٍ وَيَجْعَلُهَا عَنْ يَسَارِهِ وَيَتَأَخَّرُ قَلِيلًا وَيَدْعُو طَوِيلًا، ثُمَّ الْوُسْطَى مِثْلَهَا، ثُمَّ جَمْرَةَ الْعَقَبَةِ وَيَجْعَلُهَا عَنْ يَمِينِهِ وَيَسْتَبْطِنُ الْوَادِيَ وَلَا يَقِفُ عِنْدَهَا،"]]},{"id":"za73_4","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٤","segs":[["matn","يَفْعَلُ هَذَا فِي كُلِّ يَوْمٍ مِنْ أَيَّامِ التَّشْرِيقِ بَعْدَ الزَّوَالِ مُسْتَقْبِلَ الْقِبْلَةِ مُرَتِّبًا فَإِنْ رَمَاهُ كُلَّهُ فِي الثَّالِثِ أَجْزَأَهُ وَيُرَتِّبُهُ بِنِيَّتِهِ، فَإِنْ أَخَّرَهُ عَنْهُ أَوْ لَمْ يَبِتْ بِهَا فَعَلَيْهِ دَمٌ،"]]},{"id":"za73_5","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٥","segs":[["matn","وَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ خَرَجَ قَبْلَ الْغُرُوبِ، وَإِلَّا لَزِمَهُ الْمَبِيتُ وَالرَّمْيُ مِنَ الْغَدِ، فَإِذَا أَرَادَ الْخُرُوجَ مِنْ مَكَّةَ لَمْ يَخْرُجْ حَتَى يَطُوفَ لِلْوَدَاعِ، فَإِنْ أَقَامَ أَوْ اتَّجَرَ بَعْدَهُ أَعَادَهُ،"]]},{"id":"za73_6","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٦","segs":[["matn","وَإِنْ تَرَكَهُ غَيْرُ حَائِضٍ رَجَعَ إِلَيْهِ فَإِنْ شَقَّ أَوْ لَمْ يَرْجِعْ فَعَلَيْهِ دَمٌ، وَإِنْ أَخَّرَ طَوَافَ الزِّيَارَةِ فَطَافَهُ عِنْدَ الْخُرُوجِ أَجْزَأَ عَنْ الْوَدَاعِ، وَيَقِفُ غَيْرُ الْحَائِضِ بَيْنَ الرُّكْنِ وَالْبَابِ دَاعِيًا بِمَا وَرَدَ،"]]},{"id":"za73_7","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٧","segs":[["matn","وَتَقِفُ الْحَائِضُ بِبَابِهِ وَتَدْعُو بِالدُّعَاءِ، وَتُسْتَحَبُّ زِيَارَةُ قَبْرِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَبْرَيْ صَاحِبَيْهِ."]]},{"id":"za73_8","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٨","segs":[["matn","وَصِفَةُ الْعُمْرَةِ أَنْ يُحْرِمَ بِهَا مِنَ الْمِيقَاتِ أَوْ مِنْ أَدْنَى الْحِلِّ مِنْ مَكِّيٍّ وَنَحْوِهِ لَا مِنَ الْحَرَمِ، فَإِذَا طَافَ وَسَعَى وَقَصَّرَ حَلَّ، وَتُبَاحُ كُلَّ وَقْتٍ وَتُجْزِئُ عَنْ الْفَرْضِ."]]},{"id":"za73_9","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ٩","segs":[["matn","وَأَرْكَانُ الْحَجِّ الْإِحْرَامُ، وَالْوُقُوفُ، وَطَوَافُ الزِّيَارِةِ، وَالسَّعْيُ. وَوَاجِبَاتُهُ الْإِحْرَامُ مِنَ الْمِيقَاتِ الْمُعْتَبَرِ لَهُ، وَالْوُقُوفُ بِعَرَفَةَ إِلَى الْغُرُوبِ، وَالْمَبِيتُ لِغَيْرِ أَهْلِ السِّقَايَةِ وَالرِّعَايَةِ بِمِنًى وَمُزْدَلِفَةَ إِلَى بَعْدِ نِصْفِ اللَّيْلِ، وَالرَّمْيُ، وَالْحِلَاقُ، وَالْوَدَاعُ، وَالْبَاقِي سُنَنٌ."]]},{"id":"za73_10","label":"بَابُ صِفَةِ الْحَجِّ وَالْعُمْرَةِ · فَصْلٌ · ١٠","segs":[["matn","وَأَرْكَانُ الْعُمْرَةِ إِحْرَامٌ، وَطَوَافٌ، وَسَعْيٌ. وَوَاجِبَاتُهَا الْحِلَاقُ، وَالْإِحْرَامُ مِنْ مِيقَاتِهَا، فَمَنْ تَرَكَ الْإِحْرَامَ لَمْ يَنْعَقِدْ نُسُكُهُ، وَمَنْ تَرَكَ رُكْنًا غَيْرَهُ أَوْ نِيَّتَهِ لَمْ يَتِمَّ نُسُكُهُ إِلَّا بِهِ، وَمَنْ تَرَكَ وَاجِبًا فَعَلَيْهِ دَمٌ، أَوْ سُنَّةً فَلَا شَيْءَ عَلَيْهِ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za74","title":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ","units":[{"id":"za74_1","label":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ · ١","segs":[["matn","مَنْ فَاتَهُ الْوُقُوفُ فَاتَهُ الْحَجُّ، وَتَحَلَّلَ بِعُمْرَةٍ وَيَقْضِي، وَيُهْدِي إِنْ لَمْ يَكُنْ اشْتَرَطَ، وَمَنْ صَدَّهُ عَدُوٌّ عَنِ الْبَيْتِ أَهْدَى ثُمَّ حَلَّ، فَإِنْ فَقَدَهُ صَامَ عَشَرَةَ أَيَّامٍ ثُمَّ حَلَّ، وَإِنْ صُدَّ عَنْ عَرَفَةَ تَحَلَّلَ بِعُمْرَةٍ،"]]},{"id":"za74_2","label":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ · ٢","segs":[["matn","وَإِنْ حَصَرَهُ مَرَضٌ أَوْ ذَهَابُ نَفَقَةٍ بَقِيَ مُحْرِمًا إِنْ لَمْ يَكُنْ اشْتَرَطَ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za75","title":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ","units":[{"id":"za75_1","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · ١","segs":[["matn","أَفْضَلُهَا إِبِلٌ، ثُمَّ بَقَرٌ، ثُمَّ غَنَمٌ، وَلَا يُجْزِئُ فِيهَا إِلَّا جَذَعُ ضَأْنٍ، وَثَنِيٌّ سِوَاهُ، فَالْإِبِلُ خَمْسٌ، وَالْبَقَرُ سَنَتَانِ، وَالْمَعْزُ سَنَةٌ، وَالضَّأْنُ نِصْفُهَا، وَتُجْزِئُ الشَّاةُ عَنْ وَاحِدٍ، وَالْبَدَنَةُ وَالْبَقَرَةُ عَنْ سَبْعَةٍ،"]]},{"id":"za75_2","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · ٢","segs":[["matn","وَلَا تُجْزِئُ الْعَوْرَاءُ وَالْعَجْفَاءُ وَالْعَرْجَاءُ وَالْهَتْمَاءُ وَالْجَدَّاءُ وَالْمَرِيضَةُ وَالْعَضْبَاءُ بَلْ الْبَتْرَاءُ خِلْقَةً وَالْجَمَّاءُ وَخَصِيٌّ غَيْرُ مَجْبُوبٍ وَمَا بِأُذُنِهِ أَوْ قَرْنِهِ قَطْعٌ أَقَلُّ مِنِ النِّصْفِ."]]},{"id":"za75_3","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · ٣","segs":[["matn","وَالسُّنَّةُ نَحْرُ الْإِبِلِ قَائِمَةً مَعْقُولَةً يَدُهَا الْيُسْرَى فَيَطْعَنُهَا بِالْحَرْبَةِ فِي الْوَهْدَةِ الَّتِي بَيْنَ أَصْلِ الْعُنُقِ وَالصَّدْرِ، وَيَذْبَحُ غَيْرَهَا، وَيَجُوزُ عَكْسُهَا، وَيَقُولُ «بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ، اللَّهُمَّ هَذَا مِنْكَ وَلَكَ» وَيَتَوَلَّاهَا صَاحِبُهَا أَوْ يُوَكِّلُ مُسْلِمًا وَيَشْهَدُهَا،"]]},{"id":"za75_4","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · ٤","segs":[["matn","وَوَقْتُ الذَّبْحِ بَعْدَ صَلَاةِ الْعِيدِ أَوْ قَدْرُهُ إِلَى يَوْمَيْنِ بَعْدَهُ، وَيُكْرَهُ فِي لَيْلَتَيْهِمَا، فَإِنْ فَاتَ قَضَى وَاجِبَهُ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za76","title":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · فَصْلٌ","units":[{"id":"za76_1","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · فَصْلٌ · ١","segs":[["matn","وَيَتَعَيَّنَانِ بِقَوْلِهِ: «هَذَا هَدْيٌ أَوْ أُضْحِيَةٌ» لَا بِالنِّيَّةِ، وَإِذَا تَعَيَّنَتْ لَمْ يَجُزْ بَيْعُهَا وَلَا هِبَتُهَا إِلَّا أَنْ يُبْدِلَهَا بِخَيْرٍ مِنْهَا، وَيَجُزُّ صُوفَهَا وَنَحْوَهُ إِنْ كَانَ أَنْفَعَ لَهَا وَيَتَصَدَّقُ بِهِ، وَلَا يُعْطِي جَازِرَهَا أُجْرَتَهُ مِنْهَا،"]]},{"id":"za76_2","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · فَصْلٌ · ٢","segs":[["matn","وَلَا يَبِيعُ جِلْدَهَا وَلَا شَيْئًا مِنْهَا بَلْ يَنْتَفِعُ بِهِ، وَإِنْ تَعَيَّبَتْ ذَبَحَهَا وَأَجْزَأَتْهُ إِلَّا أَنْ تَكُونَ وَاجِبَةً فِي ذِمَّتِهِ قَبْلَ التَّعْيِينِ."]]},{"id":"za76_3","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · فَصْلٌ · ٣","segs":[["matn","وَالْأُضْحِيَةُ سُنَّةٌ، وَذَبْحُهَا أَفْضَلُ مِنَ الصَّدَقَةِ بِثَمَنِهَا، وَسُنَّ أَنْ يَأْكُلَ وَيُهْدِيَ وَيَتَصَدَّقَ أَثْلَاثًا وَإِنْ أَكَلَهَا إِلَّا أُوقِيَّةً تَصَدَّقَ بِهَا جَازَ وَإِلَّا ضَمِنَهَا وَيَحْرُمُ عَلَى مَنْ يُضَحِّي أَنْ يَأْخُذَ فِي الْعَشْرِ مِنْ شَعْرِهِ أَوْ بَشَرَتِهِ شَيْئًا."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za77","title":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · فَصْلٌ (٢)","units":[{"id":"za77_1","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · فَصْلٌ (٢) · ١","segs":[["matn","تُسَنُّ الْعَقِيقَةُ: عَنْ الْغُلَامِ شَاتَانِ وَعَنْ الْجَارِيَةِ شَاةٌ تُذْبَحُ يَوْمَ سَابِعِهِ."]]},{"id":"za77_2","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَةِ · فَصْلٌ (٢) · ٢","segs":[["matn","فَإِنْ فَاتَ فَفِي أَرْبَعَةَ عَشَرَ، فَإِنْ فَاتَ فِفِي إِحْدَى وَعِشْرِينَ، تُنْزَعُ جُدُولًا وَلَا يُكْسَرُ عَظْمُهَا، وَحُكْمُهَا كَالْأُضْحِيَةِ إِلَّا أَنَّهُ لَا يُجْزِئُ فِيهَا شِرْكٌ فِي دَمٍ، وَلَا تُسَنُّ الْفَرَعَةُ وَلَا الْعَتِيرَةُ."]]}],"group":"كِتَابُ الْمَنَاسِكِ"},{"id":"za78","title":"كِتَابُ الْجِهَادِ","units":[{"id":"za78_1","label":"كِتَابُ الْجِهَادِ · ١","segs":[["matn","وَهُوَ فَرْضُ كِفَايَةٍ، وَيَجِبُ إِذَا حَضَرَهُ، أَوْ حَصَرَ بَلَدَهُ عَدَوٌّ، أَوْ اسْتَنْفَرَهُ الْإِمَامُ، وَتَمَامُ الرِّبَاطِ أَرْبَعُونَ يَوْمًا، وَإِذَا كَانَ أَبَوَاهُ مُسْلِمَيْنِ لَمْ يُجَاهِدْ تَطَوُّعًا إِلَّا بِإِذْنِهِمَا، وَيَتَفَقَّدُ الْإِمَامُ جَيْشَهُ عِنْدَ الْمَسِيرِ، وَيَمْنَعُ الْمُخَذِّلَ وَالْمُرْجِفَ،"]]},{"id":"za78_2","label":"كِتَابُ الْجِهَادِ · ٢","segs":[["matn","وَلَهُ أَنْ يُنَفِّلَ فِي بِدَايَتِهِ الرُّبُعَ بَعْدَ الْخُمُسِ، وَفِي الرَّجْعَةِ الثُّلُثَ بَعْدَهُ، وَيَلْزَمُ الْجَيْشَ طَاعَتُهُ وَالصَّبْرُ مَعَهُ، وَلَا يَجُوزُ الْغَزْوُ إِلَّا بِإِذْنِهِ إِلَّا أَنْ يَفْجَأَهُمْ عَدُوٌّ يَخَافُونَ كَلَبَهُ، وَتُمْلَكُ الْغَنِيمَةُ بِالِاسْتِيلَاءِ عَلَيْهَا فِي دَارِ الْحَرْبِ،"]]},{"id":"za78_3","label":"كِتَابُ الْجِهَادِ · ٣","segs":[["matn","وَهْيَ لِمَنْ شَهِدَ الْوَقْعَةَ مِنْ أَهْلِ الْقِتَالِ، فَيُخْرِجُ الْخُمُسَ، ثُمَّ يَقْسِمُ بَاقِيَ الْغَنِيمَةِ، لِلرَّاجِلِ سَهْمٌ وَلِلْفَارِسِ ثَلَاثَةُ سَهْمٌ لَهُ وَسَهْمَانِ لِفَرَسِهِ، وَيُشَارِكُ الْجَيْشَ سَرَايَاهُ فِيمَا غَنِمَتْ، وَيُشَارِكُونَهُ فِيمَا غَنِمَ."]]},{"id":"za78_4","label":"كِتَابُ الْجِهَادِ · ٤","segs":[["matn","وَالْغَالُّ مِنَ الْغَنِيمَةِ يُحْرَقُ رَحْلُهُ كُلُّهُ إِلَّا السِّلَاحَ وَالْمُصْحَفَ وَمَا فِيهِ رُوْحٌ، وَإِذَا غَنِمُوا أَرْضًا فَتَحُوهَا بِالسَّيْفِ خُيِّرَ الْإِمَامُ بَيْنَ قَسْمِهَا وَوَقْفِهَا عَلَى الْمُسْلِمِينَ، وَيَضْرِبُ عَلَيْهَا خَرَاجًا مُسْتَمِرًّا يُؤْخَذُ مِمَّنْ هِيَ بِيَدِهِ،"]]},{"id":"za78_5","label":"كِتَابُ الْجِهَادِ · ٥","segs":[["matn","وَالْمَرْجِعُ فِي الْخَرَاجِ وَالْجِزْيَةِ إِلَى اجْتِهَادِ الْإِمَامِ، وَمَنْ عَجَزَ عَنْ عِمَارَةِ أَرْضِهِ أُجْبِرَ عَلَى إِجَارَتِهَا أَوْ رَفْعِ يَدِهِ عَنْهَا، وَيَجْرِي فِيهَا الْمِيرَاثُ، وَمَا أُخِذَ مِنْ مَالِ مُشْرِكٍ كَجِزْيَةٍ وَخَرَاجٍ وَعُشْرٍ،"]]},{"id":"za78_6","label":"كِتَابُ الْجِهَادِ · ٦","segs":[["matn","وَمَا تَرَكُوهُ فَزَعًا وَخُمُسِ خُمُسِ الْغَنِيْمَةِ فَفَيْءٌ يُصْرَفُ فِي مَصَالِحِ الْمُسْلِمِينَ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"za79","title":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا","units":[{"id":"za79_1","label":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · ١","segs":[["matn","لَا يُعْقَدُ لِغَيْرِ الْمَجُوسِ وَأَهْلِ الْكِتَابَيْنِ وَمَنْ تَبِعَهُمْ، وَلَا يَعْقِدُهَا إِلَّا إِمَامٌ أَوْ نَائِبُهُ، وَلَا جِزْيَةَ عَلَى صَبِيٍّ وَلَا امْرَأَةٍ وَلَا عَبْدٍ وَلَا فَقِيرٍ يَعْجِزُ عَنْهَا، وَمَنْ صَارَ أَهْلًا لَهَا أُخِذَتْ مِنْهُ فِي آخِرِ الْحَوْلِ،"]]},{"id":"za79_2","label":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · ٢","segs":[["matn","وَمَتَى بَذَلُوا الْوَاجِبَ عَلَيْهِمْ وَجَبَ قَبُولُهُ وَحَرُمَ قِتَالُهُمْ، وَيُمْتَهَنُونَ عِنْدَ أَخْذِهَا وَيُطَالُ وُقُوفُهُمْ وَتُجَرُّ أَيْدِيهِمْ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"za80","title":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · فَصْلٌ","units":[{"id":"za80_1","label":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · فَصْلٌ · ١","segs":[["matn","وَيَلْزَمُ الْإِمَامَ أَخْذُهُمْ بِحُكْمِ الْإِسْلَامِ فِي النَّفْسِ، وَالْمَالِ، وَالْعِرْضِ، وَإِقَامَةِ الْحُدُودِ عَلَيْهِمْ فِيمَا يَعْتَقِدُونَ تَحْرِيمَهُ دُونَ مَا يَعْتَقِدُونَ حِلَّهُ، وَيَلْزَمُهُمُ التَّمَيُّزُ عَنِ الْمُسْلِمِيْنَ، وَلَهُمْ رَكُوبُ غَيْرِ الْخَيْلِ بِغَيْرِ سَرْجٍ بِإِكَافٍ،"]]},{"id":"za80_2","label":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · فَصْلٌ · ٢","segs":[["matn","وَلَا يَجُوزُ تَصْدِيرُهُمْ فِي الْمَجَالِسِ وَلَا الْقِيَامُ لَهُمْ وَلَا بَدَاءَتُهُمْ بِالسَّلَامِ، وَيُمْنَعُونَ مِنْ إِحْدَاثِ كَنَائِسَ وَبِيَعٍ وَبِنَاءِ مَا انْهَدَمَ مِنْهَا وَلَوْ ظُلْمًا، وَمِنْ تَعْلِيَةِ بُنْيَانٍ عَلَى مُسْلِمٍ، لَا مُسَاوَاتُهُ لَهُ، وَمِنْ إِظْهَارِ خَمْرٍ وَخِنْزِيرٍ وَنَاقُوسٍ،"]]},{"id":"za80_3","label":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · فَصْلٌ · ٣","segs":[["matn","وَجَهْرٍ بِكِتَابِهِمْ، وَإِنْ تَهَوَّدَ نَصْرَانِيٌّ أَوْ عَكْسُهُ لَمْ يُقَرَّ وَلَمْ يُقْبَلْ مِنْهُ إِلَّا الْإِسْلَامُ أَوْ دِينُهُ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"za81","title":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · فَصْلٌ (٢)","units":[{"id":"za81_1","label":"بَابُ عَقْدِ الذِّمَّةِ وَأَحْكَامِهَا · فَصْلٌ (٢) · ١","segs":[["matn","فَإِنْ أَبَى الذِّمِّيُّ بَذْلَ الْجِزْيَةِ، أَوِ الْتِزَامَ حُكْمِ الْإِسْلَامِ، أَوْ تَعَدَّى عَلَى مُسْلِمٍ بِقَتْلٍ أَوْ زِنًا أَوْ قَطْعِ طَرِيقٍ، أَوْ تَجْسِيسٍ أَوْ إِيوَاءِ جَاسُوسٍ، أَوْ ذَكَرَ اللَّهَ أَوْ رَسُولِهِ أَوْ كِتَابِهِ بِسُوءٍ انْتَقَضَ عَهْدُهُ دُونَ نِسَائِهِ وَأَوْلَادِهِ، وَحَلَّ دَمُهُ وَمَالُهُ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"za82","title":"كِتَابُ الْبَيْعِ","units":[{"id":"za82_1","label":"كِتَابُ الْبَيْعِ · ١","segs":[["matn","وَهُوَ مُبَادَلَةُ مَالٍ وَلَوْ فِي الذِّمَّةِ أَوْ مَنْفَعَةٍ مُبَاحَةٍ كَمَمَرٍّ بِمِثْلِ أَحَدِهِمَا عَلَى التَّأْبِيدِ غَيْرَ رِبًا وَقَرْضٍ."]]},{"id":"za82_2","label":"كِتَابُ الْبَيْعِ · ٢","segs":[["matn","وَيَنْعَقِدُ بِإِيجَابٍ وَقَبُولٍ بَعْدَهُ وَقَبْلَهُ، مُتَرَاخِيًا عَنْهُ فِي مَجْلِسِهِ، فَإِنْ تَشَاغَلَا بِمَا يَقْطَعُهُ بَطَلَ وَهِي الصِّيغَةُ الْقَوْلِيَّةُ، وَبِمُعَاطَاةٍ وَهِيَ الْفِعْلِيَّةُ."]]},{"id":"za82_3","label":"كِتَابُ الْبَيْعِ · ٣","segs":[["matn","وَيُشْتَرَطُ التَّرَاضِي مِنْهُمَا، فَلَا يَصِحُّ مِنْ مُكْرَهٍ بِلَا حَقٍّ، وَأَنْ يَكُونَ الْعَاقِدُ جَائِزَ التَّصَرُّفِ، فَلَا يَصِحُّ تَصَرُّفُ صَبِيٍّ وَسَفِيهٍ بِغَيْرِ إِذْنِ وَلِيٍّ، وَأَنْ تَكُونَ الْعَيْنُ مُبَاحَةَ النَّفْعِ مِنْ غَيْرِ حَاجَةٍ كَالْبَغْلِ وَالْحِمَارِ، وَدُودِ الْقَزِّ وَبَزْرِهِ،"]]},{"id":"za82_4","label":"كِتَابُ الْبَيْعِ · ٤","segs":[["matn","وَالْفِيلِ وَسِبَاعِ الْبَهَائِمِ الَّتِي تَصْلُحُ لِلصَّيْدِ، إِلَّا الْكَلْبَ وَالْحَشَرَاتِ وَالْمُصْحَفَ وَالْمَيْتَةَ وَالسَّرْجِينَ النَّجِسَ وَالْأَدْهَانَ النَّجِسَةَ، وَلَا الْمُتَنَجِّسَةَ، وَيَجُوزُ الْاسْتِصْبَاحُ بِهَا فِي غَيْرِ مَسْجِدٍ، وَأَنْ يَكُونَ مِنْ مَالِكٍ أَوْ مَنْ يَقُومُ مَقَامَهُ،"]]},{"id":"za82_5","label":"كِتَابُ الْبَيْعِ · ٥","segs":[["matn","فَإِنْ بَاعَ مِلْكَ غَيْرِهِ أَوِ اشْتَرَى بِعَيْنِ مَالِهِ بِلَا إِذْنِهِ لَمْ يَصِحَّ، وَإِنِ اشْتَرَى لَهُ فِي ذِمَّتِهِ بِلَا إِذْنِهِ وَلَمْ يُسَمِّهِ فِي الْعَقْدِ صَحَّ لَهُ بِالْإِجَازَةِ وَلَزِمَ الْمُشْتَرِي بِعَدَمِهَا مِلْكًا،"]]},{"id":"za82_6","label":"كِتَابُ الْبَيْعِ · ٦","segs":[["matn","وَلَا يُبَاعُ غَيْرُ الْمَسَاكِنِ مِمَّا فُتِحَ عَنْوَةً كَأَرْضِ الشَّامِ وَمِصْرَ وَالْعِرَاقِ، بَلْ تُؤَجَّرُ، وَلَا يَصِحُّ بَيْعُ نَقْعِ الْبِئْرِ، وَلَا مَا يَنْبُتُ فِي أَرْضِهِ مِنْ كَلَأٍ وَشَوْكٍ، وَيَمْلِكُهُ آخِذُهُ، وَأَنْ يَكُونَ مَقْدُورًا عَلَى تَسْلِيمِهِ،"]]},{"id":"za82_7","label":"كِتَابُ الْبَيْعِ · ٧","segs":[["matn","فَلَا يَصِحُّ بَيْعُ آبِقٍ وَشَارِدٍ وَطَيْرٍ فِي هَوَاءٍ وَسَمَكٍ فِي مَاءٍ، وَلَا مَغْصُوبٍ مِنْ غَيْرِ غَاصِبِهِ أَوْ قَادِرٍ عَلَى أَخْذِهِ، وَأَنْ يَكُونَ مَعْلُومًا بِرُؤْيَةٍ أَوْ صِفَةٍ، فَإِنِ اشْتَرَى مَا لَمْ يَرَهُ أَوْ رَآهُ وَجَهِلَهُ،"]]},{"id":"za82_8","label":"كِتَابُ الْبَيْعِ · ٨","segs":[["matn","أَوْ وُصِفَ لَهُ بِمَا لَا يَكْفِي سَلَمًا لَمْ يَصِحَّ، وَلَا يُبَاعُ حَمْلٌ فِي بَطْنٍ، وَلَبَنٌ فِي ضَرْعٍ مُنْفَرِدَيْنِ، وَلَا مِسْكٌ فِي فَأْرَتِهِ وَلَا نَوًى فِي تَمْرٍ، وَصُوفٌ عَلَى ظَهْرٍ، وَفُجْلٌ وَنَحْوُهُ قَبْلَ قَلْعِهِ."]]},{"id":"za82_9","label":"كِتَابُ الْبَيْعِ · ٩","segs":[["matn","وَلَا يَصِحُّ بَيْعُ الْمُلَامَسَةِ وَالْمُنَابَذَةِ، وَلَا عَبْدٌ مِنْ عَبِيدٍ وَنَحْوِهِ، وَلَا اسْتِثْنَاؤُهُ إِلَّا مُعَيَّنًا، وَإِنِ اسْتَثْنَى مِنْ حَيَوَانٍ يُؤْكَلُ رَأْسُهُ وَجِلْدُهُ وَأَطْرَافُهُ صَحَّ، وَعَكْسُهُ الشَّحْمُ وَالْحَمْلُ،"]]},{"id":"za82_10","label":"كِتَابُ الْبَيْعِ · ١٠","segs":[["matn","وَيَصِحُّ بَيْعُ مَا مَأْكُولُهُ فِي جَوْفِهِ كَرُمَّانٍ وَبَطِّيخٍ وَالْبَاقِلَاءِ وَنَحْوِهِ فِي قِشْرِهِ، وَالْحَبِّ الْمُشْتَدِّ فِي سُنْبُلِهِ، وَأَنْ يَكُونَ الثَّمَنُ مَعْلُومًا، فَإِنْ بَاعَهُ بِرَقْمِهِ أَوْ بِأَلْفِ دِرِهَمٍ ذَهَبًا وَفِضَّةً،"]]},{"id":"za82_11","label":"كِتَابُ الْبَيْعِ · ١١","segs":[["matn","أَوْ بِمَا يَنْقَطِعُ بِهِ السِّعْرُ أَوْ بِمَا بَاعَ زَيْدٌ وَجَهِلَاهُ أَوْ أَحَدُهُمَا لَمْ يَصِحَّ."]]},{"id":"za82_12","label":"كِتَابُ الْبَيْعِ · ١٢","segs":[["matn","وَإِنْ بَاعَ ثَوْبًا أَوْ صُبْرَةً أَوْ قَطِيعًا كُلَّ ذِرَاعٍ أَوْ قَفِيزٍ أَوْ شَاةً بِدِرْهَمٍ صَحَّ، وَإِنْ بَاعَ مِنَ الصُّبْرَةِ كُلَّ قَفِيزٍ بِدِرْهَمٍ أَوْ بِمَائَةِ دِرْهَمٍ إِلَّا دِينَارًا، وَعَكْسُهُ،"]]},{"id":"za82_13","label":"كِتَابُ الْبَيْعِ · ١٣","segs":[["matn","أَوْ بَاعَ مَعْلُومًا وَمَجْهُولًا يَتَعَذَّرُ عِلْمُهُ وَلَمْ يَقُلْ كُلٌّ مِنْهُمَا بِكَذَا لَمْ يَصِحَّ، فَإِنْ لَمْ يَتَعَذَّرْ صَحَّ فِي الْمَعْلُومِ بِقِسْطِهِ،"]]},{"id":"za82_14","label":"كِتَابُ الْبَيْعِ · ١٤","segs":[["matn","وَلَوَ بَاعَ مُشَاعًا بَيْنَهُ وَبَيْنَ غَيْرِهِ كَعَبْدٍ أَوْ مَا يَنْقَسِمُ عَلَيْهِ الثَّمَنُ بِالْأَجْزَاءِ صَحَّ فِي نَصِيْبِهِ بِقِسْطِهِ، وَإِنْ بَاعَ عَبْدَهُ وَعَبْدَ غَيْرِهِ بِغَيْرِ إِذْنِهِ، أَوْ عَبْدًا وَحُرًّا أَوْ خَلًّا وَخَمْرًا، صَفْقَةً وَاحِدَةً،"]]},{"id":"za82_15","label":"كِتَابُ الْبَيْعِ · ١٥","segs":[["matn","صَحَّ فِي عَبْدِهِ وَفِي الْخَلِّ بِقِسْطِهِ، وَلِمُشْتَرٍ الْخِيَارُ إِنْ جَهِلَ الْحَالَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za83","title":"كِتَابُ الْبَيْعِ · فَصْلٌ","units":[{"id":"za83_1","label":"كِتَابُ الْبَيْعِ · فَصْلٌ · ١","segs":[["matn","وَلَا يَصِحُّ الْبَيْعُ مِمَّنْ تَلْزَمُهُ الْجُمُعَةُ بَعْدَ نِدَائِهَا الثَّانِي، وَيَصِحُّ النِّكَاحُ وَسَائِرُ الْعُقُودِ، وَلَا يَصِحُّ بَيْعُ عَصِيرٍ مِمَّنْ يَتَّخِذُهُ خَمْرًا، وَلَا سِلَاحٌ فِي فِتْنَةٍ، وَلَا عَبْدٍ مُسْلِمٍ لِكَافِرٍ إِذَا لَمْ يَعْتِقْ عَلَيْهِ،"]]},{"id":"za83_2","label":"كِتَابُ الْبَيْعِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ أَسْلَمَ فِي يَدِهِ أُجْبِرَ عَلَى إِزَالَةِ مِلْكِهِ، وَلَا تَكْفِي مُكَاتَبَتُهُ، وَإِنْ جَمَعَ بَيْنَ بَيْعٍ وَكِتَابَةٍ، أَوْ بَيْعٍ وَصَرْفٍ صَحَّ فِي غَيْرِ الْكِتَابَةِ، وَيُقَسَّطُ الْعِوَضُ عَلَيْهِمَا، وَيَحْرُمُ بَيْعُهُ عَلَى بَيْعِ أَخِيْهِ،"]]},{"id":"za83_3","label":"كِتَابُ الْبَيْعِ · فَصْلٌ · ٣","segs":[["matn","كَأَنْ يَقُولَ لَمِنَ اشْتَرَى سِلْعَةً بِعَشَرَةٍ: أَنَا أُعْطِيكَ مِثْلَهَا بِتِسْعَةٍ، وَشِرَاؤُهُ عَلَى شِرَائِهِ، كَأَنْ يَقُولَ لَمِنْ بَاعَ سِلْعَةً بِتِسْعَةٍ: عِنْدِي فِيهَا عَشَرَةٌ لِيَفْسَخَ وَيَعْقِدَ مَعَهُ، وَيَبْطُلُ الْعَقْدُ فِيهِمَا،"]]},{"id":"za83_4","label":"كِتَابُ الْبَيْعِ · فَصْلٌ · ٤","segs":[["matn","وَمَنْ بَاعَ رِبَوِيًّا بِنَسِيئَةٍ وَاعْتَاضَ عَنْ ثَمَنِهِ مَا لَا يُبَاعُ بِهِ نَسِيْئَةً، أَوِ اشْتَرَى شَيْئًا نَقْدًا بِدُونِ مَا بَاعَ بِهِ نَسِيئَةً، لَا بِالْعَكْسِ، لَمْ يَجُزْ، وَإِنِ اشْتَرَاهُ بِغَيْرِ جِنْسِهِ أَوْ بَعْدَ قَبْضِ ثَمَنِهِ،"]]},{"id":"za83_5","label":"كِتَابُ الْبَيْعِ · فَصْلٌ · ٥","segs":[["matn","أَوْ بَعْدَ تَغَيُّرِ صِفَتِهِ، أَوْ مِنْ غَيْرِ مُشْتَرِيهِ، أَوِ اشْتَرَاهُ أَبُوهُ، أَوِ ابْنُهُ جَازَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za84","title":"بَابُ الشُّرُوطِ فِي الْبَيْعِ","units":[{"id":"za84_1","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ١","segs":[["matn","مِنْهَا صَحِيحٌ كَالرَّهْنِ، وَتَأْجِيلِ ثَمَنٍ، وَكَوْنِ الْعَبْدِ كَاتِبًا أَوْ خَصِيًّا أَوْ مُسْلِمًا، وَالْأَمَةِ بِكْرًا، وَنَحْوِ أَنْ يَشْتَرِطَ الْبَائِعُ سُكْنَى الدَّارِ شَهْرًا، وَحُمْلَانَ الْبَعِيرِ إِلَى مَوْضِعٍ مُعَيَّنٍ، أَوْ شَرَطَ الْمُشْتَرِي عَلَى الْبَائِعِ حَمْلَ الْحَطَبِ أَوْ تَكْسِيْرَهُ،"]]},{"id":"za84_2","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٢","segs":[["matn","أَوْ خِيَاطَةَ الثَّوْبِ أَوْ تَفْصِيلَهُ، وَإِنْ جَمَعَ بَيْنَ شَرْطَيْنِ بَطَلَ الْبَيْعُ."]]},{"id":"za84_3","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٣","segs":[["matn","وَمِنْهَا فَاسِدٌ يُبْطِلُ الْعَقْدَ، كَاشْتِرَاطِ أَحَدِهِمَا عَلَى الْآخَرِ عَقْدًا آخَرَ، كَسَلَفٍ وَقَرْضٍ، وَبَيْعٍ وَإِجَارَةٍ وَصَرْفٍ، وَإِنْ شَرَطَ أَنْ لَا خَسَارَةَ عَلَيْهِ، أَوْ مَتَى نَفَقَ الْمَبِيعُ وَإِلَّا رَدَّهُ، أَوْ لَا يَبِيْعَ وَلَا يَهَبُهُ وَلَا يُعْتِقُهُ،"]]},{"id":"za84_4","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٤","segs":[["matn","وَإِنْ أَعْتَقَ فَالْوَلَاءُ لَهُ، أَوْ أَنْ يَفْعَلَ ذَلِكَ بَطَلَ الشَّرْطُ وَحْدَهُ، إِلَّا إِذَا شَرَطَ الْعِتْقَ، وَبِعْتُكَ عَلَى أَنْ تَنْقُدَنِي الثَّمَنَ إِلَى ثَلَاثٍ، وَإِلَّا فَلَا بَيْعَ بَيْنَنَا صَحَّ، وَبِعْتُكَ إِنْ جِئْتَنِي بِكَذَا أَوْ رَضِيَ زَيْدٌ،"]]},{"id":"za84_5","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٥","segs":[["matn","أَوْ يَقُولَ لِلْمُرْتَهِنِ: إِنْ جِئْتُكَ بِحَقِّكَ وَإِلَّا فَالرَّهْنُ لَكَ لَا يَصِحُّ الْبَيْعُ، وَإِنْ بَاعَهُ وَشَرَطَ الْبَرَاءَةَ مِنْ كُلِّ عَيْبٍ مَجْهُولٍ لَمْ يَبْرَأْ، وَإِنْ بَاعَهُ دَارًا عَلَى أَنَّهَا عَشَرَةُ أَذْرُعٍ فَبَانَتْ أَكْثَرَ أَوْ أَقَلَّ صَحَّ، وَلِمَنْ جَهِلَهُ وَفَاتَ غَرَضُهُ الْخِيَارُ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za85","title":"بَابُ الْخِيارِ","units":[{"id":"za85_1","label":"بَابُ الْخِيارِ · ١","segs":[["matn","وَهُوَ أَقْسَامٌ: الْأَوَّلُ: خِيَارُ الْمَجْلِسِ يَثْبُتُ فِي الْبَيْعِ، وَالصُّلْحُ بِمَعْنَاهُ، وَإِجَارَةً، وَالصَّرْفِ وَالسَّلَمِ دُونَ سَائِرِ الْعُقُودِ، وَلِكُلٍّ مِنَ الْمُتَبَايِعَيْنِ الْخِيَارُ مَا لَمْ يَتَفَرَّقَا عُرْفًا بِأَبْدَانِهِمَا، وَإِنْ نَفَيَاهُ أَوْ أَسْقَطَاهُ سَقَطَ،"]]},{"id":"za85_2","label":"بَابُ الْخِيارِ · ٢","segs":[["matn","وَإِنْ أَسْقَطَهُ أَحَدُهُمَا بَقِيَ خِيَارُ الْآخَرِ، وَإِذَا مَضَتْ مُدَّتُهُ لَزِمَ الْبَيْعُ."]]},{"id":"za85_3","label":"بَابُ الْخِيارِ · ٣","segs":[["matn","الثَّانِي أَنْ يَشْتَرِطَاهُ فِي الْعَقْدِ مُدَّةً مَعْلُومَةً، وَلَوْ طَوِيلَةً وَابْتِدَاؤُهَا مِنَ الْعَقْدِ، وَإِذَا مَضَتْ مُدَّتُهُ أَوْ قَطَعَاهُ بَطَلَ وَيَثْبُتُ فِي الْبَيْعِ، وَالصُّلْحِ بِمَعْنَاهُ، وَالْإِجَارَةِ فِي الذِّمَّةِ أَوْ عَلَى مُدَّةٍ لَا تَلِي الْعَقْدَ،"]]},{"id":"za85_4","label":"بَابُ الْخِيارِ · ٤","segs":[["matn","وَإِنْ شَرَطَاهُ لِأَحَدِهِمَا دُونَ صَاحِبِهِ صَحَّ، وَإِلَى الْغَدِ أَوِ اللَّيْلِ يَسْقُطُ بِأَوَّلِهِ، وَلِمَنْ لَهُ الْخِيَارُ الْفَسْخُ وَلَوْ مَعَ غَيْبَةِ الْآخَرِ وَسَخَطِهِ، وَالْمِلْكُ مُدَّةَ الْخِيَارَيْنِ لِلْمُشْتَرِي، وَلَهُ نَمَاؤُهُ الْمُنْفَصِلُ وَكَسْبُهُ،"]]},{"id":"za85_5","label":"بَابُ الْخِيارِ · ٥","segs":[["matn","وَيَحْرُمُ وَلَا يَصِحُّ تَصَرُّفُ أَحَدِهِمَا فِي الْمَبِيعِ وَعِوَضِهِ الْمُعَيَّنِ فِيهَا بَغَيْرِ إِذْنِ الْآخَرِ بِغَيْرِ تَجْرِبَةِ الْمَبِيْعِ إِلَّا عِتْقَ الْمُشْتَرِي، وَتَصَرُّفُ الْمُشْتَرِي فَسْخٌ لِخِيَارِهِ، وَمَنْ مَاتَ مِنْهُمَا بَطَلَ خِيَارُهُ."]]},{"id":"za85_6","label":"بَابُ الْخِيارِ · ٦","segs":[["matn","الثَّالِثُ إِذَا غُبِنَ فِي الْمَبِيْعِ غَبْنًا يَخْرُجُ عَنِ الْعَادَةِ، وَبِزِيَادَةِ النَّاجِشِ، وَالْمُسْتَرْسِلِ."]]},{"id":"za85_7","label":"بَابُ الْخِيارِ · ٧","segs":[["matn","الرَّابِعُ: خِيَارُ التَّدْلِيسِ كَتَسْوِيدِ شَعْرِ الْجَارِيَةِ وَتَجْعِيدِهِ، وَجَمْعِ مَاءِ الرَّحَى وَإِرْسَالِهِ عِنْدَ عَرْضِهَا."]]},{"id":"za85_8","label":"بَابُ الْخِيارِ · ٨","segs":[["matn","الْخَامِسُ: خِيَارُ الْعَيْبِ وَهُوَ مَا يُنْقِصُ قِيمَةَ الْمَبِيعِ كَمَرَضِهِ وَفَقْدِ عُضْوٍ وَسِنٍّ أَوْ زِيادَتِهِمَا، وَزِنَا الرَّقِيقِ، وَسَرِقَتِهِ وَإِبَاقِهِ وَبَوْلِهِ فِي الْفِرَاشِ، فَإِذَا عَلِمَ الْمُشْتَرِي الْعَيْبَ بَعْدُ أَمْسَكَهُ بَأَرْشِهِ، وَهُوَ قِسْطُ مَا بَيْنَ قِيمَةِ الصِّحَّةِ وَالْعَيْبِ،"]]},{"id":"za85_9","label":"بَابُ الْخِيارِ · ٩","segs":[["matn","أَوْ رَدَّهَ وَأَخَذَ الثَّمَنَ، وَإِنْ تَلِفَ الْمَبِيعُ أَوْ أَعْتَقَ الْعَبْدُ تَعَيَّنَ الْأَرْشُ، وَإِنِ اشْتَرَى مَا لَمْ يَعْلَمْ عَيْبَهُ بِدُونِ كَسْرِهِ كَجَوْزِ هِنْدٍ وَبَيْضِ نَعَامٍ فَكَسَرَهُ فَوَجَدَهُ فَاسِدًا فَأَمْسَكَهُ فَلَهُ أَرْشُهُ، وَإِنْ رَدَّهُ رَدَّ أَرْشَ كَسْرِهِ،"]]},{"id":"za85_10","label":"بَابُ الْخِيارِ · ١٠","segs":[["matn","وَإِنْ كَانَ كَبَيْضِ دَجَاجٍ رَجَعَ بِكُلِّ الثَّمَنِ، وَخِيَارُ عَيْبٍ مُتَرَاخٍ مَا لَمْ يُوْجَدْ دَلِيلُ الرِّضَا، وَلَا يَفْتَقِرُ إِلَى حُكْمٍ وَلَا رِضًا وَلَا حُضُورِ صَاحِبِهِ، وَإِنِ اخْتَلَفَا عِنْدَ مَنْ حَدَثَ الْعَيْبُ، فَقَوْلُ مُشْتَرٍ مَعَ يَمِينِهِ،"]]},{"id":"za85_11","label":"بَابُ الْخِيارِ · ١١","segs":[["matn","وَإِنْ لَمْ يَحْتَمِلْ إِلَّا قَوْلَ أَحَدِهِمَا قُبِلَ بِلَا يَمِينٍ."]]},{"id":"za85_12","label":"بَابُ الْخِيارِ · ١٢","segs":[["matn","السَّادِسُ خِيَارٌ فِي الْبَيْعِ بِتَخْبِيرِ الثَّمَنِ مَتَى بَانَ أَقَلَّ أَوْ أَكْثَرَ، وَيَثْبُتُ فِي التَّوْلِيَةِ وَالشَّرِكَةِ وَالْمُرَابَحَةِ وَالْمُوَاضَعَةِ، وَلَا بُدَّ فِي جَمِيعِهَا مِنْ مَعْرِفَةِ الْمُشْتَرِي رَأْسَ الْمَالِ،"]]},{"id":"za85_13","label":"بَابُ الْخِيارِ · ١٣","segs":[["matn","وَإِنِ اشْتَرَى بِثَمَنٍ مُؤَجَّلٍ أَوْ مِمَّنْ لَا تُقْبَلُ شَهَادَتُهُ لَهُ، أَوْ بِأَكْثَرَ مِنْ ثَمَنِهِ حِيلَةً أَوْ، بَاعَ بَعْضَ الصَّفْقَةِ بِقِسْطِهَا مِنَ الثَّمَنِ وَلَمْ يُبَيِّنْ ذَلِكَ فِي تَخْبِيرِهِ بِالثَّمَنِ، فَلِمُشْتَرٍ الْخِيَارُ بَيْنَ الْإِمْسَاكِ وَالرَّدِّ،"]]},{"id":"za85_14","label":"بَابُ الْخِيارِ · ١٤","segs":[["matn","وَمَا يُزَادُ فِي ثَمَنٍ أَوْ يُحَطُّ مِنْهُ فِي مُدَّةِ خِيَارٍ، أَوْ يُؤْخَذُ أَرْشًا لِعَيْبٍ أَوْ جِنَايَةٍ عَلَيْهِ يُلْحَقُ بِرَأْسِ مَالِهِ وَيُخْبِرُ بِهِ، وَإِنْ كَانَ ذَلِكَ بَعْدَ لُزُومِ الْبَيْعِ لَمْ يُلْحَقْ بِهِ، وَإِنْ أَخْبَرَ بِالْحَالِ فَحَسَنٌ."]]},{"id":"za85_15","label":"بَابُ الْخِيارِ · ١٥","segs":[["matn","السَّابِعُ خِيَارٌ لِاخْتِلَافِ الْمُتَبَايِعَيْنِ، فَإِذَا اخْتَلَفَا فِي قَدْرِ الثَّمَنِ تَحَالَفَا، فَيَحْلِفُ الْبَائِعُ أَوَّلًا: مَا بِعْتُهُ بِكَذَا وَإِنَّمَا بِعْتُهُ بِكَذَا، ثُمَّ يَحْلِفُ الْمُشْتَرِي: مَا اشْتَرَيْتُهُ بِكَذَا وَإِنَّمَا اشْتَرَيْتُهُ بِكَذَا."]]},{"id":"za85_16","label":"بَابُ الْخِيارِ · ١٦","segs":[["matn","وَلِكُلٍّ الْفَسْخُ إِذَا لَمْ يَرْضَ أَحَدُهُمَا بِقَوْلِ الْآخَرِ، فَإِنْ كَانَتِ السِّلْعَةُ تَالِفَةً رَجَعَا إِلَى قِيمَةِ مِثْلِهَا، فَإِنِ اخْتَلَفَا فِي صِفَتِهَا فَقَوْلُ مُشْتَرٍ، وَإِذَا فُسِخَ الْعَقْدُ انْفَسَخَ ظَاهِرًا وَبَاطِنًا،"]]},{"id":"za85_17","label":"بَابُ الْخِيارِ · ١٧","segs":[["matn","وَإِنِ اخْتَلَفَا فِي أَجَلٍ أَوْ شَرْطٍ فَقَوْلُ مَنْ يَنْفِيهِ، وَإِنِ اخْتَلَفَا فِي عَيْنِ الْمَبِيعِ تَحَالَفَا وَبَطَلَ الْبَيْعُ،"]]},{"id":"za85_18","label":"بَابُ الْخِيارِ · ١٨","segs":[["matn","وَإِنْ أَبَى كُلٌّ مِنْهُمَا تَسْلِيمَ مَا بِيَدِهِ حَتَّى يَقْبِضَ الْعِوَضَ وَالثَّمَنُ عَيْنٌ نُصِّبَ عَدْلٌ يَقْبِضُ مِنْهُمَا وَيُسَلِّمُ الْمَبِيْعَ ثُمَّ الثَّمَنَ، وَإِنْ كَانَ دَيْنًا حَالًّا أُجْبِرَ بَائِعٌ ثُمَّ مُشْتَرٍ إِنْ كَانَ الثَّمَنُ فِي الْمَجْلِسِ،"]]},{"id":"za85_19","label":"بَابُ الْخِيارِ · ١٩","segs":[["matn","وَإِنْ كَانَ غَائِبًا فِي الْبَلَدِ حُجِرَ عَلَيْهِ فِي الْمَبِيْعِ وَبَقِيَّةِ مَالِهِ حَتَّى يُحْضِرَهُ، وَإِنْ كَانَ غَائِبًا بَعِيدًا عَنْهَا وَالْمُشْتَرِي مُعْسِرٌ فَلِبَائِعٍ الْفَسْخُ، وَيَثْبُتُ الْخِيَارُ لِلْخُلْفِ فِي الصِّفَةِ وَلِتَغَيُّرِ مَا تَقَدَّمَتْ رُؤْيَتُهُ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za86","title":"بَابُ الْخِيارِ · فَصْلٌ","units":[{"id":"za86_1","label":"بَابُ الْخِيارِ · فَصْلٌ · ١","segs":[["matn","وَمَنِ اشْتَرَى مَكِيلًا وَنَحْوَهُ صَحَّ وَلَزِمَ بِالْعَقْدِ وَلَمْ يَصِحَّ تَصَرُّفُهُ فِيهِ حَتَّى يَقْبِضَهُ، وَإِنْ تَلِفَ قَبْلَهُ فَمِنْ ضَمَانِ الْبَائِعِ، وَإِنْ تَلِفَ بِآفَةٍ سَمَاوِيَّةٍ بَطَلَ الْبَيْعُ،"]]},{"id":"za86_2","label":"بَابُ الْخِيارِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ أَتْلَفَهُ آدَمِيٌّ خُيِّرَ مُشْتَرٍ بَيْنَ فَسْخٍ وَإِمْضَاءٍ وَمُطَالَبَةِ مُتْلِفِهِ بِبَدَلِهِ، وَمَا عَدَاهُ يَجُوزُ تَصَرُّفُ الْمُشْتَرِي فِيهِ قَبْلَ قَبْضِهِ، وَإِنْ تَلِفَ مَا عَدَا الْمَبِيعَ بِكَيْلٍ وَنَحْوِهِ، فَمِنْ ضَمَانِهِ مَا لَمْ يَمْنَعْهُ بَائِعٌ مِنْ قَبْضِهِ،"]]},{"id":"za86_3","label":"بَابُ الْخِيارِ · فَصْلٌ · ٣","segs":[["matn","وَيَحْصُلُ قَبْضُ مَا بِيعَ بِكَيْلٍ أَوْ وَزْنٍ أَوْ عَدٍّ أَوْ ذَرْعٍ بِذَلِكَ، وَفِي صُبْرَةٍ وَمَا يُنْقَلُ بِنَقْلِهِ وَمَا يُتَنَاوَلُ بِتَنَاوُلِهِ، وَغَيْرُهُ بِتَخْلِيَتِهِ."]]},{"id":"za86_4","label":"بَابُ الْخِيارِ · فَصْلٌ · ٤","segs":[["matn","وَالْإِقَالَةُ فَسْخٌ. تَجُوْزُ قَبْلَ قَبْضِ الْمَبِيْعِ بِمِثْلِ الثَّمَنِ، وَلَا خِيَارَ فِيهَا وَلَا شُفْعَةَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za87","title":"بَابُ الرِّبَا وَالصَّرْفِ","units":[{"id":"za87_1","label":"بَابُ الرِّبَا وَالصَّرْفِ · ١","segs":[["matn","يَحْرُمُ رِبَا الْفَضْلِ فِي مَكِيلٍ وَمَوْزُونٍ بِيعَ بِجِنْسِهِ، وَيَجِبُ فِيهِ الْحُلُولُ وَالْقَبْضُ، وَلَا يُبَاعُ مَكِيلٌ بِجِنْسِهِ إِلَّا كَيْلًا، وَلَا مَوْزُونٌ بِجِنْسِهِ إِلَّا وَزْنًا، وَلَا بَعْضُهُ بِبَعْضٍ جُزَافًا، فَإِنِ اخْتَلَفَ الْجِنْسُ جَازَتِ الثَّلَاثَةُ."]]},{"id":"za87_2","label":"بَابُ الرِّبَا وَالصَّرْفِ · ٢","segs":[["matn","وَالْجِنْسُ مَا لَهُ اسْمٌ خَاصٌّ يَشْمَلُ أَنْوَاعًا كَبُرٍّ وَنَحْوِهِ، وَفُرُوعِ الْأَجْنَاسِ، كَالْأَدِقَّةِ وَالْأَخْبَازِ وَالْأَدْهَانِ، وَاللَّحْمُ أَجْنَاسٌ بِاخْتِلَافِ أُصُولِهِ، وَكَذَا اللَّبَنُ، وَاللَّحْمُ وَالشَّحْمُ وَالْكَبِدُ أَجْنَاسٌ، وَلَا يَصِحُّ بَيْعُ لَحْمٍ بِحَيَوَانٍ مِنْ جِنْسِهِ، وَيَصِحُّ بِغَيْرِ جِنْسِهِ،"]]},{"id":"za87_3","label":"بَابُ الرِّبَا وَالصَّرْفِ · ٣","segs":[["matn","وَلَا يَجُوزُ بَيْعُ حَبٍّ بِدَقِيقِهِ وَلَا سَوِيقِهِ وَنَيْئِهِ بِمَطْبُوخِهِ وَأَصْلِهِ بِعَصِيرِهِ وَخَالِصِهِ بِمَشُوبِهِ وَرَطْبِهِ بِيَابِسِهِ، وَيَجُوْزُ بَيْعُ دَقِيقِهِ بِدَقِيقِهِ إِذَا اسْتَوَيَا فِي النُّعُومَةِ وَمَطْبُوخِهِ بِمَطْبُوخِهِ وَخُبْزِهِ بِخُبْزِهِ إِذَا اسْتَوَيَا فِي النَّشَافِ، وَعَصِيرِهِ بِعَصِيرِهِ وَرَطْبِهِ بِرَطْبِهِ،"]]},{"id":"za87_4","label":"بَابُ الرِّبَا وَالصَّرْفِ · ٤","segs":[["matn","وَلَا يُبَاعُ رِبَوِيٌّ بِجِنْسِهِ وَمَعَهُ أَوْ مَعَهُمَا مِنْ غَيْرِ جِنْسِهِمَا، وَلَا تَمْرٌ بِلَا نَوًى بِمَا فِيهِ نَوًى، وَيُبَاعُ النَّوَى بِتَمْرٍ فِيهِ نَوًى، وَلَبَنٌ وَصُوفٌ بِشَاةٍ ذَاتِ لَبَنٍ وَصُوفٍ،"]]},{"id":"za87_5","label":"بَابُ الرِّبَا وَالصَّرْفِ · ٥","segs":[["matn","وَمَرَدُّ الْكَيْلِ لِعُرْفِ الْمَدِينَةِ وَالْوَزْنِ لِعُرْفِ مَكَّةَ زَمَنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا لَا عُرْفَ لَهُ هُنَاكَ اعْتُبِرَ عُرْفُهُ فِي مَوْضِعِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za88","title":"بَابُ الرِّبَا وَالصَّرْفِ · فَصْلٌ","units":[{"id":"za88_1","label":"بَابُ الرِّبَا وَالصَّرْفِ · فَصْلٌ · ١","segs":[["matn","وَيَحْرُمُ رِبَا النَّسِيئَةِ فِي بَيْعِ كُلِّ جِنْسَيْنِ اتَّفَقَا فِي عِلَّةِ رِبَا الْفَضْلِ لَيْسَ أَحَدُهُمَا نَقْدًا كَالْمَكِيلَيْنِ وَالْمَوْزُونَيْنِ، وَإِنْ تَفَرَّقَا قَبْلَ الْقَبْضِ بَطَلَ، وَإِنْ بَاعَ مَكِيلًا بِمَوْزُونٍ جَازَ التَّفَرُّقُ قَبْلَ الْقَبْضِ،"]]},{"id":"za88_2","label":"بَابُ الرِّبَا وَالصَّرْفِ · فَصْلٌ · ٢","segs":[["matn","وَالنَّسَاءُ وَمَا لَا كَيْلَ فِيْهِ وَلَا وَزْنَ كَالثِّيَابِ وَالْحَيْوَانِ يَجُوزُ فِيهِ النَّسَاءُ، وَلَا يَجُوزُ بَيْعُ الدَّيْنِ بِالدَّيْنِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za89","title":"بَابُ الرِّبَا وَالصَّرْفِ · فَصْلٌ (٢)","units":[{"id":"za89_1","label":"بَابُ الرِّبَا وَالصَّرْفِ · فَصْلٌ (٢) · ١","segs":[["matn","وَمَتَى افْتَرَقَ الْمُتَصَارِفَانِ قَبْلَ قَبْضِ الْكُلِّ أَوِ الْبَعْضِ بَطَلَ الْعَقْدُ فِيمَا لَمْ يُقْبَضْ، وَالدَّرَاهِمُ وَالدَّنَانِيرُ تَتَعَيَّنُ بِالتَّعْيِينِ فِي الْعَقْدِ، فَلَا تُبَدَّلُ وَإِنْ وَجَدَهَا مَغْصُوبَةً بَطَلَ، وَمَعِيبَةً مِنْ جِنْسِهَا أَمْسَكَ أَوْ رَدَّ،"]]},{"id":"za89_2","label":"بَابُ الرِّبَا وَالصَّرْفِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَيَحْرُمُ الرِّبَا بَيْنَ الْمُسْلِمِ وَالْحَرْبِيِّ، وَبَيْنَ الْمُسْلِمِيْنَ مُطْلَقًا بِدَارِ إِسْلَامٍ وَحَرْبٍ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za90","title":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ","units":[{"id":"za90_1","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ١","segs":[["matn","إِذَا بَاعَ دَارًا شَمِلَ أَرْضَهَا وَبِنَاءَهَا وَسَقْفَهَا وَالْبَابَ الْمَنْصُوبَ، وَالسُّلَّمَ وَالرَّفَّ الْمُسَمَّرَيْنِ، وَالْخَابِيَةَ الْمَدْفُونَةَ، دُونَ مَا هُوَ مُودَعٌ فِيهَا مِنْ كَنْزٍ وَحَجَرٍ، وَمُنْفَصِلٍ مِنْهَا كَحَبْلٍ وَدَلْوٍ وَبَكَرَةٍ وَقُفْلٍ وَفُرُشٍ وَمِفْتَاحٍ،"]]},{"id":"za90_2","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٢","segs":[["matn","وَإِنْ بَاعَ أَرْضًا وَلَوْ لَمْ يَقُلْ بِحُقُوقِهَا شَمِلَ غَرْسَهَا وَبِنَاءَهَا، وَإِنْ كَانَ فِيهَا زَرْعٌ كَبُرٍّ وَشَعِيرٍ فَلِبَائِعٍ مُبَقًّى، وَإِنْ كَانَ يُجَزُّ أَوْ يُلْقَطُ مِرَارًا فَأُصُولُهُ لِلْمُشْتَرِي، وَالْجَزَّةُ وَاللَّقْطَةُ الظَّاهِرَتَانِ عِنْدَ الْبَيْعِ لِلْبَائِعِ، وَإِنِ اشْتَرَطَ الْمُشْتَرِي ذَلِكَ صَحَّ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za91","title":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ","units":[{"id":"za91_1","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ١","segs":[["matn","وَمَنْ بَاعَ نَخْلًا تَشَقَّقَ طَلْعُهُ فَلِبَائِعٍ مُبَقًّى إِلَى الْجَذَاذِ إِلَّا أَنْ يَشْتَرِطَهُ مُشْتَرٍ، وَكَذَلِكَ شَجَرُ الْعِنَبِ وَالتُّوتِ وَالرُّمَّانِ وَغَيْرِهِ،"]]},{"id":"za91_2","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٢","segs":[["matn","وَمَا ظَهَرَ مِنْ نَوْرِهِ كَالْمِشْمِشِ وَالتُّفَّاحِ وَمَا خَرَجَ مِنْ أَكْمَامِهِ كَالْوَرْدِ وَالْقُطْنِ وَمَا قَبْلَ ذَلِكَ وَالْوَرَقُ فَلِمُشْتَرٍ،"]]},{"id":"za91_3","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٣","segs":[["matn","وَلَا يُبَاعُ ثَمَرٌ قَبْلَ بُدُوِّ صَلَاحِهِ وَلَا زَرْعٌ قَبْلَ اشْتِدَادِ حَبِّهِ وَلَا رَطْبَةٌ وَبَقْلٌ وَلَا قِثَّاءٌ وَنَحْوُهُ كَبَاذِنْجَانٍ دُونَ الْأَصْلِ إِلَّا بِشَرْطِ الْقَطْعِ فِي الْحَالِ أَوْ جَزَّةً جَزَّةً، أَوْ لَقْطَةً لَقْطَةً، وَالْحَصَادُ وَاللَّقَاطُ عَلَى الْمُشْتَرِي،"]]},{"id":"za91_4","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٤","segs":[["matn","وَإِنْ بَاعَهُ مُطْلَقًا أَوْ بِشَرْطِ الْبَقَاءِ أَوِ اشْتَرَى ثَمَرًا لَمْ يَبْدُ صَلَاحُهُ،"]]},{"id":"za91_5","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٥","segs":[["matn","بِشَرْطِ الْقَطْعِ وَتَرَكَهُ حَتَّى بَدَا أَوْ جَزَّةً أَوْ لَقْطَةً فَنَمَتَا أَوِ اشْتَرَى مَا بَدَا صَلَاحُهُ وَحَصَلَ آخَرُ وَاشْتَبَهَا أَوْ عَرِيَّةٌ فَأَتْمَرَتْ بَطَلَ وَالْكُلُّ لِلْبَائِعِ،"]]},{"id":"za91_6","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٦","segs":[["matn","وَإِذَا بَدَا مَا لَهُ صَلَاحٌ فِي الثَّمَرَةِ وَاشْتَدَّ الْحَبُّ جَازَ بَيْعُهُ مُطْلَقًا، وَبِشَرْطِ التَّبْقِيَةِ، وَلِلْمُشْتَرِي تَبْقِيَتُهُ إِلَى الْحَصَادِ وَالْجَذَاذِ، وَيَلْزَمُ الْبَائِعَ سَقْيُهُ، إِنِ احْتَاجَ إِلَى ذَلِكَ وَإِنْ تَضَرَّرَ الْأَصْلُ،"]]},{"id":"za91_7","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٧","segs":[["matn","وَإِنْ تَلِفَتْ بِآفَةٍ سَمَاوِيَّةٍ رَجَعَ عَلَى الْبَائِعِ، وَإِنْ أَتْلَفَهُ آدَمِيٌّ خُيِّرَ مُشْتَرٍ بَيْنَ الْفَسْخِ وَالْإِمْضَاءِ وَمُطَالَبَةِ الْمُتْلِفِ، وَصَلَاحُ بَعْضِ الشَّجَرَةِ صَلَاحٌ لَهَا، وَلِسَائِرِ النَّوْعِ الَّذِي فِي الْبُسْتَانِ،"]]},{"id":"za91_8","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٨","segs":[["matn","وَبُدُوُّ الصَّلَاحِ فِي ثَمَرِ النَّخْلِ أَنْ تَحْمَرَّ أَوْ تَصْفَرَّ، وِفِي الْعِنَبِ أَنْ يَتَمَوَّهَ حُلْوًا، وَفِي بَقِيَّةِ الثَّمَرَاتِ أَنْ يَبْدُوَ فِيهِ النُّضْجُ وَيَطِيبَ أَكْلُهُ، وَمَنْ بَاعَ عَبْدًا لَهُ مَالٌ فَمَالُهُ لِبَائِعِهِ إِلَّا أَنْ يَشْتَرِطَهُ الْمُشْتَرِي،"]]},{"id":"za91_9","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · فَصْلٌ · ٩","segs":[["matn","فَإِنْ كَانَ قَصْدُهُ الْمَالَ اشْتُرِطَ عِلْمُهُ وَسَائِرُ شُرُوطِ الْبَيْعِ وَإِلَّا فَلَا، وَثِيَابُ الْجَمَّالِ لِلْبَائِعِ، وَالْعَادَةُ لِلْمُشْتَرِي."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za92","title":"بَابُ السَّلَمِ","units":[{"id":"za92_1","label":"بَابُ السَّلَمِ · ١","segs":[["matn","وَهُوَ عَقْدٌ عَلَى مَوْصُوفٍ فِي الذِّمَّةِ مُؤَجَّلٍ بِثَمَنٍ مَقْبُوضٍ بِمَجْلِسِ الْعَقْدِ، وَيَصِحُّ بِأَلْفَاظِ الْبَيْعِ وَالسَّلَمِ وَالسَّلَفِ بِشُرُوطٍ سَبْعَةٍ: أَحَدُهَا انْضِبَاطُ صِفَاتِهِ بِمَكِيلٍ وَمَوْزُونٍ وَمَذْرُوعٍ، وَأَمَّا الْمَعْدُودُ الْمُخْتَلِفُ كَالْفَوَاكِهِ وَالْبُقُولِ وَالْجُلُودِ وَالرُّؤُوسِ وَالْأَوَانِي الْمُخْتَلِفَةِ الرُّؤُوسِ،"]]},{"id":"za92_2","label":"بَابُ السَّلَمِ · ٢","segs":[["matn","وَالْأَوْسَاطِ كَالْقَمَاقِمِ وَالْأَسْطَالِ الضَّيِّقَةِ الرُّؤُوسِ، وَالْجَوَاهِرِ وَالْحَامِلِ مِنَ الْحَيَوَانِ، وَكُلِّ مَغْشُوشٍ وَمَا يَجْمَعُ أَخْلَاطًا غَيْرَ مُتَمَيِّزَةٍ كَالْغَالِيَةِ وَالْمَعَاجِينِ فَلَا يَصِحُّ السَّلَمُ فِيهِ، وَيَصِحُّ فِي الْحَيَوَانِ وَالثِّيَابِ الْمَنْسُوجَةِ مِنْ نَوْعَيْنِ،"]]},{"id":"za92_3","label":"بَابُ السَّلَمِ · ٣","segs":[["matn","وَمَا خِلْطُهُ غَيْرُ مَقْصُودٍ كَالْجُبْنِ وَخَلِّ التَّمْرِ وَالسَّكَنْجَبِينَ وَنَحْوِهَا."]]},{"id":"za92_4","label":"بَابُ السَّلَمِ · ٤","segs":[["matn","الثَّانِي ذِكْرُ الْجِنْسِ وَالنَّوْعِ وَكُلِّ وَصْفٍ يَخْتَلِفُ بِهِ الثَّمَنُ ظَاهِرًا وَحَدَاثَتُهُ وَقِدَمُهُ، وَلَا يَصِحُّ شَرْطُ الْأَرْدَأِ أَوِ الْأَجْوَدِ، بَلْ جَيِّدٌ وَرَدِيءٌ، فَإِنْ جَاءَ بِمَا شَرَطَ أَوْ أَجْوَدَ مِنْهُ مِنْ نَوْعِهِ وَلَوْ قَبْلَ مَحَلِّهِ وَلَا ضَرَرَ فِي قَبْضِهِ لَزِمَهُ أَخْذُهُ."]]},{"id":"za92_5","label":"بَابُ السَّلَمِ · ٥","segs":[["matn","الثَّالِثُ ذِكْرُ قَدْرِهِ بِكَيْلٍ أَوْ وَزْنٍ أَوْ ذَرْعٍ يُعْلَمُ، وَإِنْ أَسْلَمَ فِي الْمَكِيلِ وَزْنًا أَوْ فِي الْمَوْزُونِ كَيْلًا لَمْ يَصِحَّ."]]},{"id":"za92_6","label":"بَابُ السَّلَمِ · ٦","segs":[["matn","الرَّابِعُ ذِكْرُ أَجَلٍ مَعْلُومٍ لَهُ وَقْعٌ فِي الثَّمَنِ، فَلَا يَصِحُّ حَالًّا وَلَا إِلَى الْحَصَادِ وَالْجَذَاذِ وَلَا إِلَى يَوْمٍ، إِلَّا فِي شَيْءٍ يَأْخُذُهُ مِنْهُ كُلَّ يَوْمٍ كَخُبْزٍ وَلَحْمٍ وَنَحْوِهِمَا."]]},{"id":"za92_7","label":"بَابُ السَّلَمِ · ٧","segs":[["matn","الْخَامِسُ أَنْ يُوجَدَ غَالِبًا فِي مَحِلِّهِ، وَمَكَانِ الْوَفَاءِ، لَا وَقْتَ الْعَقْدِ، فَإِنْ تَعَذَّرَ أَوْ بَعْضُهُ فَلَهُ الصَّبْرُ أَوْ فَسْخُ الْكُلِّ أَوِ الْبَعْضِ، وَيَأْخُذُ الثَّمَنَ الْمَوْجُودَ أَوْ عِوَضَهُ."]]},{"id":"za92_8","label":"بَابُ السَّلَمِ · ٨","segs":[["matn","السَّادِسُ أَنْ يَقْبِضَ الثَّمَنَ تَامًّا، مَعْلُومًا قَدْرُهُ وَوَصْفُهُ قَبْلَ التَّفَرُّقِ، وَإِنْ قَبَضَ الْبَعْضَ ثُمَّ افْتَرَقَا بَطَلَ فِيمَا عَدَاهُ، وَإِنْ أَسْلَمَ فِي جِنْسٍ إِلَى أَجَلَيْنِ أَوْ عَكْسَهُ صَحَّ إِنْ بَيَّنَ كُلَّ جِنْسٍ وَثَمَنَهُ وَقِسْطَ كُلِّ أَجَلٍ."]]},{"id":"za92_9","label":"بَابُ السَّلَمِ · ٩","segs":[["matn","السَّابِعُ أَنْ يُسْلِمَ فِي الذِّمَّةِ فَلَا يَصِحُّ فِي عَيْنٍ، وَيَجِبُ الْوَفَاءُ مَوْضِعَ الْعَقْدِ، وَيَصِحُّ شَرْطُهُ فِي غَيْرِهِ، وَإِنْ عُقِدَ بِبَرٍّ أَوْ بَحْرٍ شَرَطَاهُ، وَلَا يَصِحُّ بَيْعُ الْمُسْلَمِ فِيهِ قَبْلَ قَبْضِهِ، وَلَا هِبَتُهُ، وَلَا الْحَوَالَةُ بِهِ،"]]},{"id":"za92_10","label":"بَابُ السَّلَمِ · ١٠","segs":[["matn","وَلَا عَلَيْهِ، وَلَا أَخْذُ عِوَضِهِ، وَلَا يَصِحُّ الرَّهْنُ وَالْكَفِيلُ بِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za93","title":"بَابُ الْقَرْضِ","units":[{"id":"za93_1","label":"بَابُ الْقَرْضِ · ١","segs":[["matn","وَهُوَ مَنْدُوبٌ، وَمَا يَصِحُّ بَيْعُهُ صَحَّ قَرْضُهُ إِلَّا بَنِي آدَمَ، وَيُمْلَكُ بِقَبْضِهِ فَلَا يَلْزَمُ رَدُّ عَيْنِهِ، بَلْ يَثْبُتُ بَدَلُهُ فِي ذِمَّتِهِ حَالًّا، وَلَوْ أَجَّلَهُ، فَإِنْ رَدَّهُ الْمُقْتَرِضُ لَزِمَ قَبُولُهُ وَإِنْ كَانَتْ مُكَسَّرَةً أَوْ فُلُوسًا،"]]},{"id":"za93_2","label":"بَابُ الْقَرْضِ · ٢","segs":[["matn","فَمَنَعَ السُّلْطَانُ الْمُعَامَلَةَ بِهَا، فَلَهُ الْقِيمَةُ وَقْتَ الْقَرْضِ، وَيَرُدُّ الْمِثْلَ فِي الْمِثْلِيَّاتِ وَالْقِيمَةُ فِي غَيْرِهَا، فَإِنْ أَعْوَزَ الْمِثْلُ فَالْقِيْمَةُ إِذًا."]]},{"id":"za93_3","label":"بَابُ الْقَرْضِ · ٣","segs":[["matn","وَيَحْرُمُ كُلُّ شَرْطٍ جَرَّ نَفْعًا، وَإِنْ بَدَأَ بِهِ بِلَا شَرْطٍ، أَوْ أَعْطَاهُ أَجْوَدَ أَوْ هَدِيَّةً بَعْدَ الْوَفَاءِ جَازَ، وَإِنْ تَبَرَّعَ لِمُقْرِضِهِ قَبْلَ وَفَائِهِ بِشَيْءٍ لَمْ تَجْرِ عَادَتُهُ بِهِ لَمْ يَجُزْ،"]]},{"id":"za93_4","label":"بَابُ الْقَرْضِ · ٤","segs":[["matn","إِلَّا أَنْ يَنْوِيَ مُكَافَأَتَهُ أَوِ احْتِسَابَهُ مِنْ دَيْنِهِ، وَإِنْ أَقْرَضَهُ أَثْمَانًا فَطَالَبَهُ بِهَا بِبَلَدٍ آخَرَ لَزِمَتْهُ، وَفِيمَا لِحَمْلِهِ مُؤْنَةٌ قِيمَتِهِ إِنْ لَمْ تَكُنْ بِبَلَدِ الْقَرْضِ أَنْقَصَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za94","title":"بَابُ الرَّهْنِ","units":[{"id":"za94_1","label":"بَابُ الرَّهْنِ · ١","segs":[["matn","يَصِحُّ فِي كُلِّ عَيْنٍ يَجُوزُ بَيْعُهَا، حَتَّى الْمُكَاتَبِ، مَعَ الْحَقِّ وَبَعْدَهُ بِدَيْنٍ ثَابِتٍ، وَيَلْزَمُ فِي حَقِّ الرَّاهِنِ فَقَطْ، وَيَصِحُّ رَهْنُ الْمُشَاعِ، وَيَجُوزُ رَهْنُ الْمَبِيعِ غَيْرِ الْمَكِيلِ وَالْمَوْزُونِ عَلَى ثَمَنِهِ وَغَيْرِهِ،"]]},{"id":"za94_2","label":"بَابُ الرَّهْنِ · ٢","segs":[["matn","وَمَا لَا يَجُوزُ بَيْعُهُ لَا يَصِحُّ رَهْنُهُ، إِلَّا الثَّمَرَةَ وَالزَّرْعَ الْأَخْضَرَ قَبْلَ بُدُوِّ صَلَاحِهِمَا بِدُونِ شَرْطِ الْقَطْعِ، وَلَا يَلْزَمُ الرَّهْنُ إِلَّا بِالْقَبْضِ، وَاسْتِدَامَتُهُ شَرْطٌ، فَإِنْ أَخْرَجَهُ إِلَى الرَّاهِنِ بِاخْتِيَارِهِ زَالَ لُزُومُهُ،"]]},{"id":"za94_3","label":"بَابُ الرَّهْنِ · ٣","segs":[["matn","فَإِنْ رَدَّهَ إِلَيْهِ عَادَ لُزُومُهُ إِلَيْهِ، وَلَا يَنْفُذُ تَصَرُّفُ وَاحِدٍ مِنْهُمَا فِيهِ بِغَيْرِ إِذْنِ الْآخَرِ، إِلَّا عِتْقُ الرَّاهِنِ فَإِنَّهُ يَصِحُّ مَعَ الْإِثْمِ، وَتُؤْخَذُ قِيمَتُهُ رَهْنًا مَكَانَهُ، وَنَمَاءُ الرَّهْنِ وَكَسْبُهُ وَأَرْشُ الْجِنَايَةِ عَلَيْهِ مُلْحَقٌ بِهِ،"]]},{"id":"za94_4","label":"بَابُ الرَّهْنِ · ٤","segs":[["matn","وَمُؤْنَتُهُ عَلَى الرَّاهِنِ وَكَفَنُهُ وَأُجْرَةُ مَخْزَنِهِ، وَهُوَ أَمَانَةٌ فِي يَدِ الْمُرْتَهِنِ إِنْ تَلِفَ مِنْ غَيْرِ تَعَدٍّ مِنْهُ فَلَا شَيْءَ عَلَيْهِ، وَلَا يَسْقُطُ بِهَلَاكِهِ شَيْءٌ مِنْ دَيْنِهِ، وَإِنْ تَلِفَ بَعْضُهُ فَبَاقِيهِ رَهْنٌ بِجَمِيعِ الدَّيْنِ،"]]},{"id":"za94_5","label":"بَابُ الرَّهْنِ · ٥","segs":[["matn","وَلَا يَنْفَكُّ بَعْضُهُ مَعَ بَقَاءِ بَعْضِ الدَّيْنِ، وَتَجُوزُ الزِّيَادَةُ فِيهِ دُونَ دَيْنِهِ، وَإِنْ رَهَنَ عِنْدَ اثْنَيْنِ شَيْئًا فَوَفَّى أَحَدَهُمَا أَوْ رَهَنَاهُ شَيْئًا فَاسْتَوْفَى مِنْ أَحَدِهِمَا انْفَكَّ فِي نَصِيبِهِ،"]]},{"id":"za94_6","label":"بَابُ الرَّهْنِ · ٦","segs":[["matn","وَمَتَى حَلَّ الدَّيْنُ وَامْتَنَعَ مِنْ وَفَائِهِ فَإِنْ كَانَ الرَّاهِنُ أَذِنَ لِلْمُرْتَهِنِ أَوِ الْعَدْلِ فِي بَيْعِهِ بَاعَهُ وَوَفَّى الدَّيْنَ، وَإِلَّا أَجْبَرَهُ الْحَاكِمُ عَلَى وَفَائِهِ أَوْ بَيْعِ الرَّهْنِ، فَإِنْ لَمْ يَفْعَلْ بَاعَهَ الْحَاكِمُ وَوَفَّى دَيْنَهَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za95","title":"بَابُ الرَّهْنِ · فَصْلٌ","units":[{"id":"za95_1","label":"بَابُ الرَّهْنِ · فَصْلٌ · ١","segs":[["matn","وَيَكُونُ عِنْدَ مَنِ اتَّفَقَا عَلَيْهِ، وَإِنْ أَذِنَا لَهُ فِي الْبَيْعِ لَمْ يَبِعْ إِلَّا بِنَقْدِ الْبَلَدِ، وَإِنْ قَبَضَ الثَّمَنَ فَتَلِفَ فِي يَدِهِ فَمِنْ ضَمَانِ الرَّاهِنِ،"]]},{"id":"za95_2","label":"بَابُ الرَّهْنِ · فَصْلٌ · ٢","segs":[["matn","وَإِنِ ادَّعَى دَفْعَ الثَّمَنِ إِلَى الْمُرْتَهِنِ فَأَنْكَرَهُ وَلَا بَيِّنَةَ وَلَمْ يَكُنْ بِحُضُورِ الرَّاهِنِ ضَمِنَ كَوَكِيلٍ، وَإِنْ شَرَطَ أَلَّا يَبِيعَهُ إِذَا حَلَّ الدَّيْنُ، أَوْ إِنْ جَاءَهُ بِحَقِّهِ فِي وَقْتِ كَذَا،"]]},{"id":"za95_3","label":"بَابُ الرَّهْنِ · فَصْلٌ · ٣","segs":[["matn","وَإِلَّا فَالرَّهْنُ لَهُ لَمْ يَصِحَّ الشَّرْطُ وَحْدَهُ، وَيُقْبَلُ قَوْلُ رَاهِنٍ فِي قَدْرِ الدَّيْنِ وَالرَّهْنِ، وَرَدِّهِ، وَفِي كَوْنِهِ عَصِيرًا لَا خَمْرًا، وَإِنْ أَقَرَّ أَنَّهُ مِلْكُ غَيْرِهِ، أَوْ أَنَّهُ جَنَى قُبِلَ عَلَى نَفْسِهِ،"]]},{"id":"za95_4","label":"بَابُ الرَّهْنِ · فَصْلٌ · ٤","segs":[["matn","وَحُكِمَ بِإِقْرَارِهِ بَعْدَ فَكِّهِ إِلَّا أَنْ يُصَدِّقَهُ الْمُرْتَهِنُ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za96","title":"بَابُ الرَّهْنِ · فَصْلٌ (٢)","units":[{"id":"za96_1","label":"بَابُ الرَّهْنِ · فَصْلٌ (٢) · ١","segs":[["matn","وَلِلْمُرْتَهِنِ أَنْ يَرْكَبَ مَا يُرْكَبُ وَيَحْلُبَ مَا يُحْلَبُ بِقَدْرِ نَفَقَتِهِ بِلَا إِذْنٍ، وَإِنْ أَنْفَقَ عَلَى الرَّهْنِ بِغَيْرِ إِذْنِ الرَّاهِنِ مَعَ إِمْكَانِهِ لَمْ يَرْجِعْ، وَإِنْ تَعَذَّرَ رَجَعَ وَلَوْ لَمْ يَسْتَأْذِنِ الْحَاكِمَ،"]]},{"id":"za96_2","label":"بَابُ الرَّهْنِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَكَذَا وَدِيعَةٌ وَدَوَابُّ مُسْتَأْجَرَةٌ هَرَبَ رَبُّهَا، وَلَوْ خَرِبَ الرَّهْنُ فَعَمَّرَهُ بِلَا إِذْنٍ رَجَعَ بِآلَتِهِ فَقَطْ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za97","title":"بَابُ الضَّمَانِ","units":[{"id":"za97_1","label":"بَابُ الضَّمَانِ · ١","segs":[["matn","لَا يَصِحُّ إِلَّا مِنْ جَائِزِ التَّصَرُّفِ، وَلِرَبِّ الْحَقِّ مُطَالَبَةُ مَنْ شَاءَ مِنْهُمَا فِي الْحَيَاةِ وَالْمَوْتِ، فَإِنْ بَرِئَتْ ذِمَّةُ الْمَضْمُونِ عَنْهُ بَرِئَتْ ذِمَّةُ الضَّامِنِ، لَا عَكْسُهُ، وَلَا تُعْتَبَرُ مَعْرِفَةُ الضَّامِنِ لِلْمَضْمُونِ عَنْهُ وَلَا لَهُ،"]]},{"id":"za97_2","label":"بَابُ الضَّمَانِ · ٢","segs":[["matn","بَلْ رِضَا الضَّامِنِ، وَيَصِحُّ ضَمَانُ الْمَجْهُولِ إِذَا آلَ إِلَى الْعِلْمِ وَالْعَوَارِي وَالْمَغْصُوبِ وَالْمَقْبُوضِ بِسَوْمٍ، وَعُهْدَةِ مَبِيعٍ، لَا ضَمَانُ الْأَمَانَاتِ بَلِ التَّعَدِّي فِيهَا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za98","title":"بَابُ الضَّمَانِ · فَصْلٌ","units":[{"id":"za98_1","label":"بَابُ الضَّمَانِ · فَصْلٌ · ١","segs":[["matn","وَتَصِحُّ الْكَفَالَةُ بِكُلِّ عَيْنٍ مَضْمُونَةٍ، وَبِبَدَنِ مَنْ عَلَيْهِ دَيْنٌ، لَا حَدَّ وَلَا قِصَاصَ، وَيُعْتَبَرُ رِضَا الْكَفِيلِ لَا مَكْفُولَ بِهِ، فَإِنْ مَاتَ أَوْ تَلِفَتِ الْعَيْنُ بِفِعْلِ اللَّهِ تَعَالَى، أَوْ سَلَّمَ نَفْسَهُ بَرِئَ الْكَفِيلُ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za99","title":"بَابُ الْحَوَالَةِ","units":[{"id":"za99_1","label":"بَابُ الْحَوَالَةِ · ١","segs":[["matn","لَا تَصِحُّ إِلَّا عَلَى دَيْنٍ مُسْتَقِرٍّ، وَلَا يُعْتَبَرُ اسْتِقْرَارُ الْمُحَالِ فِيهِ."]]},{"id":"za99_2","label":"بَابُ الْحَوَالَةِ · ٢","segs":[["matn","وَيُشْتَرَطُ اتِّفَاقُ الدَّيْنَيْنِ جِنْسًا وَوَصْفًا وَوَقْتًا وَقَدْرًا، وَلَا يُؤَثِّرُ الْفَاضِلُ، وَإِذَا صَحَّتْ نُقِلَ الْحَقُّ إِلَى ذِمَّةِ الْمُحَالِ عَلَيْهِ وَبَرِئَ الْمُحِيلُ، وَيُعَتَبَرُ رِضَاهُ لَا رِضَا الْمُحَالِ عَلَيْهِ، وَلَا رِضَا الْمُحْتَالِ عَلَى مَلِيءٍ،"]]},{"id":"za99_3","label":"بَابُ الْحَوَالَةِ · ٣","segs":[["matn","وَإِنْ كَانَ مُفْلِسًا وَلَمْ يَكُنْ رَضِيَ رَجَعَ بِهِ، وَمَنْ أُحِيلَ بِثَمَنِ مَبِيعٍ، أَوْ أُحِيلَ بِهِ عَلَيْهِ، فَبَانَ الْبَيْعُ بَاطِلًا فَلَا حَوَالَةَ، وَإِذَا فُسِخَ الْبَيْعُ لَمْ تَبْطُلْ، وَلَهُمَا أَنْ يُحِيلَا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za100","title":"بَابُ الصُّلْحِ","units":[{"id":"za100_1","label":"بَابُ الصُّلْحِ · ١","segs":[["matn","إِذَا أَقَرَّ لَهُ بِدَيْنٍ أَوْ عَيْنٍ فَأَسْقَطَ، أَوْ وَهَبَ الْبَعْضَ وَتَرَكَ الْبَاقِيَ صَحَّ إِنْ لَمْ يَكُنْ شَرَطَاهُ، وَمِمَّنْ لَا يَصِحُّ تَبَرُّعُهُ، وَإِنْ وَضَعَ بَعْضَ الْحَالِّ وَأَجَّلَ بَاقِيَهُ صَحَّ الْإِسْقَاطُ فَقَطْ،"]]},{"id":"za100_2","label":"بَابُ الصُّلْحِ · ٢","segs":[["matn","وَإِنْ صَالَحَ عَنِ الْمُؤَجَّلِ بِبَعْضِهِ حَالًّا أَوْ بِالْعَكْسِ، أَوْ أَقَرَّ لَهُ بِبَيْتٍ فَصَالَحَهُ عَلَى سُكْنَاهُ، أَوْ يَبْنِيَ لَهُ فَوْقَهُ غُرْفَةً، أَوْ صَالَحَ مُكَلَّفًا لِيُقِرَّ لَهُ بِالْعُبُودِيَّةِ أَوِ امْرَأَةً لِتُقِرَّ لَهُ بِالزَّوْجِيَّةِ بِعِوَضٍ لَمْ يَصِحَّ،"]]},{"id":"za100_3","label":"بَابُ الصُّلْحِ · ٣","segs":[["matn","وَإِنْ بَذَلَاهُمَا لَهُ صُلْحًا عَنْ دَعْوَاهُ صَحَّ، وَإِنْ قَالَ: أَقِرَّ بِدَيْنِي وَأُعْطِيكَ مِنْهُ كَذَا فَفَعَلَ صَحَّ الْإِقْرَارُ لَا الصُّلْحُ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za101","title":"بَابُ الصُّلْحِ · فَصْلٌ","units":[{"id":"za101_1","label":"بَابُ الصُّلْحِ · فَصْلٌ · ١","segs":[["matn","وَمَنِ ادُّعِيَ عَلَيْهِ بِعَيْنٍ أَوْ دَيْنٍ فَسَكَتَ أَوْ أَنْكَرَ وَهَوَ يَجْهَلُهُ ثُمَّ صَالَحَ بِمَالٍ صَحَّ، وَهُوَ لِلْمُدَّعِي بَيْعٌ يَرُدُّ مَعِيبَهُ، وَيَفْسَخُ الصُّلْحَ، وَيُؤْخَذُ مِنْهُ بِشُفْعَةٍ، وَلِلْآخَرِ إِبْرَاءٌ، فَلَا رَدَّ وَلَا شُفْعَةَ،"]]},{"id":"za101_2","label":"بَابُ الصُّلْحِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ كَذَبَ أَحَدُهُمَا لَمْ يَصِحَّ فِي حَقِّهِ بَاطِنًا، وَمَا أَخَذَهُ حَرَامٌ، وَلَا يَصِحُّ بِعِوَضٍ عَنْ حَدِّ سَرِقَةٍ وَقَذْفٍ وَلَا حَقِّ شُفْعَةٍ وَتَرْكِ شَهَادَةٍ، وَتَسْقُطُ الشُّفْعَةُ وَالْحَدُّ."]]},{"id":"za101_3","label":"بَابُ الصُّلْحِ · فَصْلٌ · ٣","segs":[["matn","وَإِنْ حَصَلَ غُصْنُ شَجَرَتِهِ فِي هَوَاءِ غَيْرِهِ أَوْ قَرَارِهِ أَزَالَهُ، فَإِنْ أَبَى لَوَاهُ إِنْ أَمْكَنَ، وَإِلَّا فَلَهُ قَطْعُهُ، وَيَجُوزُ فِي الدَّرْبِ النَّافِذِ فَتْحُ الْأَبْوَابِ لِلِاسْتِطْرَاقِ لَا إِخْرَاجُ رَوْشَنٍ وَسَابَاطٍ وَدَكَّةٍ وَمِيزَابٍ،"]]},{"id":"za101_4","label":"بَابُ الصُّلْحِ · فَصْلٌ · ٤","segs":[["matn","وَلَا يَفْعَلُ ذَلِكَ فِي مِلْكِ جَارٍ وَدَرْبٍ مُشْتَرَكٍ بِلَا إِذْنِ الْمُسْتَحِقِّ، وَلَيْسَ لَهُ وَضْعُ خُشُبَهُ عَلَى حَائِطِ جَارِهِ إِلَّا عِنْدَ الضَّرُورَةِ إِذَا لَمْ يُمْكِنْهُ التَّسْقِيفُ إِلَّا بِهِ، وَكَذَلِكَ الْمَسْجِدُ وَغَيْرُهُ،"]]},{"id":"za101_5","label":"بَابُ الصُّلْحِ · فَصْلٌ · ٥","segs":[["matn","وَإِذَا انْهَدَمَ جِدَارُهُمَا أَوْ خِيفَ ضَرَرُهُ فَطَلَبَ أَحَدُهُمَا أَنْ يُعَمِّرَهُ الْآخَرُ مَعَهُ أُجْبِرَ عَلَيْهِ، وَكَذَا النَّهْرُ وَالدُّولَابُ وَالْقَنَاةُ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za102","title":"بَابُ الْحَجْرِ","units":[{"id":"za102_1","label":"بَابُ الْحَجْرِ · ١","segs":[["matn","وَمَنْ لَمْ يَقْدِرْ عَلَى وَفَاءِ شَيْءٍ مِنْ دَيْنِهِ لَمْ يُطَالَبْ بِهِ وَحَرُمَ حَبْسُهُ، وَمَنْ مَالُهُ قَدْرُ دَيْنِهِ لَمْ يُحْجَرْ عَلَيْهِ، وَأُمِرَ بِوَفَائِهِ، فَإِنْ أَبَى حُبِسَ بِطَلَبِ رَبِّهِ،"]]},{"id":"za102_2","label":"بَابُ الْحَجْرِ · ٢","segs":[["matn","فَإِنْ أَصَرَّ وَلَمْ يَبِعْ مَالَهُ بَاعَهُ الْحَاكِمُ وَقَضَاهُ وَلَا يُطْلَبُ بِمُؤَجَّلٍ، وَمَنْ مَالُهُ لَا يَفِي بِمَا عَلَيْهِ حَالًّا وَجَبَ الْحَجْرُ عَلَيْهِ بِسُؤَالِ غُرَمَائِهِ أَوْ بَعْضِهِمْ، وَيُسْتَحَبُّ إِظْهَارُهُ،"]]},{"id":"za102_3","label":"بَابُ الْحَجْرِ · ٣","segs":[["matn","وَلَا يَنْفُذُ تَصَرُّفُهُ فِي مَالِهِ بَعْدَ الْحَجْرِ وَلَا إِقْرَارُهُ عَلَيْهِ، وَمَنْ بَاعَهُ أَوْ أَقْرَضَهُ شَيْئًا بَعْدَهُ رَجَعَ فِيهِ إِنْ جَهِلَ حَجْرَهُ وَإِلَّا فَلَا،"]]},{"id":"za102_4","label":"بَابُ الْحَجْرِ · ٤","segs":[["matn","وَإِنْ تَصَرَّفَ فِي ذِمَّتِهِ أَوْ أَقَرَّ بِدَيْنٍ أَوْ جِنَايَةٍ تُوجِبُ قَوَدًا أَوْ مَالًا صَحَّ وَيُطَالَبُ بِهِ بَعْدَ فَكِّ الْحَجْرِ عَنْهُ، وَيَبِيْعُ الْحَاكِمُ مَالَهُ وَيُقَسِّمُ ثَمَنَهُ بِقَدْرِ دُيُونِ غُرَمَائِهِ،"]]},{"id":"za102_5","label":"بَابُ الْحَجْرِ · ٥","segs":[["matn","وَلَا يَحِلُّ مُؤَجَّلٌ بِفَلَسٍ وَلَا بِمَوْتٍ إِنْ وَثَّقَ وَرَثَتُهُ بِرَهْنٍ أَوْ كَفِيلٍ مَلِيءٍ، وَإِنْ ظَهَرَ غَرِيمٌ بَعْدَ الْقِسْمَةِ رَجَعَ عَلَى الْغُرَمَاءِ بِقِسْطِهِ، وَلَا يَفُكُّ حَجْرَهُ إِلَّا حَاكِمٌ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za103","title":"بَابُ الْحَجْرِ · فَصْلٌ","units":[{"id":"za103_1","label":"بَابُ الْحَجْرِ · فَصْلٌ · ١","segs":[["matn","وَيُحْجَرُ عَلَى السَّفِيهِ وَالصَّغِيرِ وَالْمَجْنُونِ لِحَظِّهِمْ، وَمَنْ أَعْطَاهُمْ مَالَهُ بَيْعًا أَوْ قَرْضًا رَجَعَ بِعَيْنِهِ وَإِنْ أَتْلَفُوهُ لَمْ يَضْمَنُوا، وَيَلْزَمُهُمْ أَرْشُ الْجِنَايَةِ وَضَمَانُ مَالِ مَنْ لَمْ يَدْفَعْهُ إِلَيْهِمْ،"]]},{"id":"za103_2","label":"بَابُ الْحَجْرِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ تَمَّ لِصَغِيرٍ خَمْسَ عَشْرَةَ سَنَةً أَوْ نَبَتَ حَوْلَ قُبُلِهِ شَعْرٌ خَشِنٌ أَوْ أَنْزَلَ، أَوْ عَقَلَ مَجْنُونٌ وَرَشَدَ، أَوْ رَشَدَ سَفِيهٌ، زَالَ حَجْرُهُمْ بِلَا قَضَاءٍ، وَتَزِيدُ الْجَارِيَةُ فِي الْبُلُوغَ بِالْحَيْضِ، وَإِنْ حَمَلَتْ حُكِمَ بِبُلُوغِهَا،"]]},{"id":"za103_3","label":"بَابُ الْحَجْرِ · فَصْلٌ · ٣","segs":[["matn","وَلَا يَنْفَكُّ الْحَجْرُ قَبْلَ شُرُوطِهِ، وَالرُّشْدُ الصَّلَاحُ فِي الْمَالِ بِأَنْ يَتَصَرَّفَ مِرَارًا فَلَا يُغْبَنُ غَالِبًا، وَلَا يَبْذُلُ مَالَهُ فِي حَرَامٍ أَوْ فِي غَيْرِ فَائِدَةٍ، وَلَا يُدْفَعُ إِلَيْهِ حَتَّى يُخْتَبَرَ قَبْلَ بُلُوغِهِ بِمَا يَلِيقُ بِهِ،"]]},{"id":"za103_4","label":"بَابُ الْحَجْرِ · فَصْلٌ · ٤","segs":[["matn","وَوَلِيُّهُمْ حَالَ الْحَجْرِ الْأَبُ ثُمَّ وَصِيُّهُ ثُمَّ الْحَاكِمُ، وَلَا يَتَصَرَّفُ لِأَحَدِهِمْ وَلِيُّهُ إِلَّا بِالْأَحَظِّ، وَيَتَّجِرُ لَهُ مَجَّانًا، وَلَهُ دَفْعُ مَالِهِ مُضَارَبَةً بِجُزْءٍ مِنَ الرِّبْحِ،"]]},{"id":"za103_5","label":"بَابُ الْحَجْرِ · فَصْلٌ · ٥","segs":[["matn","وَيَأْكُلُ الْوَلِيُّ الْفَقِيرُ مِنْ مَالِ مُوَلِّيهِ الْأَقَلَّ مِنْ كِفَايَتِهِ أَوْ أُجْرَتِهِ مَجَّانًا، وَيُقْبَلُ قَوْلُ الْوَلِيِّ وَالْحَاكِمِ بَعْدَ فَكِّالْحَجْرِ فِي النَّفَقَةِ وَالضَّرُورَةِ وَالْغِبْطَةِ وَالتَّلَفِ وَدَفْعِ الْمَالِ، وَمَا اسْتَدَانَ الْعَبْدُ لَزِمَ سَيِّدَهُ إِنْ أَذِنَ لَهُ،"]]},{"id":"za103_6","label":"بَابُ الْحَجْرِ · فَصْلٌ · ٦","segs":[["matn","وَإِلَّا فَفِي رَقَبَتِهِ كَاسْتِيدَاعِهِ وَأَرْشِ جِنَايَتِهِ وَقِيمَةِ مُتْلَفِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za104","title":"بَابُ الْوَكَالَةِ","units":[{"id":"za104_1","label":"بَابُ الْوَكَالَةِ · ١","segs":[["matn","تَصِحُّ بِكُلِّ قَوْلٍ يَدُلُّ عَلَى الْإِذْنِ، وَيَصِحُّ الْقَبُولُ عَلَى الْفَوْرِ وَالتَّرَاخِي بِكُلِّ قَوْلٍ أَوْ فِعْلٍ دَالٍّ عَلَيْهِ، وَمَنْ لَهُ التَّصَرُّفُ فِي شَيْءٍ فَلَهُ التَّوْكِيلُ وَالتَّوَكُّلُ فِيهِ، وَيَصِحُّ التَّوْكِيلُ فِي كُلِّ حَقِّ آدَمِيٍّ مِنَ الْعُقُودِ وَالْفُسُوخِ،"]]},{"id":"za104_2","label":"بَابُ الْوَكَالَةِ · ٢","segs":[["matn","وَالْعِتْقِ وَالطَّلَاقِ، وَالرَّجْعَةِ وَتَمَلُّكِ الْمُبَاحَاتِ مِنَ الصَّيْدِ وَالْحَشِيشِ وَنَحْوِهِ، لَا الظِّهَارِ وَاللِّعَانِ وَالْأَيْمَانِ، وَفِي كُلِّ حَقٍّ لِلَّهِ تَدْخُلُهُ النِّيَابَةُ مِنَ الْعِبَادَاتِ وَالْحُدُودِ فِي إِثْبَاتِهَا وَاسْتِيفَائِهَا،"]]},{"id":"za104_3","label":"بَابُ الْوَكَالَةِ · ٣","segs":[["matn","وَلَيْسَ لِلْوَكِيلِ أَنْ يُوَكِّلَ فِيمَا وُكِّلَ فِيهِ إِلَّا أَنْ يُجْعَلَ إِلَيْهِ."]]},{"id":"za104_4","label":"بَابُ الْوَكَالَةِ · ٤","segs":[["matn","وَالْوَكَالَةُ عَقْدٌ جَائِزٌ، وَتَبْطُلُ بِفَسْخِ أَحَدِهِمَا وَمَوْتِهِ وَعَزْلِ الْوَكِيلِ وَحَجْرِ السَّفِيهِ، وَمَنْ وُكِّلَ فِي بَيْعٍ أَوْ شِرَاءٍ لَمْ يَبِعْ وَلَمْ يَشْتَرِ مِنْ نَفْسِهِ وَوَلَدِهِ، وَلَا يَبِيعُ بَعَرَضٍ وَلَا نَسَاءٍ وَلَا بِغَيْرِ نَقْدِ الْبَلَدِ،"]]},{"id":"za104_5","label":"بَابُ الْوَكَالَةِ · ٥","segs":[["matn","وَإِنْ بَاعَ بِدُونِ ثَمَنِ الْمِثْلِ أَوْ دُونِ مَا قَدَّرَهُ لَهُ أَوِ اشْتَرَى لَهُ بِأَكْثَرَ مِنْ ثَمَنِ الْمِثْلِ أَوْ مِمَّا قَدَّرَهُ لَهُ صَحَّ، وَضَمِنَ النَّقْصَ وَالزِّيَادَةَ، وَإِنْ بَاعَ بِأَزْيَدَ، أَوْ قَالَ: بِعْ بِكَذَا مُؤَجَّلًا،"]]},{"id":"za104_6","label":"بَابُ الْوَكَالَةِ · ٦","segs":[["matn","فَبَاعَ بِهِ حَالًّا، أَوْ: اشْتَرِ بِكَذَا حَالًّا، فَاشْتَرَى بِهِ مُؤَجَّلًا وَلَا ضَرَرَ فِيهِمَا صَحَّ وَإِلَّا فَلَا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za105","title":"بَابُ الْوَكَالَةِ · فَصْلٌ","units":[{"id":"za105_1","label":"بَابُ الْوَكَالَةِ · فَصْلٌ · ١","segs":[["matn","وَإِنِ اشْتَرَى مَا يَعْلَمُ عَيْبَهُ لَزِمَهُ إِنْ لَمْ يَرْضَ مُوَكِّلُهُ، فَإِنْ جَهِلَ رَدَّهُ، وَوَكِيلُ الْبَيْعِ يُسَلِّمُهُ وَلَا يَقْبِضُ الثَّمَنَ بِغَيْرِ قَرِينَةٍ، وَيُسَلِّمُ وَكِيلُ الْمُشْتَرِي الثَّمَنَ، فَلَوْ أَخَّرَهُ بِلَا عُذْرٍ وَتَلِفَ ضَمِنَهُ،"]]},{"id":"za105_2","label":"بَابُ الْوَكَالَةِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ وَكَّلَهُ فِي بَيْعٍ فَاسِدٍ فَبَاعَ صَحِيحًا، أَوْ وَكَّلَهُ فِي كُلِّ قَلِيلٍ وَكَثِيرٍ أَوْ شِرَاءِ مَا شَاءَ أَوْ عَيْنًا بِمَا شَاءَ، وَلَمْ يُعَيِّنْ لَمْ يَصِحَّ، وَالْوَكِيلُ فِي الْخُصُومَةِ لَا يَقْبِضُ وَالْعَكْسُ بِالْعَكْسِ،"]]},{"id":"za105_3","label":"بَابُ الْوَكَالَةِ · فَصْلٌ · ٣","segs":[["matn","وَاقْبِضْ حَقِّي مِنْ زَيْدٍ لَا يَقْبِضُ مِنْ وَرَثَتِهِ، إِلَّا أَنْ يَقُولَ الَّذِي قِبَلَهُ، وَلَا يَضْمَنُ وَكِيلٌ الْإِيدَاعَ إِذَا لَمْ يُشْهِدْ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za106","title":"بَابُ الْوَكَالَةِ · فَصْلٌ (٢)","units":[{"id":"za106_1","label":"بَابُ الْوَكَالَةِ · فَصْلٌ (٢) · ١","segs":[["matn","وَالْوَكِيلُ أَمِينٌ لَا يَضْمَنُ مَا تَلِفَ بِيَدِهِ بِلَا تَفْرِيطٍ، وَيُقْبَلُ قَوْلُهُ فِي نَفْيِهِ وَالْهَلَاكِ مَعَ يَمِينِهِ، وَمَنِ ادَّعَى وَكَالَةَ زَيْدٍ فِي قَبْضِ حَقِّهِ مِنْ عَمْرٍو لَمْ يَلْزَمْهُ دَفْعُهُ إِنْ صَدَّقَهُ وَلَا الْيَمِينُ إِنْ كَذَّبَهُ،"]]},{"id":"za106_2","label":"بَابُ الْوَكَالَةِ · فَصْلٌ (٢) · ٢","segs":[["matn","فَإِنْ دَفَعَهُ فَأَنْكَرَ زَيْدٌ الْوَكَالَةَ حَلَفَ وَضَمِنَهُ عَمْرٌو، وَإِنْ كَانَ الْمَدْفُوعُ وَدِيعَةً أَخَذَهَا، فَإِنْ تَلِفَتْ ضَمَّنَ أَيُّهُمَا شَاءَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za107","title":"بَابُ الشَّرِكَةِ","units":[{"id":"za107_1","label":"بَابُ الشَّرِكَةِ · ١","segs":[["matn","وَهِيَ اجْتِمَاعٌ فِي اسْتِحْقَاقٍ أَوْ تَصَرُّفٍ، وَهِيَ أَنْوَاعٌ: فَشَرِكَةُ عِنَانٍ أَنْ يَشْتَرِكَ بَدَنَانِ بِمَالَيْهِمَا الْمَعْلُومِ وَلَوْ مُتَفَاوِتًا لِيَعْمَلَا فِيهِ بِبَدَنَيْهِمَا، فَيَنْفُذُ تَصَرُّفُ كُلٍّ مِنْهُمَا فِيهِمَا بِحُكْمِ الْمِلْكِ فِي نَصِيبِهِ، وَبِالْوَكَالَةِ فِي نَصِيبِ شَرِيكِهِ،"]]},{"id":"za107_2","label":"بَابُ الشَّرِكَةِ · ٢","segs":[["matn","وَيُشْتَرَطُ أَنْ يَكُونَ رَأْسُ الْمَالِ مِنَ النَّقْدَيْنِ الْمَضْرُوبَيْنِ وَلَوْ مَغْشُوشَيْنِ يَسِيرًا، وَأَنْ يَشْتَرِطَا لِكُلٍّ مِنْهُمَا جُزْءًا مِنَ الرِّبْحِ مُشَاعًا مَعْلُومًا،"]]},{"id":"za107_3","label":"بَابُ الشَّرِكَةِ · ٣","segs":[["matn","فَإِنْ لَمْ يَذْكُرَا الرِّبْحَ أَوْ شَرَطَا لِأَحَدِهِمَا جُزْءًا مَجْهُولًا أَوْ دَرَاهِمَ مَعْلُومَةً أَوْ رِبْحَ أَحَدِ الثَّوْبَيْنِ لَمْ تَصِحَّ، وَكَذَا مُسَاقَاةٌ وَمُزَارَعَةٌ وَمُضَارَبَةٌ، وَالْوَضِيعَةُ عَلَى قَدْرِ الْمَالِ."]]},{"id":"za107_4","label":"بَابُ الشَّرِكَةِ · ٤","segs":[["matn","وَلَا يُشْتَرَطُ خَلْطُ الْمَالَيْنِ وَلَا كَوْنُهُمَا مِنْ جِنْسٍ وَاحِدٍ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za108","title":"بَابُ الشَّرِكَةِ · فَصْلٌ","units":[{"id":"za108_1","label":"بَابُ الشَّرِكَةِ · فَصْلٌ · ١","segs":[["matn","الثَّانِي: الْمُضَارَبَةُ لِمُتَّجِرٍ بِهِ بِبَعْضِ رِبْحِهِ، فَإِنْ قَالَ: وَالرِّبْحُ بَيْنَنَا."]]},{"id":"za108_2","label":"بَابُ الشَّرِكَةِ · فَصْلٌ · ٢","segs":[["matn","فَنِصْفَانِ، وَإِنْ قَالَ: وَلِي أَوْ لَكَ ثَلَاثَةُ أَرْبَاعِهِ أَوْ ثُلُثُهُ."]]},{"id":"za108_3","label":"بَابُ الشَّرِكَةِ · فَصْلٌ · ٣","segs":[["matn","صَحَّ، وَالْبَاقِي لِلْآخَرِ، وَإِنِ اخْتَلَفَا لِمَنِ الْمَشْرُوطُ فَلِعَامِلٍ، وَكَذَا مُسَاقَاةٌ وَمُزَارَعَةٌ، وَلَا يُضَارِبُ بِمَالٍ لِآخَرَ إِنْ أَضَرَّ الْأَوَّلَ وَلَمْ يَرْضَ، فَإِنْ فَعَلَ رَدَّ حِصَّتَهُ فِي الشَّرِكَةِ، وَلَا يُقْسَمُ مَعْ بَقَاءِ الْعَقْدِ إِلَّا بِاتِّفَاقِهِمَا،"]]},{"id":"za108_4","label":"بَابُ الشَّرِكَةِ · فَصْلٌ · ٤","segs":[["matn","وَإِنْ تَلِفَ رَأْسُ الْمَالِ أَوْ بَعْضُهُ بَعْدَ التَّصَرُّفِ، أَوْ خَسِرَ جُبِرَ مِنَ الرِّبْحِ قَبْلَ قِسْمَتِهِ أَوْ تَنْضِيضِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za109","title":"بَابُ الشَّرِكَةِ · فَصْلٌ (٢)","units":[{"id":"za109_1","label":"بَابُ الشَّرِكَةِ · فَصْلٌ (٢) · ١","segs":[["matn","الثَّالِثُ شَرِكَةُ الْوُجُوهِ أَنْ يَشْتَرِيَا فِي ذِمَّتَيْهِمَا، بِجَاهِهِمَا، فَمَا رَبِحَاهُ فَبَيْنَهُمَا، وَكُلُّ وَاحِدٍ مِنْهُمَا وَكِيلُ صَاحِبِهِ وَكَفِيلٌ عَنْهُ بِالثَّمَنِ، وَالْمِلْكُ بَيْنَهُمَا عَلَى مَا شَرَطَاهُ، وَالْوَضِيعَةُ عَلَى قَدْرِ مِلْكَيْهِمَا، وَالرِّبْحُ عَلَى مَا شَرَطَا."]]},{"id":"za109_2","label":"بَابُ الشَّرِكَةِ · فَصْلٌ (٢) · ٢","segs":[["matn","الرَّابِعُ شَرِكَةُ الْأَبْدَانِ أَنْ يَشْتَرِكَا فِيمَا يَكْتَسِبَانِ بِأَبْدَانِهِمَا، فَمَا تَقَبَّلَهُ أَحَدُهُمَا مِنْ عَمَلٍ يَلْزَمُهُمَا فِعْلُهُ، وَتَصِحُّ فِي الْاحْتِشَاشِ وَالْاحْتِطَابِ وَسَائِرِ الْمُبَاحَاتِ، وَإِنْ مَرِضَ أَحَدُهُمَا فَالْكَسْبُ بَيْنَهُمَا، وَإِنْ طَالَبَهُ الصَّحِيحُ أَنْ يُقِيمَ مُقَامَهُ لَزِمَهُ."]]},{"id":"za109_3","label":"بَابُ الشَّرِكَةِ · فَصْلٌ (٢) · ٣","segs":[["matn","الْخَامِسُ شَرِكَةُ الْمُفَاوَضَةِ أَنْ يُفَوِّضَ كُلٌّ مِنْهُمَا إِلَى صَاحِبِهِ كُلَّ تَصَرُّفٍ مَالِيٍّ وَبَدَنِيٍّ مِنْ أَنْوَاعِ الشَّرِكَةِ، وَالرِّبْحُ عَلَى مَا شَرَطَاهُ، وَالْوَضِيعَةُ بِقَدْرِ الْمَالِ، فَإِنْ أَدْخَلَا فِيهَا كَسْبًا أَوْ غَرَامَةً نَادِرَيْنِ أَوْ مَا يَلْزَمُ أَحَدَهُمَا مِنْ ضَمَانِ غَصْبٍ أَوْ نَحْوِهِ فَسَدَتْ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za110","title":"بَابُ الْمُسَاقَاةِ","units":[{"id":"za110_1","label":"بَابُ الْمُسَاقَاةِ · ١","segs":[["matn","تَصِحُّ عَلَى شَجَرٍ لَهُ ثَمَرٌ يُؤْكَلُ، وَعَلَى ثَمَرَةٍ مَوْجُودَةٍ، وَعَلَى شَجَرٍ يَغْرِسُهُ وَيَعْمَلُ عَلَيْهِ حَتَّى يُثْمِرَ بِجُزْءٍ مِنَ الثَّمَرَةِ، وَهُوَ عَقْدٌ جَائِزٌ، فَإِنْ فَسَخَ الْمَالِكُ قَبْلَ ظُهُورِ الثَّمَرَةِ فَلِلْعَامِلِ الْأُجْرَةُ،"]]},{"id":"za110_2","label":"بَابُ الْمُسَاقَاةِ · ٢","segs":[["matn","وَإِنْ فَسَخَهَا هُوَ فَلَا شَيْءَ لَهُ، وَيَلْزَمُ الْعَامِلَ كُلُّ مَا فِيهِ صَلَاحُ الثَّمَرَةِ مِنْ حَرْثٍ وَسَقْيٍ وَزِبَارٍ وَتَلْقِيحٍ وَتَشْمِيسٍ وَإِصْلَاحِ مَوْضِعِهِ وَطُرُقِ الْمَاءِ وَحَصَادٍ وَنَحْوِهِ،"]]},{"id":"za110_3","label":"بَابُ الْمُسَاقَاةِ · ٣","segs":[["matn","وَعَلَى رَبِّ الْمَالِ مَا يُصْلِحُهُ كَسَدِّ حَائِطٍ وَإِجْرَاءِ الْأَنْهَارِ وَالدُّولَابِ وَنَحْوِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za111","title":"بَابُ الْمُسَاقَاةِ · فَصْلٌ","units":[{"id":"za111_1","label":"بَابُ الْمُسَاقَاةِ · فَصْلٌ · ١","segs":[["matn","وَتَصِحُّ الْمُزَارَعَةُ بِجُزْءٍ مَعْلُومِ النِّسْبَةِ مِمَّا يَخْرُجُ مِنَ الْأَرْضِ لِرَبِّهَا، أَوْ لِلْعَامِلِ، وَالْبَاقِي لِلْآخَرِ، وَلَا يُشْتَرَطُ كَوْنُ الْبَذْرِ وَالْغِرَاسِ مِنْ رَبِّ الْأَرْضِ، وَعَلَيْهِ عَمَلُ النَّاسِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za112","title":"بَابُ الْإِجَارَةِ","units":[{"id":"za112_1","label":"بَابُ الْإِجَارَةِ · ١","segs":[["matn","تَصِحُّ بِثَلَاثَةِ شُرُوطٍ: مَعْرِفَةُ الْمَنْفَعَةِ كَسُكْنَى دَارٍ وَخِدْمَةِ آدَمِيٍّ وَتَعْلِيمِ عِلْمٍ."]]},{"id":"za112_2","label":"بَابُ الْإِجَارَةِ · ٢","segs":[["matn","الثَّانِي: مَعْرِفَةُ الْأُجْرَةِ وَتَصِحُّ فِي الْأَجِيرِ وَالظِّئْرِ بِطَعَامِهِمَا وَكِسْوَتِهِمَا، وَإِنْ دَخَلَ حَمَّامًا أَوْ سَفِينَةً أَوْ أَعْطَى ثَوْبَهُ قَصَّارًا أَوْ خَيَّاطًا بِلَا عَقْدٍ صَحَّ بِأُجْرَةِ الْعَادَةِ."]]},{"id":"za112_3","label":"بَابُ الْإِجَارَةِ · ٣","segs":[["matn","الثَّالِثُ: الْإِبَاحَةُ فِي الْعَيْنِ، فَلَا تَصِحُّ عَلَى نَفْعٍ مُحَرَّمٍ، كَالزِّنَا وَالزَّمْرِ وَالْغِنَاءِ، وَجَعْلِ دَارِهِ كَنِيسَةً أَوْ لِبَيْعِ الْخَمْرِ، وَتَصِحُّ إِجَارَةُ حَائِطٍ لِوَضْعِ أَطْرَافِ خُشُبِهِ عَلَيْهِ، وَلَا تُؤَجِّرُ الْمَرْأَةُ نَفْسَهَا بِغَيْرِ إِذْنِ زَوْجِهَا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za113","title":"بَابُ الْإِجَارَةِ · فَصْلٌ","units":[{"id":"za113_1","label":"بَابُ الْإِجَارَةِ · فَصْلٌ · ١","segs":[["matn","وَيُشْتَرَطُ فِي الْعَيْنِ الْمُؤَجَّرَةِ مَعْرِفَتُهَا بِرُؤْيَةٍ أَوْ صِفَةٍ فِي غَيْرَ الدَّارِ وَنَحْوِهَا، وَأَنْ يَعْقِدَ عَلَى نَفْعِهَا دُونَ أَجْزَائِهَا، فَلَا تَصِحُّ إِجَارَةُ الطَّعَامِ لِلْأَكْلِ وَلَا الشَّمْعِ لِيُشْعِلَهُ وَلَا حَيَوَانٍ لِيَأْخُذَ لَبَنَهُ إِلَّا فِي الظِّئْرِ، وَنَقْعِ الْبِئْرِ وَمَاءِ الْأَرْضِ يَدْخُلَانِ تَبَعًا."]]},{"id":"za113_2","label":"بَابُ الْإِجَارَةِ · فَصْلٌ · ٢","segs":[["matn","وَالْقُدْرَةُ عَلَى التَّسْلِيمِ، فَلَا تَصِحُّ إِجَارَةُ الْآبِقِ وَالشَّارِدِ، وَاشْتِمَالُ الْعَيْنِ عَلَى الْمَنْفَعَةِ، فَلَا تَصِحُّ إِجَارَةُ بَهِيمَةٍ زَمِنَةٍ لِحَمْلٍ، وَلَا أَرْضٍ لَا تُنْبِتُ لِلزَّرْعِ، وَأَنْ تَكُونَ الْمَنْفَعَةُ لِلْمُؤَجِّرِ أَوْ مَأْذُونًا لَهُ فِيهَا،"]]},{"id":"za113_3","label":"بَابُ الْإِجَارَةِ · فَصْلٌ · ٣","segs":[["matn","وَتَجُوزُ إِجَارَةُ الْعَيْنِ لِمَنْ يَقُومُ مَقَامَهُ، لَا بِأَكْثَرَ مِنْهُ ضَرَرًا."]]},{"id":"za113_4","label":"بَابُ الْإِجَارَةِ · فَصْلٌ · ٤","segs":[["matn","وَتَصِحُّ إِجَارَةُ الْوَقْفِ، فَإِنْ مَاتَ الْمُؤَجِّرُ فَانْتَقَلَ إِلَى مَنْ بَعْدَهُ لَمْ تَنْفَسِخْ، وَلِلثَّانِي حِصَّتُهُ مِنَ الْأُجْرَةِ، وَإِنْ أَجَّرَ الدَّارَ وَنَحْوَهَا مُدَّةً وَلَوْ طَوِيلَةً يَغْلِبُ عَلَى الظَّنِّ بَقَاءُ الْعَيْنِ فِيهَا صَحَّ،"]]},{"id":"za113_5","label":"بَابُ الْإِجَارَةِ · فَصْلٌ · ٥","segs":[["matn","وَإِنِ اسْتَأْجَرَهَا لِعَمَلٍ كَدَابَّةٍ لِرُكُوبٍ إِلَى مَوْضِعٍ مُعَيَّنٍ أَوْ بَقَرٍ لِحَرْثٍ أَوْ دِيَاسِ زَرْعٍ أَوْ مَنْ يَدُلُّهُ عَلَى طَرِيقٍ اشْتُرِطَ مَعْرِفَةُ ذَلِكَ وَضَبْطُهُ بِمَا لَا يَخْتَلِفُ."]]},{"id":"za113_6","label":"بَابُ الْإِجَارَةِ · فَصْلٌ · ٦","segs":[["matn","وَلَا تَصِحُّ عَلَى عَمَلٍ يَخْتَصُّ أَنْ يَكُونَ فَاعِلُهُ مِنْ أَهْلِ الْقُرْبَةِ وَعَلَى الْمُؤَجِّرِ كُلُّ مَا يَتَمَكَّنُ بِهِ مِنَ النَّفْعِ كَزِمَامِ الْجَمَلِ وَرَحْلِهِ وَحِزَامِهِ وَالشَّدِّ عَلَيْهِ، وَشَدِّ الْأَحْمَالِ وَالْمَحَامِلِ وَالرَّفْعِ وَالْحَطِّ، وَلُزُومِ الْبَعِيرِ وَمَفَاتِيحِ الدَّارِ وَعِمَارَتِهَا،"]]},{"id":"za113_7","label":"بَابُ الْإِجَارَةِ · فَصْلٌ · ٧","segs":[["matn","فَأَمَّا تَفْرِيغُ الْبَالُوعَةِ وَالْكَنِيفِ فَيَلْزَمُ الْمُسْتَأْجِرَ إِذَا تَسَلَّمَهَا فَارِغَةً."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za114","title":"بَابُ الْإِجَارَةِ · فَصْلٌ (٢)","units":[{"id":"za114_1","label":"بَابُ الْإِجَارَةِ · فَصْلٌ (٢) · ١","segs":[["matn","وَهِيَ عَقْدٌ لَازِمٌ، فَإِنْ آجَرَهُ شَيْئًا وَمَنَعَهُ كُلَّ الْمُدَّةِ أَوْ بَعْضَهَا فَلَا شَيْءَ لَهُ، وَإِنْ بَدَأَ الْآخَرُ قَبْلَ انْقِضَائِهَا فَعَلَيْهِ، الْأُجْرَةِ وَتَنْفَسِخُ بِتَلَفِ الْعَيْنِ الْمُؤَجَّرَةِ وَبِمَوْتِ الْمُرْتَضِعِ وَالرَّاكِبِ،"]]},{"id":"za114_2","label":"بَابُ الْإِجَارَةِ · فَصْلٌ (٢) · ٢","segs":[["matn","إِنْ لَمْ يُخَلِّفْ بَدَلًا وَانْقِلَاعِ ضِرْسٍ أَوْ بُرْئِهِ وَنَحْوِهِ، لَا بِمَوْتِ الْمُتَعَاقِدَيْنِ أَوْ أَحَدِهِمَا وَلَا بِضَيَاعِ نَفَقَةِ الْمُسْتَأْجِرِ وَنَحْوِهِ، وَإِنِ اكْتَرَى دَارًا فَانْهَدَمَتْ، أَوْ أَرْضًا لِزَرْعٍ فَانْقَطَعَ مَاؤُهَا، أَوْ غَرِقَتِ انْفَسَخَتِ الْإِجَارَةُ فِي الْبَاقِي،"]]},{"id":"za114_3","label":"بَابُ الْإِجَارَةِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَإِنْ وَجَدَ الْعَيْنَ مَعِيبَةً أَوْ حَدَثَ بِهَا عَيْبٌ فَلَهُ الْفَسْخُ وَعَلَيْهِ أُجْرَةُ مَا مَضَى،"]]},{"id":"za114_4","label":"بَابُ الْإِجَارَةِ · فَصْلٌ (٢) · ٤","segs":[["matn","وَلَا يَضْمَنُ أَجِيرٌ خَاصٌّ مَا جَنَتْ يَدُهُ خَطَأً وَلَا حَجَّامٌ وَطَبِيبٌ وَبَيْطَارٌ لَمْ تَجْنِ أَيْدِيهِمْ إِنْ عُرِفَ حِذْقُهُمْ وَلَا رَاعٍ لَمْ يَتَعَدَّ، وَيَضْمَنُ الْمُشْتَرِكُ مَا تَلِفَ بِفِعْلِهِ،"]]},{"id":"za114_5","label":"بَابُ الْإِجَارَةِ · فَصْلٌ (٢) · ٥","segs":[["matn","وَلَا يَضْمَنُ مَا تَلِفَ مِنْ حِرْزِهِ أَوْ بِغَيْرِ فِعْلِهِ وَلَا أُجْرَةَ لَهُ، وَتَجِبُ الْأُجْرَةُ بِالْعَقْدِ إِنْ لَمْ تُؤَجَّلْ وَتُسْتَحَقُّ بِتَسْلِيمِ الْعَمَلِ الَّذِي فِي الذِّمَّةِ، وَمَنْ تَسَلَّمَ عَيْنًا بِإِجَارَةٍ فَاسِدَةٍ وَفَرَغَتِ الْمُدَّةُ لَزِمَهُ أُجْرَةُ الْمِثْلِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za115","title":"بَابُ السَّبْقِ","units":[{"id":"za115_1","label":"بَابُ السَّبْقِ · ١","segs":[["matn","يَصِحُّ عَلَى الْأَقْدَامِ وَسَائِرِ الْحَيَوَانَاتِ وَالسُّفُنِ وَالْمَزَارِيقِ، وَلَا تَصِحُّ بِعِوَضٍ إِلَّا فِي إِبِلٍ وَخَيْلٍ وَسِهَامٍ، وَلَا بُدَّ مِنْ تَعْيِينِ الْمَرْكُوبَيْنِ وَاتِّحَادِهِمَا وَالرُّمَاةِ وَالْمَسَافَةِ بِقَدْرٍ مُعْتَادٍ، وَهِيَ جُعَالَةٌ لِكُلِّ وَاحِدٍ فَسْخُهَا، وَتَصِحُّ الْمُنَاضَلَةُ عَلَى مُعَيَّنِيْنَ يُحْسِنُونَ الرَّمْيَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za116","title":"بَابُ الْعَارِيَّةِ","units":[{"id":"za116_1","label":"بَابُ الْعَارِيَّةِ · ١","segs":[["matn","وَهِيَ إِبَاحَةُ نَفْعِ عَيْنٍ تَبْقَى بَعْدَ اسْتِيفَائِهِ، وَتُبَاحُ إِعَارَةُ كُلِّ ذِي نَفْعٍ مُبَاحٍ، إِلَّا الْبُضْعَ وَعَبْدًا مُسْلِمًا لِكَافِرٍ وَصَيْدًا وَنَحْوَهُ لِمُحْرِمٍ، وَأَمَةً شَابَّةً لِغَيْرِ امْرَأَةٍ أَوْ مَحْرَمٍ، وَلَا أُجْرَةَ لِمَنْ أَعَارَ حَائِطًا حَتَّى يَسْقُطَ،"]]},{"id":"za116_2","label":"بَابُ الْعَارِيَّةِ · ٢","segs":[["matn","وَلَا يُرَدُّ إِنْ سَقَطَ إِلَّا بِإِذْنِهِ، وَتُضْمَنُ الْعَارِيَّةُ بِقِيمَتِهَا يَوْمَ تَلِفَتْ وَلَوْ شَرَطَ نَفْيَ ضَمَانِهَا وَعَلَيْهِ مُؤْنَةُ رَدِّهَا، لَا الْمُؤَجَّرَةِ، وَلَا يُعِيرُهَا، فَإِنْ تَلِفَتْ عَنْدَ الثَّانِي اسْتَقَرَّتْ عَلَيْهِ قِيمَتُهَا، وَعَلَى مُعِيرِهَا أُجْرَتُهَا، وَيُضَمِّنُ أَيُّهُمَا شَاءَ،"]]},{"id":"za116_3","label":"بَابُ الْعَارِيَّةِ · ٣","segs":[["matn","وَإِنْ أَرْكَبَ مُنْقَطِعًا لِلثَّوَابِ لَمْ يَضْمَنْ، وَإِذَا قَالَ: أَجَّرْتُكَ."]]},{"id":"za116_4","label":"بَابُ الْعَارِيَّةِ · ٤","segs":[["matn","قَالَ: بَلْ أَعَرْتَنِي. أَوْ بِالْعَكْسِ عَقِبَ الْعَقْدِ قُبِلَ قَوْلُ مُدَّعِي الْإِعَارَةِ، وَبَعْدَ مُضِيِّ مُدَّةٍ قَوْلُ الْمَالِكِ بِأُجْرَةِ الْمِثْلِ، وَإِنْ قَالَ: أَعَرْتَنِي أَوْ قَالَ: أَجَّرْتَنِي."]]},{"id":"za116_5","label":"بَابُ الْعَارِيَّةِ · ٥","segs":[["matn","قَالَ: بَلْ غَصَبْتَنِي. أَوْ قَالَ: أَعَرْتُكَ. قَالَ: بَلْ أَجَّرْتَنِي وَالْبَهِيمَةُ تَالِفَةٌ. أَوِ اخْتَلَفَا فِي رَدٍّ فَقَوْلُ الْمَالِكِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za117","title":"بَابُ الْغَصْبِ","units":[{"id":"za117_1","label":"بَابُ الْغَصْبِ · ١","segs":[["matn","وَهُوَ الِاسْتِيلَاءُ عَلَى حَقِّ غَيْرِهِ قَهْرًا بِغَيْرِ حَقٍّ مِنْ عَقَارٍ وَمَنْقُولٍ، وَإِنْ غَصَبَ كَلْبًا يُقْتَنَى أَوْ خَمْرَ ذِمِّيٍّ رَدَّهُمَا، وَلَا يَرُدُّ جِلْدَ مَيْتَةٍ، وَإِتْلَافُ الثَّلَاثَةِ هَدَرٌ."]]},{"id":"za117_2","label":"بَابُ الْغَصْبِ · ٢","segs":[["matn","وَإِنِ اسْتَوْلَى عَلَى حُرٍّ لَمْ يَضْمَنْهُ، وَإِنِ اسْتَعْمَلَهُ كُرْهًا أَوْ حَبَسَهُ فَعَلَيْهِ أُجْرَتُهُ، وَيَلْزَمُ رَدُّ الْمَغْصُوبِ بِزِيَادَتِهِ وَإِنْ غَرِمَ أَضْعَافَهُ وَإِنْ بَنَى فِي الْأَرْضِ أَوْ غَرَسَ لَزِمَهُ الْقَلْعُ وَأَرْشُ نَقْصِهَا وَتَسْوِيَتُهَا وَالْأُجْرَةُ،"]]},{"id":"za117_3","label":"بَابُ الْغَصْبِ · ٣","segs":[["matn","وَلَوْ غَصَبَ جَارِحًا أَوْ عَبْدًا أَوْ فَرَسًا فَحَصَّلَ بِذَلِكَ صَيْدٌ فَلِمَالِكِهِ، وَإِنْ ضَرَبَ الْمَصُوغَ وَنَسَجَ الْغَزْلَ وَقَصَّرَ الثَّوْبَ أَوْ صَبَغَهُ وَنَجَّرَ الْخَشَبَةَ وَنَحْوَهُ أَوْ صَارَ الْحَبُّ زَرْعًا، وَالْبَيْضَةُ فَرْخًا، وَالنَّوَى غَرْسًا رَدَّهُ وَأَرْشَ نَقْصِهِ،"]]},{"id":"za117_4","label":"بَابُ الْغَصْبِ · ٤","segs":[["matn","وَلَا شَيْءَ لِلْغَاصِبِ، وَيَلْزَمُهُ ضَمَانُ نَقْصِهِ وَإِنْ خَصَى الرَّقِيقُ رَدَّهُ مَعَ قِيمَتِهِ، وَمَا نَقَصَ بِسِعْرٍ لَمْ يُضْمَنْ وَلَا بِمَرَضٍ عَادَ بِبُرْئِهِ، وَإِنْ عَادَ بِتَعْلِيمِ صَنْعَةٍ ضَمِنَ النَّقْصَ،"]]},{"id":"za117_5","label":"بَابُ الْغَصْبِ · ٥","segs":[["matn","وَإِنْ تَعَلَّمَ أَوْ سَمِنَ فَزَادَتْ قِيمَتُهُ ثُمَّ نَسِيَ أَوْ هُزِلَ فَنَقَصَتْ ضَمِنَ الزِّيَادَةَ كَمَا لَوْ عَادَتْ مِنْ غَيْرِ جِنْسِ الْأَوَّلِ، وَمِنْ جِنْسِهَا لَا يَضْمَنُ إِلَّا أَكْثَرَهُمَا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za118","title":"بَابُ الْغَصْبِ · فَصْلٌ","units":[{"id":"za118_1","label":"بَابُ الْغَصْبِ · فَصْلٌ · ١","segs":[["matn","وَإِنْ خُلِطَ بِمَا لَا يَتَمَيَّزُ كَزَيْتٍ، أَوْ حِنْطَةٍ بِمِثْلِهِمَا، أَوْ صَبَغَ الثَّوْبَ، أَوْ لَتَّ سَوِيقًا بِدُهْنٍ أَوْ عَكْسُهُ وَلَمْ تَنْقُصِ الْقِيمَةُ وَلَمْ تَزِدْ فَهُمَا شَرِيكَانِ بِقَدْرِ مَالَيْهِمَا فِيهِ، وَإِنْ نَقَصَتِ الْقِيمَةُ ضَمِنَهَا،"]]},{"id":"za118_2","label":"بَابُ الْغَصْبِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ زَادَتْ قِيمَةُ أَحَدِهِمَا فِلِصَاحِبِهِ، وَلَا يُجْبَرُ مَنْ أَبَى قَلْعَ الصِّبْغِ، وَلَوْ قُلِعَ غَرْسُ الْمُشْتَرِي أَوْ بِنَاءَهُ لِاسْتِحْقَاقِ الْأَرْضِ رَجَعَ عَلَى بَائِعِهَا بِالْغَرَامَةِ، وَإِنْ أَطْعَمَهُ لِعَالِمٍ بِغَصْبِهِ فَالضَّمَانُ عَلَيْهِ وَعَكْسُهُ بِعَكْسِهِ،"]]},{"id":"za118_3","label":"بَابُ الْغَصْبِ · فَصْلٌ · ٣","segs":[["matn","وَإِنْ أَطْعَمَهُ لِمَالِكِهِ أَوْ رَهَنَهُ أَوْ أَوْدَعَهُ أَوْ آجَرَهُ إِيَّاهُ لَمْ يَبْرَأْ إِلَّا أَنْ يَعْلَمَ، وَيَبْرَأُ بِإِعَارَتِهِ، وَمَا تَلِفَ أَوْ تَغَيَّبَ مِنْ مَغْصُوبٍ مِثْلِيٍّ غَرِمَ مِثْلَهُ إِذًا، وَإِلَّا فَقِيمَتُهُ يَوْمَ تَعَذَّرَ،"]]},{"id":"za118_4","label":"بَابُ الْغَصْبِ · فَصْلٌ · ٤","segs":[["matn","وَيُضْمَنُ غَيْرُ الْمِثْلِيِّ بِقِيمَتِهِ يَوْمَ تَلَفِهِ، وَإِنْ تَخَمَّرَ عَصِيرٌ فَالْمِثْلُ، فَإِنِ انْقَلَبَ خَلًّا دَفَعَهُ وَمَعَهُ نَقْصُ قِيمَتِهِ عَصِيرًا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za119","title":"بَابُ الْغَصْبِ · فَصْلٌ (٢)","units":[{"id":"za119_1","label":"بَابُ الْغَصْبِ · فَصْلٌ (٢) · ١","segs":[["matn","وَتَصَرُّفَاتُ الْغَاصِبِ الْحُكْمِيَّةُ بَاطِلَةٌ، وَالْقَوْلُ فِي قِيمَةِ التَّالِفِ أَوْ قَدْرِهِ أَوْ صِفَتِهِ قَوْلُهُ، وَفِي رَدِّهِ وَعَدَمِ عَيْبِهِ قَوْلُ رَبِّهِ، وَإِنْ جَهِلَ رَبَّهُ تَصَدَّقَ بِهِ عَنْهُ مَضْمُونًا،"]]},{"id":"za119_2","label":"بَابُ الْغَصْبِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَمَنْ أَتْلَفَ مُحْتَرَمًا أَوْ فَتَحَ قَفَصًا أَوْ بَابًا أَوْ حَلَّ وِكَاءً أَوْ رِبَاطًا أَوْ قَيْدًا، فَذَهَبَ مَا فِيهِ أَوْ أَتْلَفَ شَيْئًا وَنَحْوَهُ ضَمِنَهُ، وَإِنْ رَبَطَ دَابَّةً بِطَرِيقٍ ضَيِّقٍ فَعَثَرَ بِهِ إِنْسَانٌ ضَمِنَ،"]]},{"id":"za119_3","label":"بَابُ الْغَصْبِ · فَصْلٌ (٢) · ٣","segs":[["matn","كَالْكَلْبِ الْعَقُورِ لِمَنْ دَخَلَ بَيْتَهُ بِإِذْنِهِ أَوْ عَقَرَهُ خَارِجَ مَنْزِلِهِ، وَمَا أَتْلَفَتِ الْبَهِيمَةُ مِنَ الزَّرْعِ لَيْلًا ضَمِنَهُ صَاحِبُهَا، وَعَكْسُهُ النَّهَارُ،"]]},{"id":"za119_4","label":"بَابُ الْغَصْبِ · فَصْلٌ (٢) · ٤","segs":[["matn","إِلَّا أَنْ تُرْسَلَ بِقُرْبِ مَا تُتْلِفُهُ عَادَةً وَإِنْ كَانَتْ بِيَدِ رَاكِبٍ أَوْ قَائِدٍ أَوْ سَائِقٍ ضَمِنَ جِنَايَتَهَا بِمُقَدَّمِهَا لَا بِمُؤَخَّرِهَا، وَبَاقِي جِنَايَتِهَا هَدَرٌ كَقَتْلِ الصَّائِلِ عَلَيْهِ وَكَسْرِ مِزْمَارٍ وَصَلِيبٍ، وَآنِيَةِ ذَهَبٍ وَفِضَّةٍ، وَآنِيَةِ خَمْرٍ غَيْرِ مُحْتَرَمَةٍ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za120","title":"بَابُ الشُّفْعَةِ","units":[{"id":"za120_1","label":"بَابُ الشُّفْعَةِ · ١","segs":[["matn","وَهِيَ اسْتِحْقَاقُ انْتِزَاعِ حِصَّةِ شَرِيكِهِ مِمَّنِ انْتَقَلَتْ إِلَيْهِ بِعِوَضٍ مَالِيٍّ بِثَمَنِهِ الَّذِي اسْتَقَرَّ عَلَيْهِ الْعَقْدُ، فَإِنِ انْتَقَلَ بَغَيْرِ عِوَضٍ أَوْ كَانَ عِوَضُهُ صَدَاقًا أَوْ خُلْعًا أَوْ صُلْحًا عَنْ دَمِ عَمْدٍ فَلَا شُفْعَةَ، وَيَحْرُمُ التَّحَيُّلُ لِإِسْقَاطِهَا،"]]},{"id":"za120_2","label":"بَابُ الشُّفْعَةِ · ٢","segs":[["matn","وَتَثْبُتُ لِشَرِيكٍ فِي أَرْضٍ تَجِبُ قِسْمَتُهَا، وَيَتْبَعُهَا الْغِرَاسُ، وَالْبِنَاءُ، لَا الثَّمَرَةُ وَالزَّرْعُ فَلَا شُفْعَةَ لِجَارٍ، وَهِيَ عَلَى الْفَوْرِ وَقْتَ عِلْمِهِ، فَإِنْ لَمْ يَطْلُبْهَا إِذَنْ بِلَا عُذْرٍ بَطَلَتْ، وَإِنْ قَالَ لِلْمُشْتَرِي: بِعْنِي أَوْ صَالِحْنِي."]]},{"id":"za120_3","label":"بَابُ الشُّفْعَةِ · ٣","segs":[["matn","أَوْ كَذَّبَ الْعَدْلُ أَوْ طَلَبَ أَخْذَ الْبَعْضِ سَقَطَتْ، وَالشُّفْعَةُ لِاثْنَيْنِ بِقَدْرِ حَقَّيْهِمَا، فَإِنْ عَفَا أَحَدُهُمَا أَخَذَ الْآخَرُ الْكُلَّ أَوْ تَرَكَ، وَإِنِ اشْتَرَى اثْنَانِ حَقَّ وَاحِدٍ أَوْ عَكْسُهُ،"]]},{"id":"za120_4","label":"بَابُ الشُّفْعَةِ · ٤","segs":[["matn","أَوِ اشْتَرَى وَاحِدٌ شِقْصَيْنِ مِنْ أَرْضَيْنِ صَفْقَةً وَاحِدَةً فَلِلشَّفِيعِ أَخْذُ أَحَدِهِمَا، وَإِنْ بَاعَ شِقْصًا وَسَيْفًا، أَوْ تَلِفَ بَعْضُ الْمَبِيعِ فَلِلشَّفِيعِ أَخْذُ الشِّقْصِ بِحِصَّتِهِ مِنَ الثَّمَنِ، وَلَا شُفْعَةَ بِشَرِكَةِ وَقْفٍ، وَلَا غَيْرِ مِلْكٍ سَابِقٍ، وَلَا لِكَافِرٍ عَلَى مُسْلِمٍ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za121","title":"بَابُ الشُّفْعَةِ · فَصْلٌ","units":[{"id":"za121_1","label":"بَابُ الشُّفْعَةِ · فَصْلٌ · ١","segs":[["matn","وَإِنْ تَصَرَّفَ مُشْتَرِيهِ بِوَقْفِهِ أَوْ هِبَتِهِ أَوْ رَهْنِهِ لَا بِوَصِيَّةٍ سَقَطَتِ الشُّفْعَةُ وَبِبَيْعٍ فَلَهُ أَخْذُهُ بِأَحَدِ الْبَيْعَيْنِ، وَلِلْمُشْتَرِي الْغَلَّةُ، وَالنَّمَاءُ الْمُنْفَصِلُ وَالزَّرْعُ وَالثَّمَرَةُ الظَّاهِرَةُ، فَإِنْ بَنَى أَوْ غَرَسَ فَلِلشَّفِيعِ تَمَلُّكُهُ بِقِيمَتِهِ وَقَلْعُهُ وَيَغْرَمُ نَقْصَهُ،"]]},{"id":"za121_2","label":"بَابُ الشُّفْعَةِ · فَصْلٌ · ٢","segs":[["matn","وَلِرَبِّهِ أَخْذُهُ بِلَا ضَرَرٍ وَإِنْ مَاتَ الشَّفِيعُ قَبْلَ الطَّلَبِ بَطَلَتْ وَبَعْدَهُ لِوَارِثِهِ وَيَأْخُذُ بِكُلِّ الثَّمَنِ، فَإِنْ عَجَزَ عَنْ بَعْضِهِ سَقَطَتْ شُفْعَتُهُ، وَالْمُؤَجَّلُ يَأْخُذُ الْمَلِيءُ بِهِ وَضِدُّهُ بِكَفِيلٍ مَلِيءٍ،"]]},{"id":"za121_3","label":"بَابُ الشُّفْعَةِ · فَصْلٌ · ٣","segs":[["matn","وَيُقْبَلُ فِي الْخُلْفِ مَعَ عَدَمِ الْبَيِّنَةِ قَوْلُ الْمُشْتَرِي، فَإِنْ قَالَ: اشْتَرَيْتُهُ بِأَلْفٍ أَخَذَ الشَّفِيعُ بِهِ وَلَوْ أَثْبَتَ الْبَائِعُ أَكْثَرَ، وَإِنْ أَقَرَّ الْبَائِعُ بِالْبَيْعِ وَأَنْكَرَ الْمُشْتَرِي وَجَبَتْ، وَعُهْدَةُ الشَّفِيعِ عَلَى الْمُشْتَرِي وَعُهْدَةُ الْمُشْتَرِي عَلَى الْبَائِعِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za122","title":"بَابُ الْوَدِيعَةِ","units":[{"id":"za122_1","label":"بَابُ الْوَدِيعَةِ · ١","segs":[["matn","إِذَا تَلِفَتْ مِنْ بَيْنِ مَالِهِ وَلَمْ يَتَعَدَّ وَلَمْ يُفَرِّطْ لَمْ يَضْمَنْ، وَيَلْزَمُهُ حِفْظُهَا فِي حِرْزِ مِثْلِهَا، فَإِنْ عَيَّنَهُ صَاحِبُهَا فَأَحْرَزَهَا بِدُونِهِ ضَمِنَ وَبِمِثْلِهِ أَوْ أَحْرَزَ فَلَا، وَإِنْ قَطَعَ الْعَلَفَ عَنِ الدَّابَةِ بِغَيْرِ قَوْلِ صَاحِبِهَا ضَمِنَ،"]]},{"id":"za122_2","label":"بَابُ الْوَدِيعَةِ · ٢","segs":[["matn","وَإِنْ عَيَّنَ جَيْبَهُ فَتَرَكَهَا فِي كُمِّهِ أَوْ يَدِهِ ضَمِنَ وَعَكْسُهُ بِعَكْسِهِ، وَإِنْ دَفَعَهَا إِلَى مَنْ يَحْفَظُ مَالَهُ أَوْ مَالَ رَبِّهَا لَمْ يَضْمَنْ، وَعَكْسُهُ الْأَجْنَبِيُّ وَالْحَاكِمُ، وَلَا يُطَالَبَانِ إِنْ جَهِلَا،"]]},{"id":"za122_3","label":"بَابُ الْوَدِيعَةِ · ٣","segs":[["matn","وَإِنْ حَدَثَ خَوْفٌ أَوْ سَفَرٌ رَدَّهَا عَلَى رَبِّهَا، فَإِنْ غَابَ حَمَلَهَا مَعَهُ إِنْ كَانَ أَحْرَزَ وَإِلَّا أَوْدَعَهَا ثِقَةً، وَمَنْ أُوْدِعَ دَابَّةً فَرَكِبَهَا لِغَيْرِ نَفْعِهَا أَوْ ثَوْبًا فَلَبِسَهُ أَوْ دَرَاهِمَ فَأَخْرَجَهَا مِنْ مَحْرَزٍ ثُمَّ رَدَّهَا،"]]},{"id":"za122_4","label":"بَابُ الْوَدِيعَةِ · ٤","segs":[["matn","أَوْ رَفَعَ الْخَتْمَ وَنَحْوَهُ أَوْ خَلَطَهَا بِغَيْرِ مُتَمَيِّزٍ فَضَاعَ الْكُلُّ ضَمِنَ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za123","title":"بَابُ الْوَدِيعَةِ · فَصْلٌ","units":[{"id":"za123_1","label":"بَابُ الْوَدِيعَةِ · فَصْلٌ · ١","segs":[["matn","وَيُقْبَلُ قَوْلُ الْمُودَعِ فِي رَدِّهَا إِلَى رَبِّهَا أَوْ غَيْرِهِ بِإِذْنِهِ وَتَلَفِهَا وَعَدَمِ التَّفْرِيطِ، فَإِنْ قَالَ: لَمْ تُودِعْنِي."]]},{"id":"za123_2","label":"بَابُ الْوَدِيعَةِ · فَصْلٌ · ٢","segs":[["matn","ثُمَّ ثَبَتَتْ بِبَيِّنَةٍ أَوْ إِقْرَارٍ، ثُمَّ ادَّعَى رَدًّا أَوْ تَلَفًا سَابِقَيْنِ لِجُحُودِهِ لَمْ يُقْبَلَا وَلَوْ بِبَيِّنَةٍ، بَلْ فِي قَوْلِهِ: مَا لَكَ عِنْدِي شَيْءٌ."]]},{"id":"za123_3","label":"بَابُ الْوَدِيعَةِ · فَصْلٌ · ٣","segs":[["matn","وَنَحْوُهُ، أَوْ بَعْدَهُ بِهَا، وَإِنِ ادَّعَى وَارِثُهُ الرَّدَّ مِنْهُ أَوْ مِنْ مُوَرِّثِهِ لَمْ يُقْبَلْ إِلَّا بِبَيِّنَةٍ، وَإِنْ طَلَبَ أَحَدُ الْمُودِعَيْنِ نَصِيبَهُ مِنْ مَكِيلٍ أَوْ مَوْزُونٍ يَنْقَسِمُ أَخَذَهُ، وَلِلْمُسْتَوْدَعِ وَالْمُضَارَبِ وَالْمُرْتَهِنِ وَالْمُسْتَأْجِرِ مُطَالَبَةُ غَاصِبِ الْعَيْنِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za124","title":"بَابُ إِحْيَاءِ الْمَوَاتِ","units":[{"id":"za124_1","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ١","segs":[["matn","وَهِيَ الْأَرْضُ الْمُنْفَكَّةُ عَنِ الْاخْتِصَاصَاتِ وَمِلْكٍ مَعْصُومٌ، فَمَنْ أَحْيَاهَا مَلَكَهَا مِنْ مُسْلِمٍ وَكَافِرٍ بِإِذْنِ الْإِمَامِ وَعَدَمِهِ فِي دَارِ الْإِسْلَامِ وَغَيْرِهَا، وَالْعَنْوَةُ كَغَيْرِهَا، وَيُمْلَكُ بِالْإِحْيَاءِ مَا قَرُبَ مِنْ عَامِرٍ إِنْ لَمْ يَتَعَلَّقْ بِمَصْلَحَتِهِ،"]]},{"id":"za124_2","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٢","segs":[["matn","وَمَنْ أَحَاطَ مَوَاتًا أَوْ حَفَرَ بِئْرًا فَوَصَلَ إِلَى الْمَاءِ أَوْ أَجْرَاهُ إِلَيْهِ مِنْ عَيْنٍ وَنَحْوِهَا، أَوْ حَبَسَهُ عَنْهُ لِيُزْرَعَ فَقَدْ أَحْيَاهُ، وَيَمْلِكُ حَرِيمَ الْبِئْرِ الْعَادِيَّةِ خَمْسِينَ ذِرَاعًا مِنْ كُلِّ جَانِبٍ،"]]},{"id":"za124_3","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٣","segs":[["matn","وَحَرِيمَ الْبَدِيَّةِ نِصْفَهَا وَلِلْإِمَامِ إِقْطَاعُ مَوَاتٍ لِمَنْ يُحْيِيهِ وَلَا يَمْلِكُهُ وَإِقْطَاعُ الْجُلُوسِ فِي الطُّرُقِ الْوَاسِعَةِ مَا لَمْ يَضُرَّ بِالنَّاسِ، وَيَكُونُ أَحَقَّ بِجُلُوسِهَا، وَمِنْ غَيْرِ إِقْطَاعٍ لِمَنْ سَبَقَ بِالْجُلُوسِ مَا بَقِيَ قُمَاشُهُ فِيهَا وَإِنْ طَالَ،"]]},{"id":"za124_4","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٤","segs":[["matn","وَإِنْ سَبَقَ اثْنَانِ اقْتَرَعَا، وَلِمَنْ فِي أَعْلَى الْمَاءِ الْمُبَاحِ السَّقْيُ وَحَبْسُ الْمَاءِ إِلَى أَنْ يَصِلَ إِلَى كَعْبِهِ، ثُمَّ يُرْسِلُهُ إِلَى مَنْ يَلِيهِ، وَلِلْإِمَامِ دُونَ غَيْرِهِ حِمَى مَرْعًى لِدَوَابِّ الْمُسْلِمِينَ مَا لَمْ يَضُرَّهُمْ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za125","title":"بَابُ الْجَعَالَةِ","units":[{"id":"za125_1","label":"بَابُ الْجَعَالَةِ · ١","segs":[["matn","وَهِيَ أَنْ يَجْعَلَ شَيْئًا مَعْلُومًا لِمَنْ يَعْمَلُ لَهُ عَمَلًا مَعْلُومًا أَوْ مَجْهُولًا مُدَّةً مَعْلُومَةً أَوْ مَجْهُولَةً، كَرَدِّ عَبْدٍ وَلُقَطَةٍ وَخِيَاطَةٍ وَبِنَاءِ حَائِطٍ، فَمَنْ فَعَلَهُ بَعْدَ عِلْمِهِ بِقَوْلِهِ اسْتَحَقَّهُ، وَالْجَمَاعَةُ يَقْتَسِمُونَهُ، وَفِي أَثْنَائِهِ يَأْخُذُ قِسْطَ تَمَامِهِ،"]]},{"id":"za125_2","label":"بَابُ الْجَعَالَةِ · ٢","segs":[["matn","وَلِكُلٍّ فَسْخُهَا، فَمِنَ الْعَامِلِ لَا يَسْتَحِقُّ شَيْئًا وَمِنَ الْجَاعِلِ بَعْدَ الشُّرُوعِ لِلْعَامِلِ أُجْرَةُ عَمَلِهِ، وَمَعَ الْاخْتِلَافِ فِي أَصْلِهِ أَوْ قَدْرِهِ يُقْبَلُ قَوْلُ الْجَاعِلِ،"]]},{"id":"za125_3","label":"بَابُ الْجَعَالَةِ · ٣","segs":[["matn","وَمَنْ رَدَّ لُقَطَةً أَوْ ضَالَّةً أَوْ عَمِلَ لِغَيْرِهِ عَمَلًا بِغَيْرِ جُعْلٍ لَمْ يَسْتَحِقَّ عِوَضًا إِلَّا دِينَارًا أَوِ اثْنَيْ عَشَرَ دِرْهَمًا عَنْ رَدِّ الْآبِقِ، وَيَرْجِعُ بِنَفَقَتِهِ أَيْضًا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za126","title":"بَابُ اللُّقَطَةِ","units":[{"id":"za126_1","label":"بَابُ اللُّقَطَةِ · ١","segs":[["matn","وَهِيَ مَالٌ أَوْ مُخْتَصٌّ ضَلَّ عَنْ رَبِّهِ وَتَتَبَّعَهُ هِمَّةُ أَوْسَاطِ النَّاسِ، فَأَمَّا الرَّغِيفُ وَالسَّوْطُ وَنَحْوُهُمَا فَيُمْلَكُ بِلَا تَعْرِيفٍ، وَمَا امْتَنَعَ مِنْ سَبُعٍ صَغِيرٍ كَثَوْرٍ وَجَمَلٍ وَنَحْوِهِمَا حَرُمَ أَخْذُهُ،"]]},{"id":"za126_2","label":"بَابُ اللُّقَطَةِ · ٢","segs":[["matn","وَلَهُ الْتِقَاطُ غَيْرِ ذَلِكَ مِنْ حَيَوَانٍ وَغَيْرِهِ إِنْ أَمِنَ نَفْسَهُ عَلَى ذَلِكَ، وَإِلَّا فَهُوَ كَغَاصِبٍ، وَيُعَرِّفُ الْجَمِيعَ فِي مَجَامِعِ النَّاسِ غَيْرَ الْمَسَاجِدِ حَوْلًا وَيَمْلِكُهُ بَعْدَهُ حُكْمًا، لَكِنْ لَا يَتَصَرَّفُ فِيهَا قَبْلَ مَعْرِفَةِ صِفَاتِهَا،"]]},{"id":"za126_3","label":"بَابُ اللُّقَطَةِ · ٣","segs":[["matn","فَمَتَى جَاءَ طَالِبُهَا فَوَصَفَهَا لَزِمَ دَفْعُهَا إِلَيْهِ، وَالسَّفِيهُ وَالصَّبِيُّ يُعَرِّفُ لُقَطَتَهُمَا وَلِيُّهُمَا، وَمَنْ تَرَكَ حَيَوَانًا بِفَلَاةٍ لِانْقِطَاعِهِ أَوْ عَجْزِ رَبِّهِ عَنْهُ مَلَكَهُ آخِذُهُ، وَمَنْ أُخِذَ نَعْلُهُ وَنَحْوُهُ وَوَجَدَ مَوْضِعَهُ غَيْرَهُ فَلُقَطَةٌ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za127","title":"بَابُ اللَّقِيطِ","units":[{"id":"za127_1","label":"بَابُ اللَّقِيطِ · ١","segs":[["matn","وَهُوَ طِفْلٌ لَا يُعْرَفُ نَسَبُهُ وَلَا رِقُّهُ نُبِذَ أَوْ ضَلَّ، وَأَخْذُهُ فَرْضُ كِفَايَةٍ، وَهُوَ حُرٌّ وَمَا وُجِدَ مَعَهُ أَوْ تَحْتَهُ ظَاهِرًا أَوْ مَدْفُونًا، طَرِيًّا أَوْ مُتَّصِلًا بِهِ كَحَيَوَانٍ وَغَيْرِهِ، أَوْ قَرِيبًا مِنْهُ فَلَهُ،"]]},{"id":"za127_2","label":"بَابُ اللَّقِيطِ · ٢","segs":[["matn","وَيُنْفَقُ عَلَيْهِ مِنْهُ، وَإِلَّا فَمِنْ بَيْتِ الْمَالِ، وَهُوَ مُسْلِمٌ، وَحَضَانَتُهُ لِوَاجِدِهِ الْأَمِينِ، وَيُنْفِقُ عَلَيْهِ بِغَيْرِ إِذْنِ حَاكِمٍ، وَمِيرَاثُهُ وَدِيَتُهُ لِبَيْتِ الْمَالِ، وَوَلِيُّهُ فِي الْعَمْدِ الْإِمَامُ يَتَخَيَّرُ بَيْنَ الْقِصَاصِ وَالدِّيَةِ،"]]},{"id":"za127_3","label":"بَابُ اللَّقِيطِ · ٣","segs":[["matn","وَإِنْ أَقَرَّ رَجُلٌ أَوِ امْرَأَةٌ ذَاتُ زَوْجٍ مُسْلِمٍ أَوْ كَافِرٍ أَنَّهُ وَلَدُهُ لَحِقَ بِهِ وَلَوْ بَعْدَ مَوْتِ اللَّقِيطِ، وَلَا يَتْبَعُ الْكَافِرَ فِي دِينِهِ إِلَّا بِبَيِّنَةٍ تَشْهَدُ أَنَّهُ وُلِدَ عَلَى فِرَاشِهِ،"]]},{"id":"za127_4","label":"بَابُ اللَّقِيطِ · ٤","segs":[["matn","وَإِنِ اعْتَرَفَ بِالرِّقِّ مَعَ سَبْقِ مُنَافٍ، أَوْ قَالَ: إِنَّهُ كَافِرٌ، لَمْ يُقْبَلْ مِنْهُ، وَإِنِ ادَّعَاهُ جَمَاعَةٌ قُدِّمَ ذُو الْبَيِّنَةِ، وَإِلَّا فَمَنْ أَلْحَقَتْهُ الْقَافَةُ بِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"za128","title":"كِتَابُ الْوَقْفِ","units":[{"id":"za128_1","label":"كِتَابُ الْوَقْفِ · ١","segs":[["matn","وَهُوَ تَحْبِيسُ الْأَصْلِ وَتَسْبِيلُ الْمَنْفَعَةِ، وَيَصِحُّ بِالْقَوْلِ وَبِالْفِعْلِ الدَّالِّ عَلَيْهِ كَمَنْ جَعَلَ أَرْضَهُ مَسْجِدًا وَأَذِنَ لِلنَّاسِ فِي الصَّلَاةِ فِيهِ، أَوْ مَقْبَرَةً وَأَذِنَ فِي الدَّفْنِ فِيهَا، وَصَرِيحُهُ: وَقَفْتُ، وَحَبَّسْتُ، وَسَبَّلْتُ."]]},{"id":"za128_2","label":"كِتَابُ الْوَقْفِ · ٢","segs":[["matn","وَكِنَايَتُهُ: تَصَدَّقْتُ وَحَرَّمْتُ وَأَبَّدْتُ. فَتُشْتَرَطُ النِّيَّةُ مَعَ الْكِنَايَةِ أَوِ اقْتِرَانِ أَحَدِ الْأَلْفَاظِ الْخَمْسَةِ أَوْ حُكْمِ الْوَقْفِ، وَيُشْتَرَطُ فِيهِ الْمَنْفَعَةُ دَائِمًا مِنْ مُعَيَّنٍ يُنْتَفَعُ بِهِ مَعَ بَقَاءِ عَيْنِهِ كَعَقَارٍ وَحَيَوَانٍ،"]]},{"id":"za128_3","label":"كِتَابُ الْوَقْفِ · ٣","segs":[["matn","وَنَحْوِهِمَا وَأَنْ يَكُونَ عَلَى بِرٍّ كَالْمَسَاجِدِ وَالْقَنَاطِرِ وَالْمَسَاكِينِ وَالْأَقَارِبِ مِنْ مُسْلِمٍ وَذِمِّيٍّ، غَيْرَ حَرْبِيٍّ وَكَنِيسَةٍ وَنَسْخِ التَّوْرَاةِ وَالْإِنْجِيلِ، وَكُتُبِ زَنْدَقَةٍ، وَكَذَا الْوَصِيَّةُ وَالْوَقْفُ عَلَى نَفْسِهِ،"]]},{"id":"za128_4","label":"كِتَابُ الْوَقْفِ · ٤","segs":[["matn","وَيُشْتَرَطُ فِي غَيْرِ الْمَسْجِدِ وَنَحْوِهِ أَنْ يَكُونَ عَلَى مُعَيَّنٍ يَمْلِكُ لَا مَلَكٍ وَحَيَوَانٌ وَقَبْرٌ وَحَمْلٌ، لَا قَبُولُهُ وَلَا إِخْرَاجُهُ عَنْ يَدِهِ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"za129","title":"كِتَابُ الْوَقْفِ · فَصْلٌ","units":[{"id":"za129_1","label":"كِتَابُ الْوَقْفِ · فَصْلٌ · ١","segs":[["matn","وَيَجِبُ الْعَمَلُ بِشَرْطِ الْوَاقِفِ فِي جَمْعٍ وَتَقْدِيمٍ، وَضِدِّ ذَلِكَ وَاعْتِبَارِ وَصْفٍ وَعَدَمِهِ وَالتَّرْتِيبِ وَنَظَرٍ وَغَيْرِ ذَلِكَ، فَإِنْ أَطْلَقَ وَلَمْ يَشْتَرِطِ اسْتَوَى الْغَنِيُّ وَالذَّكَرُ وَضِدُّهُمَا،"]]},{"id":"za129_2","label":"كِتَابُ الْوَقْفِ · فَصْلٌ · ٢","segs":[["matn","وَالنَّظَرُ لِلْمَوْقُوفِ عَلَيْهِ وَإِنْ وَقَفَ عَلَى وَلَدِهِ أَوْ وَلَدِ غَيْرِهِ ثُمَّ عَلَى الْمَسَاكِينِ فَهُوَ لِوَلَدِهِ الذُّكُورِ وَالْإِنَاثِ بِالسَّوِيَّةِ، ثُمَّ وَلَدِ بَنِيهِ دُونَ بَنَاتِهِ، كَمَا لَوْ قَالَ عَلَى وَلَدِ وَلَدِهِ وَذُرِّيَّتِهِ لِصُلْبِهِ،"]]},{"id":"za129_3","label":"كِتَابُ الْوَقْفِ · فَصْلٌ · ٣","segs":[["matn","وَلَوْ قَالَ عَلَى بَنِيهِ أَوْ بَنِي فُلَانٍ اخْتَصَّ بِذُكُورِهِمْ إِلَّا أَنْ يَكُونُوا قَبِيلَةً فَيَدْخُلُ فِيهِ النِّسَاءُ دُونَ أَوْلَادِهِنَّ مِنْ غَيْرِهِمْ، وَالْقَرَابَةُ وَأَهْلُ بَيْتِهِ وَقَوْمُهُ يَشْمَلُ الذَّكَرَ وَالْأُنْثَى مِنْ أَوْلَادِهِ وَأَبِيهِ وَجَدِّهِ وَجَدِّ أَبِيهِ،"]]},{"id":"za129_4","label":"كِتَابُ الْوَقْفِ · فَصْلٌ · ٤","segs":[["matn","وَإِنْ وُجِدَتْ قَرِينَةٌ تَقْتَضِي إِرَادَةَ الْإِنَاثِ أَوْ حِرْمَانَهُنَّ عُمِلَ بِهَا، وَإِذَا وَقَفَ عَلَى جَمَاعَةٍ يُمْكِنُ حَصْرُهُمْ وَجَبَ تَعْمِيمُهُمْ وَالتَّسَاوِي وَإِلَّا جَازَ التَّفْضِيلُ وَالْاقْتِصَارُ عَلَى أَحَدِهِمْ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"za130","title":"كِتَابُ الْوَقْفِ · فَصْلٌ (٢)","units":[{"id":"za130_1","label":"كِتَابُ الْوَقْفِ · فَصْلٌ (٢) · ١","segs":[["matn","وَالْوَقْفُ عَقْدٌ لَازِمٌ لَا يَجُوزُ فَسْخُهُ وَلَا يُبَاعُ، إِلَّا أَنْ تَتَعَطَّلَ مَنَافِعُهُ وَيُصْرَفَ ثَمَنُهُ فِي مِثْلِهِ، وَلَوْ أَنَّهُ مَسْجِدٌ وَآلَتُهُ وَمَا فَضَلَ عَنْ حَاجَتِهِ جَازَ صَرْفُهُ إِلَى مَسْجِدٍ آخَرَ، وَالصَّدَقَةُ بِهِ عَلَى فُقَرَاءِ الْمُسْلِمِينَ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"za131","title":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ","units":[{"id":"za131_1","label":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ · ١","segs":[["matn","وَهِيَ التَّبَرُّعُ بِتَمْلِيكِ مَالِهِ الْمَعْلُومِ الْمَوْجُودِ فِي حَيَاتِهِ غَيْرَهُ وَإِنْ شَرَطَ فِيهَا عِوَضًا مَعْلُومًا فَبَيْعٌ، وَلَا يَصِحُّ مَجْهُولًا إِلَّا مَا تَعَذَّرَ عِلْمُهُ،"]]},{"id":"za131_2","label":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ · ٢","segs":[["matn","وَتَنْعَقِدُ بِالْإِيجَابِ وَالْقَبُولِ وَالْمُعَاطَاةِ الدَّالَّةِ عَلَيْهَا وَتَلْزَمُ بِالْقَبْضِ بِإِذْنِ وَاهِبٍ إِلَّا مَا كَانَ فِي يَدِ مُتَّهِبٍ،"]]},{"id":"za131_3","label":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ · ٣","segs":[["matn","وَوَارِثُ الْوَاهِبِ يَقُومُ مَقَامَهُ وَمَنْ أَبْرَأَ غَرِيمَهُ مِنْ دَيْنِهِ بِلَفْظِ الْإِحْلَالِ أَوِ الصَّدَقَةِ أَوِ الْهِبَةِ وَنَحْوِهَا بَرِئَتْ ذِمَّتُهُ وَلَوْ لَمْ يَقْبَلْ وَتَجُوزُ هِبَةُ كُلِّ عَيْنٍ تُبَاعُ وَكَلْبٍ يُقْتَنَى."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"za132","title":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ · فَصْلٌ","units":[{"id":"za132_1","label":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ · فَصْلٌ · ١","segs":[["matn","يَجِبُ التَّعْدِيلُ فِي عَطِيَّةِ أَوْلَادِهِ بِقَدْرِ إِرْثِهِمْ، فَإِنْ فَضَّلَ بَعْضَهُمْ سَوَّى بِرُجُوعٍ أَوْ زِيَادَةٍ، فَإِنْ مَاتَ قَبْلَهُ ثَبَتَتْ، وَلَا يَجُوزُ لِوَاهِبٍ أَنْ يَرْجِعَ فِي هِبَتِهِ اللَّازِمَةِ إِلَّا الْأَبَ،"]]},{"id":"za132_2","label":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ · فَصْلٌ · ٢","segs":[["matn","وَلَهُ أَنْ يَأْخُذَ وَيَتَمَلَّكَ مِنْ مَالِ وَلَدِهِ مَا لَا يَضُرُّهُ وَلَا يَحْتَاجُهُ، فَإِنْ تَصَرَّفَ فِي مَالِهِ وَلَوْ فِيمَا وَهَبَهُ لَهُ بِبَيْعٍ أَوْ عِتْقٍ أَوْ إِبْرَاءٍ أَوْ أَرَادَ أَخْذَهُ قَبْلَ رُجُوعِهِ،"]]},{"id":"za132_3","label":"بَابُ الْهِبَةِ وَالْعَطِيَّةِ · فَصْلٌ · ٣","segs":[["matn","أَوْ تَمَلُّكِهِ بِقَوْلٍ أَوْ نِيَّةٍ وَقَبْضٍ مُعْتَبَرٍ لَمْ يَصِحَّ بَلْ بَعْدَهُ، وَلَيْسَ لِلْوَلَدِ مُطَالَبَةُ أَبِيهِ بِدَيْنٍ وَنَحْوِهِ إِلَّا بِنَفَقَتِهِ الْوَاجِبَةِ عَلَيْهِ فَإِنَّ لَهُ مُطَالَبَتَهُ بِهَا وَحَبْسَهُ عَلَيْهَا."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"za133","title":"فَصْلٌ فِي تَصَرُّفَاتِ الْمَرِيضِ","units":[{"id":"za133_1","label":"فَصْلٌ فِي تَصَرُّفَاتِ الْمَرِيضِ · ١","segs":[["matn","مَنْ مَرَضُهُ غَيْرُ مَخُوفٍ كَوَجَعِ ضِرْسٍ وَعَيْنٍ وَصُدَاعٍ فَتَصَرُّفُهُ لَازِمٌ كَالصَّحِيحِ وَلَوْ مَاتَ مِنْهُ،"]]},{"id":"za133_2","label":"فَصْلٌ فِي تَصَرُّفَاتِ الْمَرِيضِ · ٢","segs":[["matn","وَإِنْ كَانَ مَخُوفًا كَبِرْسَامٍ وَذَاتِ الْجَنْبِ وَوَجَعِ قَلْبٍ وَدَوَامِ قِيَامٍ وَرُعَافٍ وَأَوَّلِ فَالِجٍ وَآخِرِ سِلٍّ وَالْحُمَّى الْمُطْبِقَةِ وَالرِّبْعِ وَمَا قَالَ طَبِيبَانِ مُسْلِمَانِ عَدْلَانِ: إِنَّهُ مَخُوفٌ وَمَنْ وَقَعَ الطَّاعُونُ بِبَلَدِهِ وَمَنْ أَخَذَهَا الطَّلْقُ لَا يَلْزَمُ تَبَرُّعُهُ لِوَارِثٍ بِشَيْءٍ،"]]},{"id":"za133_3","label":"فَصْلٌ فِي تَصَرُّفَاتِ الْمَرِيضِ · ٣","segs":[["matn","وَلَا بِمَا فَوْقَ الثُّّّّلُثِ إِلَّا بِإِجَازَةِ الْوَرَثَةِ لَهَا إِنْ مَاتَ مِنْهُ، وَإِنْ عُوفِيَ فَكَصَحِيحٍ، وَمَنِ امْتَدَّ مَرَضُهُ بِجُذَامٍ أَوْ سِلٍّ أَوْ فَالِجٍ وَلَمْ يَقْطَعْهُ بِفِرَاشٍ فَمِنْ كُلِّ مَالِهِ، وَالْعَكْسُ بِالْعَكْسِ،"]]},{"id":"za133_4","label":"فَصْلٌ فِي تَصَرُّفَاتِ الْمَرِيضِ · ٤","segs":[["matn","وَيُعْتَبَرُ الثُّلُثُ عِنْدَ مَوْتِهِ وَيُسَوَّى بَيْنَ الْمُتَقَدِّمِ وَالْمُتَأَخِّرِ فِي الْوَصِيَّةِ، وَيُبْدَأُ بِالْأَوَّلِ فَالْأَوَّلِ فِي الْعَطِيَّةِ، وَلَا يَمْلِكُ الرُّجُوعَ فِيهَا، وَيُعْتَبَرُ الْقَبُولُ لَهَا عِنْدَ وُجُودِهَا، وَيَثْبُتُ الْمِلْكُ إِذَنْ، وَالْوَصِيَّةُ بِخِلَافِ ذَلِكَ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"za134","title":"كِتَابُ الْوَصَايَا","units":[{"id":"za134_1","label":"كِتَابُ الْوَصَايَا · ١","segs":[["matn","يُسَنُّ لِمَنْ تَرَكَ خَيْرًا وَهُوَ الْمَالُ الْكَثِيرُ أَنْ يُوصِيَ بِالْخُمُسِ، وَلَا تَجُوزُ بِأَكْثَرَ مِنَ الثُّلُثِ لِأَجْنَبِيٍّ، وَلَا لِوَارِثٍ بِشَيْءٍ إِلَّا بِإِجَازَةِ الْوَرَثَةِ لَهُمَا بَعْدَ الْمَوْتِ فَتَصِحُّ تَنْفِيذًا، وَتُكْرَهُ وَصِيَّةُ فَقِيرٍ وَارِثُهُ مُحْتَاجٌ،"]]},{"id":"za134_2","label":"كِتَابُ الْوَصَايَا · ٢","segs":[["matn","وَتَجُوزُ بِالْكُلِّ لِمَنْ لَا وَارِثَ لَهُ، وَإِنْ لَمْ يَفِ الثُّلُثُ بِالْوَصَايَا فَالنَّقْصُ بِالْقِسْطِ، وَإِنْ أَوْصَى لِوَارِثٍ فَصَارَ عِنْدَ الْمَوْتِ غَيْرَ وَارِثٍ صَحَّتْ وَالْعَكْسُ بِالْعَكْسِ، وَيُعْتَبَرُ الْقَبُولُ بَعْدَ الْمَوْتِ وَإِنْ طَالَ لَا قَبْلَهُ،"]]},{"id":"za134_3","label":"كِتَابُ الْوَصَايَا · ٣","segs":[["matn","وَيَثْبُتُ الْمِلْكُ بِهِ عَقِبَ الْمَوْتِ، وَمَنْ قَبِلَهَا ثُمَّ رَدَّهَا لَمْ يَصِحَّ الرَّدُّ، وَيَجُوزُ الرُّجُوعُ فِي الْوَصِيَّةِ، وَإِنْ قَالَ: إِنْ قَدِمَ زَيْدٌ فَلَهُ مَا وَصَّيْتُ بِهِ لِعَمْرٍو فَقَدِمَ فِي حَيَاتِهِ فَلَهُ، وَبَعْدَهَا لِعَمْرٍو،"]]},{"id":"za134_4","label":"كِتَابُ الْوَصَايَا · ٤","segs":[["matn","وَيُخْرِجُ الْوَاجِبَ كُلَّهُ مِنْ دَيْنٍ وَحَجٍّ وَغَيْرِهِ مِنْ كُلِّ مَالِهِ بَعْدَ مَوْتِهِ وَإِنْ لَمْ يُوصِ بِهِ، فَإِنْ قَالَ: أَدُّوا الْوَاجِبَ مِنْ ثُلُثِي بُدِئَ بِهِ، فَإِنْ بَقِيَ مِنْهُ شَيْءٌ أَخَذَهُ صَاحِبُ التَّبَرُّعِ وَإِلَّا سَقَطَ."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"za135","title":"بَابُ الْمُوصَى لَهُ","units":[{"id":"za135_1","label":"بَابُ الْمُوصَى لَهُ · ١","segs":[["matn","تَصِحُّ لِمَنْ يَصِحُّ تَمَلُّكُهُ، وَلِعَبْدِهِ بِمُشَاعٍ كَثُلُثِهِ، وَيَعْتِقُ مِنْهُ بِقَدْرِهِ، وَيَأْخُذُ الْفَاضِلَ، وَبِمِائَةٍ أَوْ مُعَيَّنٍ لَا تَصِحُّ لَهُ، وَتَصِحُّ بِحَمْلٍ وَلِحَمْلٍ تَحَقَّقَ وُجُودُهُ قَبْلَهَا،"]]},{"id":"za135_2","label":"بَابُ الْمُوصَى لَهُ · ٢","segs":[["matn","وَإِذَا أَوْصَى مَنْ لَا حَجَّ عَلَيْهِ أَنْ يُحَجَّ عَنْهُ بِأَلْفٍ صُرِفَ مِنْ ثُلُثِهِ مُؤْنَةُ حَجَّةٍ بَعْدَ أُخْرَى حَتَّى يَنْفَدَ، وَلَا تَصِحُّ لِمَلَكٍ وَبَهِيمَةٍ وَمَيِّتٍ، فَإِنْ وَصَّى لِحَيٍّ وَمَيِّتٍ يَعْلَمُ مَوْتَهُ فَالْكُلُّ لِلْحَيِّ، وَإِنْ جَهِلَ فَالنِّصْفُ،"]]},{"id":"za135_3","label":"بَابُ الْمُوصَى لَهُ · ٣","segs":[["matn","وَإِنْ وَصَّى بِمَالِهِ لِابْنَيْهِ وَأَجْنَبِيٍّ فَرَدَّا فَلَهُ التُّسُعُ."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"za136","title":"بَابُ الْمُوصَى بِهِ","units":[{"id":"za136_1","label":"بَابُ الْمُوصَى بِهِ · ١","segs":[["matn","تَصِحُّ بِمَا يَعْجَزُ عَنْ تَسْلِيمِهِ كَآبِقٍ وَطَيْرٍ فِي هَوَاءٍ، وَبِالْمَعْدُومِ كَمَا يَحْمِلُ حَيَوَانُهُ وَشَجَرَتُهُ أَبَدًا أَوْ مُدَّةً مُعَيَّنَةً فَإِنْ لَمْ يَحْصُلْ مِنْهُ شَيْءٌ بَطَلَتِ الْوَصِيَّةُ،"]]},{"id":"za136_2","label":"بَابُ الْمُوصَى بِهِ · ٢","segs":[["matn","وَتَصِحُّ بِكَلْبِ صَيْدٍ وَنَحْوِهِ وَبِزَيْتٍ مُتَنَجِّسٍ وَلَهُ ثُلُثُهُمَا وَلَوْ كَثُرَ الْمَالُ إِنْ لَمْ تُجِزِ الْوَرَثَةُ، وَتَصِحُّ بِمَجْهُولٍ كَعَبْدٍ وَشَاةٍ، وَيُعْطَى مَا يَقَعُ عَلَيْهِ الْاسْمُ الْعُرْفِيُّ، وَإِذَا أَوْصَى بِثُلُثِهِ فَاسْتَحْدَثَ مَالًا وَلَوْ دِيَةً دَخَلَ فِي الْوَصِيَّةِ."]]},{"id":"za136_3","label":"بَابُ الْمُوصَى بِهِ · ٣","segs":[["matn","وَمَنْ أُوصِيَ لَهُ بِمُعَيَّنٍ فَتَلِفَ بَطَلَتْ. وَإِنْ تَلِفَ الْمَالَ كُلُّهُ غَيْرُهُ فَهُوَ لِلْمُوصَى لَهُ إِنْ خَرَجَ مِنْ ثُلُثِ الْمَالِ الْحَاصِلِ لِلْوَرَثَةِ."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"za137","title":"بَابُ الْوَصِيَّةِ بِالْأَنْصِبَاءِ وَالْأَجْزَاءِ","units":[{"id":"za137_1","label":"بَابُ الْوَصِيَّةِ بِالْأَنْصِبَاءِ وَالْأَجْزَاءِ · ١","segs":[["matn","إِذَا أَوْصَى بِمِثْلِ نَصِيبِ وَارِثٍ مُعَيَّنٍ فَلَهُ مِثْلُ نَصِيبِهِ مَضْمُومًا إِلَى الْمَسْأَلَةِ، فَإِذَا أَوْصَى بِمِثْلِ نَصِيبِ ابْنِهِ وَلَهُ ابْنَانِ فَلَهُ الثُّلُثُ وَإِنْ كَانُوا ثَلَاثَةً فَلَهُ الرُّبُعُ، وَإِنْ كَانَ مَعَهُمْ بِنْتٌ فَلَهُ التُّسُعَانُ،"]]},{"id":"za137_2","label":"بَابُ الْوَصِيَّةِ بِالْأَنْصِبَاءِ وَالْأَجْزَاءِ · ٢","segs":[["matn","وَإِنْ وَصَّى لَهُ بِمِثْلِ نَصِيبِ أَحَدِ وَرَثَتِهِ وَلَمْ يُبَيِّنْ كَانَ لَهُ مِثْلُ مَا لِأَقَلِّهِمْ نَصِيبًا: فَمَعَ ابْنٍ وَبِنْتٍ رُبُعٌ، وَمَعَ زَوْجَةٍ وَابْنٍ تُسُعٌ، وَبِسَهْمٍ مِنْ مَالِهِ فَلَهُ سُدُسٌ،"]]},{"id":"za137_3","label":"بَابُ الْوَصِيَّةِ بِالْأَنْصِبَاءِ وَالْأَجْزَاءِ · ٣","segs":[["matn","وَبِشَيْءٍ أَوْ جُزْءٍ أَوْ حَظٍّ أَعْطَاهُ الْوَارِثُ مَا شَاءَ."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"za138","title":"بَابُ الْمُوصَى إِلَيْهِ","units":[{"id":"za138_1","label":"بَابُ الْمُوصَى إِلَيْهِ · ١","segs":[["matn","تَصِحُّ وَصِيَّةُ الْمُسْلِمِ إِلَى كُلِّ مُسْلِمٍ مُكَلَّفٍ عَدْلٍ رَشِيدٍ وَلَوْ عَبْدًا، وَيَقْبَلُ بِإِذْنِ سَيِّدِهِ وَإِذَا أَوْصَى إِلَى زَيْدٍ وَبَعْدَهُ إِلَى عَمْرٍو وَلَمْ يَعْزِلْ زَيْدًا اشْتَرَكَا،"]]},{"id":"za138_2","label":"بَابُ الْمُوصَى إِلَيْهِ · ٢","segs":[["matn","وَلَا يَنْفَرِدُ أَحَدُهُمَا بِتَصَرُّفٍ لَمْ يَجْعَلْهُ لَهُ وَلَا تَصِحُّ وَصِيَّةٌ إِلَّا فِي تَصَرُّفٍ مَعْلُومٍ يَمْلِكُهُ الْمُوصِي كَقَضَاءِ دَيْنِهِ وَتَفْرِقَةِ ثُلُثِهِ وَالنَّظَرِ لِصِغَارِهِ وَلَا تَصِحُّ بِمَا لَا يَمْلِكُهُ الْمُوصِي كَوَصِيَّةِ الْمَرْأَةِ بِالنَّظَرِ فِي حَقِّ أَوْلَادِهَا الْأَصَاغِرِ وَنَحْوِ ذَلِكَ،"]]},{"id":"za138_3","label":"بَابُ الْمُوصَى إِلَيْهِ · ٣","segs":[["matn","وَمَنْ وُصِّيَ فِي شَيْءٍ لَمْ يَصِرْ وَصِيًّا فِي غَيْرِهِ، وَإِنْ ظَهَرَ عَلَى الْمَيِّتِ دَيْنٌ يَسْتَغْرِقُ بَعْدَ تَفْرِقَةِ الْوَصِيِّ لَمْ يَضْمَنْ، وَإِنْ قَالَ: ضَعْ ثُلُثِي حَيْثُ شِئْتَ لَمْ يَحِلَّ لَهُ وَلَا لِوَلَدِهِ،"]]},{"id":"za138_4","label":"بَابُ الْمُوصَى إِلَيْهِ · ٤","segs":[["matn","وَمَنْ مَاتَ بِمَكَانٍ لَا حَاكِمَ بِهِ وَلَا وَصِيَّ جَازَ لِبَعْضِ مَنْ حَضَرَهُ مِنَ الْمُسْلِمِينَ تَوَلِّي تَرِكَتِهِ وَعَمَلُ الْأَصْلَحِ حِينَئِذٍ فِيهَا مِنْ بَيْعٍ وَغَيْرِهِ."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"za139","title":"كِتَابُ الْفَرَائِضِ","units":[{"id":"za139_1","label":"كِتَابُ الْفَرَائِضِ · ١","segs":[["matn","وَهِيَ الْعِلْمُ بِقِسْمَةِ الْمَوَارِيثِ. أَسْبَابُ الْإِرْثِ رَحِمٌ وَنِكَاحٌ وَوَلَاءٌ، وَالْوَرَثَةُ ذُو فَرْضٍ وَعَصَبَةٍ وَرَحِمٍ، فَذَوُو الْفَرْضِ عَشَرَةٌ: الزَّوْجَانِ وَالْأَبَوَانِ وَالْجَدُّ وَالْجَدَّةُ وَالْبَنَاتُ وَبَنَاتُ الْابْنِ وَالْأَخَوَاتُ مِنْ كُلِّ جِهَةٍ وَالْإِخْوَةُ مِنَ الْأُمِّ،"]]},{"id":"za139_2","label":"كِتَابُ الْفَرَائِضِ · ٢","segs":[["matn","فَلِلزَّوْجِ النِّصْفُ وَمَعَ وُجُودِ وَلَدٍ أَوْ وَلَدِ ابْنٍ وَإِنْ نَزَلَ الرُّبُعُ، وَلِلزَّوْجَةِ فَأَكْثَرَ نِصْفُ حَالَيْهِ فِيهِمَا، وَلِكُلٍّ مِنَ الْأَبِ وَالْجَدِّ السُّدُسُ بِالْفَرْضِ مَعَ ذُكُورِ الْوَلَدِ أَوْ وَلَدِ الْابْنِ، وَيَرِثَانِ بِالتَّعْصِيبِ مَعَ عَدَمِ الْوَلَدِ وَوَلَدِ الْابْنِ، وَبِالْفَرْضِ وَالتَّعْصِيبِ مَعَ إِنَاثِهِمَا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za140","title":"كِتَابُ الْفَرَائِضِ · فَصْلٌ","units":[{"id":"za140_1","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ · ١","segs":[["matn","وَالْجَدُّ لِأَبٍ وَإِنْ عَلَا مَعَ وَلَدِ أَبَوَيْنِ، أَوْ أَبٍ كَأَخٍ مِنْهُمْ، فَإِنْ نَقَصَتْهُ الْمُقَاسَمَةُ عَنْ ثُلُثِ الْمَالِ أُعْطِيَهُ، وَمَعَ ذِي فَرْضٍ بَعْدَهُ الْأَحَظُّ مِنَ الْمُقَاسَمَةِ، أَوْ ثُلُثُ مَا بَقِيَ أَوْ سُدُسُ الْكُلِّ،"]]},{"id":"za140_2","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ · ٢","segs":[["matn","فَإِنْ لَمْ يَبْقَ سِوَى السُّدُسِ أُعْطِيَهُ وَسَقَطَ الْإِخْوَةُ إِلَّا فِي الْأَكْدَرِيَّةِ وَلَا يُعَوَّلُ وَلَا يُفْرَضُ لِأُخْتٍ مَعَهُ إِلَّا بِهَا، وَوَلَدُ الْأَبِ إِذَا انْفَرَدُوا مَعَهُ كَوَلَدِ الْأَبَوَيْنِ،"]]},{"id":"za140_3","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ · ٣","segs":[["matn","فَإِنِ اجْتَمَعُوا فَقَاسَمُوهُ أَخَذَ عَصَبَةُ وَلَدِ الْأَبَوَيْنِ مَا بِيَدِ وَلَدِ الْأَبِ، وَأُنْثَاهُمْ تَمَامَ فَرْضِهَا، وَمَا بَقِيَ لِوَلَدِ الْأَبِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za141","title":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٢)","units":[{"id":"za141_1","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٢) · ١","segs":[["matn","وَلِلْأُمِّ السُّدُسُ مَعَ وَلَدٍ أَوْ وَلَدِ ابْنٍ أَوِ اثْنَيْنِ مِنْ إِخْوَةٍ أَوْ أَخَوَاتٍ، وَالثُّلُثُ مَعَ عَدَمِهِمْ، وَالسُّدُسُ مَعَ زَوْجٍ وَأَبَوَيْنِ، وَالرُّبُعُ مَعَ زَوْجَةٍ وَأَبَوَيْنِ، وَلِلْأَبِ مِثْلَاهُمَا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za142","title":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٣)","units":[{"id":"za142_1","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٣) · ١","segs":[["matn","تَرِثُ أُمُّ الْأُمِّ وَأُمُّ الْأَبِ وَأُمُّ أَبِي الْأَبِ وَإِنْ عَلَوْنَ أُمُومَةً السُّدُسَ، فَإِنْ تَحَاذَيْنَ فَبَيْنَهُنَّ، وَمَنْ قَرُبَتْ فَلَهَا وَحْدَهَا، وَتَرِثُ أُمُّ الْأَبِ وَالْجَدِّ مَعْهُمَا كَالْعَمِّ وَتَرِثُ الْجَدَّةُ بِقَرَابَتَيْنِ ثُلُثَيِ السُّدُسِ،"]]},{"id":"za142_2","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٣) · ٢","segs":[["matn","فَلَوْ تَزَوَّجَ بِنْتَ خَالَتِهِ فَجَدَّتُهُ أُمُّ أُمِّ أُمِّ وَلَدِهِمَا وَأُمُّ أُمِّ أَبِيهِ، وَإِنْ تَزَوَّجَ بِنْتَ عَمَّتِهِ فَجَدَّتُهُ أُمُّ أُمِّ أُمِّهِ وَأُمُّ أَبِي أَبِيهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za143","title":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٤)","units":[{"id":"za143_1","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٤) · ١","segs":[["matn","وَالنِّصْفُ فَرْضُ بِنْتٍ وَحْدَهَا، ثُمَّ هُوَ لِبِنْتِ ابْنٍ وَحْدَهَا، ثُمَّ لِأُخْتٍ لِأَبَوَيْنِ أَوْ لِأَبٍ وَحْدَهَا، وَالثُّلُثَانِ لِثِنْتَيْنِ مِنَ الْجَمِيعِ فَأَكْثَرَ إِذَا لَمْ يُعَصَّبْنَ بِذَكَرٍ، وَالسُّدُسُ لِبِنْتِ ابْنٍ فَأَكْثَرَ مَعَ بِنْتٍ،"]]},{"id":"za143_2","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٤) · ٢","segs":[["matn","وَلِأُخْتٍ فَأَكْثَرَ لِأَبٍ مَعَ أُخْتٍ لِأَبَوَيْنِ مَعَ عَدَمِ مُعَصِّبٍ فِيهِمَا، فَإِنِ اسْتَكْمَلَ الثُّلُثَيْنِ بَنَاتٌ أَوْ هُمَا سَقَطَ مَنْ دُوْنَهُنَّ إِنْ لَمْ يُعَصِّبْهُنَّ ذَكَرٌ بِإِزَائِهِنَّ أَوْ أَنْزَلَ مِنْهُنَّ،"]]},{"id":"za143_3","label":"كِتَابُ الْفَرَائِضِ · فَصْلٌ (٤) · ٣","segs":[["matn","وَكَذَا الْأَخَوَاتُ مِنَ الْأَبِ مَعَ أَخَوَاتِ لِأَبَوَيْنِ إِنْ لَمْ يُعَصِّبْهُنَّ أَخُوهُنَّ، وَالْأُخْتُ فَأَكْثَرُ تَرِثُ مَا فَضَلَ عَنْ فَرْضِ الْبِنْتِ فَأَزْيَدَ، وَلِلذَّكَرِ أَوِ الْأُنْثَى مِنْ وَلَدِ الْأُمِّ السُّدُسُ، وَلِاثْنَيْنِ فَأَزْيَدَ الثُّلُثُ بَيْنَهُمْ بِالسَّوِيَّةِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za144","title":"فَصْلٌ فِي الْحَجْبِ","units":[{"id":"za144_1","label":"فَصْلٌ فِي الْحَجْبِ · ١","segs":[["matn","تَسْقُطُ الْأَجْدَادُ بِالْأَبِ، وَالْأَبْعَدُ بِالْأَقْرَبِ، وَالْجَدَّاتُ بِالْأُمِّ، وَوَلَدُ الْابْنِ بِالْابْنِ، وَوَلَدُ الْأَبَوَيْنِ بِابْنٍ، وَابْنِ ابْنٍ وَأَبٍ وَوَلَدُ الْأَبِ بِهِمْ وَبِالْأَخِ لِأَبَوَيْنِ، وَوَلَدُ الْأُمِّ بِالْوَلَدِ وَبِوَلَدِ الْابْنِ وَبِالْأَبِ وَأَبِيهِ، وَيَسْقُطُ بِهِ كُلُّ ابْنِ أَخٍ وَعَمٍّ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za145","title":"بَابُ الْعَصَبَاتِ","units":[{"id":"za145_1","label":"بَابُ الْعَصَبَاتِ · ١","segs":[["matn","وَهُمْ كُلُّ مَنْ لَوِ انْفَرَدَ لَأَخَذَ الْمَالَ بِجِهَةٍ وَاحِدَةٍ، وَمَعَ ذِي فَرْضٍ يَأْخُذُ مَا بَقِيَ، فَأَقْرَبُهُمُ ابْنٌ فَابْنُهُ وَإِنْ نَزَلَ، ثُمَّ الْأَبُ ثُمَّ الْجَدُّ وَإِنْ عَلَا مَعَ عَدَمِ أَخٍ لِأَبَوَيْنِ أَوْ لِأَبٍ،"]]},{"id":"za145_2","label":"بَابُ الْعَصَبَاتِ · ٢","segs":[["matn","ثُمَّ هُمَا ثُمَّ بَنُوهُمَا أَبَدًا، ثُمَّ عَمٌّ لِأَبَوَيْنِ، ثُمَّ عَمٌّ لِأَبٍ ثُمَّ بَنُوهُمَا كَذَلِكَ، ثُمَّ أَعْمَامُ أَبِيهِ لِأَبَوَيْنِ، ثُمَّ لِأَبٍ، ثُمَّ بَنُوهُمْ كَذَلِكَ، ثُمَّ أَعْمَامُ جَدِّهِ، ثُمَّ بَنُوهُمْ كَذَلِكَ،"]]},{"id":"za145_3","label":"بَابُ الْعَصَبَاتِ · ٣","segs":[["matn","لَا يَرِثُ بَنُو أَبٍ أَعْلَى مَعَ بَنِي أَبٍ أَقْرَبَ وَإِنْ نَزَلُوا، فَأَخٌ لِأَبٍ أَوْلَى مِنْ عَمٍّ وَابْنِهِ وَابْنِ أَخٍ لِأَبَوَيْنِ، وَهُوَ أَوِ ابْنُ أَخٍ لِأَبٍ أَوْلَى مِنِ ابْنِ ابْنِ أَخٍ لِأَبَوَيْنِ،"]]},{"id":"za145_4","label":"بَابُ الْعَصَبَاتِ · ٤","segs":[["matn","وَمَعَ الْاسْتِوَاءِ يُقَدَّمُ مَنْ لِأَبَوَيْنِ، فَإِنْ عُدِمَ عَصَبَةُ النَّسَبِ وَرِثَ الْمُعْتِقُ ثُمَّ عَصَبَتُهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za146","title":"بَابُ الْعَصَبَاتِ · فَصْلٌ","units":[{"id":"za146_1","label":"بَابُ الْعَصَبَاتِ · فَصْلٌ · ١","segs":[["matn","يَرِثُ الْابْنُ وَابْنُهُ وَالْأَخُ لِأَبَوَيْنِ وَلِأَبٍ مَعَ أُخْتِهِ مِثْلَيْهَا، وَكُلُّ عَصَبَةٍ غَيْرُهُمْ لَا تَرِثُ أُخْتُهُ مَعَهُ شَيْئًا، وَابْنَا عَمٍّ؛ أَحَدُهُمَا أَخٌ لِأُمٍّ أَوْ زَوْجٌ لَهُ فَرْضُهُ، وَالْبَاقِي لَهُمَا، وَيُبْدَأُ بِالْفُرُوضِ وَمَا بَقِيَ لِلْعَصَبَةِ، وَيَسْقُطُونَ فِي الْحِمَارِيَّةِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za147","title":"بَابُ أُصُولِ الْمَسَائِلِ","units":[{"id":"za147_1","label":"بَابُ أُصُولِ الْمَسَائِلِ · ١","segs":[["matn","الْفُرُوضُ سِتَّةٌ: نِصْفٌ وَرُبُعٌ وَثُمُنٌ وَثُلُثَانِ وَثُلُثٌ وَسُدُسٌ، وَالْأُصُولُ سَبْعَةٌ: فَنِصْفَانِ أَوْ نِصْفٌ وَمَا بَقِيَ مِنِ اثْنَيْنِ، وَثُلُثَانِ أَوْ ثُلُثٌ وَمَا بَقِيَ أَوْ هُمَا مِنْ ثَلَاثَةٍ،"]]},{"id":"za147_2","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٢","segs":[["matn","وَرُبُعٌ أَوْ ثُمُنٌ وَمَا بَقِيَ أَوْ مَعَ النِّصْفِ مِنْ أَرْبَعَةٍ وَمِنْ ثَمَانِيَةٍ، فَهَذِهِ أَرْبَعَةٌ لَا تَعُولُ، وَالنِّصْفُ مَعَ الثُّلُثَيْنِ أَوِ الثُّلُثِ أَوِ السُّدُسِ أَوْ هُوَ وَمَا بَقِيَ مِنْ سِتَّةٍ وَتَعُولُ إِلَى عَشَرَةٍ شِفْعًا وَوِتْرًا،"]]},{"id":"za147_3","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٣","segs":[["matn","وَالرُّبُعُ مَعَ الثُّلُثَيْنِ أَوِ الثُّلُثِ أَوِ السُّدُسِ مِنِ اثْنَيْ عَشَرَ وَتَعُولُ إِلَى سَبْعَةَ عَشَرَ وِتْرًا، وَالثُّمُنُ مَعَ سُدُسٍ أَوِ ثُلُثَيْنِ مِنْ أَرْبَعَةٍ وَعِشْرِينَ، وَتَعُولُ إِلَى سَبْعَةٍ وَعِشْرِينَ، وَإِنْ بَقِيَ بَعْدَ الْفُرُوضِ شَيْءٌ، وَلَا عَصَبَةَ، رُدَّ عَلَى كُلِّ فَرْضٍ بِقَدْرِهِ غَيْرَ الزَّوْجَيْنِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za148","title":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ","units":[{"id":"za148_1","label":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · ١","segs":[["matn","إِذَا انْكَسَرَ سَهْمُ فَرِيقٍ عَلَيْهِمْ ضَرَبْتَ عَدَدَهُمْ إِنْ بَايَنَ سِهَامَهُمْ أَوْ وَفْقَهُ إِنْ وَافَقَهُ بِجُزْءٍ كَثُلُثٍ وَنَحْوِهِ فِي أَصْلِ الْمَسْأَلَةِ وَعَوْلِهَا إِنْ عَالَتْ فَمَا بَلَغَ صَحَّتْ مِنْهُ وَيَصِيرُ لِلْوَاحِدِ مَا كَانَ لِجَمَاعَتِهِ أَوْ وَفْقُهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za149","title":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · فَصْلٌ","units":[{"id":"za149_1","label":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · فَصْلٌ · ١","segs":[["matn","إِذَا مَاتَ شَخْصٌ وَلَمْ تُقْسَمْ تَرِكَتُهُ حَتَّى مَاتَ بَعْضُ وَرَثَتِهِ فَإِنْ وَرِثُوهُ كَالْأَوَّلِ كَإِخْوَةٍ فَاقْسِمْهَا عَلَى مَنْ بَقِيَ"]]},{"id":"za149_2","label":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ كَانَ وَرَثَةُ كُلِّ مَيِّتٍ لَا يَرِثُونَ غَيْرَهُ كَإِخْوَةٍ لَهُمْ بَنُونَ فَصَحِّحِ الْأُولَى وَاقْسِمْ سَهْمَ كَلِّ مَيِّتٍ عَلَى مَسْأَلَتِهِ وَصَحِّحِ الْمُنْكَسِرَ كَمَا سَبَقَ،"]]},{"id":"za149_3","label":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · فَصْلٌ · ٣","segs":[["matn","وَإِنْ لَمْ يَرِثُوا الثَّانِيَ كَالْأَوَّلِ صَحَّحْتَ الْأُولَى وَقَسَمْتَ أَسْهُمَ الثَّانِي عَلَى وَرَثَتِهِ، فَإِنِ انْقَسَمَتْ صَحَّتَا مِنْ أَصْلِهَا، وَإِنْ لَمْ تَنْقَسِمْ ضَرَبْتَ كَلَّ الثَّانِيَةِ أَوْ وَفْقَهَا لِلسِّهَامِ فِي الْأُولَى،"]]},{"id":"za149_4","label":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · فَصْلٌ · ٤","segs":[["matn","وَمَنْ لَهُ شَيْءٌ مِنْهَا فَاضْرِبْهُ فِيمَا ضَرَبْتَهُ فِيهَا، وَمَنْ لَهُ مِنَ الثَّانِيَةِ شَيْءٌ فَاضْرِبْهُ فِيمَا تَرَكَهُ الْمَيِّتُ أَوْ وَفْقِهِ فَهُوَ لَهُ، وَتَعْمَلُ فِي الثَّالِثِ فَأَكْثَرَ عَمَلَكَ فِي الثَّانِي مَعَ الْأَوَّلِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za150","title":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · فَصْلٌ (٢)","units":[{"id":"za150_1","label":"بَابُ التَّصْحِيحِ وَالْمُنَاسَخَاتِ وَقِسْمَةِ التَّرِكَاتِ · فَصْلٌ (٢) · ١","segs":[["matn","إِذَا أَمْكَنَ نِسْبَةُ سَهْمِ كُلِّ وَارِثٍ مِنَ الْمَسْأَلَةِ بِجُزْءٍ فَلَهُ كَنِسْبَتِهِ"]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za151","title":"بَابُ ذَوِي الْأَرْحَامِ","units":[{"id":"za151_1","label":"بَابُ ذَوِي الْأَرْحَامِ · ١","segs":[["matn","وَيُوَرَّثُونَ بِالتَّنْزِيلِ الذَّكَرُ وَالْأُنْثَى سَوَاءٌ، فَوَلَدُ الْبَنَاتِ وَوَلَدُ بَنَاتِ الْبَنِينَ وَوَلَدُ الْأَخَوَاتِ كَأُمَّهَاتِهِمْ، وَبَنَاتُ الْإِخْوَةِ وَالْأَعْمَامِ لِأَبَوَيْنِ أَوْ لِأَبٍ وَبَنَاتُ بَنِيهِمْ وَوَلَدُ الْإِخْوَةِ لِأُمٍّ كَآبَائِهِمْ، وَالْأَخْوَالُ وَالْخَالَاتُ وَأَبُو الْأُمِّ كَالْأُمِّ، وَالْعَمَّاتُ وَالْعَمُّ لِأُمٍّ كَالْأَبِ،"]]},{"id":"za151_2","label":"بَابُ ذَوِي الْأَرْحَامِ · ٢","segs":[["matn","وَكُلُّ جَدَّةٍ أَدْلَتْ بِأَبٍ بَيْنَ أُمَّيْنِ هِيَ إِحْدَاهُمَا كَأُمِّ أَبِي أُمٍّ، أَوْ بِأَبٍ أَعْلَى مِنَ الْجَدِّ كَأُمِّ أَبِ الْجَدِّ،"]]},{"id":"za151_3","label":"بَابُ ذَوِي الْأَرْحَامِ · ٣","segs":[["matn","وَأَبُو أُمِّ أَبٍ وَأَبُو أُمِّ أُمٍّ وَأَخَوَاهُمَا وَأُخْتَاهُمَا بِمَنْزِلَتِهِمْ فَيُجْعَلُ حَقُّ كُلِّ وَارِثٍ لِمَنْ أَدْلَى بِهِ فَإِنْ أَدْلَى جَمَاعَةٌ بِوَارِثٍ وَاسْتَوَتْ مَنْزِلَتُهُمْ مِنْهُ بِلَا سَبْقٍ كَأَوْلَادِهِ فَنَصِيبُهُ لَهُمْ،"]]},{"id":"za151_4","label":"بَابُ ذَوِي الْأَرْحَامِ · ٤","segs":[["matn","فَابْنٌ وَبِنْتٌ لِأُخْتٍ مَعَ بِنْتٍ لِأُخْتٍ أُخْرَى: حَقُّ أُمِّهَا وَلِلْأُولَيَيْنِ حَقُّ أُمِّهِمَا، وَإِنِ اخْتَلَفَتْ مَنَازِلُهُمْ مِنْهُ جَعَلْتَهُمْ مَعَهُ كَمَيِّتٍ اقْتَسَمُوا إِرْثَهُ،"]]},{"id":"za151_5","label":"بَابُ ذَوِي الْأَرْحَامِ · ٥","segs":[["matn","فَإِنْ خَلَّفَ ثَلَاثَ خَالَاتٍ مُتَفَرِّقَاتٍ وَثَلَاثَ عَمَّاتٍ مُتَفَرِّقَاتٍ فَالثُّلُثُ لِلْخَالَاتِ أَخْمَاسًا وَالثُّلُثَانِ لِلْعَمَّاتِ أَخْمَاسًا وَتَصِحُّ مِنْ خَمْسَةَ عَشَرَ، وَفِي ثَلَاثَةِ أَخْوَالٍ مُتَفَرِّقِينَ لِذِي الْأُمِّ السُّدُسُ وَالْبَاقِي لِذِي الْأَبَوَيْنِ، فَإِنْ كَانَ مَعَهُمْ أَبُو أُمٍّ أَسْقَطَهُمْ،"]]},{"id":"za151_6","label":"بَابُ ذَوِي الْأَرْحَامِ · ٦","segs":[["matn","وَفِي ثَلَاثِ بَنَاتِ عُمُومَةٍ مُتَفَرِّقِينَ الْمَالُ لِلَّتِي لِلْأَبَوَيْنِ، وَإِنْ أَدْلَى جَمَاعَةٌ بِجَمَاعَةٍ قَسَمْتَ الْمَالَ بَيْنَ الْمُدْلَى بِهِمْ فَمَا صَارَ لِكُلِّ وَاحِدٍ أَخَذَهُ الْمُدْلِي بِهِ، وَإِنْ سَقَطَ بَعْضُهُمْ بِبَعْضٍ عَمِلْتَ بِهِ وَالْجِهَاتُ أُبُوَّةٌ وَأُمُومَةٌ وَبُنُوَّةٌ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za152","title":"بَابُ مِيرَاثِ الْحَمْلِ وَالْخُنْثَى الْمُشْكِلِ","units":[{"id":"za152_1","label":"بَابُ مِيرَاثِ الْحَمْلِ وَالْخُنْثَى الْمُشْكِلِ · ١","segs":[["matn","مَنْ خَلَّفَ وَرَثَةً فِيهِمْ حَمْلٌ فَطَلَبُوا الْقِسْمَةَ وُقِفَ لِلْحَمْلِ الْأَكْثَرُ مِنْ إِرْثِ ذَكَرَيْنِ أَوْ أُنْثَيَيْنِ، فَإِذَا وُلِدَ أَخَذَ حَقَّهُ وَمَا بَقِيَ فَهُوَ لِمُسْتَحِقِّهِ، وَمَنْ لَا يَحْجُبُهُ يَأْخُذُ إِرْثَهُ كَالْجَدَّةِ، وَمَنْ يُنْقِصُهُ شَيْئًا الْيَقِينَ،"]]},{"id":"za152_2","label":"بَابُ مِيرَاثِ الْحَمْلِ وَالْخُنْثَى الْمُشْكِلِ · ٢","segs":[["matn","وَمَنْ سَقَطَ بِهِ لَمْ يُعْطَ شَيْئًا، وَيَرِثُ وَيُورَثُ إِنِ اسْتَهَلَّ صَارِخًا أَوْ عَطَسَ أَوْ بَكَى أَوْ رَضَعَ أَوْ تَنَفَّسَ وَطَالَ زَمَنُ التَّنَفُّسِ أَوْ وُجِدَ دَلِيلُ حَيَاتِهِ غَيْرَ حَرَكَةٍ وَاخْتِلَاجٍ وَإِنْ ظَهَرَ بَعْضُهُ فَاسْتَهَلَّ ثُمَّ مَاتَ وَخَرَجَ لَمْ يَرِثْ،"]]},{"id":"za152_3","label":"بَابُ مِيرَاثِ الْحَمْلِ وَالْخُنْثَى الْمُشْكِلِ · ٣","segs":[["matn","وَإِنْ جُهِلَ الْمُسْتَهِلُّ مِنَ التَّوْأَمَيْنِ وَاخْتَلَفَ إِرْثُهُمَا يُعَيَّنُ بِقُرْعَةٍ، وَالْخُنْثَى الْمُشْكِلُ يَرِثُ نِصْفَ مِيرَاثِ ذَكَرٍ وَنِصْفَ مِيرَاثِ أُنْثَى."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za153","title":"بَابُ مِيرَاثِ الْمَفْقُودِ","units":[{"id":"za153_1","label":"بَابُ مِيرَاثِ الْمَفْقُودِ · ١","segs":[["matn","مَنْ خَفِيَ خَبَرُهُ بِأَسْرٍ أَوْ سَفَرٍ غَالِبُهُ السَّلَامَةُ كَتِجَارَةٍ انْتُظِرَ بِهِ تَمَامَ تِسْعِينَ سَنَةً مُنْذُ وُلِدَ،"]]},{"id":"za153_2","label":"بَابُ مِيرَاثِ الْمَفْقُودِ · ٢","segs":[["matn","وَإِنْ كَانَ غَالِبُهُ الْهَلَاكَ كَمَنْ غَرِقَ فِي مَرْكَبٍ فَسَلِمَ قَوْمٌ دُونَ قَوْمٍ أَوْ فُقِدَ مِنْ بَيْنِ أَهْلِهِ أَوْ فِي مَفَازَةٍ مَهْلَكَةٍ انْتُظِرَ بِهِ تَمَامَ أَرْبَعِ سِنِينَ مُنْذُ تَلِفَ، ثُمَّ يُقْسَمُ مَالُهُ فِيهِمَا،"]]},{"id":"za153_3","label":"بَابُ مِيرَاثِ الْمَفْقُودِ · ٣","segs":[["matn","فَإِنْ مَاتَ مُوَرِّثُهُ فِي مُدَّةِ التَّرَبُّصِ أَخَذَ كُلُّ وَارِثٍ إِذًا الْيَقِينَ وَوُقِفَ مَا بَقِيَ، فَإِنْ قَدِمَ أَخَذَ نَصِيبَهُ، وَإِنْ لَمْ يَأْتِ فَحُكْمُهُ حُكْمُ مَالِهِ، وَلِبَاقِي الْوَرَثَةِ أَنْ يَصْطَلِحُوا عَلَى مَا زَادَ عَنْ حَقِّ الْمَفْقُودِ فَيَقْتَسِمُوهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za154","title":"بَابُ مِيرَاثِ الْغَرْقَى","units":[{"id":"za154_1","label":"بَابُ مِيرَاثِ الْغَرْقَى · ١","segs":[["matn","إِذَا مَاتَ مُتَوَارِثَانِ كَأَخَوَيْنِ لِأَبٍ بِهَدْمٍ أَوْ غَرَقٍ أَوْ غُرْبَةٍ أَوْ نَارٍ وَجُهِلَ السَّابِقُ بِالْمَوْتِ وَلَمْ يَخْتَلِفُوا فِيهِ وَرِثَ كُلُّ وَاحِدٍ مِنَ الْآخَرِ مَنْ تِلَادِ مَالِهِ دُونَ مَا وَرِثَهُ مِنْهُ دَفْعًا لِلدَّوْرِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za155","title":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ","units":[{"id":"za155_1","label":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ · ١","segs":[["matn","لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ إِلَّا بِالْوَلَاءِ، وَلَا الْكَافِرُ الْمُسْلِمَ إِلَّا بِالْوَلَاءِ، وَيَتَوَارَثُ الْحَرْبِيُّ وَالذِّمِّيُّ وَالْمُسْتَأْمِنُ، وَأَهْلُ الذِّمَّةِ يَرِثُ بَعْضُهُمْ بَعْضًا مَعَ اتِّفَاقِ أَدْيَانِهِمْ لَا مَعَ اخْتِلَافِهَا وَهُمْ مِلَلٌ شَتَّى، وَالْمُرْتَدُّ لَا يَرِثُ أَحَدًا،"]]},{"id":"za155_2","label":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ · ٢","segs":[["matn","وَإِنْ مَاتَ عَلَى رِدَّتِهِ فَمَالُهُ فَيْءٌ، وَيَرِثُ الْمَجُوسُ بِقَرَابَتَيْنِ إِنْ أَسْلَمُوا أَوْ تَحَاكَمُوا إِلَيْنَا قَبْلَ إِسْلَامِهِمْ، وَكَذَا حُكْمُ الْمُسْلِمِ يَطَأُ ذَاتَ رَحِمٍ مُحَرَّمٍ مِنْهُ بِشُبْهَةٍ،"]]},{"id":"za155_3","label":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ · ٣","segs":[["matn","وَلَا إِرْثَ بِنِكَاحِ ذَاتِ رَحِمٍ مُحَرَّمٍ وَلَا بِعَقْدٍ لَا يُقَرُّ عَلَيْهِ لَوْ أَسْلَمَ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za156","title":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ","units":[{"id":"za156_1","label":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ · ١","segs":[["matn","مَنْ أَبَانَ زَوْجَتَهُ فِي صِحَّتِهِ أَوْ مَرَضِهِ غَيْرِ الْمَخُوفِ وَمَاتَ بِهِ أَوِ الْمَخُوفِ وَلَمْ يَمُتْ بِهِ لَمْ يَتَوَارَثَا، بَلْ فِي طَلَاقٍ رَجْعِيٍّ لَمْ تَنْقَضِ عِدَّتُهُ، وَإِنْ أَبَانَهَا فِي مَرَضِ مَوْتِهِ الْمَخُوفِ مُتَّهَمًا بِقَصْدِ حِرْمَانِهَا،"]]},{"id":"za156_2","label":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ · ٢","segs":[["matn","أَوْ عَلَّقَ إِبَانَتَهَا فِي صِحَّتِهِ عَلَى مَرَضِهِ أَوْ عَلَى فِعْلٍ لَهُ فَفَعَلَهُ فِي مَرَضِهِ وَنَحْوَهُ لَمْ يَرِثْهَا وَتَرِثُهُ فِي الْعِدَّةِ وَبَعْدَهَا مَا لَمْ تَتَزَوَّجْ أَوْ تَرْتَدَّ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za157","title":"بَابُ الْإِقْرَارِ بِمُشَارِكٍ فِي الْمِيرَاثِ","units":[{"id":"za157_1","label":"بَابُ الْإِقْرَارِ بِمُشَارِكٍ فِي الْمِيرَاثِ · ١","segs":[["matn","إِذَا أَقَرَّ كُلُّ الْوَرَثَةِ وَلَوْ أَنَّهُ وَاحِدٌ بِوَارِثٍ لِلْمَيِّتِ وَصَدَّقَ أَوْ كَانَ صَغِيرًا أَوْ مَجْنُونًا وَالْمُقَرُّ بِهِ مَجْهُولَ النَّسَبِ ثَبَتَ نَسَبُهُ وَإِرْثُهُ، وَإِنْ أَقَرَّ أَحَدُ ابْنَيْهِ بِأَخٍ مِثْلِهِ فَلَهُ ثُلُثُ مَا بِيَدِهِ، وَإِنْ أَقَرَّ بِأُخْتٍ فَلَهَا خُمُسُهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za158","title":"بَابُ مِيرَاثِ الْقَاتِلِ وَالْمُبَعَّضِ وَالْوَلَاءِ","units":[{"id":"za158_1","label":"بَابُ مِيرَاثِ الْقَاتِلِ وَالْمُبَعَّضِ وَالْوَلَاءِ · ١","segs":[["matn","فَمَنِ انْفَرَدَ بِقَتْلِ مُوَرِّثِهِ أَوْ شَارَكَ فِيهِ مُبَاشَرَةً أَوْ سَبَبًا بِلَا حَقٍّ لَمْ يَرِثْهُ إِنْ لَزِمَهُ قَوَدٌ أَوْ دِيَةٌ أَوْ كَفَّارَةٌ، وَالْمُكَلَّفُ وَغَيْرُهُ سَوَاءٌ،"]]},{"id":"za158_2","label":"بَابُ مِيرَاثِ الْقَاتِلِ وَالْمُبَعَّضِ وَالْوَلَاءِ · ٢","segs":[["matn","وَإِنْ قُتِلَ بِحَقٍّ قَوَدًا أَوْ حَدًّا أَوْ كُفْرًا أَوْ بِبَغْيٍ أَوْ صِيَالَةٍ أَوْ حِرَابَةٍ أَوْ شَهَادَةِ وَارِثِهِ أَوْ قَتَلَ الْعَادِلُ الْبَاغِيَ وَعَكْسُهُ وَرِثَهُ، وَلَا يَرِثُ الرَّقِيقُ وَلَا يُورَثُ،"]]},{"id":"za158_3","label":"بَابُ مِيرَاثِ الْقَاتِلِ وَالْمُبَعَّضِ وَالْوَلَاءِ · ٣","segs":[["matn","وَيَرِثُ مَنْ بَعْضُهُ حُرٌّ وَيُوَرَّثُ وَيَحْجُبُ بِقَدْرِ مَا فِيهِ مِنَ الْحُرِّيَّةِ، وَمَنْ أَعْتَقَ عَبْدًا فَلَهُ عَلَيْهِ الْوَلَاءُ وَإِنِ اخْتَلَفَ دِينُهُمَا، وَلَا يَرِثُ النِّسَاءُ بِالْوَلَاءِ إِلَّا مَنْ أَعْتَقْنَ أَوْ أَعْتَقَهُ مَنْ أَعْتَقْنَ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"za159","title":"كِتَابُ الْعِتْقِ","units":[{"id":"za159_1","label":"كِتَابُ الْعِتْقِ · ١","segs":[["matn","وَهُوَ مِنْ أَفْضَلِ الْقُرَبِ، وَيُسْتَحَبُّ عِتْقُ مَنْ لَهُ كَسْبٌ وَعَكْسُهُ بِعَكْسِهِ، وَيَصِحُّ تَعْلِيقُ الْعِتْقُ بِمَوْتٍ وَهُوَ التَّدْبِيرُ."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"za160","title":"بَابُ الْكِتَابَةِ","units":[{"id":"za160_1","label":"بَابُ الْكِتَابَةِ · ١","segs":[["matn","بَيْعُ عَبْدِهِ نَفْسَهُ بِمَالٍ مُؤَجَّلٍ فِي ذِمَّتِهِ، وَتُسَنُّ مَعَ أَمَانَةِ الْعَبْدِ وَكَسْبِهِ، وَتُكْرَهُ مَعَ عَدَمِهِ، وَيَجُوزُ بَيْعُ الْمُكَاتَبِ، وَمُشْتَرِيهِ يَقُومُ مَقَامَ مُكَاتِبِهِ، فَإِنْ أَدَّى عَتَقَ وَوَلَاؤُهُ لَهُ، وَإِنْ عَجَزَ عَادَ قِنًّا."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"za161","title":"بَابُ أَحْكَامِ أُمَّهَاتِ الْأَوْلَادِ","units":[{"id":"za161_1","label":"بَابُ أَحْكَامِ أُمَّهَاتِ الْأَوْلَادِ · ١","segs":[["matn","إِذَا أَوْلَدَ حُرٌّ أَمَتَهُ أَوْ أَمَةً لَهُ وَلِغَيْرِهِ أَوْ أَمَةً لِوَلَدِهِ خُلِقَ وَلَدُهُ حُرًّا حَيًّا وُلِدَ أَوْ مَيِّتًا قَدْ تَبَيَّنَ فِيهِ خَلْقُ الْإِنْسَانِ،"]]},{"id":"za161_2","label":"بَابُ أَحْكَامِ أُمَّهَاتِ الْأَوْلَادِ · ٢","segs":[["matn","لَا مُضْغَةٍ أَوْ جِسْمٍ بِلَا تَخْطِيطٍ صَارَتْ أُمَّ وَلَدٍ لَهُ تَعْتِقُ بِمَوْتِهِ مِنْ كُلِّ مَالِهِ، وَأَحْكَامُ أُمِّ الْوَلَدِ أَحْكَامُ الْأَمَةِ مِنْ وَطْءٍ، وَخِدْمَةٍ وَإِجَارَةٍ وَنَحْوِهِ، لَا فِي نَقْلِ الْمِلْكِ فِي رَقَبَتِهَا،"]]},{"id":"za161_3","label":"بَابُ أَحْكَامِ أُمَّهَاتِ الْأَوْلَادِ · ٣","segs":[["matn","وَلَا بِمَا يُرَادُ لَهُ كَوَقْفٍ وَبَيْعٍ وَرَهْنٍ وَنَحْوِهَا."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"za162","title":"كِتَابُ النِّكَاحِ","units":[{"id":"za162_1","label":"كِتَابُ النِّكَاحِ · ١","segs":[["matn","وَهُوَ سُنَّةٌ، وَفِعْلُهُ مَعَ الشَّهْوَةِ أَفْضَلُ مِنْ نَوَافِلِ الْعِبَادَةِ."]]},{"id":"za162_2","label":"كِتَابُ النِّكَاحِ · ٢","segs":[["matn","وَيَجِبُ عَلَى مَنْ يَخَافُ زِنًا بِتَرْكِهِ، وَيُسَنُّ نِكَاحُ وَاحِدَةٍ دَيِّنَةٍ أَجْنَبِيَّةٍ بِكْرٍ وَلُودٍ بِلَا أُمٍّ، وَلَهُ نَظَرُ مَا يَظْهَرُ غَالِبًا مِرَارًا بِلَا خَلْوَةٍ."]]},{"id":"za162_3","label":"كِتَابُ النِّكَاحِ · ٣","segs":[["matn","وَيَحْرُمُ التَّصْرِيحُ بِخِطْبَةِ الْمُعْتَدَّةِ مِنْ وَفَاةٍ وَالْمُبَانَةِ دُونَ التَّعْرِيضِ، وَيُبَاحَانِ لِمَنْ أَبَانَهَا بِدُونِ الثَّلَاثِ كَرَجْعِيَّةٍ، وَيَحْرُمَانِ مِنْهَا عَلَى غَيْرِ زَوْجِهَا، وَالتَّعْرِيضُ، إِنِّي فِي مِثْلِكِ لَرَاغِبٌ، وَتُجِيبُهُ، مَا يُرْغَبُ عَنْكَ وَنَحْوَهُمَا،"]]},{"id":"za162_4","label":"كِتَابُ النِّكَاحِ · ٤","segs":[["matn","فَإِنْ أَجَابَ وَلِيُّ مُجْبَرَةٍ أَوْ أَجَابَتْ غَيْرُ الْمُجْبَرَةِ لِمُسْلِمٍ حَرُمَ عَلَى غَيْرِهِ خِطْبَتُهَا، وَإِنْ رُدَّ أَوْ أَذِنَ أَوْ جُهِلَ الْحَالُ جَازَ."]]},{"id":"za162_5","label":"كِتَابُ النِّكَاحِ · ٥","segs":[["matn","وَيُسَنُّ الْعَقْدُ يَوْمَ الْجُمُعَةِ مَسَاءً، بِخُطْبَةِ ابْنِ مَسْعُودٍ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za163","title":"كِتَابُ النِّكَاحِ · فَصْلٌ","units":[{"id":"za163_1","label":"كِتَابُ النِّكَاحِ · فَصْلٌ · ١","segs":[["matn","وَأَرْكَانُهُ: الزَّوْجَانِ الْخَالِيَانِ مِنَ الْمَوَانِعِ، وَالْإِيجَابُ، وَالْقَبُولُ وَلَا يَصِحُّ مِمَّنْ يُحْسِنُ الْعَرَبِيَّةَ بِغَيْرِ لَفْظِ: زَوَّجْتُ أَوْ أَنْكَحْتُ، وَقَبِلْتُ هَذَا النِّكَاحَ أَوْ تَزَوَّجْتُهَا أَوْ تَزَوَّجْتُ أَوْ قَبِلْتُ،"]]},{"id":"za163_2","label":"كِتَابُ النِّكَاحِ · فَصْلٌ · ٢","segs":[["matn","وَمَنْ جَهِلَهُمَا لَمْ يَلْزَمْهُ تَعَلُّمُهُمَا وَكَفَاهُ مَعْنَاهُمَا الْخَاصُّ بِكُلِّ لِسَانٍ، فَإِنْ تَقَدَّمَ الْقَبُولُ لَمْ يَصِحَّ، وَإِنْ تَأَخَّرَ عَنِ الْإِيجَابِ صَحَّ مَا دَامَا فِي الْمَجْلِسِ وَلَمْ يَتَشَاغَلَا بِمَا يَقْطَعُهُ، وَإِنْ تَفَرَّقَا قَبْلَهُ بَطَلَ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za164","title":"كِتَابُ النِّكَاحِ · فَصْلٌ (٢)","units":[{"id":"za164_1","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٢) · ١","segs":[["matn","وَلَهُ شُرُوطٌ: أَحَدُهَا تَعْيِينُ الزَّوْجَيْنِ، فَإِنْ أَشَارَ الْوَلِيُّ إِلَى الزَّوْجَةِ أَوْ سَمَّاهَا أَوْ وَصَفَهَا بِمَا تَتَمَيَّزُ بِهِ، أَوْ قَالَ: زَوَّجْتُكَ بِنْتِي وَلَهُ وَاحِدَةٌ لَا أَكْثَرَ صَحَّ"]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za165","title":"كِتَابُ النِّكَاحِ · فَصْلٌ (٣)","units":[{"id":"za165_1","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٣) · ١","segs":[["matn","الثَّانِي رِضَاهُمَا، إِلَّا الْبَالِغَ الْمَعْتُوهَ وَالْمَجْنُونَةَ وَالصَّغِيرَ وَالْبِكْرَ وَلَوْ مُكَلَّفَةً لَا الثَّيِّبَ؛ فَإِنَّ الْأَبَ وَوَصِيَّهُ فِي النِّكَاحِ يُزَوِّجَانِهِمْ بِغَيْرِ إِذْنِهِمْ كَالسَّيِّدِ مَعَ إِمَائِهِ وَعَبْدِهِ الصَّغِيرِ."]]},{"id":"za165_2","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٣) · ٢","segs":[["matn","وَلَا يُزَوِّجُ بَاقِي الْأَوْلِيَاءِ صَغِيرَةً دُونَ تِسْعٍ وَلَا صَغِيرًا وَلَا كَبِيرَةً عَاقِلَةً وَلَا بِنْتَ تِسْعٍ إِلَّا بِإِذْنِهِمَا، وَهُوَ صُمَاتُ الْبِكْرِ وَنُطْقُ الثَّيِّبِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za166","title":"كِتَابُ النِّكَاحِ · فَصْلٌ (٤)","units":[{"id":"za166_1","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٤) · ١","segs":[["matn","الثَّالِثُ الْوَلِيُّ، وَشُرُوطُهُ: التَّكْلِيفُ، وَالذُّكُورِيَّةُ، وَالْحُرِّيَّةُ، وَالرُّشْدُ فِي الْعَقْدِ، وَاتِّفَاقُ الدِّينِ سِوَى مَا يُذْكَرُ وَالْعَدَالَةُ، فَلَا تُزَوِّجُ امْرَأَةٌ نَفْسَهَا وَلَا غَيْرَهَا، وَيُقَدَّمُ أَبُو الْمَرْأَةِ فِي إِنْكَاحِهَا، ثُمَّ وَصِيُّهُ فِيهِ،"]]},{"id":"za166_2","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٤) · ٢","segs":[["matn","ثُمَّ جَدُّهَا لِأَبٍ وَإِنْ عَلَا ثُمَّ ابْنُهَا ثُمَّ بَنُوهُ وَإِنْ نَزَلُوا، ثُمَّ أَخُوهَا لِأَبَوَيْنِ، ثُمَّ لِأَبٍ، ثُمَّ بَنُوهُمَا كَذَلِكَ ثُمَّ عَمُّهَا لِأَبَوَيْنِ، ثُمَّ لِأَبٍ، ثُمَّ بَنُوهُمَا كَذَلِكَ، ثُمَّ أَقْرَبُ عَصَبَةِ نَسَبٍ كَالْإِرْثِ، ثُمَّ الْمَوْلَى الْمُنْعِمُ،"]]},{"id":"za166_3","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٤) · ٣","segs":[["matn","ثُمَّ أَقْرَبُ عَصَبَتِهِ نَسَبًا، ثُمَّ وَلَاءٌ، ثُمَّ السُّلْطَانُ، فَإِنْ عَضَلَ الْأَقْرَبُ، أَوْ لَمْ يَكُنْ أَهْلًا، أَوْ غَابَ غَيْبَةً مُنْقَطِعَةً لَا تُقْطَعُ إِلَّا بِكُلْفَةٍ وَمَشَقَّةٍ زَوَّجَ الْأَبْعَدُ،"]]},{"id":"za166_4","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٤) · ٤","segs":[["matn","وَإِنْ زَوَّجَ الْأَبْعَدُ أَوْ أَجْنَبِيٌّ مِنْ غَيْرِ عُذْرٍ لَمْ يَصِحَّ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za167","title":"كِتَابُ النِّكَاحِ · فَصْلٌ (٥)","units":[{"id":"za167_1","label":"كِتَابُ النِّكَاحِ · فَصْلٌ (٥) · ١","segs":[["matn","الرَّابِعُ الشَّهَادَةُ، فَلَا يَصِحُّ إِلَّا بِشَاهِدَيْنِ عَدْلَيْنِ ذَكَرَيْنِ مُكَلَّفَيْنِ سَمِيعَيْنِ نَاطِقَيْنِ وَلَيْسَتِ الْكَفَاءَةُ وَهِيَ دِينٌ وَمَنْصِبٌ وَهُوَ النَّسَبُ وَالْحُرِّيَّةُ شَرْطًا فِي صِحَّتِهِ، فَلَوْ زَوَّجَ الْأَبُ عَفِيفَةً بِفَاجِرٍ أَوْ عَرَبِيَّةً بِعَجَمِيٍّ فَلِمَنْ لَمْ يَرْضَ مِنَ الْمَرْأَةِ أَوِ الْأَوْلِيَاءِ الْفَسْخُ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za168","title":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ","units":[{"id":"za168_1","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١","segs":[["matn","تَحْرُمُ أَبَدًا الْأُمُّ وَكُلُّ جَدَّةٍ وَإِنْ عَلَتْ، وَالْبِنْتُ وَبِنْتُ الْابْنِ وَبِنْتَاهُمَا مِنْ حَلَالٍ وَحَرَامٍ وَإِنْ سَفَلَتْ، وَكُلُّ أُخْتٍ وَبِنْتُهَا وَبِنْتُ ابْنَتِهَا، وَبِنْتُ كُلِّ أَخٍ وَبِنْتُهَا وَبِنْتُ ابْنِهِ وَبِنْتُهَا وَإِنْ سَفَلَتْ، وَكُلُّ عَمَّةٍ وَخَالَةٍ وَإِنْ عَلَتَا،"]]},{"id":"za168_2","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٢","segs":[["matn","وَالْمُلَاعَنَةُ عَلَى الْمُلَاعِنِ، وَيَحْرُمُ بِالرَّضَاعِ مَا يَحْرُمُ بِالنَّسَبِ، إِلَّا أُمَّ أُخْتِهِ وَأُخْتَ ابْنِهِ، وَيَحْرُمُ بِالْعَقْدِ زَوْجَةُ أَبِيهِ وَكُلِّ جَدٍّ وَزَوْجَةُ ابْنِهِ وَإِنْ نَزَلَ دُونَ بَنَاتِهِنَّ وَأُمَّهَاتِهِنَّ، وَتَحْرُمُ أُمُّ زَوْجَتِهِ وَجَدَّاتُهَا بِالْعَقْدِ وَبِنْتُهَا وَبَنَاتُ أَوْلَادِهَا بِالدُّخُولِ،"]]},{"id":"za168_3","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٣","segs":[["matn","فَإِنْ بَانَتِ الزَّوْجَةُ أَوْ مَاتَتْ بَعْدَ الْخَلْوَةِ أُبِحْنَ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za169","title":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · فَصْلٌ","units":[{"id":"za169_1","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · فَصْلٌ · ١","segs":[["matn","وَتَحْرُمُ إِلَى أَمَدٍ أُخْتُ مُعْتَدَّتِهِ وَأُخْتُ زَوْجَتِهِ وَبِنْتَاهُمَا وَعَمَّتَاهُمَا وَخَالَتَاهُمَا، فَإِنْ طُلِّقَتْ وَفَرَغَتِ الْعِدَّةُ أُبِحْنَ، فَإِنْ تَزَوَّجَهُمَا فِي عَقْدٍ أَوْ عَقْدَيْنِ مَعًا بَطَلَا،"]]},{"id":"za169_2","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · فَصْلٌ · ٢","segs":[["matn","فَإِنْ تَأَخَّرَ أَحَدُهُمَا أَوْ وَقَعَ فِي عِدَّةِ الْأُخْرَى وَهِيَ بَائِنٌ أَوْ رَجْعِيَّةٌ بَطَلَ،"]]},{"id":"za169_3","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · فَصْلٌ · ٣","segs":[["matn","وَتَحْرُمُ الْمُعْتَدَّةُ وَالْمُسْتَبْرَأَةُ مِنْ غَيْرِهِ وَالزَّانِيَةُ حَتَّى تَتُوبَ وَتَنْقَضِيَ عِدَّتُهَا وَمُطَلَّقَتُهُ ثَلَاثًا حَتَّى يَطَأَهَا زَوْجٌ غَيْرُهُ وَالْمُحْرِمَةُ حَتَّى تَحِلَّ وَلَا يَنْكِحُ كَافِرٌ مُسْلِمَةً وَلَا مُسْلِمٌ وَلَوْ عَبْدًا كَافِرَةً إِلَّا حُرَّةً كِتَابِيَّةً،"]]},{"id":"za169_4","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · فَصْلٌ · ٤","segs":[["matn","وَلَا يَنْكِحُ حُرٌّ مُسْلِمٌ أَمَةً مُسْلِمَةً إِلَّا أَنْ يَخَافَ عَنَتَ الْعُزُوبَةِ لِحَاجَةِ الْمُتْعَةِ أَوِ الْخِدْمَةِ وَيَعْجَزُ عَنْ طَوْلِ حُرَّةٍ أَوْ ثَمَنِ أَمَةٍ، وَلَا يَنْكِحُ عَبْدٌ سَيِّدَتَهُ وَلَا سَيِّدٌ أَمَتَهُ،"]]},{"id":"za169_5","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · فَصْلٌ · ٥","segs":[["matn","وَلِلْحُرِّ نِكَاحُ أَمَةِ أَبِيهِ دُونَ أَمَةِ ابْنِهِ، وَلَيْسَ لِلْحُرَّةِ نِكَاحُ عَبْدِ وَلَدِهَا، وَإِنِ اشْتَرَى أَحَدُ الزَّوْجَيْنِ أَوْ وَلَدُهُ الْحُرُّ أَوْ مُكَاتَبُهُ الزَّوْجَ الْآخَرَ أَوْ بَعْضَهُ انْفَسَخَ نِكَاحُهُمَا،"]]},{"id":"za169_6","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · فَصْلٌ · ٦","segs":[["matn","وَمَنْ حَرُمَ وَطْؤُهَا بِعَقْدٍ حَرُمَ بِمِلْكِ يَمِينٍ إِلَّا أَمَةً كِتَابِيَّةً، وَمَنْ جَمَعَ بَيْنَ مُحَلَّلَةٍ وَمُحَرَّمَةٍ فِي عَقْدٍ صَحَّ فِيمَنْ تَحِلُّ، وَلَا يَصِحُّ نِكَاحُ خُنْثَى مُشْكِلٍ قَبْلَ تَبَيُّنِ أَمْرِهِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za170","title":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ","units":[{"id":"za170_1","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · ١","segs":[["matn","إِذَا شَرَطَتْ طَلَاقَ ضَرَّتِهَا، أَوْ أَنْ لَا يَتَسَرَّى، أَوْ أَنْ لَا يَتَزَوَّجَ عَلَيْهَا، أَوْ لَا يُخْرِجَهَا مِنْ دَارِهَا أَوْ بَلَدِهَا، أَوْ شَرَطَتْ نَقْدًا مُعَيَّنًا، أَوْ زِيَادَةً فِي مَهْرِهَا صَحَّ."]]},{"id":"za170_2","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · ٢","segs":[["matn","فَإِنْ خَالَفَهُ فَلَهَا الْفَسْخُ، وَإِذَا زَوَّجَهُ وَلِيَّتَهُ عَلَى أَنْ يُزَوِّجَهُ الْآخَرُ وَلِيَّتَهُ فَفَعَلَا وَلَا مَهْرَ بَطَلَ النِّكَاحَانِ، فَإِنْ سُمِّيَ لَهُمَا مَهْرٌ صَحَّ، وَإِنْ تَزَوَّجَهَا بِشَرْطِ أَنَّهُ مَتَى حَلَّلَهَا لِلْأَوَّلِ طَلَّقَهَا، أَوْ نَوَاهُ بِلَا شَرْطٍ،"]]},{"id":"za170_3","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · ٣","segs":[["matn","أَوْ قَالَ: زَوَّجْتُكَ إِذَا جَاءَ رَأْسُ الشَّهْرِ، أَوْ إِنْ رَضِيَتْ أُمُّهَا، أَوْ إِذَا جَاءَ غَدٌ فَطَلِّقْهَا، أَوْ وَقَّتَهُ بِمُدَّةٍ بَطَلَ الْكُلُّ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za171","title":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ","units":[{"id":"za171_1","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ · ١","segs":[["matn","وَإِنْ شَرَطَ أَنْ لَا مَهْرَ لَهَا، أَوْ لَا نَفَقَةَ، أَوْ أَنْ يَقْسِمَ لَهَا أَقَلَّ مِنْ ضَرَّتِهَا أَوْ أَكْثَرَ، أَوْ شَرَطَ فِيهِ خِيَارًا،"]]},{"id":"za171_2","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ · ٢","segs":[["matn","أَوْ إِنْ جَاءَ بِالْمَهْرِ فِي وَقْتِ كَذَا وَإِلَّا فَلَا نِكَاحَ بَيْنَهُمَا بَطَلَ الشَّرْطُ وَصَحَّ النِّكَاحُ، وَإِنْ شَرَطَهَا مُسْلِمَةً فَبَانَتْ كِتَابِيَّةً، أَوْ شَرَطَهَا بِكْرًا أَوْ جَمِيلَةً أَوْ نَسِيبَةً،"]]},{"id":"za171_3","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ · ٣","segs":[["matn","أَوْ نَفْيَ عَيْبٍ لَا يَنْفَسِخُ بِهِ النِّكَاحُ فَبَانَتْ بِخِلَافِهِ فَلَهُ الْفَسْخُ، وَإِنْ عَتَقَتْ تَحْتَ حُرٍّ فَلَا خِيَارَ لَهَا بَلْ تَحْتَ عَبْدٍ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za172","title":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٢)","units":[{"id":"za172_1","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٢) · ١","segs":[["matn","وَمَنْ وَجَدَتْ زَوْجَهَا مَجْبُوبًا أَوْ بَقِيَ لَهُ مَا لَا يَطَأُ بِهِ فَلَهَا الْفَسْخُ، وَإِنْ ثَبَتَتْ عُنَّتُهُ بِإِقْرَارِهِ أَوْ بِبَيِّنَةٍ عَلَى إِقْرَارِهِ أُجِّلَ سَنَةً مُنْذُ تَحَاكُمِهُ فَإِنْ وَطِئَ فِيهَا وَإِلَّا فَلَهَا الْفَسْخُ،"]]},{"id":"za172_2","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَإِنِ اعْتَرَفَتْ أَنَّهُ وَطِئَهَا فَلَيْسَ بِعِنِّينٍ، وَلَوْ قَالَتْ فِي وَقْتٍ: رَضِيتُ بِهِ عِنِّينًا سَقَطَ خِيَارُهَا أَبَدًا."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za173","title":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٣)","units":[{"id":"za173_1","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٣) · ١","segs":[["matn","وَالرَّتَقُ وَالْقَرَنُ وَالْعَفَلُ وَالْفَتْقُ وَاسْتِطْلَاقُ بَوْلٍ وَنَجْوٍ وَقُرُوحٌ سَيَّالَةٌ فِي فَرْجٍ وَبَاسُورٌ وَنَاصُورٌ وَخِصَاءٌ وَسَلٌّ وَوِجَاءٌ وَكَوْنُ أَحَدِهِمَا خُنْثَى وَاضِحًا وَجُنُونٌ وَلَوْ سَاعَةً وَبَرَصٌ وَجُذَامٌ يُثْبِتُ لِكُلِّ وَاحِدٍ مِنْهُمَا الْفَسْخَ،"]]},{"id":"za173_2","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٣) · ٢","segs":[["matn","وَلَوْ حَدَثَ بَعْدَ الْعَقْدِ أَوْ كَانَ بِالْآخَرِ عَيْبٌ مِثْلُهُ، وَمَنْ رَضِيَ بِالْعَيْبِ أَوْ وُجِدَتْ مِنْهُ دَلَالَتُهُ مَعَ عِلْمِهِ فَلَا خِيَارَ لَهُ، وَلَا يَتِمُّ فَسْخُ أَحَدِهِمَا إِلَّا بِحَاكِمٍ، فَإِنْ كَانَ قَبْلَ الدُّخُولِ فَلَا مَهْرَ،"]]},{"id":"za173_3","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٣) · ٣","segs":[["matn","وَبَعْدَهُ لَهَا الْمُسَمَّى، وَيَرْجِعُ بِهِ عَلَى الْغَارِّ إِنْ وُجِدَ، وَالصَّغِيرَةُ وَالْمَجْنُونَةُ وَالْأَمَةُ لَا تُزَوَّجُ وَاحِدَةٌ مِنْهُنَّ بِمَعِيبٍ، فَإِنْ رَضِيَتِ الْكَبِيرَةُ مَجْبُوبًا أَوْ عِنِّينًا لَمْ تُمْنَعْ، بَلْ مِنْ مَجْنُونٍ وَمَجْذُومٍ وَأَبْرَصَ،"]]},{"id":"za173_4","label":"بَابُ الشُّرُوطِ وَالْعُيُوبِ فِي النِّكَاحِ · فَصْلٌ (٣) · ٤","segs":[["matn","وَمَتَى عَلِمَتِ الْعَيْبَ أَوْ حَدَثَ بِهِ لَمْ يُجْبِرْهَا وَلِيُّهَا عَلَى الْفَسْخِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za174","title":"بَابُ نِكَاحِ الْكُفَّارِ","units":[{"id":"za174_1","label":"بَابُ نِكَاحِ الْكُفَّارِ · ١","segs":[["matn","حُكْمُهُ كَنِكَاحِ الْمُسْلِمِينَ، وَيُقَرُّونَ عَلَى فَاسِدِهِ إِذَا اعْتَقَدُوا صِحَّتَهُ فِي شَرْعِهِمْ وَلَمْ يَرْتَفِعُوا إِلَيْنَا، فَإِنْ أَتَوْنَا قَبْلَ عَقْدِهِ عَقَدْنَاهُ عَلَى حُكْمِنَا، وَإِنْ أَتَوْنَا بَعْدَهُ أَوْ أَسْلَمَ الزَّوْجَانِ وَالْمَرْأَةُ تُبَاحُ إِذًا أُقِرَّا،"]]},{"id":"za174_2","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٢","segs":[["matn","وَإِنْ كَانَتْ مِمَّنْ لَا يَجُوزُ ابْتِدَاءُ نِكَاحِهَا فُرِّقَ بَيْنَهُمَا، وَإِنْ وَطِئَ حَرْبِيٌّ حَرْبِيَّةً فَأَسْلَمَا وَقَدِ اعْتَقَدَاهُ نِكَاحًا أُقِرَّا وَإِلَّا فُسِخَ، وَمَتَى كَانَ الْمَهْرُ صَحِيحًا أَخَذَتْهُ وَإِنْ كَانَ فَاسِدًا وَقَبَضَتْهُ اسْتَقَرَّ،"]]},{"id":"za174_3","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٣","segs":[["matn","وَإِنْ لَمْ تَقْبِضْهُ وَلَمْ يُسَمَّ فُرِضَ لَهَا مَهْرُ الْمِثْلِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za175","title":"بَابُ نِكَاحِ الْكُفَّارِ · فَصْلٌ","units":[{"id":"za175_1","label":"بَابُ نِكَاحِ الْكُفَّارِ · فَصْلٌ · ١","segs":[["matn","وَإِنْ أَسْلَمَ الزَّوْجَانِ مَعًا أَوْ زَوْجُ كِتَابِيَّةٍ فَعَلَى نِكَاحِهِمَا، فَإِنْ أَسْلَمَتْ هِيَ أَوْ أَحَدُ الزَّوْجَيْنِ غَيْرَ الْكِتَابِيَّيْنِ قَبْلَ الدُّخُولِ بَطَلَ، فَإِنْ سَبَقَتْهُ فَلَا مَهْرَ، وَإِنْ سَبَقَهَا فَلَهَا نِصْفُهُ،"]]},{"id":"za175_2","label":"بَابُ نِكَاحِ الْكُفَّارِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ أَسْلَمَ أَحَدُهُمَا بَعْدَ الدُّخُولِ وُقِفَ الْأَمْرُ عَلَى انْقِضَاءِ الْعِدَّةِ، فَإِنْ أَسْلَمَ الْآخَرُ فِيهَا دَامَ النِّكَاحُ وَإِلَّا بَانَ فَسْخُهُ مُنْذُ أَسْلَمَ الْأَوَّلُ، وَإِنْ كَفَرَا أَوْ أَحَدُهُمَا بَعْدَ الدُّخُولِ وُقِفَ الْأَمْرُ عَلَى انْقِضَاءِ الْعِدَّةِ، وَقَبْلَهُ بَطَلَ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za176","title":"بَابُ الصَّدَاقِ","units":[{"id":"za176_1","label":"بَابُ الصَّدَاقِ · ١","segs":[["matn","يُسَنُّ تَخْفِيفُهُ، وَتَسْمِيَتُهُ فِي الْعَقْدِ مِنْ أَرْبَعِمِائَةِ دِرْهَمٍ إِلَى خَمْسِمِائَةٍ، وَكُلُّ مَا صَحَّ ثَمَنًا أَوْ أُجْرَةً صَحَّ مَهْرًا وَإِنْ قَلَّ، وَإِنْ أَصْدَقَهَا تَعْلِيمَ قُرْآنٍ لَمْ يَصِحَّ، بَلْ فِقْهٍ وَأَدَبٍ وَشِعْرٍ مُبَاحٍ مَعْلُومٍ،"]]},{"id":"za176_2","label":"بَابُ الصَّدَاقِ · ٢","segs":[["matn","وَإِنْ أَصْدَقَهَا طَلَاقَ ضَرَّتِهَا لَمْ يَصِحَّ وَلَهَا مَهْرُ مِثْلِهَا، وَمَتَى بَطَلَ الْمُسَمَّى وَجَبَ مَهْرُ الْمِثْلِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za177","title":"بَابُ الصَّدَاقِ · فَصْلٌ","units":[{"id":"za177_1","label":"بَابُ الصَّدَاقِ · فَصْلٌ · ١","segs":[["matn","وَإِنْ أَصْدَقَهَا أَلْفًا إِنْ كَانَ أَبُوهَا حَيًّا وَأَلْفَيْنِ إِنْ كَانَ مَيِّتًا وَجَبَ مَهْرُ الْمِثْلِ، وَعَلَى إِنْ كَانَتْ لِي زَوْجَةٌ بِأَلْفَيْنِ أَوْ لَمْ تَكُنْ بِأَلْفٍ يَصِحُّ بِالْمُسَمَّى، وَإِذَا أُجِّلَ الصَّدَاقُ أَوْ بَعْضُهُ صَحَّ،"]]},{"id":"za177_2","label":"بَابُ الصَّدَاقِ · فَصْلٌ · ٢","segs":[["matn","فَإِنْ عَيَّنَ أَجَلًا وَإِلَّا فَمَحِلُّهُ الْفُرْقَةُ، وَإِنْ أَصْدَقَهَا مَالًا مَغْصُوبًا أَوْ خِنْزِيرًا وَنَحْوَهُ وَجَبَ مَهْرُ الْمِثْلِ، وَإِنْ وَجَدَتِ الْمُبَاحَ مَعِيبًا خُيِّرَتْ بَيْنَ أَرْشِهِ وَقِيمَتِهِ، وَإِنْ تَزَوَّجَهَا عَلَى أَلْفٍ لَهَا وَأَلْفٍ لِأَبِيهَا صَحَّتِ التَّسْمِيَةُ،"]]},{"id":"za177_3","label":"بَابُ الصَّدَاقِ · فَصْلٌ · ٣","segs":[["matn","فَلَوْ طَلَّقَ قَبْلَ الدُّخُولِ وَبَعْدَ الْقَبْضِ رَجَعَ بِالْأَلْفِ وَلَا شَيْءَ عَلَى الْأَبِ لَهُمَا، وَلَوْ شُرِطَ ذَلِكَ لِغَيْرِ الْأَبِ فَكُلُّ الْمُسَمَّى لَهَا، وَمَنْ زَوَّجَ بِنْتَهُ وَلَوْ ثَيِّبًا بِدُونِ مَهْرِ مِثْلِهَا صَحَّ،"]]},{"id":"za177_4","label":"بَابُ الصَّدَاقِ · فَصْلٌ · ٤","segs":[["matn","وَإِنْ زَوَّجَهَا بِهِ وَلِيٌّ غَيْرُهُ بِإِذْنِهَا صَحَّ، وَإِنْ لَمْ تَأْذَنْ فَمَهْرُ الْمِثْلِ، وَإِنْ زَوَّجَ ابْنَهُ الصَّغِيرَ بِمَهْرِ الْمِثْلِ أَوْ أَكْثَرَ صَحَّ فِي ذِمَّةِ الزَّوْجِ، وَإِنْ كَانَ مُعْسِرًا لَمْ يَضْمَنْهُ الْأَبُ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za178","title":"بَابُ الصَّدَاقِ · فَصْلٌ (٢)","units":[{"id":"za178_1","label":"بَابُ الصَّدَاقِ · فَصْلٌ (٢) · ١","segs":[["matn","وَتَمْلِكُ الْمَرْأَةُ صَدَاقَهَا بِالْعَقْدِ، وَلَهَا نَمَاءُ الْمُعَيَّنِ قَبْلَ الْقَبْضِ وَضِدُّهُ بِضِدِّهِ، وَإِنْ تَلِفَ فَمِنْ ضَمَانِهَا إِلَّا أَنْ يَمْنَعَهَا زَوْجُهَا قَبْضَهُ فَيَضْمَنُهُ، وَلَهَا التَّصَرُّفُ فِيهِ وَعَلَيْهَا زَكَاتُهُ،"]]},{"id":"za178_2","label":"بَابُ الصَّدَاقِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَإِنْ طَلَّقَ قَبْلَ الدُّخُولِ أَوِ الْخَلْوَةِ فَلَهُ نِصْفُهُ حُكْمًا دُونَ نَمَائِهِ الْمُنْفَصِلِ، وَفِي الْمُتَّصِلِ لَهُ نِصْفُ قِيمَتِهِ بِدُونِ نَمَائِهِ، وَإِنِ اخْتَلَفَ الزَّوْجَانِ أَوْ وَرَثَتُهُمَا فِي قَدْرِ الصَّدَاقِ أَوْ عَيْنِهِ أَوْ فِيمَا يَسْتَقِرُّ بِهِ فَقَوْلُهُ، وَفِي قَبْضِهِ فَقَوْلُهَا."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za179","title":"بَابُ الصَّدَاقِ · فَصْلٌ (٣)","units":[{"id":"za179_1","label":"بَابُ الصَّدَاقِ · فَصْلٌ (٣) · ١","segs":[["matn","يَصِحُّ تَفْوِيضُ الْبُضْعِ بِأَنْ يُزَوِّجَ الرَّجُلُ ابْنَتَهُ الْمُجْبَرَةَ، أَوْ تَأْذَنَ الْمَرْأَةُ لِوَلِيِّهَا أَنْ يُزَوِّجَهَا بِلَا مَهْرٍ، وَتَفْوِيضُ الْمَهْرِ بِأَنْ يُزَوِّجَهَا عَلَى مَا يَشَاءُ أَحَدُهُمَا أَوْ أَجْنَبِيٌّ، فَلَهَا مَهْرُ الْمِثْلِ بِالْعَقْدِ وَيَفْرِضُهُ الْحَاكِمُ بِقَدْرِهِ،"]]},{"id":"za179_2","label":"بَابُ الصَّدَاقِ · فَصْلٌ (٣) · ٢","segs":[["matn","وَمَنْ مَاتَ مِنْهُمَا قَبْلَ الْإِصَابَةِ وَالْفَرْضِ وَرِثَهُ الْآخَرُ وَلَهَا مَهْرُ نِسَائِهَا، وَإِنْ طَلَّقَهَا قَبْلَ الدُّخُولِ فَلَهَا الْمُتْعَةُ بِقَدْرِ يُسْرِ زَوْجِهَا وَعُسْرِهِ، وَيَسْتَقِرُّ مَهْرُ الْمِثْلِ بِالدُّخُولِ، وَإِنْ طَلَّقَهَا بَعْدَهُ فَلَا مُتْعَةَ،"]]},{"id":"za179_3","label":"بَابُ الصَّدَاقِ · فَصْلٌ (٣) · ٣","segs":[["matn","وَإِذَا افْتَرَقَا فِي الْفَاسِدِ قَبْلَ الدُّخُولِ وَالْخَلْوَةِ فَلَا مَهْرَ، وَبَعْدَ أَحَدِهِمَا يَجِبُ الْمُسَمَّى، وَيَجِبُ مَهْرُ الْمِثْلِ لِمَنْ وُطِئَتْ بِشُبْهَةٍ أَوْ زِنًا كُرْهًا، وَلَا يَجِبُ مَعَهُ أَرْشُ بَكَارَةٍ، وَلِلْمَرْأَةِ مَنْعُ نَفْسِهَا حَتَّى تَقْبِضَ صَدَاقَهَا الْحَالَّ،"]]},{"id":"za179_4","label":"بَابُ الصَّدَاقِ · فَصْلٌ (٣) · ٤","segs":[["matn","فَإِنْ كَانَ مُؤَجَّلًا أَوْ حَلَّ قَبْلَ التَّسْلِيمِ أَوْ سَلَّمَتْ نَفْسَهَا تَبَرُّعًا فَلَيْسَ لَهَا مَنْعُهَا، فَإِنْ أَعْسَرَ بِالْمَهْرِ الْحَالِّ فَلَهَا الْفَسْخُ وَلَوْ بَعْدَ الدُّخُولِ، وَلَا يَفْسَخُهُ إِلَّا حَاكِمٌ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za180","title":"بَابُ وَلِيمَةِ الْعُرْسِ","units":[{"id":"za180_1","label":"بَابُ وَلِيمَةِ الْعُرْسِ · ١","segs":[["matn","تُسَنُّ بِشَاةٍ فَأَقَلَّ، وَتَجِبُ فِي أَوَّلِ مَرَّةٍ إِجَابَةُ مُسْلِمٍ يَحْرُمُ هَجْرُهُ إِلَيْهَا إِنْ عَيَّنَهُ، وَلَمْ يَكُنْ ثَمَّ مُنْكَرٌ، فَإِنْ دَعَا الْجَفَلَى أَوْ فِي الْيَوْمِ الثَّالِثِ أَوْ دَعَاهُ ذِمِّيٌّ كُرِهَتِ الْإِجَابَةُ، وَمَنْ صَوْمُهُ وَاجِبٌ دَعَا وَانْصَرَفَ،"]]},{"id":"za180_2","label":"بَابُ وَلِيمَةِ الْعُرْسِ · ٢","segs":[["matn","وَالْمُتَنَفِّلُ يُفْطِرُ إِنْ جَبَرَ وَلَا يَجِبُ الْأَكْلُ، وَإِبَاحَتُهُ مُتَوَقِّفَةٌ عَلَى صَرِيحِ إِذْنٍ أَوْ قَرِينَةٍ، وَإِنْ عَلِمَ أَنَّ ثَمَّ مُنْكَرًا يَقْدِرُ عَلَى تَغْيِيرِهِ حَضَرَ وَغَيَّرُهُ، وَإِلَّا أَبَى، وَإِنْ حَضَرَ ثُمَّ عَلِمَ بِهِ أَزَالَهُ،"]]},{"id":"za180_3","label":"بَابُ وَلِيمَةِ الْعُرْسِ · ٣","segs":[["matn","فَإِنْ دَامَ لِعَجْزِهِ عَنْهُ انْصَرَفَ، وَإِنْ عَلِمَ بِهِ وَلَمْ يَرَهُ وَلَمْ يَسْمَعْهُ خُيِّرَ، وَكُرِهَ النِّثَارُ وَالْتِقَاطُهُ، وَمَنْ أَخَذَهُ أَوْ وَقَعَ فِي حِجْرِهِ فَلَهُ، وَيُسَنُّ إِعْلَانُ النِّكَاحِ وَالدُّفُّ فِيهِ لِلنِّسَاءِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za181","title":"بَابُ عِشْرَةِ النِّسَاءِ","units":[{"id":"za181_1","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١","segs":[["matn","يَلْزَمُ الزَّوْجَيْنِ الْعِشْرَةُ بِالْمَعْرُوفِ، وَيَحْرُمُ مَطْلُ كُلِّ وَاحِدٍ بِمَا يَلْزَمُهُ لِلْآخَرِ وَالتَّكَرُّهُ لِبَذْلِهِ، وَإِذَا تَمَّ الْعَقْدُ لَزِمَ تَسْلِيمُ الْحُرَّةِ الَّتِي يُوْطَأُ مِثْلُهَا فِي بَيْتِ الزَّوْجِ إِنْ طَلَبَهُ وَلَمْ تَشْتَرِطْ دَارَهَا أَوْ بَلَدَهَا،"]]},{"id":"za181_2","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٢","segs":[["matn","وَإِذَا اسْتَمْهَلَ أَحَدُهُمَا أُمْهِلَ الْعَادَةَ وُجُوبًا، لَا لِعَمَلِ جِهَازٍ، وَيَجِبُ تَسْلِيمُ الْأَمَةِ لَيْلًا فَقَطْ، وَيُبَاشِرُهَا مَا لَمْ يَضُرَّ أَوْ يَشْغَلْهَا عَنْ فَرْضٍ، وَلَهُ السَّفَرُ بِالْحُرَّةِ مَا لَمْ تَشْتَرِطْ ضِدَّهُ، وَيَحْرُمُ وَطْؤُهَا فِي الْحَيْضِ وَالدُّبُرِ،"]]},{"id":"za181_3","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٣","segs":[["matn","وَلَهُ إِجْبَارُهَا عَلَى غُسْلِ حَيْضٍ وَنَجَاسَةٍ، وَأَخْذِ مَا تَعَافُهُ النَّفْسُ مِنْ شَعْرٍ وَغَيْرِهِ وَلَا تُجْبَرُ الذِّمِّيَّةُ عَلَى غُسْلِ الْجَنَابَةِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za182","title":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ","units":[{"id":"za182_1","label":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ · ١","segs":[["matn","وَيَلْزَمُهُ أَنْ يَبِيتَ عِنْدَ الْحُرَّةِ لَيْلَةً مِنْ أَرْبَعٍ، وَيَنْفَرِدُ إِنْ أَرَادَ فِي الْبَاقِي، وَيَلْزَمُهُ الْوَطْءُ إِنْ قَدِرَ كُلَّ ثُلُثِ سَنَةٍ مَرَّةً، وَإِنْ سَافَرَ فَوْقَ نِصْفِهَا وَطَلَبَتْ قُدُومَهُ وَقَدِرَ لَزِمَهُ، فَإِنْ أَبَى أَحَدَهُمَا فُرِّقَ بَيْنَهُمَا بِطَلَبِهَا،"]]},{"id":"za182_2","label":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ · ٢","segs":[["matn","وَتُسَنُّ التَّسْمِيَةُ عِنْدَ الْوَطْءِ وَقَوْلُ الْوَارِدِ، وَيُكْرَهُ كَثْرَةُ الْكَلَامِ، وَالنَّزْعُ قَبْلَ فَرَاغِهَا، وَالْوَطْءُ بِمَرْأَى أَحَدٍ، وَالتَّحَدُّثُ بِهِ وَيَحْرُمُ جَمْعُ زَوْجَتَيْهِ فِي مَسْكَنٍ وَاحِدٍ بِغَيْرِ رِضَاهُمَا، وَلَهُ مَنْعُهَا مِنَ الْخُرُوجِ مِنْ مَنْزِلِهِ،"]]},{"id":"za182_3","label":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ · ٣","segs":[["matn","وَيُسْتَحَبُّ إِذْنُهُ أَنْ تُمَرِّضَ مَحْرَمَهَا وَتَشْهَدَ جَنَازَتَهُ، وَلَهُ مَنْعُهَا مِنْ إِجَارَةِ نَفْسِهَا وَمِنْ إِرْضَاعِ وَلَدِهَا مِنْ غَيْرِهِ إِلَّا لِضَرُورَتِهِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za183","title":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ (٢)","units":[{"id":"za183_1","label":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ (٢) · ١","segs":[["matn","وَعَلَيْهِ أَنْ يُسَاوِيَ بَيْنَ زَوْجَاتِهِ فِي الْقَسْمِ وَعِمَادُهُ اللَّيْلُ لِمَنْ مَعَاشُهُ النَّهَارُ وَالْعَكْسُ بِالْعَكْسِ، وَيَقْسِمُ لِحَائِضٍ وَنُفَسَاءَ وَمَرِيضَةٍ وَمَعِيبَةٍ وَمَجْنُونَةٍ مَأْمُونَةٍ وَغَيْرِهَا،"]]},{"id":"za183_2","label":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَإِنْ سَافَرَتْ بِلَا إِذْنِهِ أَوْ بِإِذْنِهِ فِي حَاجَتِهَا أَوْ أَبَتْ السَّفَرَ مَعَهُ أَوْ الْمَبِيتَ عِنْدَهُ فِي فِرَاشِهِ فَلَا قَسْمَ لَهَا وَلَا نَفَقَةَ، وَمَنْ وَهَبَتْ قَسْمَهَا لِضَرَّتِهَا بِإِذْنِهِ أَوْ لَهُ فَجَعَلَهُ لِأُخْرَى،"]]},{"id":"za183_3","label":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ (٢) · ٣","segs":[["matn","جَازَ فَإِنْ رَجَعَتْ قَسَمَ لَهَا مُسْتَقْبَلًا، وَلَا قَسْمَ لِإِمَائِهِ وَأُمَّهَاتِ أَوْلَادِهِ، بَلْ يَطَأُ مَنْ شَاءَ مَتَى شَاءَ، وَإِنْ تَزَوَّجَ بِكْرًا أَقَامَ عِنْدَهَا سَبْعًا ثُمَّ دَارَ، وَثَيِّبًا ثَلَاثًا، وَإِنْ أَحَبَّتْ سَبْعًا فَعَلَ وَقَضَى مِثْلَهُنَّ لِلْبَوَاقِي."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za184","title":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ (٣)","units":[{"id":"za184_1","label":"بَابُ عِشْرَةِ النِّسَاءِ · فَصْلٌ (٣) · ١","segs":[["matn","النُّشُوزُ مَعْصِيَتُهَا إِيَّاهُ فِيمَا يَجِبُ عَلَيْهَا، فَإِذَا ظَهَرَ مِنْهَا أَمَارَاتُهُ بِأَنْ لَا تُجِيبَهُ إِلَى الِاسْتِمْتَاعِ أَوْ تُجِيبَهُ مُتَبَرِّمَةً أَوْ مُتَكَرِّهَةً وَعَظَهَا، فَإِنْ أَصَرَّتْ هَجَرَهَا فِي الْمَضْجَعِ مَا شَاءَ وَفِي الْكَلَامِ ثَلَاثَةَ أَيَّامٍ، فَإِنْ أَصَرَّتْ ضَرَبَهَا غَيْرَ مُبَرِّحٍ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za185","title":"بَابُ الْخُلْعِ","units":[{"id":"za185_1","label":"بَابُ الْخُلْعِ · ١","segs":[["matn","مَنْ صَحَّ تَبَرُّعُهُ مِنْ زَوْجَةٍ وَأَجْنَبِيٍّ صَحَّ بَذْلُهُ لِعِوَضِهِ، فَإِذَا كَرِهَتْ خُلُقَ زَوْجِهَا أَوْ خَلْقَهُ أَوْ نَقْصَ دِينِهِ أَوْ خَافَتْ إِثْمًا بِتَرْكِ حَقِّهِ أُبِيحَ الْخُلْعُ وَإِلَّا كُرِهَ وَوَقَعَ، فَإِنْ عَضَلَهَا ظُلْمًا لِلِافْتِدَاءِ،"]]},{"id":"za185_2","label":"بَابُ الْخُلْعِ · ٢","segs":[["matn","وَلَمْ يَكُنْ لِزِنَاهَا أَوْ نُشُوزِهَا أَوْ تَرْكِهَا فَرْضًا فَفَعَلَتْ، أَوْ خَالَعَتْ الصَّغِيرَةُ وَالْمَجْنُونَةُ وَالسَّفِيهَةُ، أَوْ الْأَمَةُ بِغَيْرِ إِذْنِ سَيِّدِهَا لَمْ يَصِحَّ الْخُلْعُ وَوَقَعَ الطَّلَاقُ رَجْعِيًّا إِنْ كَانَ بِلَفْظِ الطَّلَاقِ أَوْ نِيَّتِهِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za186","title":"بَابُ الْخُلْعِ · فَصْلٌ","units":[{"id":"za186_1","label":"بَابُ الْخُلْعِ · فَصْلٌ · ١","segs":[["matn","وَالْخُلْعُ بِلَفْظِ صَرِيحِ الطَّلَاقِ أَوْ كِنَايَتِهِ وَقَصْدِهِ طَلَاقٌ بَائِنٌ، وَإِنْ وَقَعَ بِلَفْظِ الْخُلْعِ أَوِ الْفَسْخِ أَوِ الْفِدَاءِ، وَلَمْ يَنْوِهِ طَلَاقًا كَانَ فَسْخًا لَا يَنْقُصُ عَدَدَ الطَّلَاقِ،"]]},{"id":"za186_2","label":"بَابُ الْخُلْعِ · فَصْلٌ · ٢","segs":[["matn","وَلَا يَقَعُ بِمُعْتَدَّةٍ مِنْ خُلْعٍ طَلَاقٌ وَلَوْ وَاجَهَهَا بِهِ وَلَا يَصِحُّ شَرْطُ الرَّجْعَةِ فِيهِ، وَإِنْ خَالَعَهَا بِغَيْرِ عِوَضٍ أَوْ بِمُحَرَّمٍ لَمْ يَصِحَّ، وَيَقَعُ الطَّلَاقُ رَجْعِيًّا إِنْ كَانَ بِلَفْظِ الطَّلَاقِ أَوْ نِيَّتِهِ،"]]},{"id":"za186_3","label":"بَابُ الْخُلْعِ · فَصْلٌ · ٣","segs":[["matn","وَمَا صَحَّ مَهْرًا صَحَّ الْخُلْعُ بِهِ، وَيُكْرَهُ بِأَكْثَرَ مِمَّا أَعْطَاهَا، وَإِنْ خَالَعَتْ حَامِلٌ بِنَفَقَةِ عِدَّتِهَا صَحَّ وَيَصِحُّ بِالْمَجْهُولِ،"]]},{"id":"za186_4","label":"بَابُ الْخُلْعِ · فَصْلٌ · ٤","segs":[["matn","فَإِنْ خَالَعَتْهُ عَلَى حَمْلِ شَجَرَتِهَا أَوْ أَمَتِهَا أَوْ مَا فِي يَدِهَا أَوْ بَيْتِهَا مِنْ دَرَاهِمَ أَوْ مَتَاعٍ أَوْ عَلَى عَبْدٍ صَحَّ، وَلَهُ مَعَ عَدَمِ الْحَمْلِ وَالْمَتَاعِ وَالْعَبْدِ أَقَلُّ مُسَمَّاهُ، وَمَعَ عَدَمِ الدَّرَاهِمِ ثَلَاثَةٌ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za187","title":"بَابُ الْخُلْعِ · فَصْلٌ (٢)","units":[{"id":"za187_1","label":"بَابُ الْخُلْعِ · فَصْلٌ (٢) · ١","segs":[["matn","وَإِذَا قَالَ: مَتَى أَوْ إِذَا أَوْ إِنْ أَعْطَيْتِنِي أَلْفًا فَأَنْتِ طَالِقٌ طَلُقَتْ بِعَطِيَّتِهِ وَإِنْ تَرَاخَى، وَإِنْ قَالَتْ: اخْلَعْنِي عَلَى أَلْفٍ أَوْ بِأَلْفٍ أَوْ وَلَكَ أَلْفٌ فَفَعَلَ بَانَتْ وَاسْتَحَقَّهَا، وَطَلِّقْنِي وَاحِدَةً بِأَلْفٍ فَطَلَّقَهَا ثَلَاثًا اسْتَحَقَّهَا،"]]},{"id":"za187_2","label":"بَابُ الْخُلْعِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَعَكْسُهُ بِعَكْسِهِ، إِلَّا فِي وَاحِدَةٍ بَقِيَتْ، وَلَيْسَ لِلْأَبِ خَلْعُ زَوْجَةِ ابْنِهِ الصَّغِيرِ وَلَا طَلَاقُهَا وَلَا خُلْعُ ابْنَتِهِ بِشَيْءٍ مِنْ مَالِهَا، وَلَا يُسْقِطُ الْخُلْعُ غَيْرَهُ مِنَ الْحُقُوقِ،"]]},{"id":"za187_3","label":"بَابُ الْخُلْعِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَإِنْ عَلَّقَ طَلَاقَهَا بِصِفَةٍ ثُمَّ أَبَانَهَا فَوُجِدَتْ ثُمَّ نَكَحَهَا فَوُجِدَتْ بَعْدَهُ طَلُقَتْ كَعِتْقٍ وَإِلَّا فَلَا."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"za188","title":"كِتَابُ الطَّلَاقِ","units":[{"id":"za188_1","label":"كِتَابُ الطَّلَاقِ · ١","segs":[["matn","يُبَاحُ لِلْحَاجَةِ، وَيُكْرَهُ لِعَدَمِهَا، وَيُسْتَحَبُّ لِلضَّرَرِ، وَيَجِبُ لِلْإِيلَاءِ، وَيَحْرُمُ لِلْبِدْعَةِ، وَيَصِحُّ مِنْ زَوْجٍ مُكَلَّفٍ وَمُمَيِّزٍ يَعْقِلُهُ، وَمَنْ زَالَ عَقْلُهُ مَعْذُورًا لَمْ يَقَعْ طَلَاقُهُ وَعَكْسُهُ الْآثِمُ،"]]},{"id":"za188_2","label":"كِتَابُ الطَّلَاقِ · ٢","segs":[["matn","وَمَنْ أُكْرِهَ عَلَيْهِ ظُلْمًا بِإِيلَامٍ لَهُ أَوْ لِوَلَدِهِ أَوْ أَخْذِ مَالٍ يَضُرُّهُ أَوْ هَدَّدَهُ بِأَحَدِهَا قَادِرٌ يَظُنُّ إِيقَاعَهُ بِهِ فَطَلَّقَ تَبَعًا لِقَوْلِهِ لَمْ يَقَعْ، وَيَقَعُ الطَّلَاقُ فِي نِكَاحٍ مُخْتَلَفٍ فِيهِ، وَمِنَ الْغَضْبَانِ، وَوَكِيلُهُ كَهُوَ،"]]},{"id":"za188_3","label":"كِتَابُ الطَّلَاقِ · ٣","segs":[["matn","وَيُطَلِّقُ وَاحِدَةً وَمَتَى شَاءَ إِلَّا أَنْ يُعَيِّنَ لَهُ وَقْتًا وَعَدَدًا وَامْرَأَتُهُ كَوَكِيلِهِ فِي طَلَاقِ نَفْسِهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za189","title":"كِتَابُ الطَّلَاقِ · فَصْلٌ","units":[{"id":"za189_1","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ · ١","segs":[["matn","إِذَا طَلَّقَهَا مَرَّةً فِي طُهْرٍ لَمْ يُجَامِعْ فِيهِ وَتَرَكَهَا حَتَّى تَنْقَضِيَ عِدَّتُهَا فَهُوَ سُنَّةٌ، وَتَحْرُمُ الثَّلَاثُ إِذًا، وَإِنْ طَلَّقَ مَنْ دَخَلَ بِهَا فِي حَيْضٍ أَوْ طُهْرٍ وَطِئَ فِيهِ فَبِدْعَةٌ يَقَعُ وَتُسَنُّ رَجْعَتُهَا،"]]},{"id":"za189_2","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ · ٢","segs":[["matn","وَلَا سُنَّةَ وَلَا بِدْعَةَ لِصَغِيرَةٍ وَآيِسَةٍ وَغَيْرِ مَدْخُولٍ بِهَا وَمَنْ بَانَ حَمْلُهَا."]]},{"id":"za189_3","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ · ٣","segs":[["matn","وَصَرِيحُهُ لَفْظُ الطَّلَاقِ وَمَا تَصَرَّفَ مِنْهُ غَيْرَ أَمْرٍ وَمُضَارِعٍ، وَمُطَلِّقَةٍ اسْمَ فَاعِلٍ فَيَقَعُ بِهِ وَإِنْ لَمْ يَنْوِهِ جَادٌّ أَوْ هَازِلٌ،"]]},{"id":"za189_4","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ · ٤","segs":[["matn","فَإِنْ نَوَى بِطَالِقٍ مِنْ وَثَاقٍ أَوْ فِي نِكَاحٍ سَابِقٍ مِنْهُ أَوْ مِنْ غَيْرِهِ أَوْ أَرَادَ طَاهِرًا فَغَلِطَ لَمْ يُقْبَلْ حُكْمًا، وَلَوْ سُئِلَ: أَطَلَّقْتَ امْرَأَتَكَ؟ فَقَالَ: نَعَمْ وَقَعَ، أَوْ أَلَكَ امْرَأَةٌ؟ فَقَالَ: لَا وَأَرَادَ الْكَذِبَ فَلَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za190","title":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٢)","units":[{"id":"za190_1","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٢) · ١","segs":[["matn","وَكِنَايَاتُهُ الظَّاهِرَةُ، نَحْوُ: أَنْتِ خَلِيَّةٌ وَبَرِيَّةٌ وَبَائِنٌ وَبَتَّةٌ وَبَتْلَةٌ وَأَنْتِ حُرَّةٌ وَأَنْتِ الْحَرَجُ، وَالْخَفِيَّةُ نَحْوُ اخْرُجِي وَاذْهَبِي وَذُوقِي وَتَجَرَّعِي وَاعْتَدِّي وَاسْتَبْرِئِي وَاعْتَزِلِي وَلَسْتِ لِي بِامْرَأَةٍ وَالْحَقِي بِأَهْلِكِ وَمَا أَشْبَهَهُ،"]]},{"id":"za190_2","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَلَا يَقَعُ بِكِنَايَةٍ وَلَوْ ظَاهِرَةً طَلَاقٌ إِلَّا بِنِيَّةٍ مُقَارِنَةٍ لِلَّفْظِ، إِلَّا حَالَ خُصُومَةٍ أَوْ غَضَبٍ أَوْ جَوَابِ سُؤَالِهَا، فَلَوْ لَمْ يُرِدْهُ أَوْ أَرَادَ غَيْرَهُ فِي هَذِهِ الْأَحْوَالِ لَمْ يُقْبَلْ حُكْمًا،"]]},{"id":"za190_3","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَيَقَعُ مَعَ النِّيَّةِ بِالظَّاهِرَةِ ثَلَاثٌ وَإِنْ نَوَى وَاحِدَةً، وَبِالْخَفِيَّةِ مَا نَوَاهُ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za191","title":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٣)","units":[{"id":"za191_1","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٣) · ١","segs":[["matn","وَإِنْ قَالَ: أَنْتِ عَلَيَّ حَرَامٌ أَوْ كَظَهْرِ أُمِّي فَهُوَ ظِهَارٌ وَلَوْ نَوَى بِهِ الطَّلَاقَ، وَكَذَلِكَ مَا أَحَلَّ اللَّهُ عَلَيَّ حَرَامٌ، وَإِنْ قَالَ: مَا أَحَلَّ اللَّهُ عَلَيَّ حَرَامٌ، أَعْنِي بِهِ الطَّلَاقَ."]]},{"id":"za191_2","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٣) · ٢","segs":[["matn","طَلُقَتْ ثَلَاثًا، وَإِنْ قَالَ: أَعْنِي بِهِ طَلَاقًا فَوَاحِدَةً، وَإِنْ قَالَ: كَالْمَيْتَةِ وَالدَّمِ وَالْخِنْزِيرِ وَقَعَ مَا نَوَاهُ مِنْ طَلَاقٍ وَظِهَارٍ وَيَمِينٍ، وَإِنْ لَمْ يَنْوِ شَيْئًا فَظِهَارٌ، وَإِنْ قَالَ: حَلَفْتُ بِالطَّلَاقِ وَكَذَبَ لَزِمَهُ حُكْمًا،"]]},{"id":"za191_3","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٣) · ٣","segs":[["matn","وَإِنْ قَالَ: أَمْرُكِ بِيَدِكِ مَلَكَتْ ثَلَاثًا وَلَوْ نَوَى وَاحِدَةً، وَيَتَرَاخَى مَا لَمْ يَطَأْ أَوْ يُطَلِّقْ أَوْ يَفْسَخْ، وَيَخْتَصُّ اخْتَارِي نَفْسَكِ بِوَاحِدَةٍ وَبِالْمَجْلِسِ الْمُتَّصِلِ مَا لَمْ يَزِدْهَا فِيهِمَا،"]]},{"id":"za191_4","label":"كِتَابُ الطَّلَاقِ · فَصْلٌ (٣) · ٤","segs":[["matn","فَإِنْ رَدَّتْ أَوْ وَطِئَ أَوْ طَلَّقَ أَوْ فَسَخَ بَطَلَ خِيَارُهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za192","title":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ","units":[{"id":"za192_1","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١","segs":[["matn","يَمْلِكُ مَنْ كُلُّهُ حُرٌّ أَوْ بَعْضُهُ ثَلَاثًا وَالْعَبْدُ اثْنَتَيْنِ حُرَّةً كَانَتْ زَوْجَتَاهُمَا أَوْ أَمَةً، فَإِذَا قَالَ: أَنْتِ الطَّلَاقُ أَوْ طَالِقٌ أَوْ عَلَيَّ أَوْ يَلْزَمُنِي وَقَعَ ثَلَاثًا بِنِيَّتِهَا، وَإِلَّا فَوَاحِدَةٌ،"]]},{"id":"za192_2","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٢","segs":[["matn","وَيَقَعُ بِلَفْظِ كُلِّ الطَّلَاقِ أَوْ أَكْثَرِهِ أَوْ عَدَدِ الْحَصَى أَوِ الرِّيحِ أَوْ نَحْوِ ذَلِكَ ثَلَاثٌ وَلَوْ نَوَى وَاحِدَةً،"]]},{"id":"za192_3","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٣","segs":[["matn","وَإِنْ طَلَّقَ عُضْوًا أَوْ جُزْءًا مُشَاعًا أَوْ مُعَيَّنًا أَوْ مُبْهَمًا أَوْ قَالَ: نِصْفَ طَلْقَةٍ أَوْ جُزْءًا مِنْ طَلْقَةٍ طَلُقَتْ، وَعَكْسُهُ الرُّوحُ وَالسِّنُّ وَالشَّعْرُ وَالظُّفُرُ وَنَحْوُهُ،"]]},{"id":"za192_4","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٤","segs":[["matn","وَإِذَا قَالَ لِمَدْخُولٍ بِهَا: أَنْتِ طَالِقٌ وَكَرَّرَهُ وَقَعَ الْعَدَدُ إِلَّا أَنْ يَنْوِيَ تَأْكِيدًا يَصِحُّ أَوْ إِفْهَامًا، وَإِنْ كَرَّرَهُ بِبَلْ أَوْ بِثُمَّ أَوْ بِالْفَاءِ أَوْ قَالَ بَعْدَهَا أَوْ قَبْلَهَا أَوْ مَعَهَا طَلْقَةً وَقَعَ ثِنْتَانِ،"]]},{"id":"za192_5","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٥","segs":[["matn","وَإِنْ لَمْ يَدْخُلْ بِهَا بَانَتْ بِالْأُولَى وَلَمْ يَلْزَمْهُ مَا بَعْدَهَا، وَالْمُعَلَّقُ كَالْمُنَجَّزِ فِي هَذَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za193","title":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · فَصْلٌ","units":[{"id":"za193_1","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · فَصْلٌ · ١","segs":[["matn","وَيَصِحُّ مِنْهُ اسْتِثْنَاءُ النِّصْفِ فَأَقَلَّ مِنْ عَدَدِ الطَّلَاقِ وَالْمُطَلَّقَاتِ، فَإِذَا قَالَ: أَنْتِ طَالِقٌ طَلْقَتَيْنِ إِلَّا وَاحِدَةً وَقَعَتْ وَاحِدَةً، وَإِنْ قَالَ: ثَلَاثًا إِلَّا وَاحِدَةً فَطَلْقَتَانِ، وَإِنِ اسْتَثْنَى بِقَلْبِهِ مِنْ عَدَدِ الْمُطَلَّقَاتِ صَحَّ دُونَ عَدَدِ الطَّلَقَاتِ،"]]},{"id":"za193_2","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ قَالَ: أَرْبَعُكُنَّ إِلَّا فُلَانَةَ طَوَالِقُ صَحَّ الِاسْتِثْنَاءُ وَلَا يَصِحُّ اسْتِثْنَاءٌ لَمْ يَتَّصِلْ عَادَةً، فَلَوِ انْفَصَلَ وَأَمْكَنَ الْكَلَامُ دُونَهُ بَطَلَ، وَشَرْطُهُ النِّيَّةُ قَبْلَ كَمَالِ مَا اسْتَثْنَى مِنْهُ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za194","title":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ","units":[{"id":"za194_1","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · ١","segs":[["matn","إِذَا قَالَ: أَنْتِ طَالِقٌ أَمْسِ أَوْ قَبْلَ أَنْ أَنْكِحَكِ وَلَمْ يَنْوِ وُقُوعَهُ فِي الْحَالِ لَمْ يَقَعْ، وَإِنْ أَرَادَ بِطَلَاقٍ سَبَقَ مِنْهُ أَوْ مِنْ زَيْدٍ وَأَمْكَنَ قُبِلَ،"]]},{"id":"za194_2","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · ٢","segs":[["matn","فَإِنْ مَاتَ أَوْ جُنَّ أَوْ خَرِسَ قَبْلَ بَيَانِ مُرَادِهِ لَمْ تَطْلُقْ، وَإِنْ قَالَ: طَالِقٌ ثَلَاثًا قَبْلَ قُدُومِ زَيْدٍ بِشَهْرٍ فَقَدِمَ قَبْلَ مُضِيِّهِ لَمْ تَطْلُقْ، وَبَعْدَ شَهْرٍ وَجُزْءٍ تَطْلُقُ فِيهِ يَقَعُ،"]]},{"id":"za194_3","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · ٣","segs":[["matn","فَإِنْ خَالَعَهَا بَعْدَ الْيَمِينِ بِيَوْمٍ وَقَدِمَ بَعْدَ شَهْرٍ وَيَوْمَيْنِ صَحَّ الْخُلْعُ وَبَطَلَ الطَّلَاقُ، وَعَكْسُهُمَا بَعْدَ شَهْرٍ وَسَاعَةٍ، وَإِنْ قَالَ: طَالِقٌ قَبْلَ مَوْتِي. طَلُقَتْ فِي الْحَالِ، وَعَكْسُهُ مَعَهُ أَوْ بَعْدَهُ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za195","title":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ","units":[{"id":"za195_1","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ · ١","segs":[["matn","وَأَنْتِ طَالِقٌ إِنْ طِرْتِ أَوْ صَعَدْتِ السَّمَاءَ أَوْ قَلَبْتِ الْحَجَرَ ذَهَبًا."]]},{"id":"za195_2","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ · ٢","segs":[["matn","وَنَحْوَهُ مِنَ الْمُسْتَحِيلِ لَمْ تَطْلُقْ، وَتَطْلُقُ فِي عَكْسِهِ فَوْرًا وَهُوَ النَّفْيُ فِي الْمُسْتَحِيلِ مِثْلَ لَأَقْتُلَنَّ الْمَيِّتَ أَوْ لَأَصْعَدَنَّ السَّمَاءَ وَنَحْوِهِمَا، وَأَنْتِ طَالِقٌ الْيَوْمَ إِذَا جَاءَ غَدٌ."]]},{"id":"za195_3","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ · ٣","segs":[["matn","لَغْوٌ، وَإِذَا قَالَ: أَنْتِ طَالِقٌ فِي هَذَا الشَّهْرِ أَوِ الْيَوْمِ."]]},{"id":"za195_4","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ · ٤","segs":[["matn","طَلُقَتْ فِي الْحَالِ، وَإِنْ قَالَ: فِي غَدٍ أَوِ السَّبْتِ أَوْ رَمَضَانَ."]]},{"id":"za195_5","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ · ٥","segs":[["matn","طَلَقَتْ فِي أَوَّلِهِ، وَإِنْ قَالَ: أَرَدْتُ آخِرَ الْكُلِّ."]]},{"id":"za195_6","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ · ٦","segs":[["matn","دُيِّنَ وَقُبِلَ، وَأَنْتِ طَالِقٌ إِلَى شَهْرٍ. طَلُقَتْ عِنْدَ انْقِضَائِهِ إِلَّا أَنْ يَنْوِيَ فِي الْحَالِ فَيَقَعَ، وَطَالِقٌ إِلَى سَنَةٍ."]]},{"id":"za195_7","label":"بَابُ الطَّلَاقِ فِي الْمَاضِي وَالْمُسْتَقْبَلِ · فَصْلٌ · ٧","segs":[["matn","تَطْلُقُ بِاثْنَيْ عَشَرَ شَهْرًا، فَإِنْ عَرَّفَهَا بِاللَّامِ. طَلُقَتْ بِانْسِلَاخِ ذِي الْحِجَّةِ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za196","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ","units":[{"id":"za196_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ١","segs":[["matn","لَا يَصِحُّ إِلَّا مِنْ زَوْجٍ، فَإِذَا عَلَّقَهُ بِشَرْطٍ."]]},{"id":"za196_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٢","segs":[["matn","لَمْ تَطْلُقْ قَبْلَهُ، وَلَوْ قَالَ: عَجَّلْتُهُ وَإِنْ قَالَ: سَبَقَ لِسَانِي بِالشَّرْطِ وَلَمْ أُرِدْهُ."]]},{"id":"za196_3","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٣","segs":[["matn","وَقَعَ فِي الْحَالِ، وَإِنْ قَالَ: أَنْتِ طَالِقٌ، وَقَالَ: أَرَدْتُ إِنْ قُمْتِ."]]},{"id":"za196_4","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٤","segs":[["matn","لَمْ يُقْبَلْ حُكْمًا. وَأَدَوَاتُ الشَّرْطِ إِنْ وَإِذَا وَمَتَى وَأَيُّ وَمَنْ وَكُلَّمَا وَهِيَ وَحْدَهَا لِلتِّكْرَارِ وَكُلُّهَا وَمَهْمَا بِلَا لَمْ أَوْ نِيَّةِ فَوْرٍ أَوْ قَرِينَتِهِ لِلتَّرَاخِي، وَمَعَ لَمْ لِلْفَوْرِ، إِلَّا إِنْ مَعَ عَدَمِ نِيَّةِ فَوْرٍ أَوْ قَرِينَتِهِ،"]]},{"id":"za196_5","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٥","segs":[["matn","فَإِذَا قَالَ: إِنْ قُمْتِ أَوْ إِذَا أَوْ مَتَى أَوْ أَيُّ وَقْتٍ أَوْ مَنْ قَامَتْ أَوْ كُلَّمَا قُمْتِ فَأَنْتِ طَالِقٌ."]]},{"id":"za196_6","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٦","segs":[["matn","فَمَتَى وُجِدَ طَلُقَتْ، وَإِنْ تَكَرَّرَ الشَّرْطُ لَمْ يَتَكَرَّرِ الْحِنْثُ إِلَّا فِي كُلَّمَا وَإِنْ لَمْ أُطَلِّقْكِ فَأَنْتِ طَالِقٌ وَلَمْ يَنْوِ وَقْتًا وَلَمْ تَقُمْ قَرِينَةٌ بِفَوْرٍ وَلَمْ يُطَلِّقْهَا طَلُقَتْ فِي آخِرِ حَيَاةِ أَوَّلِهِمَا مَوْتًا، وَمَتَى لَمْ،"]]},{"id":"za196_7","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٧","segs":[["matn","أَوْ إِذَا لَمْ، أَوْ أَيَّ وَقْتٍ لَمْ أُطَلِّقْكِ فَأَنْتِ طَالِقٌ، وَمَضَى زَمَنٌ يُمْكِنُ إِيقَاعُهُ فِيهِ وَلَمْ يَفْعَلْ طَلُقَتْ، وَكُلَّمَا لَمْ أُطَلِّقْكِ فَأَنْتِ طَالِقٌ،"]]},{"id":"za196_8","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٨","segs":[["matn","وَمَضَى مَا يُمْكِنُ إِيقَاعُ ثَلَاثٍ مُرَتَّبَةٍ فِيهِ طَلُقَتِ الْمَدْخُولُ بِهَا ثَلَاثًا وَتَبِينُ غَيْرُهَا بِالْأُولَى،"]]},{"id":"za196_9","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٩","segs":[["matn","وَإِنْ قُمْتِ فَقَعَدْتِ أَوْ ثُمَّ قَعَدْتِ أَوْ قَعَدْتِ إِذَا قُمْتِ أَوْ إِنْ قَعَدْتِ إِنْ قُمْتِ فَأَنْتِ طَالِقٌ لَمْ تَطْلُقْ حَتَّى تَقُومَ ثُمَّ تَقْعُدَ، وَبِالْوَاوِ تَطْلُقُ بِوُجُودِهِمَا وَلَوْ غَيْرَ مُرَتَّبَيْنِ، وَبِأَوْ بِوُجُودِ أَحَدِهِمَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za197","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ","units":[{"id":"za197_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ · ١","segs":[["matn","إِذَا قَالَ: إِنْ حِضْتِ فَأَنْتِ طَالِقٌ. طَلُقَتْ بِأَوَّلِ حَيْضٍ مُتَيَقَّنٍ، وَإِذَا حِضْتِ حَيْضَةً."]]},{"id":"za197_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ · ٢","segs":[["matn","تَطْلُقْ بِأَوَّلِ الطُّهْرِ مِنْ حَيْضَةٍ كَامِلَةٍ، وَفِي: إِذَا حِضْتِ نِصْفَ حَيْضَةٍ. تَطْلُقْ فِي نِصْفِ عَادَتِهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za198","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٢)","units":[{"id":"za198_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٢) · ١","segs":[["matn","إِذَا عَلَّقَهُ بِالْحَمْلِ فَوَلَدَتْ لِأَقَلَّ مِنْ سِتَّةِ أَشْهُرٍ طَلُقَتْ مُنْذُ حَلَفَ، وَإِنْ قَالَ: إِنْ لَمْ تَكُونِي حَامِلًا فَأَنْتِ طَالِقٌ."]]},{"id":"za198_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٢) · ٢","segs":[["matn","حَرُمَ وَطْؤُهَا قَبْلَ اسْتِبْرَائِهَا بِحَيْضَةٍ فِي الْبَائِنِ، وَهِي عَكْسُ الْأُولَى فِي الْأَحْكَامِ، وَإِنْ عَلَّقَ طَلْقَةً إِنْ كَانَتْ حَامِلًا بِذَكَرٍ وَطَلْقَتَيْنِ بِأُنْثَى فَوَلَدَتْهُمَا طَلُقَتْ ثَلَاثًا، وَإِنْ كَانَ مَكَانَهُ إِنْ كَانَ حَمْلُكِ أَوْ مَا فِي بَطْنِكِ لَمْ تَطْلُقْ بِهِمَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za199","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٣)","units":[{"id":"za199_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٣) · ١","segs":[["matn","إِذَا عَلَّقَ طَلْقَةً عَلَى الْوِلَادَةِ بِذَكَرٍ وَطَلْقَتَيْنِ بِأُنْثَى فَوَلَدَتْ ذَكَرًا ثُمَّ أُنْثَى حَيًّا أَوْ مَيِّتًا طَلُقَتْ بِالْأَوَّلِ وَبَانَتْ بِالثَّانِي وَلَمْ تَطْلُقْ بِهِ، وَإِنْ أَشْكَلَ كَيْفِيَّةُ وَضْعِهِمَا فَوَاحِدَةٌ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za200","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٤)","units":[{"id":"za200_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٤) · ١","segs":[["matn","إِذَا عَلَّقَهُ عَلَى الطَّلَاقِ ثُمَّ عَلَّقَهُ عَلَى الْقِيَامِ أَوْ عَلَّقَهُ عَلَى الْقِيَامِ ثُمَّ عَلَى وُقُوعِ الطَّلَاقِ، فَقَامَتْ طَلُقَتْ طَلْقَتَيْنِ فِيهِمَا، وَإِنْ عَلَّقَهُ عَلَى قِيَامِهَا ثُمَّ عَلَى طَلَاقِهِ لَهَا فَقَامَتْ فَوَاحِدَةٌ،"]]},{"id":"za200_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٤) · ٢","segs":[["matn","وَإِنْ قَالَ: كُلَّمَا طَلَّقْتُكِ أَوْ كُلَّمَا وَقَعَ عَلَيْكِ طَلَاقِي فَأَنْتِ طَالِقٌ."]]},{"id":"za200_3","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٤) · ٣","segs":[["matn","فَوُجِدَا طَلُقَتْ فِي الْأُولَى طَلْقَتَيْنِ، وَفِي الثَّانِيَةِ ثَلَاثًا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za201","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٥)","units":[{"id":"za201_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٥) · ١","segs":[["matn","إِذَا قَالَ: إِذَا حَلَفْتُ بِطَلَاقِكِ فَأَنْتِ طَالِقٌ. ثُمَّ قَالَ: أَنْتِ طَالِقٌ إِنْ قُمْتِ: طَلُقَتْ فِي الْحَالِ، لَا إِنْ عَلَّقَهُ بِطُلُوعِ الشَّمْسِ وَنَحْوِهِ؛ لِأَنَّهُ شَرْطٌ لَا حَلِفٌ، وَإِنْ حَلَفْتُ بِطَلَاقِكِ فَأَنْتِ طَالِقٌ، أَوْ إِنْ كَلَّمْتُكِ فَأَنْتِ طَالِقٌ."]]},{"id":"za201_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٥) · ٢","segs":[["matn","وَأَعَادَهُ مَرَّةً أُخْرَى طَلُقَتْ وَاحِدَةً، وَمَرَّتَيْنِ فَثِنْتَانِ، وَثَلَاثًا فَثَلَاثٌ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za202","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٦)","units":[{"id":"za202_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٦) · ١","segs":[["matn","إِذَا قَالَ: إِنْ كَلَّمْتُكِ فَأَنْتِ طَالِقٌ فَتَحَقَّقِي، أَوْ قَالَ: تَنَحِّي أَوِ اسْكُتِي."]]},{"id":"za202_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٦) · ٢","segs":[["matn","طَلُقَتْ، وَإِنْ بَدَأْتُكِ بِكَلَامٍ فَأَنْتِ طَالِقٌ فَقَالَتْ: إِنْ بَدَأْتُكَ بِهِ فَعَبْدِي حُرٌّ."]]},{"id":"za202_3","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٦) · ٣","segs":[["matn","انْحَلَّتْ يَمِينُهُ مَا لَمْ يَنْوِ عَدَمَ الْبُدَاءَةِ فِي مَجْلِسٍ آخَرَ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za203","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٧)","units":[{"id":"za203_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٧) · ١","segs":[["matn","إِذَا قَالَ: إِنْ خَرَجْتِ بَغَيْرِ إِذْنِي أَوْ إِلَّا بِإِذْنِي أَوْ حَتَّى آذَنَ لَكِ أَوْ إِنْ خَرَجْتِ إِلَى غَيْرِ الْحَمَّامِ بِغَيْرِ إِذْنِي فَأَنْتِ طَالِقٌ."]]},{"id":"za203_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٧) · ٢","segs":[["matn","فَخَرَجَتْ مَرَّةً بِإِذْنِهِ، ثُمَّ خَرَجَتْ بِغَيْرِ إِذْنِهِ أَوْ أَذِنَ لَهَا، وَلَمْ تَعْلَمْ أَوْ خَرَجَتْ تُرِيدَ الْحَمَّامَ وَغَيْرَهُ، أَوْ عَدَلَتْ مِنْهُ إِلَى غَيْرِهِ طَلُقَتْ فِي الْكُلِّ، لَا إِنْ أَذِنَ فِيهِ كُلَّمَا شَاءَتْ أَوْ قَالَ: إِلَّا بِإِذْنِ زَيْدٍ. فَمَاتَ زَيْدٌ ثُمَّ خَرَجَتْ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za204","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨)","units":[{"id":"za204_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨) · ١","segs":[["matn","إِذَا عَلَّقَهُ بِمَشِيئَتِهَا بِإِنْ أَوْ غَيْرِهَا مِنَ الْحُرُوفِ لَمْ تَطْلُقْ حَتَّى تَشَاءَ وَلَوْ تَرَاخَى، فَإِنْ قَالَتْ: قَدْ شِئْتُ إِنْ شِئْتَ."]]},{"id":"za204_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨) · ٢","segs":[["matn","فَشَاءَ لَمْ تَطْلُقْ، وَإِنْ قَالَ: إِنْ شِئْتِ وَشَاءَ أَبُوكِ أَوْ زَيْدٌ."]]},{"id":"za204_3","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨) · ٣","segs":[["matn","لَمْ يَقَعْ حَتَّى يَشَاءَا مَعًا وَإِنْ شَاءَ أَحَدُهُمَا فَلَا، وَأَنْتِ طَالِقٌ وَعَبْدِي حُرٌّ إِنْ شَاءَ اللَّهُ."]]},{"id":"za204_4","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨) · ٤","segs":[["matn","وَقَعَا، وَإِنْ دَخَلْتِ الدَّارَ فَأَنْتِ طَالِقٌ إِنْ شَاءَ اللَّهُ."]]},{"id":"za204_5","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨) · ٥","segs":[["matn","طَلُقَتْ إِنْ دَخَلَتْ، وَأَنْتِ طَالِقٌ لِرِضَا زَيْدٍ أَوْ لِمَشِيئَتِهِ."]]},{"id":"za204_6","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨) · ٦","segs":[["matn","طَلُقَتْ فِي الْحَالِ، فَإِنْ قَالَ: أَرَدْتُ الشَّرْطَ. قُبِلَ حُكْمًا وَأَنْتِ طَالِقٌ إِنْ رَأَيْتِ الْهِلَالَ."]]},{"id":"za204_7","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٨) · ٧","segs":[["matn","فَإِنْ نَوَى رُؤْيَتَهُا لَمْ تَطْلُقْ حَتَّى تَرَاهُ وَإِلَّا طَلُقَتْ بَعْدَ الْغُرُوبِ بِرُؤْيَةِ غَيْرِهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za205","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٩)","units":[{"id":"za205_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٩) · ١","segs":[["matn","وَإِنْ حَلَفَ لَا يَدْخُلُ دَارًا أَوْ لَا يَخْرُجُ مِنْهَا فَأَدْخَلَ أَوْ أَخْرَجَ بَعْضَ جَسَدِهِ أَوْ دَخَلَ طَاقَ الْبَابِ، أَوْ لَا يَلْبَسُ ثَوْبًا مِنْ غَزْلِهَا فَلَبِسَ ثَوْبًا فِيهِ مِنْهُ،"]]},{"id":"za205_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٩) · ٢","segs":[["matn","أَوْ لَا يَشْرَبُ مَاءَ هَذَا الْإِنَاءِ فَشَرِبَ بَعْضَهُ لَمْ يَحْنَثْ، وَإِنْ فَعَلَ الْمَحْلُوفَ عَلَيْهِ نَاسِيًا أَوْ جَاهِلًا حَنِثَ فِي طَلَاقٍ وَعِتَاقٍ فَقَطْ، وَإِنْ فَعَلَ بَعْضَهُ لَمْ يَحْنَثْ إِلَّا أَنْ يَنْوِيَهُ،"]]},{"id":"za205_3","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · فَصْلٌ (٩) · ٣","segs":[["matn","وَإِنْ حَلَفَ لَيَفْعَلَنَّهُ لَمْ يَبَرَّ إِلَّا بِفِعْلِهِ كُلِّهِ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za206","title":"بَابُ التَّأْوِيلِ فِي الْحَلِفِ","units":[{"id":"za206_1","label":"بَابُ التَّأْوِيلِ فِي الْحَلِفِ · ١","segs":[["matn","وَمَعْنَاهُ: أَنْ يُرِيدَ بِلَفْظِهِ مَا يُخَالِفُ ظَاهِرَهُ، فَإِذَا حَلَفَ وَتَأَوَّلَ يَمِينَهُ نَفَعَهُ إِلَّا أَنْ يَكُونَ ظَالِمًا، فَإِنْ حَلَّفَهُ ظَالِمٌ مَا لِزَيْدٍ عِنْدَكَ شَيْءٌ وَلَهُ عِنْدَهُ وَدِيعَةٌ بِمَكَانٍ فَنَوَى غَيْرَهُ أَوْ بِمَا الَّذِي،"]]},{"id":"za206_2","label":"بَابُ التَّأْوِيلِ فِي الْحَلِفِ · ٢","segs":[["matn","أَوْ حَلَفَ مَا زَيْدٌ هَا هُنَا وَنَوَى غَيْرَ مَكَانِهِ، أَوْ حَلَفَ عَلَى امْرَأَتِهِ لَا سَرَقْتِ مِنِّي شَيْئًا فَخَانَتْهُ فِي وَدِيعَةٍ وَلَمْ يَنْوِهَا لَمْ يَحْنَثْ فِي الْكُلِّ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za207","title":"بَابُ الشَّكِّ فِي الطَّلَاقِ","units":[{"id":"za207_1","label":"بَابُ الشَّكِّ فِي الطَّلَاقِ · ١","segs":[["matn","مَنْ شَكَّ فِي طَلَاقٍ أَوْ شَرْطِهِ لَمْ يَلْزَمْهُ، وَإِنْ شَكَّ فِي عَدَدِهِ فَطَلْقَةٌ، وَتُبَاحُ لَهُ، فَإِذَا قَالَ لِامْرَأَتَيْهِ: إِحْدَاكُمَا طَالِقٌ."]]},{"id":"za207_2","label":"بَابُ الشَّكِّ فِي الطَّلَاقِ · ٢","segs":[["matn","طَلُقَتْ الْمَنْوِيَّةُ وَإِلَّا مَنْ قَرَعَتْ، كَمَنْ طَلَّقَ إِحْدَاهُمَا، بَائِنًا وَأُنْسِيَهَا، وَإِنْ تَبَيَّنَ أَنَّ الْمُطَلَّقَةَ غَيْرُ الَّتِي قَرَعَتْ رُدَّتْ إِلَيْهِ مَا لَمْ تَتَزَوَّجْ أَوْ تَكُنِ الْقُرْعَةُ بِحَاكِمٍ، وَإِنْ قَالَ: إِنْ كَانَ هَذَا الطَّائِرُ غُرَابًا فَفُلَانَةُ طَالِقٌ، وَإِنْ كَانَ حَمَامًا فَفُلَانَةُ."]]},{"id":"za207_3","label":"بَابُ الشَّكِّ فِي الطَّلَاقِ · ٣","segs":[["matn","وَجُهِلَ لَمْ تَطْلُقَا، وَإِنْ قَالَ لِزَوْجَتِهِ وَأَجْنَبِيَّةٍ اسْمُهَا هِنْدُ: إِحْدَاكُمَا أَوْ هِنْدُ طَالِقٌ."]]},{"id":"za207_4","label":"بَابُ الشَّكِّ فِي الطَّلَاقِ · ٤","segs":[["matn","طَلُقَتِ امْرَأَتُهُ، وَإِنْ قَالَ: أَرَدْتُ الْأَجْنَبِيَّةَ. لَمْ يُقْبَلْ حُكْمًا إِلَّا بِقَرِينَةٍ، وَإِنْ قَالَ لِمَنْ ظَنَّهَا زَوْجَتَهُ: أَنْتِ طَالِقٌ. طَلُقَتِ الزَّوْجَةُ وَكَذَا عَكْسُهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za208","title":"بَابُ الرَّجْعَةِ","units":[{"id":"za208_1","label":"بَابُ الرَّجْعَةِ · ١","segs":[["matn","مَنْ طَلَّقَ بِلَا عِوَضٍ زَوْجَةً مَدْخُولًا بِهَا أَوْ مَخْلُوًّا بِهَا دُونَ مَا لَهُ مِنَ الْعَدَدِ فَلَهُ رَجْعَتُهَا فِي عِدَّتِهَا وَلَوْ كَرِهَتْ بِلَفْظِ: «رَاجَعْتُ امْرَأَتِي» وَنَحْوِهِ لَا «نَكَحْتُهَا وَنَحْوِهِ، وَيُسَنُّ الْإِشْهَادُ،»"]]},{"id":"za208_2","label":"بَابُ الرَّجْعَةِ · ٢","segs":[["matn","«وَهِيَ زَوْجَةٌ لَهَا وَعَلَيْهَا حُكْمُ الزَّوْجَاتِ، لَكِنْ لَا قَسْمَ لَهَا وَتَحْصُلُ الرَّجْعَةُ أَيْضًا بِوَطْئِهَا، وَلَا تَصِحُّ مُعَلَّقَةً بِشَرْطٍ، فَإِذَا طَهَرَتْ مِنَ الْحَيْضَةِ الثَّالِثَةِ وَلَمْ تَغْتَسِلْ فَلَهُ رَجْعَتُهَا،»"]]},{"id":"za208_3","label":"بَابُ الرَّجْعَةِ · ٣","segs":[["matn","«وَإِنْ فَرَغَتْ عِدَّتُهَا قَبْلَ رَجْعَتِهَا بَانَتْ وَحَرُمَتْ قَبْلَ عَقْدٍ جَدِيدٍ، وَمَنْ طَلَّقَ دُونَ مَا يَمْلِكُ ثُمَّ رَاجَعَ أَوْ تَزَوَّجَ لَمْ يَمْلِكْ أَكْثَرَ مِمَّا بَقِيَ، وَطِئَهَا زَوْجٌ غَيْرُهُ أَوْ لَا. »"]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za209","title":"بَابُ الرَّجْعَةِ · فَصْلٌ","units":[{"id":"za209_1","label":"بَابُ الرَّجْعَةِ · فَصْلٌ · ١","segs":[["matn","وَإِنِ ادَّعَتِ انْقِضَاءَ عِدَّتَهُا فِي زَمَنٍ يُمْكِنُ انْقِضَاؤُهَا فِيهِ أَوْ بِوَضْعِ الْحَمْلِ الْمُمْكِنِ وَأَنْكَرَهُ فَقَوْلُهَا، وَإِنِ ادَّعَتْهُ الْحُرَّةُ بِالْحَيْضِ فِي أَقَلَّ مِنْ تِسْعَةٍ وَعِشْرِينَ يَوْمًا وَلَحْظَةً لَمْ تُسْمَعْ دَعْوَاهَا، وَإِنْ بَدَأَتْهُ فَقَالَتْ: انْقَضَتْ عِدَّتِي."]]},{"id":"za209_2","label":"بَابُ الرَّجْعَةِ · فَصْلٌ · ٢","segs":[["matn","فَقَالَ: كُنْتُ رَاجَعْتُكِ. أَوْ بَدَأَهَا بِهِ فَأَنْكَرَتْهُ فَقَوْلُهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za210","title":"بَابُ الرَّجْعَةِ · فَصْلٌ (٢)","units":[{"id":"za210_1","label":"بَابُ الرَّجْعَةِ · فَصْلٌ (٢) · ١","segs":[["matn","إِذَا اسْتَوْفَى مَا يَمْلِكُ مِنَ الطَّلَاقِ حَرُمَتْ حَتَّى يَطَأَهَا زَوْجٌ فِي قُبُلٍ وَلَوْ مُرَاهِقًا، وَيَكْفِي تَغْيِيبُ الْحَشَفَةِ أَوْ قَدْرِهَا مَعَ جَبٍّ فِي فَرْجِهَا مَعَ انْتِشَارٍ وَإِنْ لَمْ يُنْزِلْ،"]]},{"id":"za210_2","label":"بَابُ الرَّجْعَةِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَلَا تَحِلُّ بِوَطْءِ دُبُرٍ وَشُبْهَةٍ وَمِلْكِ يَمِينٍ وَنِكَاحٍ فَاسِدٍ، وَلَا فِي حَيْضٍ وَنِفَاسٍ وَإِحْرَامٍ وَصِيَامِ فَرْضٍ، وَمَنِ ادَّعَتْ مُطَلَّقَتُهُ الْمُحَرَّمَةُ وَقَدْ غَابَتْ نِكَاحَ مَنْ أَحَلَّهَا وَانْقِضَاءَ عِدَّتِهَا مِنْهُ فَلَهُ نِكَاحُهَا إِنْ صَدَّقَهَا وَأَمْكَنَ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"za211","title":"كِتَابُ الْإِيلَاءِ","units":[{"id":"za211_1","label":"كِتَابُ الْإِيلَاءِ · ١","segs":[["matn","وَهُوَ حَلِفُ زَوْجٍ بِاللَّهِ تَعَالَى أَوْ صِفَتِهِ عَلَى تَرْكِ وَطْءِ زَوْجَتِهِ فِي قُبُلِهَا أَكْثَرَ مِنْ أَرْبَعَةِ أَشْهُرٍ، وَيَصِحُّ مِنْ كَافِرٍ وَقِنٍّ وَمُمَيِّزٍ وَغَضْبَانَ وَسَكْرَانَ وَمَرِيضٍ مَرْجُوٍّ بُرْؤُهُ وَمِمَّنْ لَمْ يَدْخُلْ بِهَا،"]]},{"id":"za211_2","label":"كِتَابُ الْإِيلَاءِ · ٢","segs":[["matn","لَا مِنْ مَجْنُونٍ وَمُغْمًى عَلَيْهِ وَعَاجِزٍ عَنْ وَطْءٍ لِجَبٍّ كَامِلٍ أَوْ شَلَلٍ، فَإِذَا قَالَ: وَاللَّهِ لَا وَطِئْتُكِ أَبَدًا."]]},{"id":"za211_3","label":"كِتَابُ الْإِيلَاءِ · ٣","segs":[["matn","أَوْ عَيَّنَ مُدَّةً تَزِيدُ عَلَى أَرْبَعَةِ أَشْهُرٍ أَوْ حَتَّى يَنْزِلَ عِيسَى أَوْ يَخْرُجَ الدَّجَّالُ أَوْ حَتَّى تَشْرَبِي الْخَمْرَ أَوْ تُسْقِطِي دَيْنَكِ أَوْ تَهَبِي مَالَكِ وَنَحْوَهُ فَمُولٍ،"]]},{"id":"za211_4","label":"كِتَابُ الْإِيلَاءِ · ٤","segs":[["matn","فَإِذَا مَضَى أَرْبَعَةُ أَشْهُرٍ مِنْ يَمِينِهِ وَلَوْ قِنًّا فَإِنْ وَطِئَ وَلَوْ بِتَغْيِيبِ حَشَفَةٍ فَقَدْ فَاءَ، وَإِلَّا أَمَرَهُ بِالطَّلَاقِ، فَإِنْ أَبَى طَلَّقَ حَاكِمٌ عَلَيْهِ وَاحِدَةً أَوْ ثَلَاثًا أَوْ فَسَخَ،"]]},{"id":"za211_5","label":"كِتَابُ الْإِيلَاءِ · ٥","segs":[["matn","وَإِنْ وَطِئَ فِي الدُّبُرِ أَوْ دُونَ الْفَرْجِ فَمَا فَاءَ، وَإِنِ ادَّعَى بَقَاءَ الْمُدَّةِ أَوْ أَنَّهُ وَطِئَهَا وَهِيَ ثَيِّبٌ صُدِّقَ مَعَ يَمِينِهِ، وَإِنْ كَانَتْ بِكْرًا وَادَّعَتِ الْبَكَارَةَ وَشَهِدَ بِذَلِكَ امْرَأَةٌ عَدْلٌ صُدِّقَتْ، وَإِنْ تَرَكَ وَطْأَهَا؛ إِضْرَارًا بِهَا بِلَا يَمِينٍ وَلَا عُذْرٍ فَكَمُولٍ."]]}],"group":"كِتَابُ الْإِيلَاءِ"},{"id":"za212","title":"كِتَابُ الظِّهَارِ","units":[{"id":"za212_1","label":"كِتَابُ الظِّهَارِ · ١","segs":[["matn","وَهُوَ مُحَرَّمٌ، فَمَنْ شَبَّهَ زَوْجَتَهُ أَوْ بَعْضَهَا بِبَعْضِ أَوْ بِكُلِّ مَنْ تَحْرُمُ عَلَيْهِ أَبَدًا بِنَسَبٍ أَوْ رَضَاعٍ مِنْ ظَهْرٍ أَوْ بَطْنٍ أَوْ عُضْوٍ آخَرَ لَا يَنْفَصِلُ بِقَوْلِهِ لَهَا: أَنْتِ عَلَيَّ أَوْ مَعِي أَوْ مِنِّي كَظَهْرِ أُمِّي أَوْ كَيَدِ أُخْتِي أَوْ وَجْهِ حَمَاتِي وَنَحْوِهِ،"]]},{"id":"za212_2","label":"كِتَابُ الظِّهَارِ · ٢","segs":[["matn","أَوْ أَنْتِ عَلَيَّ حَرَامٌ أَوْ كَالْمَيْتَةِ وَالدَّمِ فَهُوَ مُظَاهِرٌ، وَإِنْ قَالَتْهُ لِزَوْجِهَا فَلَيْسَ بِظِهَارٍ وَعَلَيْهَا كَفَّارَتُهُ، وَيَصِحُّ مِنْ كُلِّ زَوْجَةٍ."]]}],"group":"كِتَابُ الظِّهَارِ"},{"id":"za213","title":"كِتَابُ الظِّهَارِ · فَصْلٌ","units":[{"id":"za213_1","label":"كِتَابُ الظِّهَارِ · فَصْلٌ · ١","segs":[["matn","وَيَصِحُّ الظِّهَارُ مُعَجَّلًا وَمُعَلَّقًا بِشَرْطٍ، فَإِذَا وُجِدَ صَارَ مُظَاهِرًا وَمُطْلَقًا وَمُؤَقَّتًا، فَإِنْ وَطِئَ فِيهِ كَفَّرَ، وَإِنْ فَرَغَ الْوَقْتُ زَالَ الظِّهَارُ، وَيَحْرُمُ قَبْلَ أَنْ يُكَفِّرَ وَطْءٌ وَدَوَاعِيهِ مِمَّنْ ظَاهَرَ مِنْهَا،"]]},{"id":"za213_2","label":"كِتَابُ الظِّهَارِ · فَصْلٌ · ٢","segs":[["matn","وَلَا تَثْبُتُ الْكَفَّارَةُ فِي الذِّمَّةِ إِلَّا بِالْوَطْءِ وَهُوَ الْعَوْدُ، وَيَلْزَمُ إِخْرَاجُهَا قَبْلَهُ عِنْدَ الْعَزْمِ عَلَيْهِ، وَتَلْزَمُهُ كَفَّارَةٌ وَاحِدَةٌ بِتَكْرِيرِهِ قَبْلَ التَّكْفِيرِ مِنْ وَاحِدَةٍ وَلِظِهَارِهِ مِنْ نِسَائِهِ بِكَلِمَةٍ وَاحِدَةٍ، وَإِنْ ظَاهَرَ مِنْهُنَّ بِكَلِمَاتٍ فَكَفَّارَاتٌ."]]}],"group":"كِتَابُ الظِّهَارِ"},{"id":"za214","title":"كِتَابُ الظِّهَارِ · فَصْلٌ (٢)","units":[{"id":"za214_1","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٢) · ١","segs":[["matn","كَفَّارَتُهُ عِتْقُ رَقَبَةٍ فَإِنْ لَمْ يَجِدْ صَامَ شَهْرَيْنِ مُتَتَابِعَيْنِ فَإِنْ لَمْ يَسْتَطِعْ أَطْعَمَ سِتِّينَ مِسْكِينًا،"]]},{"id":"za214_2","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَلَا تَلْزَمُ الرَّقَبَةُ إِلَّا لِمَنْ مَلَكَهَا أَوْ أَمْكَنَهُ ذَلِكَ بِثَمَنِ مِثْلِهَا فَاضِلًا عَنْ كِفَايَتِهِ دَائِمًا وَكِفَايَةِ مَنْ يَمُونُهُ وَعَمَّا يَحْتَاجُهُ مِنْ مَسْكَنٍ وَخَادِمٍ وَمَرْكُوبٍ وَعَرَضِ بِذْلَةٍ وَثِيَابِ تَجَمُّلٍ،"]]},{"id":"za214_3","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَمَالٍ يَقُومُ كَسْبُهُ بِمَؤْنَتِهِ وَكُتُبِ عِلْمٍ وَوَفَاءِ دَيْنٍ،"]]},{"id":"za214_4","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٢) · ٤","segs":[["matn","وَلَا يُجْزِئُ فِي الْكَفَّارَاتِ كُلِّهَا إِلَّا رَقَبَةٌ مُؤْمِنَةٌ سَلِيمَةٌ مِنْ عَيْبٍ يَضُرُّ بِالْعَمَلِ ضَرَرًا بَيِّنًا كَالْعَمَى وَالشَّلَلِ لِيَدٍ أَوْ رِجْلٍ أَوْ أَقْطَعِهِمَا أَوْ أَقْطَعِ الْإِصْبَعِ الْوُسْطَى أَوِ السَّبَّابَةِ أَوِ الْإِبْهَامِ أَوِ الْأَنْمُلَةِ مِنَ الْإِبْهَامِ أَوْ أَقْطَعِ الْخِنْصَرِ وَالْبِنْصَرِ مِنْ يَدٍ وَاحِدَةٍ،"]]},{"id":"za214_5","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٢) · ٥","segs":[["matn","وَلَا يُجْزِئُ مَرِيضٌ مَيْؤُوسٌ مِنْهُ وَنَحْوُهُ وَلَا أُمُّ وَلَدٍ، وَيُجْزِئُ الْمُدَبَّرُ وَوَلَدُ الزِّنَا وَالْأَحْمَقُ وَالْمَرْهُونُ وَالْجَانِي وَالْأَمَةُ الْحَامِلُ وَلَوِ اسْتُثْنِيَ حَمْلَهُا."]]}],"group":"كِتَابُ الظِّهَارِ"},{"id":"za215","title":"كِتَابُ الظِّهَارِ · فَصْلٌ (٣)","units":[{"id":"za215_1","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٣) · ١","segs":[["matn","يَجِبُ التَّتَابُعُ فِي الصَّوْمِ، فَإِنْ تَخَلَّلَهُ رَمَضَانٌ أَوْ فِطْرٌ يَجِبُ كَعِيدٍ وَأَيَّامِ تَشْرِيقٍ وَحَيْضٍ وَجُنُونٍ وَمَرَضٍ مَخُوفٍ وَنَحْوِهِ أَوْ أَفْطَرَ نَاسِيًا أَوْ مُكْرَهًا أَوْ لِعُذْرٍ يُبِيحُ الْفِطْرَ لَمْ يَنْقَطِعْ،"]]},{"id":"za215_2","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٣) · ٢","segs":[["matn","وَيُجْزِئُ التَّكْفِيرُ بِمَا يُجْزِئُ فِي فِطْرَةٍ فَقَطْ، وَلَا يُجْزِئُ مِنَ الْبُرِّ أَقَلُّ مِنْ مُدٍّ وَلَا مِنْ غَيْرِهِ أَقَلُّ مِنْ مُدَّيْنِ لِكُلِّ وَاحِدٍ مِمَّنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِمْ، وَإِنْ غَدَّى الْمَسَاكِينَ أَوْ عَشَّاهُمْ لَمْ يُجْزِئْهُ،"]]},{"id":"za215_3","label":"كِتَابُ الظِّهَارِ · فَصْلٌ (٣) · ٣","segs":[["matn","وَتَجِبُ النِّيَّةُ فِي التَّكْفِيرِ مِنْ صَوْمٍ وَغَيْرِهِ، وَإِنْ أَصَابَ الْمُظَاهَرَ مِنْهَا لَيْلًا أَوْ نَهَارًا انْقَطَعَ التَّتَابُعُ، وَإِنْ أَصَابَ غَيْرَهَا لَيْلًا لَمْ يَنْقَطِعْ."]]}],"group":"كِتَابُ الظِّهَارِ"},{"id":"za216","title":"كِتَابُ اللِّعَانِ","units":[{"id":"za216_1","label":"كِتَابُ اللِّعَانِ · ١","segs":[["matn","يُشْتَرَطُ فِي صِحَّتِهِ أَنْ يَكُونَ بَيْنَ زَوْجَيْنِ، وَمَنْ عَرَفَ الْعَرَبِيَّةَ لَمْ يَصِحَّ لِعَانُهُ بِغَيْرِهَا، وَإِنْ جَهِلَهَا فَبِلُغَتِهِ، فَإِذَا قَذَفَ امْرَأَتَهُ بِالزِّنَا فَلَهُ إِسْقَاطُ الْحَدِّ بِاللِّعَانِ فَيَقُولُ قَبْلَهَا،"]]},{"id":"za216_2","label":"كِتَابُ اللِّعَانِ · ٢","segs":[["matn","أَرْبَعَ مَرَّاتٍ: «أَشْهَدُ بِاللَّهِ لَقَدْ زَنَتْ زَوْجَتِي هَذِهِ» وَيُشِيرُ إِلَيْهَا، وَمَعَ غَيْبَتِهَا يُسَمِّيهَا وَيَنْسِبُهَا،"]]},{"id":"za216_3","label":"كِتَابُ اللِّعَانِ · ٣","segs":[["matn","وَفِي الْخَامِسَةِ: «وَأَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ» ثُمَّ تَقُولُ هِيَ أَرْبَعَ مَرَّاتٍ: «أَشْهَدُ بِاللَّهِ لَقَدْ كَذَبَ فِيمَا رَمَانِي بِهِ مِنَ الزِّنَا» ثُمَّ تَقُولُ فِي الْخَامِسَةِ: «وَأَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنْ الصَّادِقِينَ»"]]},{"id":"za216_4","label":"كِتَابُ اللِّعَانِ · ٤","segs":[["matn","فَإِنْ بَدَأَتْ بِاللِّعَانِ قَبْلَهُ أَوْ نَقَصَ أَحَدُهُمَا شَيْئًا مِنَ الْأَلْفَاظِ الْخَمْسَةِ أَوْ لَمْ يَحْضُرْهُمَا حَاكِمٌ أَوْ نَائِبُهُ أَوْ أَبْدَلَ لَفْظَةَ أَشْهَدُ بِأُقْسِمُ أَوْ أَحْلِفُ أَوْ لَفْظَةَ اللَّعْنَةِ بِالْإِبْعَادِ أَوٍ الْغَضَبِ بِالسَّخَطِ لَمْ يَصِحَّ."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"za217","title":"كِتَابُ اللِّعَانِ · فَصْلٌ","units":[{"id":"za217_1","label":"كِتَابُ اللِّعَانِ · فَصْلٌ · ١","segs":[["matn","وَإِنْ قَذَفَ زَوْجَتَهُ الصَّغِيرَةَ أَوِ الْمَجْنُونَةَ عُزِّرَ وَلَا لِعَانَ، وَمِنْ شَرْطِهِ قَذْفُهَا بِالزِّنَا لَفْظًا كَزَنَيْتِ أَوْ يَا زَانِيَةُ أَوْ رَأَيْتُكِ تَزْنِينَ فِي قُبُلٍ أَوْ دُبُرٍ، فَإِنْ قَالَ: وُطِئْتِ بِشُبْهَةٍ أَوْ مُكْرَهَةً أَوْ نَائِمَةً،"]]},{"id":"za217_2","label":"كِتَابُ اللِّعَانِ · فَصْلٌ · ٢","segs":[["matn","أَوْ قَالَ: لَمْ تَزْنِ وَلَكِنْ لَيْسَ هَذَا الْوَلَدُ مِنِّي."]]},{"id":"za217_3","label":"كِتَابُ اللِّعَانِ · فَصْلٌ · ٣","segs":[["matn","فَشَهِدَتِ امْرَأَةٌ ثِقَةٌ أَنَّهُ وُلِدَ عَلَى فِرَاشِهِ لَحِقَهُ نَسَبُهُ وَلَا لِعَانَ، وَمِنْ شَرْطِهِ أَنْ تُكَذِّبَهُ الزَّوْجَةُ، وَإِذَا تَمَّ سَقَطَ عَنْهُ الْحَدُّ وَالتَّعْزِيرُ وَتَثْبُتُ الْفُرْقَةُ بَيْنَهُمَا بِتَحْرِيمٍ مُؤَبَّدٍ."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"za218","title":"كِتَابُ اللِّعَانِ · فَصْلٌ (٢)","units":[{"id":"za218_1","label":"كِتَابُ اللِّعَانِ · فَصْلٌ (٢) · ١","segs":[["matn","مَنْ وَلَدَتْ زَوْجَتُهُ مَنْ أَمْكَنَ أَنَّهُ مِنْهُ لَحِقَهُ، بِأَنْ تَلِدَهُ بَعْدَ نِصْفِ سَنَةٍ مُنْذُ أَمْكَنَ وَطْؤُهُ أَوْ دُونَ أَرْبَعِ سِنِينَ مُنْذُ أَبَانَهَا، وَهُوَ مِمَّنْ يُولَدُ لِمِثْلِهِ كَابْنِ عَشْرٍ،"]]},{"id":"za218_2","label":"كِتَابُ اللِّعَانِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَلَا يُحْكَمُ بِبُلُوغِهِ إِنْ شُكَّ فِيهِ وَمَنِ اعْتَرَفَ بِوَطْءِ أَمَتِهِ فِي الْفَرْجِ أَوْ دُونَهُ فَوَلَدَتْ لِنِصْفِ سَنَةٍ أَوْ أَزْيَدَ لَحِقَهُ وَلَدُهَا إِلَّا أَنْ يَدَّعِيَ الِاسْتِبْرَاءَ وَيَحْلِفَ عَلَيْهِ،"]]},{"id":"za218_3","label":"كِتَابُ اللِّعَانِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَإِنْ قَالَ: وَطِئْتُهَا دُونَ الْفَرْجِ أَوْ فِيهِ وَلَمْ أُنْزِلْ أَوْ عَزَلْتُ."]]},{"id":"za218_4","label":"كِتَابُ اللِّعَانِ · فَصْلٌ (٢) · ٤","segs":[["matn","لَحِقَهُ، وَإِنْ أَعْتَقَهَا أَوْ بَاعَهَا بَعْدَ اعْتِرَافِهِ بِوَطْئِهَا فَأَتَتْ بِوَلَدٍ لِدُونِ نِصْفِ سَنَةٍ لَحِقَهُ وَالْبَيْعُ بَاطِلٌ."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"za219","title":"كِتَابُ الْعِدَدِ","units":[{"id":"za219_1","label":"كِتَابُ الْعِدَدِ · ١","segs":[["matn","تَلْزَمُ الْعِدَّةُ كُلَّ امْرَأَةٍ فَارَقَتْ زَوْجًا خَلَا بِهَا مُطَاوِعَةً مَعَ عِلْمِهِ بِهَا وَقُدْرَتِهِ عَلَى وَطْئِهَا،"]]},{"id":"za219_2","label":"كِتَابُ الْعِدَدِ · ٢","segs":[["matn","وَلَوْ مَعَ مَا يَمْنَعُهُ مِنْهُمَا أَوْ مِنْ أَحَدِهِمَا حِسًّا أَوْ شَرْعًا أَوْ وَطِئَهَا أَوْ مَاتَ عَنْهَا حَتَّى فِي نِكَاحٍ فَاسِدٍ فِيهِ خِلَافٌ، وَإِنْ كَانَ بَاطِلًا وِفَاقًا لَمْ تَعْتَدَّ لِلْوَفَاةِ،"]]},{"id":"za219_3","label":"كِتَابُ الْعِدَدِ · ٣","segs":[["matn","وَمَنْ فَارَقَهَا حَيًّا قَبْلَ وَطْءٍ وَخَلْوَةٍ أَوْ بَعْدَهُمَا، أَوْ أَحَدِهِمَا وَهُوَ مِمَّنْ لَا يُولَدُ لِمِثْلِهِ أَوْ تَحَمَّلَتْ بِمَاءِ الزَّوْجِ أَوْ قَبَّلَهَا أَوْ لَمَسَهَا بِلَا خَلْوَةٍ فَلَا عِدَّةَ."]]}],"group":"كِتَابُ الْعِدَدِ"},{"id":"za220","title":"كِتَابُ الْعِدَدِ · فَصْلٌ","units":[{"id":"za220_1","label":"كِتَابُ الْعِدَدِ · فَصْلٌ · ١","segs":[["matn","وَالْمُعْتَدَّاتُ سِتٌّ: الْحَامِلُ وَعِدَّتُهَا مِنْ مَوْتٍ وَغَيْرِهِ إِلَى وَضْعِ كُلِّ الْحَمْلِ بِمَا تَصِيرُ بِهِ أَمَةٌ أُمَّ وَلَدٍ، فَإِنْ لَمْ يَلْحَقْهُ لِصِغَرِهِ أَوْ لِكَوْنِهِ مَمْسُوحًا أَوْ وَلَدَتْ لِدُونِ سِتَّةِ أَشْهُرٍ مُنْذُ نَكَحَهَا،"]]},{"id":"za220_2","label":"كِتَابُ الْعِدَدِ · فَصْلٌ · ٢","segs":[["matn","وَنَحْوَهُ وَعَاشَ لَمْ تَنْقَضِ بِهِ، وَأَكْثَرُ مُدَّةِ الْحَمْلِ أَرْبَعُ سِنِينَ وَأَقَلُّهَا سِتَّةُ أَشْهُرٍ وَغَالِبُهَا تِسْعَةُ وَيُبَاحُ إِلْقَاءُ النُّطْفَةِ قَبْلَ أَرْبَعِينَ يَوْمًا بِدَوَاءٍ مُبَاحٍ."]]}],"group":"كِتَابُ الْعِدَدِ"},{"id":"za221","title":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢)","units":[{"id":"za221_1","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ١","segs":[["matn","الثَّانِيةُ الْمُتَوَفَّى عَنْهَا زَوْجُهَا بِلَا حَمْلٍ مِنْهُ قَبْلَ الدُّخُولِ وَبَعْدَهُ، لِلْحُرَّةِ أَرْبَعَةُ أَشْهُرٍ وَعَشْرَةُ وَلِلْأَمَةِ نِصْفُهَا، فَإِنْ مَاتَ زَوْجُ رَجْعِيَّةٍ فِي عِدَّةِ طَلَاقٍ سَقَطَتْ وَابْتَدَأَتْ عِدَّةَ وَفَاةٍ مُنْذُ مَاتَ،"]]},{"id":"za221_2","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَإِنْ مَاتَ فِي عِدَّةِ مَنْ أَبَانَهَا فِي الصِّحَّةِ لَمْ تَنْتَقِلْ، وَتَعْتَدُّ مَنْ أَبَانَهَا فِي مَرَضِ مَوْتِهِ الْأَطْوَلَ مِنْ عِدَّةِ وَفَاةٍ وَطَلَاقٍ مَا لَمْ تَكُنْ أَمَةً أَوْ ذِمِّيَّةً أَوْ جَاءَتْ الْبَيْنُونَةُ مِنْهَا فَلِطَلَاقٍ لَا غَيْرِهِ،"]]},{"id":"za221_3","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٣","segs":[["matn","وَإِنْ طَلَّقَ بَعْضَ نِسَائِهِ مُبْهَمَةً أَوْ مُعَيَّنَةً ثُمَّ أُنْسِيَهَا ثُمَّ مَاتَ قَبْلَ قُرْعَةٍ اعْتَدَّ كُلٌّ مِنْهُنَّ سِوَى حَامِلٍ الْأَطْوَلَ مِنْهُمَا."]]},{"id":"za221_4","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٤","segs":[["matn","الثَّالِثَةُ الْحَائِلُ ذَاتُ الْأَقْرَاءِ وَهِيَ الْحِيَضُ الْمُفَارَقَةُ فِي الْحَيَاةِ، فَعِدَّتُهَا إِنْ كَانَتْ حُرَّةً أَوْ مُبَعَّضَةً ثَلَاثَةُ قُرُوءٍ كَامِلَةٌ، وَإِلَّا قَرْءَانِ."]]},{"id":"za221_5","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٥","segs":[["matn","الرَّابِعَةُ مَنْ فَارَقَهَا حَيًّا وَلَمْ تَحِضْ لِصِغَرٍ أَوْ إِيَاسٍ، فَتَعْتَدُّ حُرَّةٌ ثَلَاثَةَ أَشْهُرٍ وَأَمَةٌ شَهْرَانِ، وَمُبَعَّضَةٌ بِالْحِسَابِ، وَيُجْبَرُ الْكَسْرُ."]]},{"id":"za221_6","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٦","segs":[["matn","الْخَامِسَةُ مَنِ ارْتَفَعَ حَيْضُهَا وَلَمْ تَدْرِ سَبَبَهُ فَعِدَّتُهَا سَنَةٌ: تِسْعَةُ أَشْهُرٍ لِلْحَمْلِ وَثَلَاثَةٌ لِلْعِدَّةِ، وَتَنْقُصُ الْأَمَةُ شَهْرًا، وَعِدَّةُ مَنْ بَلَغَتْ وَلَمْ تَحِضْ وَالْمُسْتَحَاضَةِ النَّاسِيَةِ وَالْمُسْتَحَاضَةِ الْمُبْتَدَأَةِ ثَلَاثَةُ أَشْهُرٍ، وَالْأَمَةُ شَهْرَانِ،"]]},{"id":"za221_7","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٧","segs":[["matn","وَإِنْ عَلِمَتْ مَا رَفَعَهُ مِنْ مَرَضٍ أَوْ رَضَاعٍ أَوْ غَيْرِهِمَا فَلَا تَزَالُ فِي عِدَّةٍ حَتَّى يَعُودَ الْحَيْضُ فَتَعْتَدَّ بِهِ أَوْ تَبْلُغَ سِنَّ الْإِيَاسِ فَتَعْتَدَّ عِدَّتَهُ."]]},{"id":"za221_8","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٨","segs":[["matn","السَّادِسَةُ امْرَأَةُ الْمَفْقُودِ تَتَرَبَّصُ مَا تَقَدَّمَ فِي مِيرَاثِهِ، ثُمَّ تَعْتَدُّ لِلْوَفَاةِ، وَأَمَةٌ كَحُرَّةٍ فِي التَّرَبُّصِ، وَفِي الْعِدَّةِ نِصْفُ عِدَّةِ الْحُرَّةِ، وَلَا تَفْتَقِرُ إِلَى حُكْمِ حَاكِمٍ بِضَرْبِ الْمُدَّةِ وَعِدَّةِ الْوَفَاةِ،"]]},{"id":"za221_9","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ٩","segs":[["matn","وَإِنْ تَزَوَّجَتْ فَقَدِمَ الْأَوَّلُ قَبْلَ وَطْءِ الثَّانِي فَهِيَ لِلْأَوَّلِ، وَبَعْدَهُ لَهُ أَخْذُهَا زَوْجَةً بِالْعَقْدِ الْأَوَّلِ، وَلَوْ لَمْ يُطَلِّقِ الثَّانِي، وَلَا يَطَأُ قَبْلَ فَرَاغِ عِدَّةِ الثَّانِي، وَلَهُ تَرْكُهَا مَعَهُ مِنْ غَيْرِ تَجْدِيدِ عَقْدٍ،"]]},{"id":"za221_10","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٢) · ١٠","segs":[["matn","وَيَأْخُذُ قَدْرَ الصَّدَاقِ الَّذِي أَعْطَاهَا مِنَ الثَّانِي، وَيَرْجِعُ الثَّانِي عَلَيْهَا بِمَا أَخَذَهُ مِنْهُ."]]}],"group":"كِتَابُ الْعِدَدِ"},{"id":"za222","title":"كِتَابُ الْعِدَدِ · فَصْلٌ (٣)","units":[{"id":"za222_1","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٣) · ١","segs":[["matn","وَمَنْ مَاتَ زَوْجُهَا الْغَائِبُ أَوْ طَلَّقَ اعْتَدَّتْ مُنْذُ الْفُرْقَةِ وَإِنْ لَمْ تُحِدَّ، وَعِدَّةُ مَوْطُوءَةٍ بِشُبْهَةٍ أَوْ زِنًا أَوْ بِعَقْدٍ فَاسِدٍ كَمُطَلَّقَةٍ،"]]},{"id":"za222_2","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٣) · ٢","segs":[["matn","وَإِنْ وُطِئَتْ مُعْتَدَّةٌ بِشُبْهَةٍ أَوْ نِكَاحٍ فَاسِدٍ فُرِّقَ بَيْنَهُمَا وَأَتَمَّتْ عِدَّةَ الْأَوَّلِ وَلَا يُحْتَسَبُ مِنْهَا مُقَامُهَا عِنْدَ الثَّانِي ثُمَّ اعْتَدَّتْ لِلثَّانِي، وَتَحِلُّ لَهُ بِعَقْدٍ بَعْدَ انْقِضَاءِ الْعِدَّتَيْنِ،"]]},{"id":"za222_3","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٣) · ٣","segs":[["matn","وَإِنْ تَزَوَّجَتْ فِي عِدَّتِهَا لَمْ تَنْقَطِعْ حَتَّى يَدْخُلَ بِهَا، فَإِذَا فَارَقَهَا بَنَتْ عَلَى عِدَّتِهَا مِنَ الْأَوَّلِ، ثُمَّ اسْتَأْنَفَتِ الْعِدَّةَ مِنَ الثَّانِي، وَإِنْ أَتَتْ بِوَلَدٍ مِنْ أَحَدِهِمَا انْقَضَتْ مِنْهُ عِدَّتُهَا بِهِ ثُمَّ اعْتَدَّتْ لِلْآخَرِ،"]]},{"id":"za222_4","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٣) · ٤","segs":[["matn","وَمَنْ وَطِئَ مُعْتَدَّتَهُ الْبَائِنَ بِشُبْهَةٍ اسْتَأْنَفَتِ الْعِدَّةَ بِوَطْئِهِ، وَدَخَلَتْ فِيهَا بَقِيَّةُ الْأُولَى، وَإِنْ نَكَحَ مَنْ أَبَانَهَا فِي عِدَّتِهَا ثُمَّ طَلَّقَهَا قَبْلَ الدُّخُولِ بَنَتْ."]]}],"group":"كِتَابُ الْعِدَدِ"},{"id":"za223","title":"كِتَابُ الْعِدَدِ · فَصْلٌ (٤)","units":[{"id":"za223_1","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٤) · ١","segs":[["matn","يَلْزَمُ الْإِحْدَادُ مُدَّةَ الْعِدَّةِ كُلَّ مُتَوَفًّى زَوْجُهَا عَنْهَا فِي نِكَاحٍ صَحِيحٍ، وَلَوْ ذِمِّيَّةً أَوْ أَمَةً أَوْ غَيْرَ مُكَلَّفَةٍ، وَيُبَاحُ لِبَائِنٍ مِنْ حَيٍّ، وَلَا يَجِبُ عَلَى رَجْعِيَّةٍ وَمَوْطُوءَةٍ بِشُبْهَةٍ أَوْ زِنًا أَوْ فِي نِكَاحٍ فَاسِدٍ أَوْ بَاطِلٍ أَوْ مِلْكِ يَمِينٍ."]]},{"id":"za223_2","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٤) · ٢","segs":[["matn","وَالْإِحْدَادُ اجْتِنَابُ مَا يَدْعُو إِلَى جِمَاعِهَا وَيُرَغِّبُهُ فِي النَّظَرِ إِلَيْهَا مِنَ الزِّينَةِ وَالطِّيبِ وَالتَّحْسِينِ وَالْحِنَّاءِ وَمَا صُبِغَ لِلزِّينَةِ، وَحُلِيٍّ وَكُحْلٍ أَسْوَدَ، لَا تُوتِياءَ وَنَحْوِهَا وَلَا نِقَابٍ، وَأَبْيَضَ وَلَوْ كَانَ حَسَنًا،"]]},{"id":"za223_3","label":"كِتَابُ الْعِدَدِ · فَصْلٌ (٤) · ٣","segs":[["matn","فَصْلٌ وَتَجِبُ عِدَّةُ الْوَفَاةِ فِي الْمَنْزِلِ حَيْثُ وَجَبَتْ، فَإِنْ تَحَوَّلَتْ خَوْفًا أَوْ قَهْرًا أَوْ بِحَقٍّ انْتَقَلَتْ حَيْثُ شَاءَتْ، وَلَهَا الْخُرُوجُ لِحَاجَتِهَا نَهَارًا لَا لَيْلًا، وَإِنْ تَرَكَتِ الْإِحْدَادَ أَثِمَتْ، وَتَمَّتْ عِدَّتُهَا بِمُضِيِّ زَمَانِهَا."]]}],"group":"كِتَابُ الْعِدَدِ"},{"id":"za224","title":"بَابُ الِاسْتِبْرَاءِ","units":[{"id":"za224_1","label":"بَابُ الِاسْتِبْرَاءِ · ١","segs":[["matn","مَنْ مَلَكَ أَمَةً يُوطَأُ مِثْلُهَا مِنْ صَغِيرٍ وَذَكَرٍ وَضِدِّهِمَا حَرُمَ عَلِيْهِ وَطْؤُهَا وَمُقَدِّمَاتُهُ قَبْلَ اسْتِبْرَائِهَا، وَاسْتِبْرَاءُ الْحَامِلِ بِوَضْعِهَا، وَمَنْ تَحِيضُ بِحَيْضَةٍ، وَالْآيِسَةِ وَالصَّغِيرَةِ بِمُضِيِّ شَهْرٍ."]]}],"group":"كِتَابُ الْعِدَدِ"},{"id":"za225","title":"كِتَابُ الرَّضَاعِ","units":[{"id":"za225_1","label":"كِتَابُ الرَّضَاعِ · ١","segs":[["matn","يَحْرُمُ مِنَ الرَّضَاعِ مَا يَحْرُمُ مِنَ النَّسَبِ، وَالْمُحَرِّمُ خَمْسُ رَضَعَاتٍ فِي الْحَوْلَيْنِ، وَالسَّعُوطُ وَالْوَجُورُ وَلَبَنُ الْمَيْتَةِ وَالْمَوْطُوءَةِ بِشُبْهَةٍ أَوْ بِعَقْدٍ فَاسِدٍ أَوْ بَاطِلٍ أَوْ زِنًا مُحَرِّمٌ، وَعَكْسُهُ الْبَهِيمَةُ وَغَيْرُ حُبْلَى وَلَا مَوْطُوءَةٍ،"]]},{"id":"za225_2","label":"كِتَابُ الرَّضَاعِ · ٢","segs":[["matn","فَمَتَى أَرْضَعَتِ امْرَأَةٌ طِفْلًا صَارَ وَلَدَهَا فِي النِّكَاحِ وَالنَّظَرِ وَالْخَلْوَةِ وَالْمَحْرَمِيَّةِ، وَوَلَدَ مَنْ نُسِبَ لَبَنُهَا إِلَيْهِ بِحَمْلٍ أَوْ وَطْءٍ، وَمَحَارِمُهُ مَحَارِمَهُ وَمَحَارِمُهَا مَحَارِمَهُ دُونَ أَبَوَيْهِ وَأُصُولِهِمَا وَفُرُوعِهِمَا، فَتُبَاحُ الْمُرْضِعَةُ لِأَبِي الْمُرْتَضِعِ وَأَخِيهِ مِنَ النَّسَبِ،"]]},{"id":"za225_3","label":"كِتَابُ الرَّضَاعِ · ٣","segs":[["matn","وَأُمُّهُ وَأُخْتُهُ مِنَ النَّسَبِ لِأَبِيهِ وَأَخِيهِ، وَمَنْ حَرُمَتْ عَلَيْهِ بِنْتُهَا فَأَرْضَعَتْ طِفْلَةً حَرَّمَتْهَا عَلَيْهِ وَفَسَخَتْ نِكَاحَهَا مِنْهُ إِنْ كَانَتْ زَوْجَتَهُ، وَكُلُّ امْرَأَةٍ أَفْسَدَتْ نِكَاحَ نَفْسِهَا بِرَضَاعٍ قَبْلَ الدُّخُولِ فَلَا مَهْرَ لَهَا،"]]},{"id":"za225_4","label":"كِتَابُ الرَّضَاعِ · ٤","segs":[["matn","وَكَذَا إِنْ كَانَتْ طِفْلَةً فَدَبَّتْ فَرَضَعَتْ مِنْ نَائِمَةٍ، وَبَعْدَ الدُّخُولِ مَهْرُهَا بِحَالِهِ، وَإِنْ أَفْسَدَهُ غَيْرُهَا فَلَهَا عَلَى الزَّوْجِ نِصْفُ الْمُسَمَّى قَبْلَهُ وَجَمِيعُهُ بَعْدَهُ، وَيَرْجِعُ الزَّوْجُ بِهِ عَلَى الْمُفْسِدِ، وَمَنْ قَالَ لِزَوْجَتِهِ: أَنْتِ أُخْتِي لِرَضَاعٍ."]]},{"id":"za225_5","label":"كِتَابُ الرَّضَاعِ · ٥","segs":[["matn","بَطَلَ النِّكَاحُ، فَإِنْ كَانَ قَبْلَ الدُّخُولِ وَصَدَّقَتْهُ فَلَا مَهْرَ، وَإِنْ أَكْذَبَتْهُ فَلَهَا نِصْفُهُ، وَيَجِبُ كُلُّهُ بَعْدَهُ، وَإِنْ قَالَتْ هِيَ ذَلِكَ وَأَكْذَبَهَا فَهِيَ زَوْجَتُهُ حُكْمًا، وَإِذَا شُكَّ فِي الرَّضَاعِ أَوْ كَمَالِهِ أَوْ شَكَّتِ الْمُرْضِعَةُ وَلَا بَيِّنَةَ فَلَا تَحْرِيمَ."]]}],"group":"كِتَابُ الرَّضَاعِ"},{"id":"za226","title":"كِتَابُ النَّفَقَاتِ","units":[{"id":"za226_1","label":"كِتَابُ النَّفَقَاتِ · ١","segs":[["matn","يَلْزَمُ الزَّوْجَ نَفَقَةُ زَوْجَتِهِ قُوتًا وَكِسْوَةً وَسُكْنَاهَا بِمَا يَصْلُحُ لِمِثْلِهَا، وَيَعْتَبِرُ الْحَاكِمُ ذَلِكَ بِحَالِهِمَا عِنْدَ التَّنَازُعِ، فَيَفْرِضُ لِلْمُوسِرَةِ تَحْتَ الْمُوسِرِ قَدْرَ كِفَايَتِهَا مِنْ أَرْفَعِ خُبْزِ الْبَلَدِ وَأُدْمِهِ وَلَحْمًا عَادَةَ الْمُوسِرِينَ بِمَحَلِّهِمَا،"]]},{"id":"za226_2","label":"كِتَابُ النَّفَقَاتِ · ٢","segs":[["matn","وَمَا يَلْبَسُ مِثْلُهَا مِنْ حَرِيرٍ وَغَيْرِهِ، وَلِلنَّوْمِ فِرَاشٌ وَلِحَافٌ وَإِزَارٌ وَمِخَدَّةٌ، وَلِلْجُلُوسِ حَصِيرٌ جَيِّدٌ وَزِلِّيٌّ، وَلِلْفَقِيرَةِ تَحْتَ الْفَقِيرِ مِنْ أَدْنَى خُبْزِ الْبَلَدِ وَأُدْمٍ يُلَائِمُهُ، وَمَا يَلْبَسُ مِثْلُهَا وَيَجْلِسُ عَلَيْهِ."]]},{"id":"za226_3","label":"كِتَابُ النَّفَقَاتِ · ٣","segs":[["matn","وَلِلْمُتَوَسِّطَةِ مَعَ الْمُتَوَسِّطِ وَالْغَنِيَّةِ مَعَ الْفَقِيرِ، وَعَكْسِهِا مَا بَيْنَ ذَلِكَ عُرْفًا، وَعَلَيْهِ مُؤْنَةُ نَظَافَةِ زَوْجَتِهِ دُونَ خَادِمِهَا، لَا دَوَاءَ وَأُجْرَةَ طَبِيبٍ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za227","title":"كِتَابُ النَّفَقَاتِ · فَصْلٌ","units":[{"id":"za227_1","label":"كِتَابُ النَّفَقَاتِ · فَصْلٌ · ١","segs":[["matn","وَنَفَقَةُ الْمُطَلَّقَةِ الرَّجْعِيَّةِ وَكِسْوَتُهَا وَسُكْنَاهَا كَالزَّوْجَةِ، وَلَا قَسْمَ لَهَا، وَالْبَائِنُ بِفَسْخٍ أَوْ طَلَاقٍ لَهَا ذَلِكَ إِنْ كَانَتْ حَامِلًا، وَالنَّفَقَةُ لِلْحَمْلِ لَا لَهَا مِنْ أَجْلِهِ، وَمَنْ حُبِسَتْ وَلَوْ ظُلْمًا أَوْ نَشَزَتْ أَوْ تَطَوَّعَتْ بِلَا إِذْنِهِ،"]]},{"id":"za227_2","label":"كِتَابُ النَّفَقَاتِ · فَصْلٌ · ٢","segs":[["matn","بِصَوْمٍ أَوْ حَجٍّ أَوْ أَحْرَمَتْ بِنَذْرِ حَجٍّ أَوْ صَوْمٍ أَوْ صَامَتْ عَنْ كَفَّارَةٍ أَوْ قَضَاءِ رَمَضَانَ مَعَ سَعَةِ وَقْتِهِ، أَوْ سَافَرَتْ لِحَاجَتِهَا وَلَوْ بِإِذْنِهِ سَقَطَتْ، وَلَا نَفَقَةَ وَلَا سُكْنَى لِمُتَوَفًّى عَنْهَا،"]]},{"id":"za227_3","label":"كِتَابُ النَّفَقَاتِ · فَصْلٌ · ٣","segs":[["matn","وَلَهَا أَخْذُ نَفَقَةِ كُلِّ يَوْمٍ مِنْ أَوَّلِهِ لَا قِيمَتُهَا، وَلَا عَلَيْهَا أَخْذُهَا، فَإِنِ اتَّفَقَا عَلَيْهِ أَوْ عَلَى تَأْخِيرِهَا أَوْ تَعْجِيلِهَا مُدَّةً طَوِيلَةً أَوْ قَلِيلَةً جَازَ، وَلَهَا الْكِسْوَةُ كُلَّ عَامٍ مَرَّةً فِي أَوَّلِهِ،"]]},{"id":"za227_4","label":"كِتَابُ النَّفَقَاتِ · فَصْلٌ · ٤","segs":[["matn","وَإِذَا غَابَ وَلَمْ يُنْفِقْ لَزِمَتْهُ نَفَقَةُ مَا مَضَى، وَإِنْ أَنْفَقَتْ فِي غَيْبَتِهِ مِنْ مَالِهِ فَبَانَ مَيِّتًا غَرَّمَهَا الْوَارِثُ مَا أَنْفَقَتْهُ بَعْدَ مَوْتِهِ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za228","title":"كِتَابُ النَّفَقَاتِ · فَصْلٌ (٢)","units":[{"id":"za228_1","label":"كِتَابُ النَّفَقَاتِ · فَصْلٌ (٢) · ١","segs":[["matn","وَمَنْ تَسَلَّمَ زَوْجَتَهُ أَوْ بَذَلَتْ نَفْسَهَا وَمِثْلُهَا يُوطَأُ وَجَبَتْ نَفَقَتُهَا، وَلَوْ مَعَ صِغَرِ زَوْجٍ وَمَرَضِهِ وَجَبِّهِ وَعُنَّتِهِ، وَلَهَا مَنْعُ نَفْسِهَا حَتَّى تَقْبِضَ صَدَاقَهَا الْحَالَّ، فَإِنْ سَلَّمَتْ نَفْسَهَا طَوْعًا ثُمَّ أَرَادَتِ الْمَنْعَ لَمْ تَمْلِكْهُ،"]]},{"id":"za228_2","label":"كِتَابُ النَّفَقَاتِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَإِذَا أَعْسَرَ بِنَفَقَةِ الْقُوتِ أَوْ الْكِسْوَةِ أَوْ بَعْضِهَا أَوْ الْمَسْكَنِ فَلَهَا فَسْخُ النِّكَاحِ، فَإِنْ غَابَ وَلَمْ يَدَعْ لَهَا نَفَقَةً وَتَعَذَّرَ أَخْذُهَا مِنْ مَالِهِ وَاسْتِدَانَتُهَا عَلَيْهِ فَلَهَا الْفَسْخُ بِإِذْنِ حَاكِمٍ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za229","title":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ","units":[{"id":"za229_1","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ١","segs":[["matn","تَجِبُ أَوْ تَتِمَّتُهَا لِأَبَوَيْهِ وَإِنْ عَلَوْا وَلِوَلَدِهِ وَإِنْ سَفَلَ، حَتَّى ذَوِي الْأَرْحَامِ مِنْهُمْ حَجَبَهُ مُعْسِرٌ أَوْ لَا، وَكُلُّ مَنْ يَرِثُهُ بِفَرْضٍ أَوْ تَعْصِيبٍ، لَا بِرَحِمٍ سِوَى عَمُودَيْ نَسَبِهِ،"]]},{"id":"za229_2","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٢","segs":[["matn","سَوَاءٌ وَرِثَهُ الْآخَرُ كَأَخٍ أَوْ لَا كَعَمَّةٍ وَعَتِيقٍ بِمَعْرُوفٍ مَعَ فَقْرِ مَنْ تَجِبُ لَهُ وَعَجْزِهِ عَنْ تَكَسُّبٍ إِذَا فَضَلَ عَنْ قُوتِ نَفْسِهِ وَزَوْجَتِهِ وَرَقِيقِهِ يَوْمَهُ وَلَيْلَتَهُ وَكِسْوَةٍ وَسُكْنَى مِنْ حَاصِلٍ أَوْ مُتَحَصِّلٍ لَا مِنْ رَأْسِ مَالٍ وَثَمَنِ مِلْكٍ وَآلَةِ صَنْعَةٍ وَمَنْ لَهُ وَارِثٌ غَيْرُ أَبٍ فَنَفَقَتُهُ عَلَيْهِمْ عَلَى قَدْرِ إِرْثِهِمْ،"]]},{"id":"za229_3","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٣","segs":[["matn","فَعَلَى الْأُمِّ الثُّلُثُ وَالثُّلُثَانِ عَلَى الْجَدِّ، وَعَلَى الْجَدَّةِ السُّدُسُ وَالْبَاقِي عَلَى الْأَخِ، وَالْأَبُ يَنْفَرِدُ بِنَفَقَةِ وَلَدِهِ، وَمَنْ لَهُ ابْنٌ فَقِيرٌ وَأَخٌ مُوسِرٌ فَلَا نَفَقَةَ لَهُ عَلَيْهِمَا، وَمَنْ أُمُّهُ فَقِيرَةٌ وَجَدَّتُهُ مُوسِرَةٌ فَنَفَقَتُهُ عَلَى الْجَدَّةِ،"]]},{"id":"za229_4","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٤","segs":[["matn","وَمَنْ عَلَيْهِ نَفَقَةُ زَيْدٍ فَعَلَيْهِ نَفَقَةُ زَوْجَتِهِ كَظِئْرٍ لِحَوْلَيْنِ، وَلَا نَفَقَةَ مَعَ اخْتِلَافِ دِينٍ إِلَّا بِالْوَلَاءِ، وَعَلَى الْأَبِ أَنْ يَسْتَرْضِعَ لِوَلَدِهِ وَيُؤَدِّيَ الْأُجْرَةِ، وَلَا يَمْنَعَ أُمَّهُ إِرْضَاعَهُ، وَلَا يَلْزَمُهَا إِلَّا لِضَرُورَةٍ كَخَوْفِ تَلَفِهِ،"]]},{"id":"za229_5","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٥","segs":[["matn","وَلَهَا طَلَبُ أُجْرَةِ الْمِثْلِ وَلَوْ أَرْضَعَهُ غَيْرُهَا مَجَّانًا بَائِنًا كَانَتْ أَوْ تَحْتَهُ، وَإِنْ تَزَوَّجَتْ آخَرَ فَلَهُ مَنْعُهَا مِنْ إِرْضَاعِ وَلَدِ الْأَوَّلِ مَا لَمْ يُضْطَرَّ إِلَيْهَا."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za230","title":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · فَصْلٌ","units":[{"id":"za230_1","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · فَصْلٌ · ١","segs":[["matn","وَعَلَيْهِ نَفَقَةُ رَقِيقِهِ طَعَامًا وَكِسْوَةً وَسُكْنَى، وَأَلَّا يُكَلِّفَهُ مُشِقًّا كَثِيرًا، وَإِنِ اتَّفَقَا عَلَى الْمُخَارَجَةِ جَازَ، وَيُرِيحُهُ وَقْتَ الْقَائِلَةِ وَالنَّوْمِ وَالصَّلَاةِ، وَيُرْكِبُهُ فِي السَّفَرِ عُقْبَةً، وَإِنْ طَلَبَ نِكَاحًا زَوَّجَهُ أَوْ بَاعَهُ، وَإِنْ طَلَبَتْهُ أَمَةٌ وَطِئَهَا أَوْ زَوَّجَهَا أَوْ بَاعَهَا."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za231","title":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · فَصْلٌ (٢)","units":[{"id":"za231_1","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · فَصْلٌ (٢) · ١","segs":[["matn","وَعَلَيْهِ عَلَفُ بَهَائِمِهِ وَسَقْيُهَا وَمَا يُصْلِحُهَا، وَأَنْ لَا يُحَمِّلَهَا مَا تَعْجِزُ عَنْهُ، وَلَا يَحْلِبَ مِنْ لَبَنِهَا مَا يَضُرُّ وَلَدَهَا، فَإِنْ عَجَزَ عَنْ نَفَقَتِهَا أُجْبِرَ عَلَى بَيْعِهَا أَوْ إِجَارَتِهَا أَوْ ذَبْحِهَا إِنْ أُكِلَتْ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za232","title":"بَابُ الْحَضَانَةِ","units":[{"id":"za232_1","label":"بَابُ الْحَضَانَةِ · ١","segs":[["matn","تَجِبُ لِحِفْظِ صَغِيرٍ وَمَعْتُوهٍ وَمَجْنُونٍ، وَالْأَحَقُّ بِهَا أُمٌّ ثُمَّ أُمَّهَاتُهَا الْقُرْبَى فَالْقُرْبَى، ثُمَّ أَبٌ ثُمَّ أُمَّهَاتُهُ كَذَلِكَ، ثُمَّ جَدٌّ ثُمَّ أُمَّهَاتُهُ كَذَلِكَ، ثُمَّ أُخْتٌ لِأَبَوَيْنِ، ثُمَّ لِأَمٍّ ثُمَّ لِأَبٍ ثُمَّ خَالَةٌ لِأَبَوَيْنِ،"]]},{"id":"za232_2","label":"بَابُ الْحَضَانَةِ · ٢","segs":[["matn","ثُمَّ لِأَمٍّ ثُمَّ لِأَبٍ ثُمَّ عَمَّاتٌ كَذَلِكَ، ثُمَّ خَالَاتُ أُمِّهِ، ثُمَّ خَالَاتُ أَبِيهِ ثُمَّ عَمَّاتُ أَبِيهِ، ثُمَّ بَنَاتُ إِخْوَتِهِ وَأَخَوَاتِهِ، ثُمَّ بَنَاتُ أَعْمَامِهِ وَعَمَّاتِهِ، ثُمَّ بَنَاتُ أَعْمَامِ أَبِيهِ وَبَنَاتُ عَمَّاتِ أَبِيهِ،"]]},{"id":"za232_3","label":"بَابُ الْحَضَانَةِ · ٣","segs":[["matn","ثُمَّ لِبَاقِي الْعَصَبَةِ الْأَقْرَبَ فَالْأَقْرَبَ، فَإِنْ كَانَتْ أُنْثَى فَمِنْ مَحَارِمِهَا، ثُمَّ لِذَوِي أَرْحَامِهِ، ثُمَّ لِلْحَاكِمِ وَإِنِ امْتَنَعَ مَنْ لَهُ الْحَضَانَةُ أَوْ كَانَ غَيْرَ أَهْلٍ انْتَقَلَتْ إِلَى مَنْ بَعْدَهُ، وَلَا حَضَانَةَ لِمَنْ فِيهِ رِقٌّ وَلَا لِفَاسِقٍ،"]]},{"id":"za232_4","label":"بَابُ الْحَضَانَةِ · ٤","segs":[["matn","وَلَا لِكَافِرٍ، وَلَا لِمُزَوَّجَةٍ بِأَجْنَبِيٍّ مِنْ مَحْضُونٍ مِنْ حِينِ عَقْدٍ، فَإِنْ زَالَ الْمَانِعُ رَجَعَ إِلَى حَقِّهِ، وَإِنْ أَرَادَ أَحَدُ أَبَوَيْهِ سَفَرًا طَوِيلًا إِلَى بَلَدٍ بَعِيدٍ لِيَسْكُنَهُ، وَهُوَ وَطَرِيقُهُ آمِنَانِ، فَحَضَانَتُهُ لِأَبِيهِ،"]]},{"id":"za232_5","label":"بَابُ الْحَضَانَةِ · ٥","segs":[["matn","وَإِنْ بَعُدَ السَّفَرُ لِحَاجَةٍ أَوْ قَرُبَ لَهَا أَوْ لِلسُّكْنَى فَلِأُمِّهِ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za233","title":"بَابُ الْحَضَانَةِ · فَصْلٌ","units":[{"id":"za233_1","label":"بَابُ الْحَضَانَةِ · فَصْلٌ · ١","segs":[["matn","وَإِذَا بَلَغَ الْغُلَامُ سَبْعَ سِنِينَ عَاقِلًا خُيِّرَ بَيْنَ أَبَوَيْهِ فَكَانَ مَعَ مَنِ اخْتَارَ مِنْهُمَا، وَلَا يُقَرُّ بِيَدِ مَنْ لَا يَصُونُهُ وَيُصْلِحُهُ، وَأَبُو الْأُنْثَى أَحَقُّ بِهَا بَعْدَ السَّبْعِ، وَيَكُونُ الذَّكَرُ بَعْدَ رُشْدِهِ حَيْثُ شَاءَ، وَالْأُنْثَى عِنْدَ أَبِيهَا حَتَّى يَتَسَلَّمَهَا زَوْجُهَا."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"za234","title":"كِتَابُ الْجِنَايَاتِ","units":[{"id":"za234_1","label":"كِتَابُ الْجِنَايَاتِ · ١","segs":[["matn","وَهِيَ عَمْدٌ يَخْتَصُّ الْقَوَدُ بِهِ بِشَرْطِ الْقَصْدِ، وَشِبْهُ عَمْدٍ، وَخَطَأٌ."]]},{"id":"za234_2","label":"كِتَابُ الْجِنَايَاتِ · ٢","segs":[["matn","فَالْعَمْدُ أَنْ يَقْصِدَ مَنْ يَعْلَمُهُ آدَمِيًّا مَعْصُومًا فَيَقْتُلَهُ بِمَا يَغْلِبُ عَلَى الظَّنِّ مَوْتُهُ بِهِ، مِثْلُ أَنْ يَجْرَحَهُ بِمَا لَهُ مَوْرٌ فِي الْبَدَنِ، أَوْ يَضْرِبَهُ بِحَجَرٍ كَبِيرٍ وَنَحْوِهِ،"]]},{"id":"za234_3","label":"كِتَابُ الْجِنَايَاتِ · ٣","segs":[["matn","أَوْ يُلْقِيَ عَلَيْهِ حَائِطًا أَوْ يُلْقِيَهُ مِنْ شَاهِقٍ أَوْ فِي نَارٍ، أَوْ مَاءٍ يُغْرِقُهُ، وَلَا يُمْكِنُهُ التَّخَلُّصُ مِنْهُمَا، أَوْ يَخْنِقَهُ، أَوْ يَحْبِسَهُ وَيَمْنَعَهُ الطَّعَامَ أَوْ الشَّرَابَ، فَيَمُوتَ مِنْ ذَلِكَ فِي مُدَّةٍ يَمُوتُ فِيهَا غَالِبًا،"]]},{"id":"za234_4","label":"كِتَابُ الْجِنَايَاتِ · ٤","segs":[["matn","أَوْ يَقْتُلَهُ بِسِحْرٍ أَوْ سُمٍّ، أَوْ شَهِدَتْ عَلَيْهِ بَيِّنَةٌ بِمَا يُوجِبُ قَتْلَهُ، ثُمَّ رَجَعُوا وَقَالُوا: عَمَدْنَا قَتْلَهُ."]]},{"id":"za234_5","label":"كِتَابُ الْجِنَايَاتِ · ٥","segs":[["matn","وَنَحْوَ ذَلِكَ. وَشِبْهُ الْعَمْدِ أَنْ يَقْصِدَ جِنَايَةً لَا تَقْتُلُ غَالِبًا وَلَمْ يَجْرَحْهُ بِهَا، كَمَنْ ضَرَبَهُ فِي غَيْرِ مَقْتَلٍ بِسَوْطٍ، أَوْ عَصَا صَغِيرَةٍ أَوْ لَكَزَهُ وَنَحْوِهِ."]]},{"id":"za234_6","label":"كِتَابُ الْجِنَايَاتِ · ٦","segs":[["matn","وَالْخَطَأُ أَنْ يَفْعَلَ مَا لَهُ فِعْلُهُ، مِثْلَ: أَنْ يَرْمِيَ صَيْدًا أَوْ غَرَضًا أَوْ شَخْصًا فَيُصِيبَ آدَمِيًّا لَمْ يَقْصِدْهُ، وَعَمْدُ الصَّبِيِّ وَالْمَجْنُونِ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za235","title":"كِتَابُ الْجِنَايَاتِ · فَصْلٌ","units":[{"id":"za235_1","label":"كِتَابُ الْجِنَايَاتِ · فَصْلٌ · ١","segs":[["matn","تُقْتَلُ الْجَمَاعَةُ بِالْوَاحِدِ، وَإِنْ سَقَطَ الْقَوَدُ أَدَّوْا دِيَةً وَاحِدَةً، وَمَنْ أَكْرَهَ مُكَلَّفًا عَلَى قَتْلِ مُكَافِئِهِ فَقَتَلَهُ، فَالْقَتْلُ أَوِ الدِّيَةُ عَلَيْهِمَا،"]]},{"id":"za235_2","label":"كِتَابُ الْجِنَايَاتِ · فَصْلٌ · ٢","segs":[["matn","وَإِنْ أَمَرَ بِالْقَتْلِ غَيْرَ مُكَلَّفٍ أَوْ مُكَلَّفًا يَجْهَلُ تَحْرِيمَهُ أَوْ أَمَرَ بِهِ السُّلْطَانُ ظُلْمًا مَنْ لَا يَعْرِفُ ظُلْمَهُ فِيهِ فَقَتَلَ فَالْقَوَدُ أَوِ الدِّيَةُ عَلَى الْآمِرِ،"]]},{"id":"za235_3","label":"كِتَابُ الْجِنَايَاتِ · فَصْلٌ · ٣","segs":[["matn","وَإِنْ قَتَلَ الْمَأْمُورُ الْمُكَلَّفُ عَالِمًا تَحْرِيمَ الْقَتْلِ فَالضَّمَانُ عَلَيْهِ دُونَ الْآمِرِ، وَإِنِ اشْتَرَكَ فِيهِ اثْنَانِ لَا يَجِبُ الْقَوَدُ عَلَى أَحَدِهِمَا مُفْرَدًا لِأُبُوَّةٍ أَوْ غَيْرِهَا فَالْقَوَدُ عَلَى الشَّرِيكِ، فَإِنْ عَدَلَ إِلَى طَلَبِ الْمَالِ لَزِمَهُ نِصْفُ الدِّيَةِ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za236","title":"بَابُ شُرُوطِ الْقِصَاصِ","units":[{"id":"za236_1","label":"بَابُ شُرُوطِ الْقِصَاصِ · ١","segs":[["matn","وَهِيَ أَرْبَعَةٌ: عِصْمَةُ الْمَقْتُولِ فَلَوْ قَتَلَ مُسْلِمٌ أَوْ ذِمِّيٌّ حَرْبِيًّا أَوْ مُرْتَدًّا لَمْ يَضْمَنْهُ بِقِصَاصٍ وَلَا دِيَةٍ."]]},{"id":"za236_2","label":"بَابُ شُرُوطِ الْقِصَاصِ · ٢","segs":[["matn","الثَّانِي التَّكْلِيفُ فَلَا قِصَاصَ عَلَى صَغِيرٍ وَلَا مَجْنُونٍ."]]},{"id":"za236_3","label":"بَابُ شُرُوطِ الْقِصَاصِ · ٣","segs":[["matn","الثَّالِثُ الْمُكَافَأَةُ بِأَنْ يُسَاوِيَهُ فِي الدِّينِ وَالْحُرِّيَّةِ وَالرِّقِّ، فَلَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ، وَلَا حُرٌّ بِعَبْدٍ وَعَكْسُهُ يُقْتَلُ، وَيُقْتَلُ الذَّكَرُ بِالْأُنْثَى، وَالْأُنْثَى بِالذَّكَرِ."]]},{"id":"za236_4","label":"بَابُ شُرُوطِ الْقِصَاصِ · ٤","segs":[["matn","الرَّابِعُ عَدَمُ الْوِلَادَةِ فَلَا يُقْتَلُ أَحَدُ الْأَبَوَيْنِ وَإِنْ عَلَا بِالْوَلَدِ وَإِنْ سَفَلَ، وَيُقْتَلُ الْوَلَدُ بِكُلٍّ مِنْهُمَا."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za237","title":"بَابُ اسْتِيفَاءِ الْقِصَاصِ","units":[{"id":"za237_1","label":"بَابُ اسْتِيفَاءِ الْقِصَاصِ · ١","segs":[["matn","يُشْتَرَطُ لَهُ ثَلَاثَةُ شُرُوطٍ: أَحَدُهَا كَوْنُ مُسْتَحِقِّهِ مُكَلَّفًا، فَإِنْ كَانَ صَبِيًّا أَوْ مَجْنُونًا لَمْ يَسْتَوْفِ وَحُبِسَ الْجَانِي إِلَى الْبُلُوغِ وَالْإِفَاقَةِ."]]},{"id":"za237_2","label":"بَابُ اسْتِيفَاءِ الْقِصَاصِ · ٢","segs":[["matn","الثَّانِي اتِّفَاقُ الْأَوْلِياءِ الْمُشْتَرِكِينَ فِيهِ عَلَى اسْتِيفَائِهِ، وَلَيْسَ لِبَعْضِهِمْ أَنْ يَنْفَرِدَ بِهِ، وَإِنْ كَانَ مَنْ بَقِيَ غَائِبًا أَوْ صَغِيرًا أَوْ مَجْنُونًا انْتُظِرَ الْقُدُومُ وَالْبُلُوغُ وَالْعَقْلُ."]]},{"id":"za237_3","label":"بَابُ اسْتِيفَاءِ الْقِصَاصِ · ٣","segs":[["matn","الثَّالِثُ أَنْ يُؤْمَنَ فِي الِاسْتِيفَاءِ أَنْ يَتَعَدَّى الْجَانِيَ، فَإِذَا وَجَبَ عَلَى حَامِلٍ أَوْ حَائِلٍ فَحَمَلَتْ لَمْ تُقْتَلْ حَتَّى تَضَعَ الْوَلَدَ وَتُسْقِيَهُ اللَّبَأَ، ثُمَّ إِنْ وُجِدَ مَنْ يُرْضِعُهُ وَإِلَّا تُرِكَتْ حَتَّى تَفْطِمَهُ،"]]},{"id":"za237_4","label":"بَابُ اسْتِيفَاءِ الْقِصَاصِ · ٤","segs":[["matn","وَلَا يُقْتَصُّ مِنْهَا فِي الطَّرَفِ حَتَّى تَضَعَ، وَالْحَدُّ فِي ذَلِكَ كَالْقِصَاصِ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za238","title":"بَابُ اسْتِيفَاءِ الْقِصَاصِ · فَصْلٌ","units":[{"id":"za238_1","label":"بَابُ اسْتِيفَاءِ الْقِصَاصِ · فَصْلٌ · ١","segs":[["matn","وَلَا يُسْتَوْفَى قِصَاصٌ إِلَّا بِحَضْرَةِ سُلْطَانٍ أَوْ نَائِبِهِ وَآلَةٍ مَاضِيَةٍ، وَلَا يُسْتَوْفَى فِي النَّفْسُ إِلَّا بِضَرْبِ الْعُنُقِ بِسَيْفٍ وَلَوْ كَانَ الْجَانِي قَتَلَهُ بِغَيْرِهِ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za239","title":"بَابُ الْعَفْوِ عَنِ الْقِصَاصِ","units":[{"id":"za239_1","label":"بَابُ الْعَفْوِ عَنِ الْقِصَاصِ · ١","segs":[["matn","يَجِبُ بِالْعَمْدِ الْقَوَدُ أَوْ الدِّيَةُ، فَيُخَيَّرُ الْوَلِيُّ بَيْنَهُمَا، وَعَفْوُهُ مَجَّانًا أَفْضَلُ، فَإِنِ اخْتَارَ الْقَوَدَ أَوْ عَفَا عَنِ الدِّيَةِ فَقَطْ فَلَهُ أَخْذُهَا وَالصُّلْحُ عَلَى أَكْثَرَ مِنْهَا، وَإِنِ اخْتَارَهَا أَوْ عَفَا مُطْلَقًا،"]]},{"id":"za239_2","label":"بَابُ الْعَفْوِ عَنِ الْقِصَاصِ · ٢","segs":[["matn","أَوْ هَلَكَ الْجَانِي فَلَيْسَ لَهُ غَيْرُهَا، وَإِذَا قَطَعَ إِصْبَعًا عَمْدًا فَعَفَا عَنْهَا، ثُمَّ سَرَتْ إِلَى الْكَفِّ أَوِ النَّفْسِ، وَكَانَ الْعَفْوُ عَلَى غَيْرِ شَيْءٍ فَهَدَرٌ، وَإِنْ كَانَ الْعَفْوُ عَلَى مَالٍ فَلَهُ تَمَامُ الدِّيَةِ،"]]},{"id":"za239_3","label":"بَابُ الْعَفْوِ عَنِ الْقِصَاصِ · ٣","segs":[["matn","وَإِنْ وَكَّلَ مَنْ يَقْتَصُّ ثُمَّ عَفَا فَاقْتَصَّ وَكِيلُهُ وَلَمْ يَعْلَمْ فَلَا شَيْءَ عَلَيْهِمَا، وَإِنْ وَجَبَ لِرَقِيقٍ قَوَدٌ أَوْ تَعْزِيرُ قَذْفٍ فَطَلَبُهُ وَإِسْقَاطُهُ إِلَيْهِ، فَإِنْ مَاتَ فَلِسَيِّدِهِ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za240","title":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ","units":[{"id":"za240_1","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · ١","segs":[["matn","مَنْ أُقِيدَ بِأَحَدٍ فِي النَّفْسِ أُقِيدَ بِهِ فِي الطَّرَفِ وَالْجِرَاحِ، وَمَنْ لَا فَلَا، وَلَا يَجِبُ إِلَّا بِمَا يُوجِبُ الْقَوَدَ فِي النَّفْسِ."]]},{"id":"za240_2","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · ٢","segs":[["matn","وَهَوَ نَوْعَانِ: أَحَدُهُمَا فِي الطَّرَفِ فَتُؤْخَذُ الْعَيْنُ وَالْأَنْفُ وَالْأُذُنُ وَالسِّنُّ وَالْجَفْنُ وَالشَّفَةُ وَالْيَدُ وَالرِّجْلُ وَالْإِصْبَعُ وَالْكَفُّ وَالْمِرْفَقُ وَالذَّكَرُ وَالْخُصْيَةُ وَالْأَلْيَةُ وَالشُّفْرُ، كُلُّ وَاحِدٍ مِنْ ذَلِكَ بِمِثْلِهِ."]]},{"id":"za240_3","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · ٣","segs":[["matn","وَلِلْقِصَاصِ فِي الطَّرَفِ شُرُوطٌ: الْأَوَّلُ الْأَمْنُ مِنَ الْحَيْفِ بِأَنْ يَكُونَ الْقَطْعُ مِنْ مَفْصِلٍ، أَوْ لَهُ حَدٌّ يَنْتَهِي إِلَيْهِ كَمَارِنِ الْأَنْفِ وَهُوَ مَا لَانَ مِنْهُ."]]},{"id":"za240_4","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · ٤","segs":[["matn","الثَّانِي الْمُمَاثَلَةُ فِي الِاسْمِ وَالْمَوْضِعِ، فَلَا تُؤْخَذُ يَمِينٌ بِيَسَارٍ وَلَا يَسَارٌ بِيَمِينٍ، وَلَا خِنْصِرٌ بِبِنْصِرٍ، وَلَا أَصْلِيٌّ بِزَائِدٍ، وَعَكْسُهُ، وَلَوْ تَرَاضَيَا لَمْ يَجُزْ."]]},{"id":"za240_5","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · ٥","segs":[["matn","الثَّالِثُ اسْتِوَاؤُهُمَا فِي الصِّحَّةِ وَالْكَمَالِ، فَلَا تُؤْخَذُ صَحِيحَةٌ بِشَلَّاءَ، وَلَا كَامِلَةُ الْأَصَابِعِ بِنَاقِصَةٍ، وَلَا عَيْنٌ صَحِيحَةٌ بِقَائِمَةٍ، وَيُؤْخَذُ عَكْسُهُ، وَلَا أَرْشَ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za241","title":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · فَصْلٌ","units":[{"id":"za241_1","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · فَصْلٌ · ١","segs":[["matn","النَّوْعُ الثَّانِي الْجِرَاحُ فَيُقْتَصُّ فِي كُلِّ جُرْحٍ يَنْتَهِي إِلَى عَظْمٍ، كَالْمُوضِّحَةِ وَجُرْحِ الْعَضُدِ وَالسَّاقِ وَالْفَخِذِ وَالْقَدَمِ، وَلَا يُقْتَصُّ فِي غَيْرِ ذَلِكَ مِنَ الشِّجَاجِ وَالْجُرُوحِ غَيْرَ كَسْرِ سِنٍّ، إِلَّا أَنْ يَكُونَ أَعْظَمَ مِنَ الْمُوضِّحَةِ،"]]},{"id":"za241_2","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · فَصْلٌ · ٢","segs":[["matn","كَالْهَاشِمَةِ وَالْمُنَقِّلَةِ وَالْمَأْمُومَةِ فَلَهُ أَنْ يَقْتَصَّ مُوَضِّحَةً، وَلَهُ أَرْشُ الزَّائِدِ، وَإِذَا قَطَعَ جَمَاعَةٌ طَرَفًا أَوْ جَرَحُوا جُرْحًا يُوجِبُ الْقَوَدَ فَعَلَيْهِمُ الْقَوَدُ، وَسِرَايَةُ الْجِنَايَةِ مَضْمُونَةٌ فِي النَّفْسِ فَمَا دُونَهَا، وَسِرَايَةُ الْقَوَدِ مَهْدُورَةٌ،"]]},{"id":"za241_3","label":"بَابُ مَا يُوجِبُ الْقِصَاصَ فِيمَا دُونَ النَّفْسِ · فَصْلٌ · ٣","segs":[["matn","وَلَا يُقْتَصُّ مِنْ عُضْوٍ وَجُرْحٍ قَبْلَ بُرْئِهِ كَمَا لَا تُطْلَبُ لَهُ دِيَةٌ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"za242","title":"كِتَابُ الدِّيَاتِ","units":[{"id":"za242_1","label":"كِتَابُ الدِّيَاتِ · ١","segs":[["matn","كُلُّ مَنْ أَتْلَفَ إِنْسَانًا بِمُبَاشَرَةٍ أَوْ سَبَبٍ لَزِمَتْهُ دِيَتُهُ، فَإِنْ كَانَتْ عَمْدًا مَحْضًا فَفِي مَالِ الْجَانِي حَالَّةٌ، وَشِبْهُ الْعَمْدِ وَالْخَطَأُ عَلَى عَاقِلَتِهِ، وَإِنْ غَصَبَ حُرًّا صَغِيرًا فَنَهَشَتْهُ حَيَّةٌ أَوْ أَصَابَتْهُ صَاعِقَةٌ أَوْ مَاتَ بِمَرَضٍ،"]]},{"id":"za242_2","label":"كِتَابُ الدِّيَاتِ · ٢","segs":[["matn","أَوْ غَلَّ حُرًّا مُكَلَّفًا وَقَيَّدَهُ فَمَاتَ بِالصَّاعِقَةِ أَوِ الْحَيَّةِ وَجَبَتِ الدِّيَةُ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za243","title":"كِتَابُ الدِّيَاتِ · فَصْلٌ","units":[{"id":"za243_1","label":"كِتَابُ الدِّيَاتِ · فَصْلٌ · ١","segs":[["matn","وَإِذَا أَدَّبَ الرَّجُلُ وَلَدَهُ، أَوْ سُلْطَانٌ رَعِيَّتَهُ، أَوْ مُعَلِّمٌ صَبِيَّهُ، وَلَمْ يُسْرِفْ لَمْ يَضْمَنْ مَا تَلِفَ بِهِ، وَلَوْ كَانَ التَّأْدِيبُ لِحَامِلٍ فَأَسْقَطَتْ جَنِينًا ضَمِنَهُ الْمُؤَدِّبُ، وَإِنْ طَلَبَ السُّلْطَانُ امْرَأَةً لِكَشْفِ حَقِّ اللَّهِ،"]]},{"id":"za243_2","label":"كِتَابُ الدِّيَاتِ · فَصْلٌ · ٢","segs":[["matn","أَوِ اسْتَعْدَى عَلَيْهَا رَجُلٌ بِالشُّرَطِ فِي دَعْوَى لَهُ فَأَسْقَطَتْ ضَمِنَهُ السُّلْطَانُ وَالْمُسْتَعْدِي، وَلَوْ مَاتَتْ فَزَعًا لَمْ يَضْمَنَا، وَمَنْ أَمَرَ شَخْصًا مُكَلَّفًا أَنْ يَنْزِلَ بِئْرًا أَوْ يَصْعَدَ شَجَرَةً فَهَلَكَ بِهِ لَمْ يَضْمَنْهُ،"]]},{"id":"za243_3","label":"كِتَابُ الدِّيَاتِ · فَصْلٌ · ٣","segs":[["matn","وَلَوْ أَنَّ الْآمِرَ سُلْطَانٌ كَمَا لَوِ اسْتَأْجَرَهُ سُلْطَانٌ أَوْ غَيْرُهُ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za244","title":"بَابُ مَقَادِيرِ دِيَاتِ النَّفْسِ","units":[{"id":"za244_1","label":"بَابُ مَقَادِيرِ دِيَاتِ النَّفْسِ · ١","segs":[["matn","دِيَةُ الْحُرِّ الْمُسْلِمِ مِائَةُ بَعِيرٍ، أَوْ أَلْفُ مِثْقَالٍ ذَهَبًا، أَوِ اثْنَا عَشَرَ أَلْفَ دِرْهَمٍ فِضَّةً، أَوْ مِائَتَا بَقَرَةٍ، أَوْ أَلْفَا شَاةٍ، هَذِهِ أُصُولُ الدِّيَةِ، فَأَيَّهَا أَحْضَرَ مَنْ تَلْزَمُهُ لَزِمَ الْوَلِيَّ قَبُولُهُ،"]]},{"id":"za244_2","label":"بَابُ مَقَادِيرِ دِيَاتِ النَّفْسِ · ٢","segs":[["matn","فَفِي قَتْلِ الْعَمْدِ وَشِبْهِهِ خَمْسٌ وَعِشْرُونَ بِنْتَ مَخَاضٍ، وَخَمْسٌ وَعِشْرُونَ بِنْتَ لَبُونٍ، وَخَمْسٌ وَعِشْرُونَ حِقَّةً، وَخَمْسٌ وَعِشْرُونَ جَذَعَةً، وَفِي الْخَطَأِ تَجِبُ أَخْمَاسًا ثَمَانُونَ مِنَ الْأَرْبَعَةِ الْمَذْكُورَةِ وَعِشْرُونَ مِنْ بَنِي مَخَاضٍ، وَلَا تُعْتَبَرُ الْقِيمَةُ فِي ذَلِكَ،"]]},{"id":"za244_3","label":"بَابُ مَقَادِيرِ دِيَاتِ النَّفْسِ · ٣","segs":[["matn","بَلِ السَّلَامَةُ، وَدِيَةُ الْكِتَابِيِّ نِصْفُ دِيَةِ الْمُسْلِمِ، وَدِيَةُ الْمَجُوسِيِّ وَالْوَثَنِيِّ ثَمَانُمِائَةِ دِرْهَمٍ، وَنِسَاؤُهُمْ عَلَى النِّصْفِ كَالْمُسْلِمِينَ، وَدِيَةُ قِنٍّ قِيمَتُهُ، وَفِي جِرَاحِهِ مَا نَقَصَهُ بَعْدَ الْبُرْءِ،"]]},{"id":"za244_4","label":"بَابُ مَقَادِيرِ دِيَاتِ النَّفْسِ · ٤","segs":[["matn","وَيَجِبُ فِي الْجَنِينِ ذَكَرًا كَانَ أَوْ أُنْثَى عُشْرُ دِيَةِ أُمِّهِ غُرَّةٌ، وَعُشْرُ قِيمَتِهَا إِنْ كَانَ مَمْلُوكًا، وَتُقَدَّرُ الْحُرَّةُ أَمَةً، وَإِنْ جَنَى رَقِيقٌ خَطَأً أَوْ عَمْدًا لَا قَوَدَ فِيهِ، أَوْ فِيهِ قَوَدٌ وَاخْتِيرَ فِيهِ الْمَالُ،"]]},{"id":"za244_5","label":"بَابُ مَقَادِيرِ دِيَاتِ النَّفْسِ · ٥","segs":[["matn","أَوْ أَتْلَفَ مَالًا بِغَيْرِ إِذْنِ سَيِّدِهِ تَعَلَّقَ ذَلِكَ بِرَقَبَتِهِ، فَيُخَيَّرُ سَيِّدُهُ بَيْنَ أَنْ يَفْدِيَهُ بِأَرْشِ جِنَايَتِهِ أَوْ يُسَلِّمَهُ إِلَى وَلِيِّ الْجِنَايَةِ فَيَمْلِكَهُ أَوْ يَبِيعَهُ وَيَدْفَعَ ثَمَنَهُ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za245","title":"بَابُ دِيَاتِ الْأَعْضَاءِ وَمَنَافِعِهَا","units":[{"id":"za245_1","label":"بَابُ دِيَاتِ الْأَعْضَاءِ وَمَنَافِعِهَا · ١","segs":[["matn","مَنْ أَتْلَفَ مَا فِي الْإِنْسَانِ مِنْهُ شَيْءٌ وَاحِدٌ كَالْأَنْفِ وَاللِّسَانِ وَالذَّكَرِ فَفِيهِ دِيَةُ النَّفْسِ، وَمَا فِيهِ مِنْهُ شَيْئَانِ كَالْعَيْنَيْنِ وَالْأُذُنَيْنِ وَالشَّفَتَيْنِ وَاللَّحْيَيْنِ وَثَدْيَيِ الْمَرْأَةِ وَثَنْدُوَتَيِ الرَّجُلِ وَالْيَدَيْنِ وَالرِّجْلَيْنِ وَالْأَلْيَتَيْنِ وَالْأُنْثَيَيْنِ وَإِسْكَتَيِ الْمَرْأَةِ فَفِيهِمَا الدِّيَةُ،"]]},{"id":"za245_2","label":"بَابُ دِيَاتِ الْأَعْضَاءِ وَمَنَافِعِهَا · ٢","segs":[["matn","وَفِي أَحَدِهِمَا نِصْفُهَا، وَفِي الْمَنْخِرَيْنِ ثُلُثَا الدِّيَةِ، وَفِي الْحَاجِزِ بَيْنَهُمَا ثُلُثُهَا، وَفِي الْأَجْفَانِ الْأَرْبَعَةِ الدِّيَةُ، وَفِي كُلِّ جَفْنٍ رُبُعُهَا، وَفِي أَصَابِعِ الْيَدَيْنِ الدِّيَةُ كَأَصَابِعِ الرِّجْلَيْنِ، وَفِي كُلِّ أُصْبَعٍ عُشْرُ الدِّيَةِ،"]]},{"id":"za245_3","label":"بَابُ دِيَاتِ الْأَعْضَاءِ وَمَنَافِعِهَا · ٣","segs":[["matn","وَفِي كُلِّ أَنْمُلَةٍ ثُلُثُ عُشْرِ الدِّيَةِ، وَالْإِبْهَامِ مَفْصِلَانِ، وَفِي كُلِّ مَفْصِلٍ نِصْفُ عُشْرِ الدِّيَةِ كَدِيَةِ السِّنِّ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za246","title":"بَابُ دِيَاتِ الْأَعْضَاءِ وَمَنَافِعِهَا · فَصْلٌ","units":[{"id":"za246_1","label":"بَابُ دِيَاتِ الْأَعْضَاءِ وَمَنَافِعِهَا · فَصْلٌ · ١","segs":[["matn","وَفِي كُلِّ حَاسَّةٍ دِيَةٌ كَامِلَةٌ، وَهِيَ: السَّمْعُ، وَالْبَصَرُ، وَالشَّمُّ، وَالذَّوْقُ وَكَذَا فِي الْكَلَامِ وَالْعَقْلِ، وَمَنْفَعَةِ الْمَشْيِ وَالْأَكْلِ وَالنِّكَاحِ، وَعَدَمِ اسْتِمْسَاكِ الْبَوْلِ أَوِ الْغَائِطِ، وَفِي كُلِّ وَاحِدٍ مِنَ الشُّعُورِ الْأَرْبَعَةِ الدِّيَةُ، وَهِيَ: شَعْرُ الرَّأْسِ، وَاللِّحْيَةِ، وَالْحَاجِبَيْنِ،"]]},{"id":"za246_2","label":"بَابُ دِيَاتِ الْأَعْضَاءِ وَمَنَافِعِهَا · فَصْلٌ · ٢","segs":[["matn","وَأَهْدَابِ الْعَيْنَيْنِ، فَإِنْ عَادَ فَنَبَتَ سَقَطَ مُوجَبُهُ، وَفِي عَيْنِ الْأَعْوَرِ الدِّيَةُ كَامِلَةً، وَإِنْ قَلَعَ الْأَعْوَرُ عَيْنَ الصَّحِيحِ الْمُمَاثِلَةَ لِعَيْنِهِ الصَّحِيحَةِ عَمْدًا فَعَلَيْهِ دِيَةٌ كَامِلَةٌ وَلَا قِصَاصَ، وَفِي قَطْعِ يَدِ الْأَقْطَعِ نِصْفُ الدِّيَةِ كَغَيْرِهِ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za247","title":"بَابُ الشِّجَاجِ وَكَسْرِ الْعِظَامِ","units":[{"id":"za247_1","label":"بَابُ الشِّجَاجِ وَكَسْرِ الْعِظَامِ · ١","segs":[["matn","الشَّجَّةُ: الْجُرْحُ فِي الرَّأْسِ وَالْوَجْهِ خَاصَّةً «وَهِيَ عَشْرٌ: الْحَارِصَةُ الَّتِي تَحْرِصُ الْجِلْدَ، أَيْ: تَشُقُّهُ قَلِيلًا وَلَا تُدْمِيهِ، ثُمَّ الْبَازِلَةُ الدَّامِيَةُ الدَّامِعَةُ، وَهِيَ الَّتِي يَسِيلُ مِنْهَا الدَّمُ، ثُمَّ الْبَاضِعَةُ، وَهِيَ الَّتِي تَبْضَعُ اللَّحْمَ، ثُمَّ الْمُتَلَاحِمَةُ،»"]]},{"id":"za247_2","label":"بَابُ الشِّجَاجِ وَكَسْرِ الْعِظَامِ · ٢","segs":[["matn","«وَهِيَ الْغَائِصَةُ فِي اللَّحْمِ، ثُمَّ» السِّمْحَاقُ، وَهِيَ مَا بَيْنَهَا وَبَيْنَ الْعَظْمِ قِشْرَةٌ رَقِيقَةٌ، فَهَذِهِ الْخَمْسُ لَا مُقَدَّرَ فِيهَا، بَلْ حُكُومَةٌ، وَفِي الْمُوَضِّحَةِ وَهِيَ مَا تُوَضِّحُ اللَّحْمَ، وَتُبْرِزُهُ خَمْسَةُ أَبْعِرَةٍ، ثُمَّ الْهَاشِمَةُ،"]]},{"id":"za247_3","label":"بَابُ الشِّجَاجِ وَكَسْرِ الْعِظَامِ · ٣","segs":[["matn","وَهِيَ الَّتِي تُوَضِّحُ الْعَظْمَ وَتَهْشِمُهُ وَفِيهَا عَشَرَةُ أَبْعِرَةٍ، ثُمَّ الْمُنَقِّلَةُ وَهِيَ مَا تُوَضِّحُ وَتَهْشِمُ وَتَنْقُلُ عِظَامَهَا وَفِيهَا خَمْسَ عَشْرَةَ مِنَ الْإِبِلِ، وَفِي كُلِّ وَاحِدَةٍ مِنَ الْمَأْمُومَةِ وَالدَّامِغَةِ ثُلُثُ الدِّيَةِ، وَفِي الْجَائِفَةِ ثُلُثُ الدِّيَةِ،"]]},{"id":"za247_4","label":"بَابُ الشِّجَاجِ وَكَسْرِ الْعِظَامِ · ٤","segs":[["matn","وَهِيَ الَّتِي تَصِلُ إِلَى بَاطِنِ الْجَوْفِ، وَفِي الضِّلَعِ وَكُلِّ وَاحِدَةٍ مِنَ التَّرْقُوَتَيْنِ بَعِيرٌ، وَفِي كَسْرِ الذِّرَاعِ وَهُوَ السَّاعِدُ الْجَامِعُ لِعَظْمَيِ الزِّنْدِ وَالْعَضُدِ، وَالْفَخِذِ وَالسَّاقِ إِذَا جُبِرَ ذَلِكَ مُسْتَقِيمًا بَعِيرَانِ،"]]},{"id":"za247_5","label":"بَابُ الشِّجَاجِ وَكَسْرِ الْعِظَامِ · ٥","segs":[["matn","وَمَا عَدَا ذَلِكَ مِنَ الْجِرَاحِ وَكَسْرِ الْعِظَامِ فَفِيهِ حُكُومَةٌ، وَالْحُكُومَةُ: أَنْ يُقَوَّمَ الْمَجْنِيُّ عَلَيْهِ كَأَنَّهُ عَبْدٌ لَا جِنَايَةَ بِهِ، ثُمَّ يُقَوَّمَ وَهِيَ بِهِ قَدْ بَرِئَتْ، فَمَا نَقَصَ مِنَ الْقِيمَةِ فَلَهُ مِثْلُ نِسْبَتِهِ مِنَ الدِّيَةِ،"]]},{"id":"za247_6","label":"بَابُ الشِّجَاجِ وَكَسْرِ الْعِظَامِ · ٦","segs":[["matn","كَأَنَّ قِيمَتُهُ عَبْدًا سَلِيمًا سِتُّونَ وَقِيمَتُهُ بِالْجِنَايَةِ خَمْسُونَ فَفِيهِ سُدُسُ دِيَتِهِ، إِلَّا أَنْ تَكُونَ الْحُكُومَةُ فِي مَحَلٍّ لَهُ مُقَدَّرٌ فَلَا يُبْلَغُ بِهَا الْمُقَدَّرُ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za248","title":"بَابُ الْعَاقِلَةِ وَمَا تَحْمِلُهُ","units":[{"id":"za248_1","label":"بَابُ الْعَاقِلَةِ وَمَا تَحْمِلُهُ · ١","segs":[["matn","عَاقِلَةُ الْإِنْسَانِ عَصَبَاتُهُ كُلُّهُمْ مِنَ النَّسَبِ وَالْوَلَاءِ، قَرِيبُهُمْ وَبَعِيدُهُمْ، حَاضِرُهُمْ وَغَائِبُهُمْ، حَتَّى عَمُودَيْ نَسَبِهِ، وَلَا عَقْلَ عَلَى رَقِيقٍ وَغَيْرِ مُكَلَّفٍ وَفَقِيرٍ وَلَا أُنْثَى وَلَا مُخَالِفٍ لِدِينِ الْجَانِي،"]]},{"id":"za248_2","label":"بَابُ الْعَاقِلَةِ وَمَا تَحْمِلُهُ · ٢","segs":[["matn","وَلَا تَحْمِلُ الْعَاقِلَةُ عَمْدًا مَحْضًا وَلَا عَبْدًا وَلَا صُلْحًا وَلَا اعْتِرَافًا لَمْ تُصَدِّقْهُ بِهِ، وَلَا مَا دُونَ ثُلُثِ الدِّيَةِ التَّامَّةِ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za249","title":"بَابُ الْعَاقِلَةِ وَمَا تَحْمِلُهُ · فَصْلٌ","units":[{"id":"za249_1","label":"بَابُ الْعَاقِلَةِ وَمَا تَحْمِلُهُ · فَصْلٌ · ١","segs":[["matn","مَنْ قَتَلَ نَفْسًا مُحَرَّمَةً خَطَأً مُبَاشَرَةً أَوْ تَسَبُّبًا فَعَلَيْهِ الْكَفَّارَةُ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za250","title":"بَابُ الْقَسَامَةِ","units":[{"id":"za250_1","label":"بَابُ الْقَسَامَةِ · ١","segs":[["matn","وَهِيَ أَيْمَانٌ مُكَرَّرَةٌ فِي دَعْوَى قَتْلِ مَعْصُومٍ، مِنْ شَرْطِهَا اللَّوْثُ، وَهُوَ الْعَدَاوَةُ الظَّاهِرَةُ كَالْقَبَائِلِ الَّتِي يَطْلُبُ بَعْضُهَا بَعْضًا بِالثَّأْرِ، فَمَنِ ادُّعِيَ عَلَيْهِ الْقَتْلُ مِنْ غَيْرِ لَوْثٍ حَلَفَ يَمِينًا وَاحِدَةً وَبَرِّئَ،"]]},{"id":"za250_2","label":"بَابُ الْقَسَامَةِ · ٢","segs":[["matn","وَيُبْدَأُ بِأَيْمَانِ الرِّجَالِ مِنْ وَرَثَةِ الدَّمِ، فَيَحْلِفُونَ خَمْسِينَ يَمِينًا، فَإِنْ نَكَلَ الْوَرَثَةُ أَوْ كَانُوا نِسَاءً حَلَفَ الْمُدَّعَى عَلَيْهِ خَمْسِينَ يَمِينًا وَبَرِّئَ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"za251","title":"كِتَابُ الْحُدُودِ","units":[{"id":"za251_1","label":"كِتَابُ الْحُدُودِ · ١","segs":[["matn","لَا يَجِبُ الْحَدُّ إِلَّا عَلَى بَالِغٍ عَاقِلٍ مُلْتَزِمٍ عَالِمٍ بِالتَّحْرِيمِ، فَيُقِيمُهُ الْإِمَامُ أَوْ نَائِبُهُ فِي غَيْرِ مَسْجِدٍ، وَيُضْرَبُ الرَّجُلُ فِي الْحَدِّ قَائِمًا بِسَوْطٍ لَا جَدِيدٍ وَلَا خَلَقٍ، وَلَا يُمَدُّ وَلَا يُرْبَطُ وَلَا يُجَرَّدُ،"]]},{"id":"za251_2","label":"كِتَابُ الْحُدُودِ · ٢","segs":[["matn","بَلْ يَكُونُ عَلَيْهِ قَمِيصٌ أَوْ قَمِيصَانِ، وَلَا يُبَالَغُ بِضَرْبِهِ بِحَيْثُ يَشُقُّ الْجِلْدَ، وَيُفَرَّقُ الضَّرْبُ عَلَى بَدَنِهِ، وَيُتَّقَى الرَّأْسُ وَالْوَجْهُ وَالْفَرْجُ وَالْمَقَاتِلُ، وَالْمَرْأَةُ كَالرَّجُلِ فِيهِ، إِلَّا أَنَّهَا تُضْرَبُ جَالِسَةً وَتُشَدُّ عَلَيْهَا ثِيَابُهَا وَتُمْسَكُ يَدَاهَا لِئَلَّا تَنْكَشِفَ،"]]},{"id":"za251_3","label":"كِتَابُ الْحُدُودِ · ٣","segs":[["matn","وَأَشَدُّ الْجَلْدِ جَلْدُ الزِّنَا، ثُمَّ الْقَذْفِ ثُمَّ الشُّرْبِ ثُمَّ التَّعْزِيرِ، وَمَنْ مَاتَ فِي حَدٍّ فَالْحَقُّ قَتَلَهُ، وَلَا يُحْفَرُ لِلْمَرْجُومِ فِي الزِّنَا."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za252","title":"بَابُ حَدِّ الزِّنَا","units":[{"id":"za252_1","label":"بَابُ حَدِّ الزِّنَا · ١","segs":[["matn","إِذَا زَنَى الْمُحْصَنُ رُجِمَ حَتَّى يَمُوتَ، وَالْمُحْصَنُ مَنْ وَطِئَ امْرَأَتَهُ الْمُسْلِمَةَ أَوْ الذِّمِّيَّةَ فِي نِكَاحٍ صَحِيحٍ، وَهُمَا بَالِغَانِ عَاقِلَانِ حُرَّانِ، فَإِنِ اخْتَلَّ شَرْطٌ مِنْهَا فِي أَحَدِهِمَا فَلَا إِحْصَانَ لِوَاحِدٍ مِنْهُمَا،"]]},{"id":"za252_2","label":"بَابُ حَدِّ الزِّنَا · ٢","segs":[["matn","وَإِذَا زَنَى الْحُرُّ غَيْرُ الْمُحْصَنِ جُلِدَ مِائَةَ جَلْدَةٍ وَغُرِّبَ عَامًا وَلَوِ امْرَأَةً، وَالرَّقِيقُ خَمْسِينَ جَلْدَةً وَلَا يُغَرَّبُ، وَحَدُّ لُوطِيٍّ كَزَانٍ،"]]},{"id":"za252_3","label":"بَابُ حَدِّ الزِّنَا · ٣","segs":[["matn","وَلَا يَجِبُ الْحَدُّ إِلَّا بِثَلَاثَةِ شُرُوطٍ: أَحَدُهَا تَغْيِيبُ حَشَفَتِهِ الْأَصْلِيَّةِ كُلِّهَا فِي قُبُلٍ أَوْ دُبُرٍ أَصْلِيَّيْنِ حَرَامًا مَحْضًا."]]},{"id":"za252_4","label":"بَابُ حَدِّ الزِّنَا · ٤","segs":[["matn","الثَّانِي انْتِفَاءُ الشُّبْهَةِ، فَلَا يُحَدُّ بِوَطْءِ أَمَةٍ لَهُ فِيهَا شِرْكٌ أَوْ لِوَلَدِهِ أَوْ وَطْءِ امْرَأَةٍ ظَنَّهَا زَوْجَتَهُ أَوْ سُرِّيَّتَهُ، أَوْ فِي نِكَاحٍ بَاطِلٍ اعْتَقَدَ صِحَّتَهُ، أَوْ نِكَاحٍ أَوْ مِلْكٍ مُخْتَلَفٍ فِيهِ وَنَحْوِهِ، أَوْ أُكْرِهَتِ الْمَرْأَةُ عَلَى الزِّنَا."]]},{"id":"za252_5","label":"بَابُ حَدِّ الزِّنَا · ٥","segs":[["matn","الثَّالِثُ ثُبُوتُ الزِّنَا، وَلَا يَثْبُتُ إِلَّا بِأَحَدِ أَمْرَيْنِ: أَحَدُهُمَا: أَنْ يُقِرَّ بِهِ أَرْبَعَ مَرَّاتٍ فِي مَجْلِسٍ أَوْ مَجَالِسَ، وَيُصَرِّحَ بِذِكْرِ حَقِيقَةِ الْوَطْءِ، وَلَا يَنْزِعُ عَنْ إِقْرَارِهِ حَتَّى يَتِمَّ عَلَيْهِ الْحَدُّ."]]},{"id":"za252_6","label":"بَابُ حَدِّ الزِّنَا · ٦","segs":[["matn","الثَّانِي: أَنْ يَشْهَدَ عَلَيْهِ فِي مَجْلِسٍ وَاحِدٍ بِزِنًا وَاحِدٍ، يَصِفُونَهُ أَرْبَعَةٌ مِمَّنْ تُقْبَلُ شَهَادَتُهُمْ فِيهِ، سَوَاءٌ أَتَوْا الْحَاكِمَ جُمْلَةً أَوْ مُتَفَرِّقِينَ، وَإِنْ حَمَلَتِ امْرَأَةٌ لَا زَوْجَ لَهَا وَلَا سَيِّدَ لَمْ تُحَدَّ بِمُجَرَّدِ ذَلِكَ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za253","title":"بَابُ حَدِّ الْقَذْفِ","units":[{"id":"za253_1","label":"بَابُ حَدِّ الْقَذْفِ · ١","segs":[["matn","إِذَا قَذَفَ الْمُكَلَّفُ مُحْصَنًا جُلِدَ ثَمَانِينَ جَلْدَةً إِنْ كَانَ حُرًّا، وَإِنْ كَانَ عَبْدًا أَرْبَعِينَ، وَالْمُعْتَقُ بَعْضُهُ بِحِسَابِهِ، وَقَذْفُ غَيْرِ الْمُحْصَنِ يُوجِبُ التَّعْزِيرَ، وَهُوَ حَقٌّ لِلْمَقْذُوفِ."]]},{"id":"za253_2","label":"بَابُ حَدِّ الْقَذْفِ · ٢","segs":[["matn","وَالْمُحْصَنُ هُنَا: الْحُرُّ الْمُسْلِمُ الْعَاقِلُ الْعَفِيفُ الْمُلْتَزِمُ الَّذِي يُجَامِعُ مِثْلُهُ، وَلَا يُشْتَرَطُ بُلُوغُهُ."]]},{"id":"za253_3","label":"بَابُ حَدِّ الْقَذْفِ · ٣","segs":[["matn","وَصَرِيحُ الْقَذْفِ يَا زَانِي يَا لُوطِيُّ وَنَحْوُهُ. وَكِنَايَتُهُ يَا قَحْبَةُ، يَا فَاجِرَةُ، يَا خَبِيثَةُ، فَضَحْتِ زَوْجَكِ، أَوْ نَكَّسْتِ رَأْسَهُ، أَوْ جَعَلْتِ لَهُ قُرُونًا وَنَحْوَهُ، إِنْ فَسَّرَهُ بِغَيْرِ الْقَذْفِ قُبِلَ، وَإِنْ قَذَفَ أَهْلَ بَلَدٍ أَوْ جَمَاعَةً لَا يُتَصَوَّرُ مِنْهُمُ الزِّنَا عَادَةً عُزِّرَ،"]]},{"id":"za253_4","label":"بَابُ حَدِّ الْقَذْفِ · ٤","segs":[["matn","وَيَسْقُطُ حَدُّ الْقَذْفِ بِالْعَفْوِ، وَلَا يُسْتَوْفَى بِدُونِ الطَّلَبِ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za254","title":"بَابُ حَدِّ الْمُسْكِرِ","units":[{"id":"za254_1","label":"بَابُ حَدِّ الْمُسْكِرِ · ١","segs":[["matn","كُلُّ شَرَابٍ أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ، وَهُوَ خَمْرٌ مِنْ أَيِّ شَيْءٍ كَانَ، وَلَا يُبَاحُ شُرْبُهُ لِلَذَّةٍ وَلَا لِتَدَاوٍ وَلَا عَطَشٍ وَلَا غَيْرِهِ، إِلَّا لِدَفْعِ لُقْمَةٍ غَصَّ بِهَا وَلَمْ يَحْضُرْهُ غَيْرُهُ،"]]},{"id":"za254_2","label":"بَابُ حَدِّ الْمُسْكِرِ · ٢","segs":[["matn","وَإِذَا شَرِبَهُ الْمُسْلِمُ مُخْتَارًا عَالِمًا أَنَّ كَثِيرَهُ يُسْكِرُ فَعَلَيْهِ الْحَدُّ ثَمَانُونَ جَلْدَةً مَعَ الْحُرِّيَّةِ، وَأَرْبَعُونَ مَعَ الرِّقِّ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za255","title":"بَابُ التَّعْزِيرِ","units":[{"id":"za255_1","label":"بَابُ التَّعْزِيرِ · ١","segs":[["matn","وَهُوَ التَّأْدِيبُ، وَهُوَ وَاجِبٌ فِي كُلِّ مَعْصِيَةٍ لَا حَدَّ فِيهَا وَلَا كَفَّارَةَ: كَاسْتِمْتَاعٍ لَا حَدَّ فِيهِ، وَسَرِقَةٍ لَا قَطْعَ فِيهَا، وَجِنَايَةٍ لَا قَوَدَ فِيهَا، وَإِتْيَانِ الْمَرْأَةِ الْمَرْأَةَ، وَالْقَذْفِ بِغَيْرِ الزِّنَا وَنَحْوِهِ،"]]},{"id":"za255_2","label":"بَابُ التَّعْزِيرِ · ٢","segs":[["matn","وَلَا يُزَادُ فِي التَّعْزِيرِ عَلَى عَشْرِ جَلَدَاتٍ، وَمَنِ اسْتَمْنَى بِيَدِهِ بِغَيْرِ حَاجَةٍ عُزِّرَ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za256","title":"بَابُ الْقَطْعِ فِي السَّرِقَةِ","units":[{"id":"za256_1","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ١","segs":[["matn","إِذَا أَخَذَ الْمُلْتَزِمُ نِصَابًا مِنْ حِرْزِ مِثْلِهِ مِنْ مَالِ مَعْصُومٍ، لَا شُبْهَةَ لَهُ فِيهِ، عَلَى وَجْهِ الِاخْتِفَاءِ قُطِعَ، فَلَا قَطْعَ عَلَى مُنْتَهِبٍ وَلَا مُخْتَلِسٍ وَلَا غَاصِبٍ وَلَا خَائِنٍ فِي وَدِيعَةٍ أَوْ عَارِيَّةٍ أَوْ غَيْرِهَا،"]]},{"id":"za256_2","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٢","segs":[["matn","وَيُقْطَعُ الطَّرَّارُ الَّذِي يَبُطُّ الْجَيْبَ أَوْ غَيْرَهُ وَيَأْخُذُ مِنْهُ."]]},{"id":"za256_3","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٣","segs":[["matn","وَيُشْتَرَطُ أَنْ يَكُونَ الْمَسْرُوقُ مَالًا مُحْتَرَمًا، فَلَا قَطْعَ بِسَرِقَةِ آلَةِ لَهْوٍ وَلَا مُحَرَّمٍ كَالْخَمْرِ، وَيُشْتَرَطُ أَنْ يَكُونَ نِصَابًا وَهُوَ ثَلَاثَةُ دَرَاهِمَ أَوْ رُبْعُ دِينَارٍ، أَوْ عَرَضٌ قِيمَتُهُ كَأَحَدِهِمَا،"]]},{"id":"za256_4","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٤","segs":[["matn","وَإِذَا نَقَصَتْ قِيمَةُ الْمَسْرُوقِ أَوْ مَلَكَهَا السَّارِقُ لَمْ يَسْقُطِ الْقَطْعُ وَتُعْتَبَرُ قِيمَتُهَا وَقْتَ إِخْرَاجِهَا مِنَ الْحِرْزِ، فَلَوْ ذَبَحَ فِيهِ كَبْشًا أَوْ شَقَّ فِيهِ ثَوْبًا،"]]},{"id":"za256_5","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٥","segs":[["matn","فَنَقَصَتْ قِيمَتُهُ عَنْ نِصَابٍ ثُمَّ أَخْرَجَهُ أَوْ تَلِفَ فِيهِ الْمَالَ لَمْ يُقْطَعْ، وَأَنْ يُخْرِجَهُ مِنَ الْحِرْزِ، فَإِنْ سَرَقَهُ مِنْ غَيْرِ حِرْزٍ فَلَا قَطْعَ."]]},{"id":"za256_6","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٦","segs":[["matn","وَحِرْزُ الْمَالِ مَا الْعَادَةُ حِفْظُهُ فِيهِ، وَيَخْتَلِفُ بِاخْتِلَافِ الْأَمْوَالِ وَالْبُلْدَانِ وَعَدْلِ السُّلْطَانِ وَجَوْرِهِ وَقُوَّتِهِ وَضَعْفِهِ، فَحِرْزُ الْأَمْوَالِ وَالْجَوَاهِرِ وَالْقُمَاشِ فِي الدُّورِ وَالدَّكَاكِينِ وَالْعُمْرَانِ وَرَاءَ الْأَبْوَابِ وَالْأَغْلَاقِ الْوَثِيقَةِ،"]]},{"id":"za256_7","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٧","segs":[["matn","وَحِرْزُ الْبَقْلِ وَقُدُورِ الْبَاقِلَاءِ وَنَحْوِهِمَا وَرَاءَ الشَّرَائِجِ إِذَا كَانَ فِي السُّوقِ حَارِسٌ، وَحِرْزُ الْحَطَبِ وَالْخَشَبِ الْحَظَائِرُ، وَحِرْزُ الْمَوَاشِي الصِّيَرُ، وَحِرْزُهَا فِي الْمَرْعَى بِالرَّاعِي وَنَظَرِهِ إِلَيْهَا غَالِبًا، وَأَنْ تَنْتَفِيَ الشُّبْهَةُ،"]]},{"id":"za256_8","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٨","segs":[["matn","فَلَا يُقْطَعُ بِالسَّرِقَةِ مِنْ مَالِ أَبِيهِ وَإِنْ عَلَا، وَلَا مِنْ مَالِ وَلَدِهِ وَإِنْ سَفَلَ، وَالْأَبُ وَالْأُمُّ فِي هَذَا سَوَاءٌ، وَيُقْطَعُ الْأَخُ وَكُلُّ قَرِيبٍ بِسَرِقَةِ مَالِ قَرِيبِهِ، وَلَا يُقْطَعُ أَحَدٌ مِنَ الزَّوْجَيْنِ بِسَرِقَتِهِ مِنْ مَالِ الْآخَرِ،"]]},{"id":"za256_9","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٩","segs":[["matn","وَلَوْ كَانَ مُحْرَزًا عَنْهُ، وَإِذَا سَرَقَ عَبْدٌ مِنْ مَالِ سَيِّدِهِ أَوْ سَيِّدٌ مِنْ مَالِ مُكَاتَبِهِ، أَوْ حُرٌّ مِنْ بَيْتِ الْمَالِ، أَوْ مِنْ غَنِيمَةٍ لَمْ تُخَمَّسْ، أَوْ فَقِيرٌ مِنْ غَلَّةِ وَقْفٍ عَلَى الْفُقَرَاءِ،"]]},{"id":"za256_10","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ١٠","segs":[["matn","أَوْ شَخْصٌ مِنْ مَالٍ فِيهِ شَرِكَةٌ لَهُ أَوْ لِأَحَدٍ مِمَّنْ لَا يُقْطَعُ بِالسَّرِقَةِ مِنْهُ لَمْ يُقْطَعْ."]]},{"id":"za256_11","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ١١","segs":[["matn","وَلَا يُقْطَعُ إِلَّا بِشَهَادَةِ عَدْلَيْنِ، أَوْ إِقْرَارِ مَرَّتَيْنِ، وَلَا يَنْزِعُ عَنْ إِقْرَارِهِ حَتَّى يُقْطَعَ، وَأَنْ يُطَالِبَ الْمَسْرُوقُ مِنْهُ بِمَالِهِ، وَإِذَا وَجَبَ الْقَطْعُ قُطِعَتْ يَدُهُ الْيُمْنَى مِنْ مَفْصِلِ الْكَفِّ وَحُسِمَتْ،"]]},{"id":"za256_12","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ١٢","segs":[["matn","وَمَنْ سَرَقَ شَيْئًا مِنْ غَيْرِ حِرْزٍ ثَمَرًا كَانَ أَوْ كُثَرًا أَوْ غَيْرَهُمَا أُضْعِفَتْ عَلَيْهِ الْقِيمَةُ وَلَا قَطْعَ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za257","title":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ","units":[{"id":"za257_1","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ١","segs":[["matn","وَهُمُ الَّذِينَ يَعْرِضُونَ لِلنَّاسِ بِالسِّلَاحِ فِي الصَّحْرَاءِ أَوِ الْبُنْيَانِ، فَيَغْصِبُونَهُمُ الْمَالَ مُجَاهَرَةً لَا سَرِقَةً، فَمَنْ مِنْهُمْ قَتَلَ مُكَافِئًا أَوْ غَيْرَهُ كَالْوَلَدِ وَالْعَبْدِ وَالذِّمِّيِّ، وَأَخَذَ الْمَالَ قُتِلَ ثُمَّ صُلِبَ حَتَّى يَشْتَهِرَ،"]]},{"id":"za257_2","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٢","segs":[["matn","وَإِنْ قَتَلَ وَلَمْ يَأْخُذِ الْمَالَ قُتِلَ حَتْمًا وَلَمْ يُصْلَبْ، وَإِنْ جَنَوْا بِمَا يُوجِبُ قَوَدًا فِي الطَّرَفِ تَحَتَّمَ اسْتِيفَاؤُهُ،"]]},{"id":"za257_3","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٣","segs":[["matn","وَإِنْ أَخَذَ كُلُّ وَاحِدٍ مِنَ الْمَالِ قَدْرَ مَا يُقْطَعُ بِأَخْذِهِ السَّارِقُ وَلَمْ يَقْتُلُوا قُطِعَ مِنْ كُلِّ وَاحِدٍ يَدُهُ الْيُمْنَى وَرِجْلُهُ الْيُسْرَى فِي مَقَامٍ وَاحِدٍ، وَحُسِمَتَا ثُمَّ خُلِّيَ،"]]},{"id":"za257_4","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٤","segs":[["matn","فَإِنْ لَمْ يُصِيبُوا نَفْسًا وَلَا مَالًا يَبْلُغُ نِصَابَ السَّرِقَةِ نُفُوا بِأَنْ يُشَرَّدُوا فَلَا يُتْرَكُونَ يَأْوُونَ إِلَى بَلَدٍ، وَمَنْ تَابَ مِنْهُمْ قَبْلَ أَنْ يُقْدَرَ عَلَيْهِ سَقَطَ عَنْهُ مَا كَانَ لِلَّهِ مِنْ نَفْيٍ وَقَطْعٍ وَصَلْبٍ وَتَحَتُّمِ قَتْلٍ،"]]},{"id":"za257_5","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٥","segs":[["matn","وَأُخِذَ بِمَا لِلْآدَمِيِّينَ مِنْ نَفْسٍ وَطَرَفٍ وَمَالٍ إِلَّا أَنْ يُعْفَى لَهُ عَنْهَا، وَمَنْ صَالَ عَلَى نَفْسِهِ أَوْ حُرْمَتِهِ أَوْ مَالِهِ آدَمِيٌّ أَوْ بَهِيمَةٌ فَلَهُ الدَّفْعُ عَنْ ذَلِكَ بِأَسْهَلِ مَا يَغْلِبُ عَلَى ظَنِّهِ دَفْعُهُ بِهِ،"]]},{"id":"za257_6","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٦","segs":[["matn","فَإِنْ لَمْ يَنْدَفِعْ إِلَّا بِالْقَتْلِ فَلَهُ ذَلِكَ وَلَا ضَمَانَ عَلَيْهِ، وَإِنْ قُتِلَ فَهُوَ شَهِيدٌ، وَيَلْزَمُهُ الدَّفْعُ عَنْ نَفْسِهِ وَحُرْمَتِهِ دُونَ مَالِهِ، وَمَنْ دَخَلَ مَنْزِلَ رَجُلٍ مُتَلَصِّصًا فَحُكْمُهُ كَذَلِكَ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za258","title":"بَابُ قِتَالِ أَهْلِ الْبَغْيِ","units":[{"id":"za258_1","label":"بَابُ قِتَالِ أَهْلِ الْبَغْيِ · ١","segs":[["matn","إِذَا خَرَجَ قَوْمٌ لَهُمْ شَوْكَةٌ وَمَنَعَةٌ عَلَى الْإِمَامِ بِتَأْوِيلٍ سَائِغٍ فَهُمْ بُغَاةٌ، وَعَلَيْهِ أَنْ يُرَاسِلَهُمْ فَيَسْأَلَهُمْ مَا يَنْقِمُونَ مِنْهُ، فَإِنْ ذَكَرُوا مَظْلِمَةً أَزَالَهَا، وَإِنِ ادَّعَوْا شُبْهَةً كَشَفَهَا، فَإِنْ فَاؤُوا وَإِلَّا قَاتَلَهُمْ،"]]},{"id":"za258_2","label":"بَابُ قِتَالِ أَهْلِ الْبَغْيِ · ٢","segs":[["matn","وَإِنِ اقْتَتَلَتْ طَائِفَتَانِ لِعَصَبِيَّةٍ أَوْ رِئَاسَةٍ فَهُمَا ظَالِمَتَانِ، وَتَضْمَنُ كُلُّ وَاحِدَةٍ مَا أَتْلَفَتْ عَلَى الْأُخْرَى."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za259","title":"بَابُ حُكْمِ الْمُرْتَدِّ","units":[{"id":"za259_1","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ١","segs":[["matn","وَهُوَ الَّذِي يَكْفُرُ بَعْدَ إِسْلَامِهِ، فَمَنْ أَشْرَكَ بِاللَّهِ، أَوْ جَحَدَ رُبُوبِيَّتَهُ، أَوْ وَحْدَانِيَّتَهُ أَوْ سَبَّ اللَّهَ أَوْ رَسُولَهُ فَقَدْ كَفَرَ، وَمَنْ جَحَدَ تَحْرِيمَ الزِّنَا أَوْ شَيْئًا مِنَ الْمُحَرَّمَاتِ الظَّاهِرَةِ الْمُجْمَعِ عَلَيْهَا بِجَهْلٍ عُرِّفَ ذَلِكَ، وَإِنْ كَانَ مِثْلُهُ لَا يَجْهَلُهُ كَفَرَ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za260","title":"بَابُ حُكْمِ الْمُرْتَدِّ · فَصْلٌ","units":[{"id":"za260_1","label":"بَابُ حُكْمِ الْمُرْتَدِّ · فَصْلٌ · ١","segs":[["matn","فَمَنِ ارْتَدَّ عَنِ الْإِسْلَامِ وَهُوَ مُكَلَّفٌ مُخْتَارٌ، رَجُلٌ أَوِ امْرَأَةٌ، دُعِيَ إِلَيْهِ ثَلَاثَةَ أَيَّامٍ، وَضُيِّقَ عَلَيْهِ، فَإِنْ لَمْ يُسْلِمْ قُتِلَ بِالسَّيْفِ، وَلَا تُقْبَلُ تَوْبَةُ مَنْ سَبَّ اللَّهَ أَوْ رَسُولَهُ، وَلَا مَنْ تَكَرَّرَتْ رِدَّتُهُ،"]]},{"id":"za260_2","label":"بَابُ حُكْمِ الْمُرْتَدِّ · فَصْلٌ · ٢","segs":[["matn","بَلْ يُقْتَلُ بِكُلِّ حَالٍ، وَتَوْبَةُ الْمُرْتَدِّ وَكُلِّ كَافِرٍ إِسْلَامُهُ؛ بِأَنْ يَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَمَنْ كَانَ كُفْرُهُ بِجَحْدِ فَرْضٍ وَنَحْوِهِ فَتَوْبَتُهُ مَعَ الشَّهَادَتَيْنِ إِقْرَارُهُ بِالْمَجْحُودِ بِهِ،"]]},{"id":"za260_3","label":"بَابُ حُكْمِ الْمُرْتَدِّ · فَصْلٌ · ٣","segs":[["matn","أَوْ قَوْلُهُ: أَنَا بَرِيءٌ مِنْ كُلِّ دِينٍ يُخَالِفُ دِينَ الْإِسْلَامَ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"za261","title":"كِتَابُ الْأَطْعِمَةِ","units":[{"id":"za261_1","label":"كِتَابُ الْأَطْعِمَةِ · ١","segs":[["matn","الْأَصْلُ فِيهَا الْحِلُّ، فَيُبَاحُ كُلُّ طَاهِرٍ لَا مَضَرَّةَ فِيهِ مِنْ حَبٍّ وَثَمَرٍ وَغَيْرِهِمَا، وَلَا يَحِلُّ نَجِسٌ كَالْمَيْتَةِ وَالدَّمِ، وَلَا مَا فِيهِ مَضَرَّةٌ كَالسُّمِّ وَنَحْوِهِ،"]]},{"id":"za261_2","label":"كِتَابُ الْأَطْعِمَةِ · ٢","segs":[["matn","وَحَيَوَانَاتُ الْبَرِّ مُبَاحَةٌ إِلَّا الْحُمُرَ الْإِنْسِيَّةَ وَمَا لَهُ نَابٌ يَفْرِسُ بِهِ غَيْرَ الضَّبُعِ كَالْأَسَدِ وَالنِّمِرِ وَالذِّئْبِ وَالْفِيلِ وَالْفَهْدِ وَالْكَلْبِ وَالْخِنْزِيرِ وَابْنِ آوَى وَابْنِ عِرْسٍ وَالسِّنَّوْرِ وَالنِّمْسِ وَالْقِرْدِ وَالدُّبِّ،"]]},{"id":"za261_3","label":"كِتَابُ الْأَطْعِمَةِ · ٣","segs":[["matn","وَمَا لَهُ مِخْلَبٌ مِنَ الطَّيْرِ يَصِيدُ بِهِ كَالْعُقَابِ وَالْبَازِي وَالصَّقْرِ وَالشَّاهِينِ وَالْبَاشِقِ وَالْحِدَأَةِ وَالْبُومَةِ، وَمَا يَأْكُلُ الْجِيَفَ كَالنِّسْرِ وَالرَّخَمِ وَاللَّقْلَقِ وَالْعَقْعَقِ وَالْغُرَابِ الْأَبْقَعِ وَالْغُدَافِ وَهُوَ أَسْوَدُ صَغِيرٌ أَغْبَرُ وَالْغُرَابِ الْأَسْوَدِ الْكَبِيرِ،"]]},{"id":"za261_4","label":"كِتَابُ الْأَطْعِمَةِ · ٤","segs":[["matn","وَمَا يَسْتَخْبِثُ كَالْقُنْفُذِ وَالنِّيْصِ وَالْفَأْرَةِ وَالْحَيَّةِ وَالْحَشَرَاتِ كُلِّهَا وَالْوَطْوَاطِ وَمَا تَوَلَّدَ مِنْ مَأْكُولٍ وَغَيْرِهِ كَالْبَغْلِ."]]}],"group":"كِتَابُ الْأَطْعِمَةِ"},{"id":"za262","title":"كِتَابُ الْأَطْعِمَةِ · فَصْلٌ","units":[{"id":"za262_1","label":"كِتَابُ الْأَطْعِمَةِ · فَصْلٌ · ١","segs":[["matn","وَمَا عَدَا ذَلِكَ فَحَلَالٌ، كَالْخَيْلِ وَبَهِيمَةِ الْأَنْعَامِ وَالدَّجَاجِ وَالْوَحْشِيِّ مِنَ الْحُمُرِ وَالْبَقَرِ وَالظِّبَاءِ وَالنَّعَامَةِ وَالْأَرْنَبِ وَسَائِرِ الْوَحْشِ، وَيُبَاحُ حَيَوَانُ الْبَحْرِ كُلُّهُ، إِلَّا الضِّفْدَعَ وَالتِّمْسَاحَ وَالْحَيَّةَ،"]]},{"id":"za262_2","label":"كِتَابُ الْأَطْعِمَةِ · فَصْلٌ · ٢","segs":[["matn","وَمَنِ اضْطُرَّ إِلَى مُحَرَّمٍ غَيْرَ السُّمِّ حَلَّ لَهُ مِنْهُ مَا يَسُدُّ رَمَقَهُ، وَمَنِ اضْطُرَّ إِلَى نَفْعِ مَالِ الْغَيْرِ مَعَ بَقَاءِ عَيْنِهِ لِدَفْعِ بَرْدٍ أَوِ اسْتِسْقَاءِ مَاءٍ وَنَحْوِهِ وَجَبَ بَذْلُهُ لَهُ مَجَّانًا،"]]},{"id":"za262_3","label":"كِتَابُ الْأَطْعِمَةِ · فَصْلٌ · ٣","segs":[["matn","وَمَنْ مَرَّ بِثَمَرِ بُسْتَانٍ فِي شَجَرَةٍ أَوْ مُتَسَاقِطٍ عَنْهُ وَلَا حَائِطَ عَلَيْهِ، وَلَا نَاظِرَ، فَلَهُ الْأَكْلُ مِنْهُ مَجَّانًا مِنْ غَيْرِ حَمْلٍ."]]},{"id":"za262_4","label":"كِتَابُ الْأَطْعِمَةِ · فَصْلٌ · ٤","segs":[["matn","وَتَجِبُ ضِيَافَةُ الْمُسْلِمِ الْمُجْتَازِ بِهِ فِي الْقُرَى يَوْمًا وَلَيْلَةً."]]}],"group":"كِتَابُ الْأَطْعِمَةِ"},{"id":"za263","title":"بَابُ الذَّكَاةِ","units":[{"id":"za263_1","label":"بَابُ الذَّكَاةِ · ١","segs":[["matn","لَا يُبَاحُ شَيْءٌ مِنَ الْحَيَوَانِ الْمَقْدُورِ عَلَيْهِ بِغَيْرِ ذَكَاةٍ، إِلَّا الْجَرَادَ وَالسَّمَكَ وَكُلَّ مَا لَا يَعِيشُ إِلَّا فِي الْمَاءِ، وَيُشْتَرَطُ لِلذَّكَاةِ أَرْبَعَةُ شُرُوطٍ: أَهْلِيَّةُ الْمُذَكِّي بِأَنْ يَكُونَ عَاقِلًا مُسْلِمًا أَوْ كِتَابِيًّا،"]]},{"id":"za263_2","label":"بَابُ الذَّكَاةِ · ٢","segs":[["matn","وَلَوْ مُرَاهِقًا أَوِ امْرَأَةً أَوْ أَقْلَفَ أَوْ أَعْمَى، وَلَا تُبَاحُ ذَكَاةُ سَكْرَانَ وَمَجْنُونٍ وَوَثَنِيٍّ وَمَجُوسِيٍّ وَمُرْتَدٍّ."]]},{"id":"za263_3","label":"بَابُ الذَّكَاةِ · ٣","segs":[["matn","الثَّانِي: الْآلَةُ فَتُبَاحُ الذَّكَاةُ بِكُلِّ مُحَدَّدٍ وَلَوْ مَغْصُوبًا مِنْ حَدِيدٍ وَحَجَرٍ وَقَصَبٍ وَغَيْرِهِ، إِلَّا السِّنَّ وَالظُّفُرَ."]]},{"id":"za263_4","label":"بَابُ الذَّكَاةِ · ٤","segs":[["matn","الثَّالِثُ: قَطْعُ الْحُلْقُومِ وَالْمَرِيءِ وَذَكَاةُ مَا عُجِزَ عَنْهُ مِنَ الصَّيْدِ وَالنَّعَمِ الْمُتَوَحِّشَةِ وَالْوَاقِعَةِ فِي بِئْرٍ وَنَحْوِهَا بِجَرْحِهِ فِي أَيِّ مَوْضِعٍ كَانَ مِنْ بَدَنِهِ إِلَّا أَنْ يَكُونَ رَأْسُهُ فِي الْمَاءِ وَنَحْوَهُ فَلَا يُبَاحُ."]]},{"id":"za263_5","label":"بَابُ الذَّكَاةِ · ٥","segs":[["matn","الرَّابِعُ: أَنْ يَقُولَ عِنْدَ الذَّبْحِ: «بِسْمِ اللَّهِ» لَا يُجْزِئُهُ غَيْرُهَا، فَإِنْ تَرَكَهَا سَهْوًا أُبِيحَتْ، لَا عَمْدًا."]]},{"id":"za263_6","label":"بَابُ الذَّكَاةِ · ٦","segs":[["matn","وَيُكْرَهُ أَنْ يَذْبَحَ بِآلَةٍ كَالَّةٍ، وَأَنْ يُحِدَّهَا وَالْحَيَوَانُ يُبْصِرُهُ، وَأَنْ يُوَجِّهَهُ إِلَى غَيْرِ الْقِبْلَةِ، وَأَنْ يَكْسِرَ عُنُقَهَ، أَوْ يَسْلُخَهُ قَبْلَ أَنْ يَبْرُدَ."]]}],"group":"كِتَابُ الْأَطْعِمَةِ"},{"id":"za264","title":"بَابُ الصَّيْدِ","units":[{"id":"za264_1","label":"بَابُ الصَّيْدِ · ١","segs":[["matn","لَا يَحِلُّ الصَّيْدُ الْمَقْتُولُ فِي الِاصْطِيَادِ إِلَّا بِأَرْبَعَةِ شُرُوطٍ: أَحَدُهَا أَنْ يَكُونَ الصَّائِدُ مِنْ أَهْلِ الذَّكَاةِ."]]},{"id":"za264_2","label":"بَابُ الصَّيْدِ · ٢","segs":[["matn","الثَّانِي الْآلَةُ وَهِيَ نَوْعَانِ: مُحَدَّدٌ يُشْتَرَطُ فِيهِ مَا يُشْتَرَطُ فِي آلَةِ الذَّبْحِ، وَأَنْ يَجْرَحَ فَإِنْ قَتَلَهُ بِثِقَلِهِ لَمْ يُبَحْ، وَمَا لَيْسَ بِمُحَدَّدٍ كَالْبُنْدُقِ وَالْعَصَا وَالشَّبَكَةِ وَالْفَخِّ لَا يَحِلُّ مَا قُتِلَ بِهِ، وَالنَّوْعُ الثَّانِي الْجَارِحَةُ فَيُبَاحُ مَا قَتَلَتْهُ إِنْ كَانَتْ مُعَلَّمَةً."]]},{"id":"za264_3","label":"بَابُ الصَّيْدِ · ٣","segs":[["matn","الثَّالِثُ إِرْسَالُ الْآلَةِ قَاصِدًا، فَإِنِ اسْتَرْسَلَ الْكَلْبُ أَوْ غَيْرُهُ بِنَفْسِهِ لَمْ يُبَحْ إِلَّا أَنْ يَزْجُرَهُ فَيَزِيدَ فِي عَدْوِهِ فِي طَلَبِهِ فَيَحِلَّ."]]},{"id":"za264_4","label":"بَابُ الصَّيْدِ · ٤","segs":[["matn","الرَّابِعُ التَّسْمِيَةُ عِنْدَ إِرْسَالِ السَّهْمِ أَوِ الْجَارِحَةِ، فَإِنْ تَرَكَهَا عَمْدًا أَوْ سَهْوًا لَمْ يُبَحْ. وَيُسَنُّ أَنْ يَقُولَ مَعَهَا: «اللَّهُ أَكْبَرُ» كَالذَّكَاةِ."]]}],"group":"كِتَابُ الْأَطْعِمَةِ"},{"id":"za265","title":"كِتَابُ الْأَيْمَانِ","units":[{"id":"za265_1","label":"كِتَابُ الْأَيْمَانِ · ١","segs":[["matn","وَالْيَمِينُ الَّتِي تَجِبُ بِهَا الْكَفَّارَةُ إِذَا حَنِثَ هِيَ الْيَمِينُ بِاللَّهِ، أَوْ صِفَةٍ مِنْ صِفَاتِهِ، أَوْ بِالْقُرْآنِ أَوْ بِالْمُصْحَفِ، وَالْحَلِفُ بِغَيْرِ اللَّهِ مُحَرَّمٌ، وَلَا تَجِبُ بِهِ كَفَّارَةٌ."]]},{"id":"za265_2","label":"كِتَابُ الْأَيْمَانِ · ٢","segs":[["matn","وَيُشْتَرَطُ لِوُجُوبِ الْكَفَّارَةِ ثَلَاثَةُ شُرُوطٍ: الْأَوَّلُ أَنْ تَكُونَ الْيَمِينُ مُنْعَقِدَةً، وَهِيَ الَّتِي قُصِدَ عَقْدُهَا عَلَى مُسْتَقْبَلٍ مُمْكِنٍ، فَإِنْ حَلَفَ عَلَى أَمْرٍ مَاضٍ كَاذِبًا عَالِمًا فَهِيَ الْغَمُوسُ."]]},{"id":"za265_3","label":"كِتَابُ الْأَيْمَانِ · ٣","segs":[["matn","وَلَغْوُ الْيَمِينِ الَّذِي يَجْرِي عَلَى لِسَانِهِ بِغَيْرِ قَصْدٍ كَقَوْلِهِ: «لَا وَاللَّهِ» «وَبَلَى وَاللَّهِ» وَكَذَا يَمِينٌ عَقَدَهَا يَظُنُّ صِدْقَ نَفْسِهِ فَبَانَ بِخِلَافِهِ، فَلَا كَفَّارَةَ فِي الْجَمِيعِ."]]},{"id":"za265_4","label":"كِتَابُ الْأَيْمَانِ · ٤","segs":[["matn","الثَّانِي أَنْ يَحْلِفَ مُخْتَارًا، فَإِنْ حَلَفَ مُكْرَهًا لَمْ تَنْعَقِدْ يَمِينُهُ."]]},{"id":"za265_5","label":"كِتَابُ الْأَيْمَانِ · ٥","segs":[["matn","الثَّالِثُ الْحِنْثُ فِي يَمِينِهِ، بِأَنْ يَفْعَلَ مَا حَلَفَ عَلَى تَرْكِهِ أَوْ بِتَرْكِ مَا حَلَفَ عَلَى فِعْلِهِ مُخْتَارًا ذَاكِرًا، فَإِنْ حَنَثَ مُكْرَهًا أَوْ نَاسِيًا فَلَا كَفَّارَةَ، وَمَنْ قَالَ فِي يَمِينٍ مُكَفَّرَةٍ: «إِنْ شَاءَ اللَّهُ» لَمْ يَحْنَثْ."]]},{"id":"za265_6","label":"كِتَابُ الْأَيْمَانِ · ٦","segs":[["matn","وَيُسَنُّ الْحِنْثُ فِي الْيَمِينِ إِذَا كَانَ خَيْرًا، وَمَنْ حَرَّمَ حَلَالًا سِوَى زَوْجَتِهِ مِنْ أَمَةٍ أَوْ طَعَامٍ أَوْ لِبَاسٍ أَوْ غَيْرِهِ لَمْ يَحْرُمْ، وَتَلْزَمُهُ كَفَّارَةُ يَمِينٍ إِنْ فَعَلَهُ."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"za266","title":"كِتَابُ الْأَيْمَانِ · فَصْلٌ","units":[{"id":"za266_1","label":"كِتَابُ الْأَيْمَانِ · فَصْلٌ · ١","segs":[["matn","يُخَيَّرُ مَنْ لَزِمَتْهُ كَفَّارَةُ يَمِينٍ بَيْنَ إِطْعَامِ عَشَرَةِ مَسَاكِينَ أَوْ كِسْوَتِهِمْ أَوْ عِتْقِ رَقَبَةٍ، فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ مُتَتَابِعَةٍ، وَمَنْ لَزِمَتْهُ أَيْمَانٌ قَبْلَ التَّكْفِيرِ مُوجَبُهَا وَاحِدٌ فَعَلَيْهِ كَفَّارَةٌ وَاحِدَةٌ، وَإِنْ اخْتَلَفَ مُوجَبُهَا كَظِهَارٍ وَيَمِينٍ بِاللَّهِ لَزِمَاهُ وَلَمْ يَتَدَاخَلَا."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"za267","title":"بَابُ جَامِعِ الْأَيْمَانِ","units":[{"id":"za267_1","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١","segs":[["matn","يُرْجَعُ فِي الْأَيْمَانِ إِلَى نِيَّةِ الْحَالِفِ إِذَا احْتَمَلَهَا اللَّفْظُ، فَإِنْ عُدِمَتِ النِّيَّةُ رُجِعَ إِلَى سَبَبِ الْيَمِينِ وَمَا هَيَّجَهَا، فَإِنْ عُدِمَ ذَلِكَ رُجِعَ إِلَى التَّعْيِينِ،"]]},{"id":"za267_2","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢","segs":[["matn","فَإِذَا حَلَفَ: «لَا لَبِسْتُ هَذَا الْقَمِيصَ» فَجَعَلَهُ سَرَاوِيلَ أَوْ رِدَاءً أَوْ عِمَامَةً وَلَبِسَهُ، أَوْ: «لَا كَلَّمْتُ هَذَا الصَّبِيَّ» فَصَارَ شَيْخًا، أَوْ: «زَوْجَةَ فُلَانٍ هَذِهِ، أَوْ صَدِيقَهُ فُلَانًا،»"]]},{"id":"za267_3","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٣","segs":[["matn","«أَوْ مَمْلُوكَهُ سَعِيدًا» فَزَالَتْ الزَّوْجِيَّةُ وَالْمِلْكُ وَالصَّدَاقَةُ ثُمَّ كَلَّمَهُمْ، أَوْ: «لَا أَكَلْتُ لَحْمَ هَذَا الْحَمَلِ» فَصَارَ كَبْشًا، أَوْ: «هَذَا الرُّطَبَ» فَصَارَ تَمْرًا أَوْ دِبْسًا أَوْ خَلًّا، أَوْ: «هَذَا اللَّبَنَ» فَصَارَ جُبْنًا أَوْ كَشْكًا وَنَحْوَهُ،"]]},{"id":"za267_4","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٤","segs":[["matn","ثُمَّ أَكَلَ حَنِثَ فِي الْكُلِّ، إِلَّا أَنْ يَنْوِيَ مَا دَامَ عَلَى تِلْكَ الصِّفَةِ."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"za268","title":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ","units":[{"id":"za268_1","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ١","segs":[["matn","فَإِنْ عُدِمَ ذَلِكَ رُجِعَ إِلَى مَا يَتَنَاوَلُهُ الِاسْمُ، وَهُوَ ثَلَاثَةٌ: شَرْعِيٌّ وَحَقِيقِيٌّ وَعُرْفِيٌّ فَالشَّرْعِيُّ: مَا لَهُ مَوْضُوعٌ فِي الشَّرْعِ وَمَوْضُوعٌ فِي اللُّغَةِ، فَالْمُطْلَقُ يَنْصَرِفُ إِلَى الْمَوْضُوعِ الشَّرْعِيِّ الصَّحِيحِ،"]]},{"id":"za268_2","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ٢","segs":[["matn","فَإِذَا حَلَفَ لَا يَبِيعُ أَوْ لَا يَنْكِحُ فَعَقَدَ عَقْدًا فَاسِدًا لَمْ يَحْنَثْ، وَإِنْ قَيَّدَ يَمِينَهُ بِمَا يَمْنَعُ الصِّحَّةَ كَأَنْ حَلَفَ لَا يَبِيعُ الْخَمْرَ أَوِ الْحُرَّ حَنِثَ بِصُورَةِ الْعَقْدِ."]]},{"id":"za268_3","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ٣","segs":[["matn","وَالْحَقِيقِيُّ: هُوَ الَّذِي لَمْ يَغْلِبْ مَجَازُهُ عَلَى حَقِيقَتِهِ كَاللَّحْمِ، فَإِذَا حَلَفَ لَا يَأْكُلُ اللَّحْمَ فَأَكَلَ شَحْمًا أَوْ مُخًّا أَوْ كَبِدًا، أَوْ نَحْوَهُ لَمْ يَحْنَثْ،"]]},{"id":"za268_4","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ٤","segs":[["matn","وَإِنْ حَلَفَ لَا يَأْكُلُ أُدْمًا حَنِثَ بِأَكْلِ الْبَيْضِ وَالتَّمْرِ وَالْمِلْحِ وَالزَّيْتُونِ وَنَحْوِهِ وَكُلِّ مَا يُصْطَبَغُ بِهِ، وَلَا يَلْبَسُ شَيْئًا فَلَبِسَ ثَوْبًا أَوْ دِرْعًا أَوْ جَوْشَنًا أَوْ نَعْلًا حَنِثَ،"]]},{"id":"za268_5","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ٥","segs":[["matn","وَإِنْ حَلَفَ لَا يُكَلِّمُ إِنْسَانًا حَنِثَ بِكَلَامِ كُلِّ إِنْسَانٍ، وَلَا يَفْعَلُ شَيْئًا فَوَكَّلَ مَنْ فَعَلَهُ حَنِثَ، إِلَّا أَنْ يَنْوِيَ مُبَاشَرَتَهَ بِنَفْسِهِ."]]},{"id":"za268_6","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ٦","segs":[["matn","وَالْعُرْفِيُّ: مَا اشْتَهَرَ مَجَازُهُ فَغَلَبَ الْحَقِيقَةَ كَالرَّاوِيَةِ وَالْغَائِطِ وَنَحْوِهِمَا، فَتَتَعَلَّقُ الْيَمِينُ بِالْعُرْفِ، فَإِذَا حَلَفَ عَلَى وَطْءِ زَوْجَتِهِ أَوْ وَطْءِ دَارٍ تَعَلَّقَتْ يَمِينُهُ بِجِمَاعِهَا وَبِدُخُولِ الدَّارِ،"]]},{"id":"za268_7","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ٧","segs":[["matn","وَإِنْ حَلَفَ لَا يَأْكُلُ شَيْئًا فَأَكَلَهُ مُسْتَهْلَكًا فِي غَيْرِهِ كَمَنْ حَلَفَ لَا يَأْكُلُ سَمْنًا فَأَكَلَ خَبِيصًا فِيهِ سَمْنٌ لَا يَظْهَرُ فِيهِ طَعْمُهُ، أَوْ لَا يَأْكُلُ بَيْضًا فَأَكَلَ نَاطِفًا لَمْ يَحْنَثْ،"]]},{"id":"za268_8","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ · ٨","segs":[["matn","وَإِنْ ظَهَرَ طَعْمُ شَيْءٍ مِنَ الْمَحْلُوفِ عَلَيْهِ حَنِثَ."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"za269","title":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ (٢)","units":[{"id":"za269_1","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ (٢) · ١","segs":[["matn","وَإِنْ حَلَفَ لَا يَفْعَلُ شَيْئًا كَكَلَامِ زَيْدٍ وَدُخُولِ دَارٍ وَنَحْوِهِ فَفَعَلَهُ مُكْرَهًا لَمْ يَحْنَثْ، وَإِنْ حَلَفَ عَلَى نَفْسِهِ أَوْ غَيْرِهِ مِمَّنْ يَقْصُدُ مَنْعَهُ كَالزَّوْجَةِ وَالْوَلَدِ، أَنْ لَا يَفْعَلَ شَيْئًا فَفَعَلَهُ نَاسِيًا أَوْ جَاهِلًا حَنِثَ،"]]},{"id":"za269_2","label":"بَابُ جَامِعِ الْأَيْمَانِ · فَصْلٌ (٢) · ٢","segs":[["matn","فِي الطَّلَاقِ وَالْعَتَاقِ فَقَطْ، وَعَلَى مَنْ لَا يَمْتَنِعُ بِيَمِينِهِ مِنْ سُلْطَانٍ وَغَيْرِهِ فَفَعَلَهُ حَنِثَ مُطْلَقًا، وَإِنْ فَعَلَ هُوَ أَوْ غَيْرُهُ مِمَّنْ قَصَدَ مَنْعَهُ بَعْضَ مَا حَلَفَ عَلَى كُلِّهِ لَمْ يَحْنَثْ مَا لَمْ تَكُنْ نِيَّةٌ."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"za270","title":"بَابُ النَّذْرِ","units":[{"id":"za270_1","label":"بَابُ النَّذْرِ · ١","segs":[["matn","لَا يَصِحُّ إِلَّا مِنْ بَالِغٍ عَاقِلٍ وَلَوْ كَافِرًا، وَالصَّحِيحُ مِنْهُ خَمْسَةِ أَقْسَامٍ: الْمُطْلَقُ مِثْلَ أَنْ يَقُولَ: «لِلَّهِ عَلَيَّ نَذْرٌ» وَلَمْ يُسَمِّ شَيْئًا فَيَلْزَمُهُ كَفَّارَةُ يَمِينٍ."]]},{"id":"za270_2","label":"بَابُ النَّذْرِ · ٢","segs":[["matn","الثَّانِي نَذْرُ اللَّجَاجِ وَالْغَضَبِ وَهُوَ تَعْلِيقُ نَذْرِهِ بِشَرْطٍ يَقْصِدُ الْمَنْعَ مِنْهُ أَوِ الْحَمْلَ عَلَيْهِ أَوِ التَّصْدِيقَ أَوِ التَّكْذِيبَ، فَيُخَيَّرُ بَيْنَ فِعْلِهِ وَبِينَ كَفَّارَةِ يَمِينٍ."]]},{"id":"za270_3","label":"بَابُ النَّذْرِ · ٣","segs":[["matn","الثَّالِثُ نَذْرُ الْمُبَاحِ كَلُبْسِ ثَوْبِهِ وَرُكُوبِ دَابَّتِهِ، فَحُكْمُهُ كَالثَّانِي، وَإِنْ نَذَرَ مَكْرُوهًا مِنْ طَلَاقٍ أَوْ غَيْرِهِ اسْتُحِبَّ أَنْ يُكَفِّرَ وَلَا يَفْعَلُهُ."]]},{"id":"za270_4","label":"بَابُ النَّذْرِ · ٤","segs":[["matn","الرَّابِعُ نَذْرُ الْمَعْصِيَةِ كَشُرْبِ خَمْرٍ وَصَوْمِ يَوْمِ الْحَيْضِ وَالنَّحْرِ، فَلَا يَجُوزُ الْوَفَاءُ بِهِ وَيُكَفِّرُ."]]},{"id":"za270_5","label":"بَابُ النَّذْرِ · ٥","segs":[["matn","الْخَامِسُ نَذْرُ التَّبَرُّرِ مُطْلَقًا أَوْ مُعَلَّقًا، كَفِعْلِ الصَّلَاةِ وَالصِّيَامِ وَالْحَجِّ وَنَحْوِهِ، كَقَوْلِهِ: «إِنْ شَفَى اللَّهُ مَرِيضِي أَوْ سَلَّمَ مَالِيَ الْغَائِبَ فَلِلَّهِ عَلَيَّ كَذَا» فَوُجِدَ الشَّرْطُ لَزِمَهُ الْوَفَاءُ بِهِ،"]]},{"id":"za270_6","label":"بَابُ النَّذْرِ · ٦","segs":[["matn","إِلَّا إِذَا نَذَرَ الصَّدَقَةَ بِمَالِهِ كُلِّهِ أَوْ بِمُسَمًّى مِنْهُ يَزِيدُ عَلَى ثُلُثِ الْكُلِّ؛ فَإِنَّهُ يُجْزِئُهُ قَدْرِ الثُّلْثِ، وَفِيمَا عَدَاهَا يَلْزَمُهُ الْمُسَمَّى، وَمَنْ نَذَرَ صَوْمَ شَهْرٍ لَزِمَهُ التَّتَابُعُ،"]]},{"id":"za270_7","label":"بَابُ النَّذْرِ · ٧","segs":[["matn","وَإِنْ نَذَرَ أَيَّامًا مَعْدُودَةً لَمْ يَلْزَمْهُ إِلَّا بِشَرْطٍ أَوْ نِيَّةٍ."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"za271","title":"كِتَابُ الْقَضَاءِ","units":[{"id":"za271_1","label":"كِتَابُ الْقَضَاءِ · ١","segs":[["matn","وَهُوَ فَرْضُ كِفَايَةٍ، يَلْزَمُ الْإِمَامَ أَنْ يَنْصِبَ فِي كُلِّ إِقْلِيمٍ قَاضِيًا، وَيَخْتَارَ أَفْضَلَ مَنْ يَجِدُهُ عِلْمًا وَوَرَعًا، وَيَأْمُرُهُ بِتَقْوَى اللَّهِ، وَأَنْ يَتَحَرَّى الْعَدْلَ وَيَجْتَهِدَ فِي إِقَامَتِهِ فَيَقُولُ: «وَلَّيْتُكَ الْحُكْمَ» أَوْ «قَلَّدْتُكَ» وَنَحْوَهُ، وَيُكَاتِبُهُ فِي الْبُعْدِ."]]},{"id":"za271_2","label":"كِتَابُ الْقَضَاءِ · ٢","segs":[["matn","وَتُفِيدُ وِلَايَةُ الْحُكْمِ الْعَامَّةُ الْفَصْلَ بَيْنَ الْخُصُومِ وَأَخْذَ الْحَقِّ لِبَعْضِهِمْ مِنْ بَعْضٍ، وَالنَّظَرَ فِي أَمْوَالِ غَيْرِ الْمُرْشَدِينَ، وَالْحَجْرَ عَلَى مَنْ يَسْتَوْجِبُهُ لِسَفَهٍ أَوْ فَلَسٍ، وَالنَّظَرَ فِي وُقُوفِ عَمَلِهِ لِيَعْمَلَ بِشَرْطِهَا، وَتَنْفِيذَ الْوَصَايَا،"]]},{"id":"za271_3","label":"كِتَابُ الْقَضَاءِ · ٣","segs":[["matn","وَتَزْوِيجَ مَنْ لَا وَلِيَّ لَهَا، وَإِقَامَةَ الْحُدُودِ، وَإِمَامَةَ الْجُمُعَةِ وَالْعِيدِ، وَالنَّظَرَ فِي مَصَالِحِ عَمَلِهِ بِكَفِّ الْأَذَى عَنِ الطُّرُقَاتِ وَأَفْنِيَتِهَا وَنَحْوِهِ، وَيَجُوزُ أَنْ يُوَلَّى عُمُومَ النَّظَرِ فِي عُمُومِ الْعَمَلِ وَيُوَلِّيَ خَاصًّا فِيهِمَا أَوْ فِي أَحَدِهِمَا."]]},{"id":"za271_4","label":"كِتَابُ الْقَضَاءِ · ٤","segs":[["matn","وَيُشْتَرَطُ فِي الْقَاضِي عَشْرُ صِفَاتٍ: كَوْنُهُ بَالِغًا، عَاقِلًا، ذَكَرًا، حُرًّا، مُسْلِمًا، عَدْلًا، سَمِيعًا، بَصِيرًا، مُتَكَلِّمًا، مُجْتَهِدًا، وَلَوْ فِي مَذْهَبِهِ، وَإِذَا حَكَّمَ اثْنَانِ بَيْنَهُمَا رَجُلًا يَصْلُحُ لِلْقَضَاءِ نَفَذَ حُكْمُهُ فِي الْمَالِ وَالْحُدُودِ وَاللِّعَانِ وَغَيْرِهَا."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"za272","title":"بَابُ آدَابِ الْقَاضِي","units":[{"id":"za272_1","label":"بَابُ آدَابِ الْقَاضِي · ١","segs":[["matn","يَنْبَغِي أَنْ يَكُونَ قَوِيًّا مِنْ غَيْرِ عُنْفٍ، لَيِّنًا مِنْ غَيْرِ ضَعْفٍ، حَلِيمًا ذَا أَنَاةٍ وَفِطْنَةٍ، وَلْيَكُنْ مَجْلِسُهُ فِي وَسْطِ الْبَلَدِ فَسِيحًا، وَيَعْدِلْ بَيْنَ الْخَصْمَيْنِ فِي لَحْظِهِ وَلَفْظِهِ وَمَجْلِسِهِ وَدُخُولِهِمَا عَلَيْهِ."]]},{"id":"za272_2","label":"بَابُ آدَابِ الْقَاضِي · ٢","segs":[["matn","وَيَنْبَغِي أَنْ يَحْضُرَ مَجْلِسَهُ فُقَهَاءُ الْمَذَاهِبِ وَيُشَاوِرَهُمْ فِيمَا يُشْكِلُ عَلَيْهِ."]]},{"id":"za272_3","label":"بَابُ آدَابِ الْقَاضِي · ٣","segs":[["matn","وَيَحْرُمُ الْقَضَاءُ وَهُوَ غَضْبَانُ كَثِيرًا، أَوْ حَاقِنٌ أَوْ فِي شِدَّةِ جُوعٍ أَوْ عَطَشٍ، أَوْ هَمٍّ أَوْ مَلَلٍ، أَوْ كَسَلٍ أَوْ نُعَاسٍ، أَوْ بَرْدٍ مُؤْلِمٍ أَوْ حَرٍّ مُزْعِجٍ، وَإِنْ خَالَفَ فَأَصَابَ الْحَقَّ نَفَذَ،"]]},{"id":"za272_4","label":"بَابُ آدَابِ الْقَاضِي · ٤","segs":[["matn","وَيَحْرُمُ قَبُولُ رِشْوَةٍ وَكَذَا هَدِيَّةٍ إِلَّا مِمَّنْ كَانَ يُهَادِيهِ قَبْلَ وِلَايَتِهِ إِذَا لَمْ تَكُنْ لَهُ حُكُومَةٌ."]]},{"id":"za272_5","label":"بَابُ آدَابِ الْقَاضِي · ٥","segs":[["matn","وَيُسْتَحَبُّ أَنْ لَا يَحْكُمَ إِلَّا بِحَضْرَةِ الشُّهُودِ، وَلَا يَنْفُذُ حُكْمُهُ لِنَفْسِهِ، وَلَا لِمَنْ لَا تُقْبَلُ شَهَادَتُهُ لَهُ، وَمَنِ ادَّعَى عَلَى غَيْرِ بَرْزَةٍ لَمْ تَحْضُرْ وَأُمِرَتْ بِالتَّوْكِيلِ، وَإِنْ لَزِمَهَا يَمِينٌ أَرْسَلَ مَنْ يُحَلِّفُهَا، وَكَذَا الْمَرِيضُ."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"za273","title":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ","units":[{"id":"za273_1","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١","segs":[["matn","إِذَا حَضَرَ إِلَيْهِ خَصْمَانِ قَالَ: أَيُّكُمَا الْمُدَّعِي؟ فَإِنْ سَكَتَ حَتَّى يُبْدَأَ جَازَ، فَمَنْ سَبَقَ بِالدَّعْوَى قَدَّمَهُ، فَإِنْ أَقَرَّ لَهُ حَكَمَ لَهُ عَلَيْهِ، وَإِنْ أَنْكَرَ قَالَ لِلْمُدَّعِي: إِنْ كَانَ لَكَ بَيِّنَةٌ فَأَحْضِرْهَا إِنْ شِئْتَ."]]},{"id":"za273_2","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٢","segs":[["matn","فَإِنْ أَحْضَرَهَا سَمِعَهَا وَحَكَمَ بِهَا، وَلَا يَحْكُمُ بِعِلْمِهِ، وَإِنْ قَالَ الْمُدَّعِي: مَا لِي بَيِّنَةٌ."]]},{"id":"za273_3","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٣","segs":[["matn","أَعْلَمَهُ الْحَاكِمُ أَنَّ لَهُ الْيَمِينَ عَلَى خَصْمِهِ عَلَى صِفَةِ جَوَابِهِ، فَإِنْ سَأَلَ إِحْلَافَهُ أَحْلَفَهُ، وَخَلَّى سَبِيلَهُ، وَلَا يُعْتَدُّ بِيَمِينِهِ قَبْلَ مَسْأَلَةِ الْمُدَّعِي، وَإِنْ نَكَلَ قَضَى عَلَيْهِ، فَيَقُولُ: إِنْ حَلَفْتَ وَإِلَّا قَضَيْتُ عَلَيْكَ."]]},{"id":"za273_4","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٤","segs":[["matn","فَإِنْ لَمْ يَحْلِفْ قَضَى عَلَيْهِ، فَإِنْ حَلَفَ الْمُنْكِرُ ثُمَّ أَحْضَرَ الْمُدَّعِي بَيِّنَةً حَكَمَ بِهَا، وَلَمْ تَكُنِ الْيَمِينُ مُزِيْلَةً لِلْحَقِّ."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"za274","title":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · فَصْلٌ","units":[{"id":"za274_1","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · فَصْلٌ · ١","segs":[["matn","وَلَا تَصِحُّ الدَّعْوَى إِلَّا مُحَرَّرَةً مَعْلُومَةَ الْمُدَّعَى بِهِ، إِلَّا مَا نُصَحِّحُهُ مَجْهُولًا كَالْوَصِيَّةِ وَعَبْدٍ مِنْ عَبِيدِهِ مَهْرًا وَنَحْوِهِ، وَإِنِ ادَّعَى عَقْدَ نِكَاحٍ أَوْ بَيْعٍ أَوْ غَيْرِهِمَا فَلَا بُدَّ مِنْ ذِكْرِ شُرُوطِهِ،"]]},{"id":"za274_2","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · فَصْلٌ · ٢","segs":[["matn","وَإِنِ ادَّعَتِ امْرَأَةٌ نِكَاحَ رَجُلٍ لِطَلَبِ نَفَقَةٍ أَوْ مَهْرٍ أَوْ نَحْوِهِمَا سُمِعَتْ دَعْوَاهَا، وَإِنْ لَمْ تَدَّعِ سِوَى النِّكَاحِ لَمْ تُقْبَلْ، وَإِنِ ادَّعَى الْإِرْثَ ذَكَرَ سَبَبَهُ."]]},{"id":"za274_3","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · فَصْلٌ · ٣","segs":[["matn","وَتُعْتَبَرُ عَدَالَةُ الْبَيِّنَةِ ظَاهِرًا وَبَاطِنًا، وَمَنْ جُهِلَتْ عَدَالَتُهُ سَأَلَ عَنْهُ، وَإِنْ عَلِمَ عَدَالَتَهُ عَمِلَ بِهَا، وَإِنْ جَرَحَ الْخَصْمُ الشُّهُودَ كُلِّفَ الْبَيِّنَةَ بِهِ وَأُنْظِرَ لَهُ ثَلَاثَةً إِنْ طَلَبَهُ، وَلِلْمُدَّعِي مُلَازَمَتُهُ، فَإِنْ لَمْ يَأْتِ بِبَيِّنَةٍ حَكَمَ عَلَيْهِ،"]]},{"id":"za274_4","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · فَصْلٌ · ٤","segs":[["matn","وَإِنْ جَهِلَ حَالَ الْبَيِّنَةِ طَلَبَ مِنَ الْمُدَّعِي تَزْكِيَتَهُمْ، وَيَكْفِي فِيهَا عَدْلَانِ يَشْهَدَانِ بِعَدَالَتِهِ، وَلَا يُقْبَلُ فِي التَّرْجَمَةِ وَالتَّزْكِيَةِ وَالْجَرْحِ وَالتَّعْرِيفِ وَالرِّسَالَةِ إِلَّا قَوْلُ عَدْلَيْنِ،"]]},{"id":"za274_5","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · فَصْلٌ · ٥","segs":[["matn","وَيُحْكَمُ عَلَى الْغَائِبِ إِذَا ثَبَتَ عَلَيْهِ الْحَقُّ وَإِنِ ادَّعَى عَلَى حَاضِرٍ فِي الْبَلَدِ غَائِبٍ عَنْ مَجْلِسِ الْحُكْمِ وَأَتَى بِبَيِّنَةٍ لَمْ تُسْمَعِ الدَّعْوَى وَلَا الْبَيِّنَةُ."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"za275","title":"بَابُ كِتَابِ الْقَاضِي إِلَى الْقَاضِي","units":[{"id":"za275_1","label":"بَابُ كِتَابِ الْقَاضِي إِلَى الْقَاضِي · ١","segs":[["matn","يُقْبَلُ كِتَابُ الْقَاضِي إِلَى الْقَاضِي فِي كُلِّ حَقٍّ حَتَّى الْقَذْفِ، لَا فِي حُدُودِ اللَّهِ كَحَدِّ الزِّنَا وَنَحْوِهِ، وَيُقْبَلُ فِيمَا حَكَمَ بِهِ لِيُنَفِّذَهُ وَإِنْ كَانَ فِي بَلَدٍ وَاحِدٍ،"]]},{"id":"za275_2","label":"بَابُ كِتَابِ الْقَاضِي إِلَى الْقَاضِي · ٢","segs":[["matn","وَلَا يُقْبَلُ فِيمَا ثَبَتَ عِنْدَهُ لِيَحْكُمَ بِهِ إِلَّا أَنْ يَكُونَ بَيْنَهُمَا مَسَافَةُ قَصْرٍ، وَيَجُوزُ أَنْ يَكْتُبَ إِلَى قَاضٍ مُعَيَّنٍ وَإِلَى كُلِّ مَنْ يَصِلُ إِلَيْهِ كِتَابُهُ مِنْ قُضَاةِ الْمُسْلِمِينَ،"]]},{"id":"za275_3","label":"بَابُ كِتَابِ الْقَاضِي إِلَى الْقَاضِي · ٣","segs":[["matn","وَلَا يُقْبَلُ إِلَّا أَنْ يُشْهِدَ بِهِ الْقَاضِي الْكَاتِبُ شَاهِدَيْنِ، فَيَقْرَؤُهُ عَلَيْهِمَا ثُمَّ يَقُولُ: اشْهَدَا أَنَّ هَذَا كِتَابِي إِلَى فُلَانٍ ابْنِ فُلَانٍ. ثُمَّ يَدْفَعُهُ إِلَيْهِمَا."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"za276","title":"بَابُ الْقِسْمَةِ","units":[{"id":"za276_1","label":"بَابُ الْقِسْمَةِ · ١","segs":[["matn","لَا تَجُوزُ قِسْمَةُ الْأَمْلَاكِ الَّتِي لَا تَنْقَسِمُ إِلَّا بِضَرَرٍ أَوْ رَدِّ عِوَضٍ إِلَّا بِرِضَا الشُّرَكَاءِ، كَالدُّورِ الصِّغَارِ وَالْحَمَّامِ وَالطَّاحُونِ الصَّغِيرَيْنِ وَالْأَرْضِ الَّتِي لَا تَتَعَدَّلُ بِأَجْزَاءٍ وَلَا قِيمَةٍ لِبِنَاءٍ أَوْ بِئْرٍ فِي بَعْضِهَا،"]]},{"id":"za276_2","label":"بَابُ الْقِسْمَةِ · ٢","segs":[["matn","فَهَذِهِ الْقِسْمَةُ فِي حُكْمِ الْبَيْعِ، وَلَا يُجْبَرُ مَنِ امْتَنَعَ مِنْ قِسْمَتِهَا، وَأَمَّا مَا لَا ضَرَرَ وَلَا رَدَّ عِوَضٍ فِي قِسْمَتِهِ كَالْقَرْيَةِ وَالْبُسْتَانِ وَالدَّارِ الْكَبِيرَةِ وَالْأَرْضِ وَالدَّكَاكِينِ الْوَاسِعَةِ وَالْمَكِيلِ وَالْمَوْزُونِ مِنْ جِنْسٍ وَاحِدٍ كَالْأَدْهَانِ وَالْأَلْبَانِ، وَنَحْوِهَا،"]]},{"id":"za276_3","label":"بَابُ الْقِسْمَةِ · ٣","segs":[["matn","إِذَا طَلَبَ الشَّرِيكُ قِسْمَتَهَا أُجْبِرَ الْآخَرُ عَلَيْهَا، وَهَذِهِ الْقِسْمَةُ إِفْرَازٌ لَا بَيْعٌ، وَيَجُوزُ لِلشُّرَكَاءِ أَنْ يَتَقَاسَمُوا بِأَنْفُسِهِمْ، وَبِقَاسِمٍ يَنْصِبُونَهُ، أَوْ يَسْأَلُوا الْحَاكِمَ نَصْبَهُ، وَأُجْرَتُهُ عَلَى قَدْرِ الْأَمْلَاكِ، فَإِذَا اقْتَسَمُوا أَوْ اقْتَرَعُوا لَزِمَتِ الْقِسْمَةُ، وَكَيْفَ اقْتَرَعُوا جَازَ."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"za277","title":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ","units":[{"id":"za277_1","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ١","segs":[["matn","الْمُدَّعِي مَنْ إِذَا سَكَتَ تُرِكَ، وَالْمُدَّعَى عَلَيْهِ مَنْ إِذَا سَكَتَ لَمْ يُتْرَكْ، وَلَا تَصِحُّ الدَّعْوَى وَالْإِنْكَارُ إِلَّا مِنْ جَائِزِ التَّصَرُّفِ، وَإِذَا تَدَاعَيَا عَيْنًا بِيَدِ أَحَدِهِمَا فَهِيَ لَهُ مَعَ يَمِينِهِ،"]]},{"id":"za277_2","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٢","segs":[["matn","إِلَّا أَنْ تَكُونَ لَهُ بَيِّنَةٌ فَلَا يَحْلِفُ، وَإِنْ أَقَامَ كُلُّ وَاحِدٍ بَيِّنَةً أَنَّهَا لَهُ قُضِيَ لِلْخَارِجِ بِبَيِّنَتِهِ، وَلَغَتْ بَيِّنَةُ الدَّاخِلِ."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"za278","title":"كِتَابُ الشَّهَادَاتِ","units":[{"id":"za278_1","label":"كِتَابُ الشَّهَادَاتِ · ١","segs":[["matn","تَحَمُّلُ الشَّهَادَاتِ فِي غَيْرِ حَقِّ اللَّهِ فَرْضُ كِفَايَةٍ، وَإِنْ لَمْ يُوجَدْ إِلَّا مَنْ يَكْفِي تَعَيَّنَ عَلَيْهِ،"]]},{"id":"za278_2","label":"كِتَابُ الشَّهَادَاتِ · ٢","segs":[["matn","وَأَدَاؤُهَا فَرْضُ عَيْنٍ عَلَى مَنْ تَحَمَّلَهَا مَتَى دُعِيَ إِلَيْهِ وَقَدِرَ بِلَا ضَرَرٍ فِي بَدَنِهِ أَوْ عِرْضِهِ أَوْ مَالِهِ أَوْ أَهْلِهِ، وَكَذَا فِي التَّحَمُّلِ، وَلَا يَحِلُّ كِتْمَانُهَا، وَلَا أَنْ يَشْهَدَ إِلَّا بِمَا يَعْلَمُهُ بِرُؤْيَةٍ، أَوْ سَمَاعٍ،"]]},{"id":"za278_3","label":"كِتَابُ الشَّهَادَاتِ · ٣","segs":[["matn","أَوْ اسْتِفَاضَةٍ فِيْمَا يَتَعَذَّرُ عِلْمُهُ بِدُونِهَا كَنَسَبٍ وَمَوْتٍ وَمِلْكٍ مُطْلَقٍ وَنِكَاحٍ، وَوَقْفٍ وَنَحْوِهَا، وَمَنْ شَهِدَ بِنِكَاحٍ أَوْ غَيْرِهِ مِنَ الْعُقُودِ فَلَا بُدَّ مِنْ ذِكْرِ شُرُوطِهِ،"]]},{"id":"za278_4","label":"كِتَابُ الشَّهَادَاتِ · ٤","segs":[["matn","وَإِنْ شَهِدَ بِرَضَاعٍ أَوْ سَرِقَةٍ أَوْ شُرْبٍ أَوْ قَذْفٍ فَإِنَّهُ يَصِفُهُ، وَيَصِفُ الزِّنَا بِذِكْرِ الزَّمَانِ وَالْمَكَانِ وَالْمَزْنِيِّ بِهَا، وَيَذْكُرُ مَا يُعْتَبَرُ لِلْحُكْمِ وَيَخْتَلِفُ بِهِ فِي الْكُلِّ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"za279","title":"كِتَابُ الشَّهَادَاتِ · فَصْلٌ","units":[{"id":"za279_1","label":"كِتَابُ الشَّهَادَاتِ · فَصْلٌ · ١","segs":[["matn","شُرُوطُ مَنْ تُقْبَلُ شَهَادَتُهُ سِتَّةٌ: الْبُلُوغُ فَلَا تُقْبَلُ شَهَادَةُ الصِّبْيَانِ، الثَّانِي الْعَقْلُ فَلَا تُقْبَلُ شَهَادَةُ مَجْنُونٍ وَلَا مَعْتُوهٍ، وَتُقْبَلُ مِمَّنْ يُخْنَقُ أَحْيَانًا فِي حَالِ إِفَاقَتِهِ،"]]},{"id":"za279_2","label":"كِتَابُ الشَّهَادَاتِ · فَصْلٌ · ٢","segs":[["matn","الثَّالِثُ الْكَلَامُ فَلَا تُقْبَلُ شَهَادَةُ الْأَخْرَسِ وَلَوْ فُهِمَتْ إِشَارَتُهُ إِلَّا إِذَا أَدَّاهَا بِخَطِّهِ، الرَّابِعُ الْإِسْلَامُ، الْخَامِسُ الْحِفْظُ السَّادِسُ الْعَدَالَةُ وَيُعْتَبَرُ لَهَا شَيْئَانِ: الصَّلَاحُ فِي الدِّينِ: وَهُوَ أَدَاءُ الْفَرَائِضِ بِسُنَنِهَا الرَّاتِبَةِ،"]]},{"id":"za279_3","label":"كِتَابُ الشَّهَادَاتِ · فَصْلٌ · ٣","segs":[["matn","وَاجْتِنَابُ الْمَحَارِمِ بِأَنْ لَا يَأْتِيَ كَبِيرَةً وَلَا يُدْمِنَ عَلَى صَغِيرَةٍ، فَلَا تُقْبَلُ شَهَادَةُ فَاسِقٍ، الثَّانِي: اسْتِعْمَالُ الْمُرُوءَةِ، وَهُوَ فِعْلُ مَا يُجَمِّلُهُ وَيُزَيِّنُهُ، وَاجْتِنَابُ مَا يُدَنِّسُهُ وَيَشِينُهُ،"]]},{"id":"za279_4","label":"كِتَابُ الشَّهَادَاتِ · فَصْلٌ · ٤","segs":[["matn","وَمَتَى زَالَتِ الْمَوَانِعُ فَبَلَغَ الصَّبِيُّ وَعَقَلَ الْمَجْنُونُ وَأَسْلَمَ الْكَافِرُ وَتَابَ الْفَاسِقُ، قُبِلَتْ شَهَادَتُهُمْ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"za280","title":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ","units":[{"id":"za280_1","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · ١","segs":[["matn","لَا تُقْبَلُ شَهَادَةُ عَمُودَيِ النَّسَبِ بَعْضِهِمْ لِبَعْضٍ، وَلَا شَهَادَةُ أَحَدِ الزَّوْجَيْنِ لِصَاحِبِهِ، وَتُقْبَلُ عَلَيْهِمْ، وَلَا مَنْ يَجُرُّ إِلَى نَفْسِهِ نَفْعًا أَوْ يَدْفَعُ عَنْهَا ضَرَرًا،"]]},{"id":"za280_2","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · ٢","segs":[["matn","وَلَا عَدُوٍّ عَلَى عَدُوِّهِ كَمَنْ شَهِدَ عَلَى مَنْ قَذَفَهُ أَوْ قَطَعَ الطَّرِيقَ عَلَيْهِ، وَمَنْ سَرَّهُ مَسَاءَةُ شَخْصٍ أَوْ غَمَّهُ فَرَحُهُ فَهُوَ عَدُوُّهُ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"za281","title":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ","units":[{"id":"za281_1","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ · ١","segs":[["matn","وَلَا يُقْبَلُ فِي الزِّنَا وَالْإِقْرَارِ بِهِ إِلَّا أَرْبَعَةٌ، وَيَكْفِي عَلَى مَنْ أَتَى بَهِيمَةً رَجُلَانِ،"]]},{"id":"za281_2","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ · ٢","segs":[["matn","وَيُقْبَلُ فِي بَقِيَّةِ الْحُدُودِ وَالْقِصَاصِ وَمَا لَيْسَ بِعُقُوبَةٍ وَلَا مَالٍ وَلَا يُقْصَدُ بِهِ الْمَالُ وَيَطَّلِعُ عَلَيْهِ الرِّجَالُ غَالِبًا كَنِكَاحٍ وَطَلَاقٍ وَرَجْعَةٍ وَخُلْعٍ وَنَسَبٍ وَوَلَاءٍ وَإِيْصَاءٍ إِلَيْهِ يُقْبَلُ فِيهِ رَجُلَانِ،"]]},{"id":"za281_3","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ · ٣","segs":[["matn","وَيُقْبَلُ فِي الْمَالِ وَمَا يُقْصَدُ بِهِ كَالْبَيْعِ وَالْأَجَلِ وَالْخِيَارِ فِيهِ وَنَحْوِهِ رَجُلَانِ أَوْ رَجُلٌ وَامْرَأَتَانِ وَرَجُلٌ وَيَمِينُ الْمُدَّعِي، وَمَا لَا يَطَّلِعُ عَلَيْهِ الرِّجَالُ غَالِبًا كَعُيُوبِ النِّسَاءِ تَحْتَ الثِّيَابِ وَالْبَكَارَةِ وَالثُّيُوبَةِ وَالْحَيْضِ وَالْوِلَادَةِ،"]]},{"id":"za281_4","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ · ٤","segs":[["matn","وَالرَّضَاعِ وَالِاسْتِهْلَالِ وَنَحْوِهِ يُقْبَلُ فِيهِ شَهَادَةُ امْرَأَةٍ عَدْلٍ، وَالرَّجُلُ فِيهِ كَالْمَرْأَةِ، وَمَنْ أَتَى بِرَجُلٍ وَامْرَأَتَيْنِ أَوْ شَاهِدٍ وَيَمِينٍ فِيمَا يُوجِبُ الْقَوَدَ لَمْ يَثْبُتْ بِهِ قَوَدٌ وَلَا مَالٌ،"]]},{"id":"za281_5","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ · ٥","segs":[["matn","وَإِنْ أَتَى بِذَلِكَ فِي سَرِقَةٍ ثَبَتَ الْمَالُ دُونَ الْقَطْعِ، وَإِنْ أَتَى بِذَلِكَ فِي خُلْعٍ ثَبَتَ لَهُ الْعِوَضُ، وَتَثْبُتُ الْبَيْنُونَةُ بِمُجَرَّدِ دَعْوَاهُ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"za282","title":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ (٢)","units":[{"id":"za282_1","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ (٢) · ١","segs":[["matn","وَلَا تُقْبَلُ الشَّهَادَةُ عَلَى الشَّهَادَةِ إِلَّا فِي حَقٍّ يُقْبَلُ فِيهِ كِتَابُ الْقَاضِي إِلَى الْقَاضِي، وَلَا يُحْكَمُ بِهَا إِلَّا أَنْ تَتَعَذَّرَ شَهَادَةُ الْأَصْلِ بِمَوْتٍ أَوْ مَرَضٍ أَوْ غَيْبَةٍ مَسَافَةَ قَصْرٍ،"]]},{"id":"za282_2","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَلَا يَجُوزُ لِشَاهِدِ الْفَرْعِ أَنْ يَشْهَدَ إِلَّا أَنْ يَسْتَرْعِيَهُ شَاهِدُ الْأَصْلِ، فَيَقُولَ: اشْهَدْ عَلَى شَهَادَتِي بِكَذَا."]]},{"id":"za282_3","label":"بَابُ مَوَانِعِ الشَّهَادَةِ وَعَدَدِ الشُّهُودِ · فَصْلٌ (٢) · ٣","segs":[["matn","أَوْ يَسْمَعَهُ يُقِرُّ بِهَا عِنْدَ الْحَاكِمِ أَوْ يَعْزُوَهَا إِلَى سَبَبٍ مِنْ قَرْضٍ أَوْ بَيْعٍ أَوْ نَحْوِهِ، وَإِذَا رَجَعَ شُهُودُ الْمَالِ بَعْدَ الْحُكْمِ لَمْ يُنْقَضْ وَيَلْزَمُهُمُ الضَّمَانُ دُوْنَ مَنْ زَكَّاهُمْ، وَإِنْ حَكَمَ بِشَاهِدٍ وَيَمِينٍ ثُمَّ رَجَعَ الشَّاهِدُ غَرِمَ الْمَالَ كُلَّهُ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"za283","title":"بَابُ الْيَمِينِ فِي الدَّعَاوَى","units":[{"id":"za283_1","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ١","segs":[["matn","لَا يُسْتَحْلَفُ فِي الْعِبَادَاتِ وَلَا فِي حُدُودِ اللَّهِ، وَيُسْتَحْلَفُ الْمُنْكِرُ فِي كُلِّ حَقٍّ لِآدَمِيٍّ إِلَّا النِّكَاحَ وَالطَّلَاقَ وَالرَّجْعَةَ وَالْإِيلَاءَ وَأَصْلَ الرِّقِّ وَالْوَلَاءَ وَالِاسْتِيلَادَ وَالنَّسَبَ وَالْقَوَدَ وَالْقَذْفَ."]]},{"id":"za283_2","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٢","segs":[["matn","وَالْيَمِينُ الْمَشْرُوعَةُ الْيَمِينُ بِاللَّهِ وَلَا تُغَلَّظُ إِلَّا فِيْمَا لَهُ خَطَرٌ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"za284","title":"كِتَابُ الْإِقْرَارِ","units":[{"id":"za284_1","label":"كِتَابُ الْإِقْرَارِ · ١","segs":[["matn","يَصِحُّ مِنْ مُكَلَّفٍ مُخْتَارٍ غَيْرِ مَحْجُورٍ عَلَيْهِ، وَلَا يَصِحُّ مِنْ مُكْرَهٍ، وَإِنْ أُكْرِهَ عَلَى وَزْنِ مَالٍ فَبَاعَ مِلْكَهُ لِذَلِكَ صَحَّ، وَمَنْ أَقَرَّ فِي مَرَضِهِ بِشَيْءٍ فَكَإِقْرَارِهِ فِي صِحَّتِهِ، إِلَّا فِي إِقْرَارِهِ بِالْمَالِ لِوَارِثِهِ فَلَا يُقْبَلُ،"]]},{"id":"za284_2","label":"كِتَابُ الْإِقْرَارِ · ٢","segs":[["matn","وَإِنْ أَقَرَّ لِامْرَأَتِهِ بِالصَّدَاقِ فَلَهَا مَهْرُ الْمِثْلِ بِالزَّوْجِيَّةِ، لَا بِإِقْرَارِهِ، وَلَوْ أَقَرَّ أَنَّهُ كَانَ أَبَانَهَا فِي صِحَّتِهِ لَمْ يَسْقُطْ إِرْثُهَا، وَإِنْ أَقَرَّ لِوَارِثٍ فَصَارَ عِنْدَ الْمَوْتِ أَجْنَبِيًّا لَمْ يَلْزَمْ إِقْرَارُهُ؛ لَا أَنَّهُ بَاطِلٌ،"]]},{"id":"za284_3","label":"كِتَابُ الْإِقْرَارِ · ٣","segs":[["matn","وَإِنْ أَقَرَّ لِغَيْرِ وَارِثٍ أَوْ أَعْطَاهُ صَحَّ، وَإِنْ صَارَ عِنْدَ الْمَوْتِ وَارِثًا، ، وَإِنْ أَقَرَّتِ امْرَأَةٌ عَلَى نَفْسِهَا بِنِكَاحٍ وَلَمْ يَدَّعِهِ اثْنَانِ قُبِلَ، وَإِنْ أَقَرَّ وَلِيُّهَا الْمُجْبِرُ بِالنِّكَاحِ أَوْ الَّذِي أَذِنَتْ لَهُ صَحَّ،"]]},{"id":"za284_4","label":"كِتَابُ الْإِقْرَارِ · ٤","segs":[["matn","وَإِنْ أَقَرَّ بِنَسَبِ صَغِيرٍ أَوْ مَجْنُونٍ مَجْهُولِ النَّسَبِ أَنَّهُ ابْنُهُ ثَبَتَ نَسَبُهُ، فَإِنْ كَانَ مَيْتًا وَرِثَهُ، وَإِذَا ادَّعَى عَلَى شَخْصٍ بِشَيْءٍ فَصَدَّقَهُ صَحَّ."]]}],"group":"كِتَابُ الْإِقْرَارِ"},{"id":"za285","title":"كِتَابُ الْإِقْرَارِ · فَصْلٌ","units":[{"id":"za285_1","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ١","segs":[["matn","إِذَا وَصَلَ بِإِقْرَارِهِ مَا يُسْقِطُهُ مِثْلُ أَنْ يَقُولَ: لَهُ عَلَيَّ أَلْفٌ لَا تَلْزَمُنِي."]]},{"id":"za285_2","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ٢","segs":[["matn","وَنَحْوُهُ، لَزِمَهُ الْأَلْفُ، وَإِنْ قَالَ: كَانَ لَهُ عَلَيَّ وَقَضَيْتُهُ."]]},{"id":"za285_3","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ٣","segs":[["matn","فَقَوْلُهُ بِيَمِينِهِ مَا لَمْ تَكُنْ بَيِّنَةٌ أَوْ يَعْتَرِفُ بِسَبَبِ الْحَقِّ، وَإِنْ قَالَ: لَهُ عَلَيَّ مِائَةٌ."]]},{"id":"za285_4","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ٤","segs":[["matn","ثُمَّ سَكَتَ سُكُوتًا يُمْكِنُهُ الْكَلَامُ فِيهِ ثُمَّ قَالَ: زُيُوفًا أَوْ مُؤَجَّلَةً."]]},{"id":"za285_5","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ٥","segs":[["matn","لَزِمَهُ مِائَةٌ جَيِّدَةٌ حَالَّةٌ، وَإِنْ أَقَرَّ بِدَيْنٍ مُؤَجَّلٍ فَأَنْكَرَ الْمُقَرُّ لَهُ الْأَجَلَ فَقَوْلُ الْمُقِرِّ مَعَ يَمِينِهِ، وَإِنْ أَقَرَّ أَنَّهُ وَهَبَ أَوْ رَهَنَ وَأَقْبَضَ أَوْ أَقَرَّ بِقَبْضِ ثَمَنٍ أَوْ غَيْرِهِ ثُمَّ أَنْكَرَ الْقَبْضَ وَلَمْ يَجْحَدِ الْإِقْرَارَ،"]]},{"id":"za285_6","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ٦","segs":[["matn","وَسَأَلَ إِحْلَافَ خَصْمِهِ فَلَهُ ذَلِكَ، وَإِنْ بَاعَ شَيْئًا أَوْ وَهَبَهُ أَوْ أَعْتَقَهُ ثُمَّ أَقَرَّ أَنَّ ذَلِكَ كَانَ لِغَيْرِهِ لَمْ يُقْبَلْ قَوْلُهُ، وَلَمْ يَنْفَسِخِ الْبَيْعُ وَلَا غَيْرُهُ وَلَزِمَتْهُ غَرَامَتُهُ،"]]},{"id":"za285_7","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ٧","segs":[["matn","وَإِنْ قَالَ: لَمْ يَكُنْ مِلْكِي ثُمَّ مَلَكْتُهُ بَعْدُ."]]},{"id":"za285_8","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ · ٨","segs":[["matn","وَأَقَامَ بَيِّنَةً قُبِلَتْ، إِلَّا أَنْ يَكُونَ قَدْ أَقَرَّ أَنَّهُ مِلْكُهُ أَوْ أَنَّهُ قَبَضَ ثَمَنَ مِلْكِهِ لَمْ يُقْبَلْ."]]}],"group":"كِتَابُ الْإِقْرَارِ"},{"id":"za286","title":"كِتَابُ الْإِقْرَارِ · فَصْلٌ (٢)","units":[{"id":"za286_1","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ (٢) · ١","segs":[["matn","إِذَا قَالَ: لَهُ عَلَيَّ شَيْءٌ أَوْ كَذَا قِيلَ لَهُ: فَسِّرْهُ، فَإِنْ أَبَى حُبِسَ حَتَّى يُفَسِّرَهُ، فَإِنْ فَسَّرَهُ بِحَقِّ شُفْعَةٍ أَوْ بِأَقَلِّ مَالٍ قُبِلَ، وَإِنْ فَسَّرَهُ بِمَيْتَةٍ أَوْ خَمْرٍ أَوْ كَقِشْرِ جَوْزَةٍ لَمْ يُقْبَلْ،"]]},{"id":"za286_2","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ (٢) · ٢","segs":[["matn","وَيُقْبَلُ بِكَلْبٍ مُبَاحٍ نَفْعُهُ أَوْ حَدِّ قَذْفٍ، وَإِنْ قَالَ: لَهُ عَلَيَّ أَلْفٌ."]]},{"id":"za286_3","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ (٢) · ٣","segs":[["matn","رُجِعَ فِي تَفْسِيرِ جِنْسِهِ إِلَيْهِ، فَإِنْ فَسَّرَهُ بِجِنْسٍ أَوْ بِأَجْنَاسٍ قُبِلَ مِنْهُ، وَإِذَا قَالَ: لَهُ عَلَيَّ مَا بَيْنَ دِرْهَمٍ وَعَشَرَةٍ."]]},{"id":"za286_4","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ (٢) · ٤","segs":[["matn","لَزِمَهُ ثَمَانِيَةٌ، وَإِنْ قَالَ: مَا بَيْنَ دِرْهَمٍ إِلَى عَشَرَةٍ أَوْ مِنْ دِرْهَمٍ إِلَى عَشَرَةٍ."]]},{"id":"za286_5","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ (٢) · ٥","segs":[["matn","لَزِمَهُ تِسْعَةٌ، وَإِنْ قَالَ: لَهُ عَلَيَّ دِرْهَمٌ أَوْ دِيْنَارٌ."]]},{"id":"za286_6","label":"كِتَابُ الْإِقْرَارِ · فَصْلٌ (٢) · ٦","segs":[["matn","لَزِمَهُ أَحَدُهُمَا وَإِنْ قَالَ: لَهُ عَلَيَّ تَمْرٌ فِي جِرَابٍ، أَوْ سِكِّينٌ فِي قِرَابٍ، أَوْ فَصٌّ فِي خَاتَمٍ. وَنَحْوِهِ، فَهُوَ مُقِرٌّ بِالْأَوَّلِ."]]}],"group":"كِتَابُ الْإِقْرَارِ"}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
